INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation)
VALUES
  ('23', 'yes', 'Yesaya', 1, 1, 'Penglihatan yang telah dilihat Yesaya bin Amos tentang Yehuda dan Yerusalem dalam zaman Uzia, Yotam, Ahas dan Hizkia, raja-raja Yehuda.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 2, 'Dengarlah, hai langit, dan perhatikanlah, hai bumi, sebab TUHAN berfirman: "Aku membesarkan anak-anak dan mengasuhnya, tetapi mereka memberontak terhadap Aku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 3, 'Lembu mengenal pemiliknya, tetapi Israel tidak; keledai mengenal palungan yang disediakan tuannya, tetapi umat-Ku tidak memahaminya."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 4, 'Celakalah bangsa yang berdosa, kaum yang sarat dengan kesalahan, keturunan yang jahat-jahat, anak-anak yang berlaku buruk! Mereka meninggalkan TUHAN, menista Yang Mahakudus, Allah Israel, dan berpaling membelakangi Dia.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 5, 'Di mana kamu mau dipukul lagi, kamu yang bertambah murtad? Seluruh kepala sakit dan seluruh hati lemah lesu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 6, 'Dari telapak kaki sampai kepala tidak ada yang sehat: bengkak dan bilur dan luka baru, tidak dipijit dan tidak dibalut dan tidak ditaruh minyak.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 7, 'Negerimu menjadi sunyi sepi, kota-kotamu habis terbakar; di depan matamu orang-orang asing memakan hasil dari tanahmu. Sunyi sepi negeri itu seolah-olah ditunggangbalikkan orang asing.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 8, 'Puteri Sion tertinggal sendirian seperti pondok di kebun anggur, seperti gubuk di kebun mentimun dan seperti kota yang terkepung.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 9, 'Seandainya TUHAN semesta alam tidak meninggalkan pada kita sedikit orang yang terlepas, kita sudah menjadi seperti Sodom, dan sama seperti Gomora.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 10, 'Dengarlah firman TUHAN, hai pemimpin-pemimpin, manusia Sodom! Perhatikanlah pengajaran Allah kita, hai rakyat, manusia Gomora!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 11, '"Untuk apa itu korbanmu yang banyak-banyak?" firman TUHAN; "Aku sudah jemu akan korban-korban bakaran berupa domba jantan dan akan lemak dari anak lembu gemukan; darah lembu jantan dan domba-domba dan kambing jantan tidak Kusukai.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 12, 'Apabila kamu datang untuk menghadap di hadirat-Ku, siapakah yang menuntut itu dari padamu, bahwa kamu menginjak-injak pelataran Bait Suci-Ku?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 13, 'Jangan lagi membawa persembahanmu yang tidak sungguh, sebab baunya adalah kejijikan bagi-Ku. Kalau kamu merayakan bulan baru dan sabat atau mengadakan pertemuan-pertemuan, Aku tidak tahan melihatnya, karena perayaanmu itu penuh kejahatan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 14, 'Perayaan-perayaan bulan barumu dan pertemuan-pertemuanmu yang tetap, Aku benci melihatnya; semuanya itu menjadi beban bagi-Ku, Aku telah payah menanggungnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 15, 'Apabila kamu menadahkan tanganmu untuk berdoa, Aku akan memalingkan muka-Ku, bahkan sekalipun kamu berkali-kali berdoa, Aku tidak akan mendengarkannya, sebab tanganmu penuh dengan darah.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 16, 'Basuhlah, bersihkanlah dirimu, jauhkanlah perbuatan-perbuatanmu yang jahat dari depan mata-Ku. Berhentilah berbuat jahat,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 17, 'belajarlah berbuat baik; usahakanlah keadilan, kendalikanlah orang kejam; belalah hak anak-anak yatim, perjuangkanlah perkara janda-janda!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 18, 'Marilah, baiklah kita berperkara! ?firman TUHAN?Sekalipun dosamu merah seperti kirmizi, akan menjadi putih seperti salju; sekalipun berwarna merah seperti kain kesumba, akan menjadi putih seperti bulu domba.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 19, 'Jika kamu menurut dan mau mendengar, maka kamu akan memakan hasil baik dari negeri itu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 20, 'Tetapi jika kamu melawan dan memberontak, maka kamu akan dimakan oleh pedang." Sungguh, TUHAN yang mengucapkannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 21, 'Bagaimana ini, kota yang dahulu setia sekarang sudah menjadi sundal! Tadinya penuh keadilan dan di situ selalu diam kebenaran, tetapi sekarang penuh pembunuh.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 22, 'Perakmu tidak murni lagi dan arakmu bercampur air.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 23, 'Para pemimpinmu adalah pemberontak dan bersekongkol dengan pencuri. Semuanya suka menerima suap dan mengejar sogok. Mereka tidak membela hak anak-anak yatim, dan perkara janda-janda tidak sampai kepada mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 24, 'Sebab itu demikianlah firman Tuhan, TUHAN semesta alam, Yang Mahakuat pelindung Israel; "Ha, Aku akan melampiaskan dendam-Ku kepada para lawan-Ku, dan melakukan pembalasan kepada para musuh-Ku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 25, 'Aku akan bertindak terhadap engkau: Aku akan memurnikan perakmu dengan garam soda, dan akan menyingkirkan segala timah dari padanya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 26, 'Aku akan mengembalikan para hakimmu seperti dahulu, dan para penasihatmu seperti semula. Sesudah itu engkau akan disebutkan kota keadilan, kota yang setia."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 27, 'Sion akan Kubebaskan dengan penghakiman yang adil dan orang-orangnya yang bertobat akan Kubebaskan dengan tindakan yang benar.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 28, 'Tetapi orang-orang yang memberontak dan orang-orang berdosa akan dihancurkan bersama, dan orang-orang yang meninggalkan TUHAN akan habis lenyap.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 29, 'Sungguh, kamu akan mendapat malu karena pohon-pohon keramat yang kamu inginkan; dan kamu akan tersipu-sipu karena taman-taman dewa yang kamu pilih.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 30, 'Sebab kamu akan seperti pohon keramat yang daunnya layu, dan seperti kebun yang kekurangan air.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 1, 31, 'Maka yang kuat menjadi seolah-olah kapas dan pekerjaannya menjadi seolah-olah bunga api; keduanya menimbulkan api dan tidak ada yang dapat memadamkan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 2, 1, 'Firman yang dinyatakan kepada Yesaya bin Amos tentang Yehuda dan Yerusalem.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 2, 2, 'Akan terjadi pada hari-hari yang terakhir: gunung tempat rumah TUHAN akan berdiri tegak di hulu gunung-gunung dan menjulang tinggi di atas bukit-bukit; segala bangsa akan berduyun-duyun ke sana,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 2, 3, 'dan banyak suku bangsa akan pergi serta berkata: "Mari, kita naik ke gunung TUHAN, ke rumah Allah Yakub, supaya Ia mengajar kita tentang jalan-jalan-Nya, dan supaya kita berjalan menempuhnya; sebab dari Sion akan keluar pengajaran dan firman TUHAN dari Yerusalem."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 2, 4, 'Ia akan menjadi hakim antara bangsa-bangsa dan akan menjadi wasit bagi banyak suku bangsa; maka mereka akan menempa pedang-pedangnya menjadi mata bajak dan tombak-tombaknya menjadi pisau pemangkas; bangsa tidak akan lagi mengangkat pedang terhadap bangsa, dan mereka tidak akan lagi belajar perang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 2, 5, 'Hai kaum keturunan Yakub, mari kita berjalan di dalam terang TUHAN!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 2, 6, 'Sungguh, telah Kaubuang umat-Mu, yakni kaum keturunan Yakub, sebab di mana-mana mereka melakukan tenung seperti yang di Timur dan sihir seperti orang Filistin, dan orang-orang asing di antara mereka terlalu banyak.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 2, 7, 'Negerinya penuh emas dan perak dan tak terbatas harta bendanya; negerinya penuh kuda dan tak terbatas jumlah keretanya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 2, 8, 'Negerinya penuh berhala-berhala; mereka sujud menyembah kepada buatan tangannya sendiri dan kepada yang dikerjakan oleh tangannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 2, 9, 'Maka manusia ditundukkan dan orang direndahkan?janganlah ampuni mereka!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 2, 10, 'Masuklah di sela gunung batu dan bersembunyilah di dalam liang tanah terhadap kedahsyatan TUHAN dan terhadap semarak kemegahan-Nya!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 2, 11, 'Manusia yang sombong akan direndahkan, dan orang yang angkuh akan ditundukkan; dan hanya TUHAN sajalah yang maha tinggi pada hari itu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 2, 12, 'Sebab TUHAN semesta alam menetapkan suatu hari untuk menghukum semua yang congkak dan angkuh serta menghukum semua yang meninggikan diri, supaya direndahkan;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 2, 13, 'untuk menghukum semua pohon aras di Libanon yang tumbuh meninggi dan tetap menjulang, dan menghukum semua pohon tarbantin di Basan;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 2, 14, 'untuk menghukum semua gunung yang tinggi-tinggi dan semua bukit yang menjulang ke atas;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 2, 15, 'untuk menghukum semua menara yang tinggi-tinggi dan semua tembok yang berkubu;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 2, 16, 'untuk menghukum semua kapal Tarsis dan semua kapal yang paling indah.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 2, 17, 'Manusia yang sombong akan ditundukkan dan orang yang angkuh akan direndahkan; hanya TUHAN sajalah yang maha tinggi pada hari itu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 2, 18, 'Sedang berhala-berhala akan hilang sama sekali.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 2, 19, 'Maka orang akan masuk ke dalam gua-gua di gunung batu dan ke dalam liang-liang di tanah terhadap kedahsyatan TUHAN dan terhadap semarak kemegahan-Nya, pada waktu Ia bangkit menakut-nakuti bumi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 2, 20, 'Pada hari itu berhala-berhala perak dan berhala-berhala emas yang dibuat manusia untuk sujud menyembah kepadanya akan dilemparkannya kepada tikus dan kelelawar,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 2, 21, 'dan ia akan masuk ke dalam lekuk-lekuk di gunung batu dan ke dalam celah-celah di bukit batu terhadap kedahsyatan TUHAN dan terhadap semarak kemegahan-Nya, pada waktu Ia bangkit menakut-nakuti bumi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 2, 22, 'Jangan berharap pada manusia, sebab ia tidak lebih dari pada embusan nafas, dan sebagai apakah ia dapat dianggap?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 1, 'Maka sesungguhnya Tuhan, TUHAN semesta alam, akan menjauhkan dari Yerusalem dan dari Yehuda setiap orang yang mereka andalkan, segala persediaan makanan dan minuman:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 2, 'pahlawan dan orang perang, hakim dan nabi, petenung dan tua-tua,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 3, 'perwira dan orang yang terpandang, penasihat dan ahli sihir, dan orang yang paham mantera.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 4, 'Aku akan mengangkat pemuda-pemuda menjadi pemimpin mereka, dan anak-anak akan memerintah atas mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 5, 'Maka bangsa itu akan desak-mendesak, seorang kepada seorang, yang satu kepada yang lain; orang muda akan membentak-bentak terhadap orang tua, orang hina terhadap orang mulia.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 6, 'Sehingga apabila seorang memegang saudaranya di rumah ayahnya dan berkata: "Engkau masih mempunyai jubah, jadilah pemimpin kami, dan reruntuhan ini di bawah kuasamu",', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 7, 'maka pada waktu itu saudaranya akan menjawab: "Aku tidak mau menjadi tabib; di rumahku tidak ada roti dan tidak ada jubah; janganlah angkat aku menjadi pemimpin bangsa."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 8, 'Sungguh, Yerusalem telah runtuh dan Yehuda telah rubuh; sebab perkataan mereka dan perbuatan mereka melawan TUHAN dan mereka menantang kemuliaan hadirat-Nya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 9, 'Air muka mereka menyatakan kejahatan mereka, dan seperti orang Sodom, mereka dengan terang-terangan menyebut-nyebut dosanya, tidak lagi disembunyikannya. Celakalah orang-orang itu! Sebab mereka mendatangkan malapetaka kepada dirinya sendiri.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 10, 'Katakanlah berbahagia orang benar! Sebab mereka akan memakan hasil pekerjaannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 11, 'Celakalah orang fasik! Malapetaka akan menimpanya, sebab mereka akan diperlakukan menurut perbuatannya sendiri.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 12, 'Adapun umat-Ku, penguasa mereka ialah anak-anak, dan perempuan-perempuan memerintah atasnya. Hai umat-Ku, pemimpin-pemimpinmu adalah penyesat, dan jalan yang kamu tempuh mereka kacaukan!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 13, 'TUHAN mengambil tempat untuk menuntut dan berdiri untuk mengadili bangsa-bangsa.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 14, 'TUHAN bertindak sebagai hakim atas tua-tua dan pemimpin-pemimpin umat-Nya: "Kamulah yang memusnahkan kebun anggur itu, barang rampasan dari orang yang tertindas tertumpuk di dalam rumahmu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 15, 'Mengapa kamu menyiksa umat-Ku dan menganiaya orang-orang yang tertindas?" demikianlah firman Tuhan ALLAH semesta alam.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 16, 'TUHAN berfirman: Oleh karena wanita Sion telah menjadi sombong dan telah berjalan dengan jenjang leher dan dengan main mata, berjalan dengan dibuat-buat langkahnya dan gemerencing dengan giring-giring kakinya,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 17, 'maka Tuhan akan membuat batu kepala wanita Sion penuh kudis dan TUHAN akan mencukur rambut sebelah dahi mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 18, 'Pada waktu itu Tuhan akan menjauhkan segala perhiasan mereka: gelang-gelang kaki, jamang-jamang dan bulan-bulanan;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 19, 'perhiasan-perhiasan telinga, pontoh-pontoh dan kerudung-kerudung;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 20, 'perhiasan-perhiasan kepala, gelang-gelang rantai kaki, tali-tali pinggang, tempat-tempat wewangian dan jimat-jimat;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 21, 'cincin meterai dan anting-anting hidung;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 22, 'pakaian-pakaian pesta, jubah-jubah, selendang-selendang dan pundi-pundi;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 23, 'cermin-cermin, baju-baju dalam dari kain lenan, ikat-ikat kepala dan baju-baju luar.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 24, 'Maka sebagai ganti rempah-rempah harum akan ada bau busuk, sebagai ganti ikat pinggang seutas tali, sebagai ganti selampit rambut kepala yang gundul, sebagai ganti pakaian hari raya sehelai kain kabung; dan tanda selar sebagai ganti kemolekan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 25, 'Orang-orangmu akan tewas oleh pedang, dan pahlawan-pahlawanmu oleh perang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 3, 26, 'Pintu-pintu gerbang Sion akan mengaduh dan berkabung, dan kota itu akan seperti perempuan bulus yang duduk di bumi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 4, 1, 'Pada waktu itu tujuh orang perempuan akan memegang seorang laki-laki, serta berkata: "Kami akan menanggung makanan dan pakaian kami sendiri; hanya biarlah namamu dilekatkan kepada nama kami; ambillah aib yang ada pada kami!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 4, 2, 'Pada waktu itu tunas yang ditumbuhkan TUHAN akan menjadi kepermaian dan kemuliaan, dan hasil tanah menjadi kebanggaan dan kehormatan bagi orang-orang Israel yang terluput.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 4, 3, 'Dan orang yang tertinggal di Sion dan yang tersisa di Yerusalem akan disebut kudus, yakni setiap orang di Yerusalem yang tercatat untuk beroleh hidup,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 4, 4, 'apabila TUHAN telah membersihkan kekotoran puteri Sion dan menghapuskan segala noda darah Yerusalem dari tengah-tengahnya dengan roh yang mengadili dan yang membakar.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 4, 5, 'Maka TUHAN akan menjadikan di atas seluruh wilayah gunung Sion dan di atas setiap pertemuan yang diadakan di situ segumpal awan pada waktu siang dan segumpal asap serta sinar api yang menyala-nyala pada waktu malam, sebab di atas semuanya itu akan ada kemuliaan TUHAN sebagai tudung', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 4, 6, 'dan sebagai pondok tempat bernaung pada waktu siang terhadap panas terik dan sebagai perlindungan dan persembunyian terhadap angin ribut dan hujan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 1, 'Aku hendak menyanyikan nyanyian tentang kekasihku, nyanyian kekasihku tentang kebun anggurnya: Kekasihku itu mempunyai kebun anggur di lereng bukit yang subur.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 2, 'Ia mencangkulnya dan membuang batu-batunya, dan menanaminya dengan pokok anggur pilihan; ia mendirikan sebuah menara jaga di tengah-tengahnya dan menggali lobang tempat memeras anggur; lalu dinantinya supaya kebun itu menghasilkan buah anggur yang baik, tetapi yang dihasilkannya ialah buah anggur yang asam.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 3, 'Maka sekarang, hai penduduk Yerusalem, dan orang Yehuda, adililah antara Aku dan kebun anggur-Ku itu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 4, 'Apatah lagi yang harus diperbuat untuk kebun anggur-Ku itu, yang belum Kuperbuat kepadanya? Aku menanti supaya dihasilkannya buah anggur yang baik, mengapa yang dihasilkannya hanya buah anggur yang asam?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 5, 'Maka sekarang, Aku mau memberitahukan kepadamu apa yang hendak Kulakukan kepada kebun anggur-Ku itu: Aku akan menebang pagar durinya, sehingga kebun itu dimakan habis, dan melanda temboknya, sehingga kebun itu diinjak-injak;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 6, 'Aku akan membuatnya ditumbuhi semak-semak, tidak dirantingi dan tidak disiangi, sehingga tumbuh puteri malu dan rumput; Aku akan memerintahkan awan-awan, supaya jangan diturunkannya hujan ke atasnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 7, 'Sebab kebun anggur TUHAN semesta alam ialah kaum Israel, dan orang Yehuda ialah tanam-tanaman kegemaran-Nya; dinanti-Nya keadilan, tetapi hanya ada kelaliman, dinanti-Nya kebenaran tetapi hanya ada keonaran.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 8, 'Celakalah mereka yang menyerobot rumah demi rumah dan mencekau ladang demi ladang, sehingga tidak ada lagi tempat bagi orang lain dan hanya kamu sendiri yang tinggal di dalam negeri!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 9, 'Di telingaku terdengar firman TUHAN semesta alam: "Sesungguhnya banyak rumah akan menjadi sunyi sepi; rumah-rumah yang besar dan yang baik tidak akan ada penghuninya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 10, 'Sebab kebun anggur yang luasnya sepuluh hari membajak akan menghasilkan hanya satu bat anggur; dan satu homer benih akan menghasilkan hanya satu efa gandum."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 11, 'Celakalah mereka yang bangun pagi-pagi dan terus mencari minuman keras, dan duduk-duduk sampai malam hari, sedang badannya dihangatkan anggur!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 12, 'Kecapi dan gambus, rebana dan suling, serta anggur terdapat dalam perjamuan-perjamuan mereka, tetapi perbuatan TUHAN tidak dipandangnya dan pekerjaan TUHAN tidak dilihatnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 13, 'Sebab itu umat-Ku harus pergi ke dalam pembuangan, oleh sebab mereka tidak mengerti apa-apa; orang-orang yang mulia akan mati kelaparan, dan khalayak ramai akan menderita kehausan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 14, 'Sebab itu dunia orang mati akan membuka kerongkongannya lapang-lapang dan akan mengangakan mulutnya lebar-lebar dengan tiada terhingga, sehingga lenyap ke dalamnya segala kesemarakan dan keramaian Yerusalem, segala kegaduhannya dan orang-orang yang bersukaria di kota itu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 15, 'Maka manusia akan ditundukkan, dan orang akan direndahkan, ya, orang-orang sombong akan direndahkan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 16, 'Tetapi TUHAN semesta alam akan ternyata maha tinggi dalam keadilan-Nya, dan Allah yang maha kudus akan menyatakan kekudusan-Nya dalam kebenaran-Nya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 17, 'Maka domba-domba akan makan rumput di situ seperti di padangnya sendiri dan kambing-kambing akan mencari makan dalam reruntuhan gedung-gedung orang kaya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 18, 'Celakalah mereka yang memancing kesalahan dengan tali kedustaan dan dosa seperti dengan tali gerobak,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 19, 'yang berkata: "Baiklah Allah lekas-lekas dan cepat-cepat melakukan tindakan-Nya, supaya kita lihat; dan baiklah keputusan Yang Mahakudus, Allah Israel, datang mendekat, supaya kita tahu."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 20, 'Celakalah mereka yang menyebutkan kejahatan itu baik dan kebaikan itu jahat, yang mengubah kegelapan menjadi terang dan terang menjadi kegelapan, yang mengubah pahit menjadi manis, dan manis menjadi pahit.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 21, 'Celakalah mereka yang memandang dirinya bijaksana, yang menganggap dirinya pintar!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 22, 'Celakalah mereka yang menjadi jago minum dan juara dalam mencampur minuman keras;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 23, 'yang membenarkan orang fasik karena suap dan yang memungkiri hak orang benar.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 24, 'Sebab itu seperti lidah api memakan jerami, dan seperti rumput kering habis lenyap dalam nyala api, demikian akar-akar mereka akan menjadi busuk, dan kuntumnya akan beterbangan seperti abu, oleh karena mereka telah menolak pengajaran TUHAN semesta alam dan menista firman Yang Mahakudus, Allah Israel.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 25, 'Sebab itu bangkitlah murka TUHAN terhadap umat-Nya, diacungkan-Nya tangan-Nya terhadap mereka dan dipukul-Nya mereka; gunung-gunung akan gemetar, dan mayat-mayat mereka akan seperti kotoran di tengah jalan. Sekalipun semuanya ini terjadi, murka-Nya belum surut, dan tangan-Nya masih teracung.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 26, 'Ia akan melambaikan panji-panji kepada bangsa yang dari jauh, dan akan bersuit memanggil mereka dari ujung bumi; sesungguhnya mereka akan datang dengan segera, dengan cepat!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 27, 'Tiada yang lelah dan tiada yang tersandung di antaranya; mereka tidak terlelap dan tidak tertidur, tidak terlepas ikat pinggangnya dan tali kasutnya tidak terputus;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 28, 'anak panahnya ditajamkan, dan segala busurnya dilentur; kuku kudanya keras seperti batu api dan roda keretanya seperti puting beliung.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 29, 'Aumnya seperti singa betina, mereka mengaum seperti singa muda; mereka meraung dan menangkap mangsanya, membawanya lari dan tidak ada yang melepaskan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 5, 30, 'Pada hari itu mereka akan diliputi oleh suara seperti suara laut menderu. Jika orang memandang ke bumi, sesungguhnya, ada gelap yang menyesakkan, dan terang menjadi gelap oleh awan-awan!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 6, 1, 'Dalam tahun matinya raja Uzia aku melihat Tuhan duduk di atas takhta yang tinggi dan menjulang, dan ujung jubah-Nya memenuhi Bait Suci.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 6, 2, 'Para Serafim berdiri di sebelah atas-Nya, masing-masing mempunyai enam sayap; dua sayap dipakai untuk menutupi muka mereka, dua sayap dipakai untuk menutupi kaki mereka dan dua sayap dipakai untuk melayang-layang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 6, 3, 'Dan mereka berseru seorang kepada seorang, katanya: "Kudus, kudus, kuduslah TUHAN semesta alam, seluruh bumi penuh kemuliaan-Nya!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 6, 4, 'Maka bergoyanglah alas ambang pintu disebabkan suara orang yang berseru itu dan rumah itupun penuhlah dengan asap.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 6, 5, 'Lalu kataku: "Celakalah aku! aku binasa! Sebab aku ini seorang yang najis bibir, dan aku tinggal di tengah-tengah bangsa yang najis bibir, namun mataku telah melihat Sang Raja, yakni TUHAN semesta alam."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 6, 6, 'Tetapi seorang dari pada Serafim itu terbang mendapatkan aku; di tangannya ada bara, yang diambilnya dengan sepit dari atas mezbah.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 6, 7, 'Ia menyentuhkannya kepada mulutku serta berkata: "Lihat, ini telah menyentuh bibirmu, maka kesalahanmu telah dihapus dan dosamu telah diampuni."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 6, 8, 'Lalu aku mendengar suara Tuhan berkata: "Siapakah yang akan Kuutus, dan siapakah yang mau pergi untuk Aku?" Maka sahutku: "Ini aku, utuslah aku!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 6, 9, 'Kemudian firman-Nya: "Pergilah, dan katakanlah kepada bangsa ini: Dengarlah sungguh-sungguh, tetapi mengerti: jangan! Lihatlah sungguh-sungguh, tetapi menanggap: jangan!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 6, 10, 'Buatlah hati bangsa ini keras dan buatlah telinganya berat mendengar dan buatlah matanya melekat tertutup, supaya jangan mereka melihat dengan matanya dan mendengar dengan telinganya dan mengerti dengan hatinya, lalu berbalik dan menjadi sembuh."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 6, 11, 'Kemudian aku bertanya: "Sampai berapa lama, ya Tuhan?" Lalu jawab-Nya: "Sampai kota-kota telah lengang sunyi sepi, tidak ada lagi yang mendiami, dan di rumah-rumah tidak ada lagi manusia dan tanah menjadi sunyi dan sepi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 6, 12, 'TUHAN akan menyingkirkan manusia jauh-jauh, sehingga hampir seluruh negeri menjadi kosong.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 6, 13, 'Dan jika di situ masih tinggal sepersepuluh dari mereka, mereka harus sekali lagi ditimpa kebinasaan, namun keadaannya akan seperti pohon beringin dan pohon jawi-jawi yang tunggulnya tinggal berdiri pada waktu ditebang. Dan dari tunggul itulah akan keluar tunas yang kudus!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 1, 'Dalam zaman Ahas bin Yotam bin Uzia, raja Yehuda, maka Rezin, raja Aram, dengan Pekah bin Remalya, raja Israel, maju ke Yerusalem untuk berperang melawan kota itu, namun mereka tidak dapat mengalahkannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 2, 'Lalu diberitahukanlah kepada keluarga Daud: "Aram telah berkemah di wilayah Efraim," maka hati Ahas dan hati rakyatnya gemetar ketakutan seperti pohon-pohon hutan bergoyang ditiup angin.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 3, 'Berfirmanlah TUHAN kepada Yesaya: "Baiklah engkau keluar menemui Ahas, engkau dan Syear Yasyub, anakmu laki-laki, ke ujung saluran kolam atas, ke jalan raya pada Padang Tukang Penatu,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 4, 'dan katakanlah kepadanya: Teguhkanlah hatimu dan tinggallah tenang, janganlah takut dan janganlah hatimu kecut karena kedua puntung kayu api yang berasap ini, yaitu kepanasan amarah Rezin dengan Aram dan anak Remalya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 5, 'Oleh karena Aram dan Efraim dengan anak Remalya telah merancang yang jahat atasmu, dengan berkata:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 6, 'Marilah kita maju menyerang Yehuda dan menakut-nakutinya serta merebutnya, kemudian mengangkat anak Tabeel sebagai raja di tengah-tengahnya,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 7, 'maka beginilah firman Tuhan ALLAH: Tidak akan sampai hal itu, dan tidak akan terjadi,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 8, 'sebab Damsyik ialah ibu kota Aram, dan Rezin ialah kepala Damsyik. Dalam enam puluh lima tahun Efraim akan pecah, tidak menjadi bangsa lagi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 9, 'Dan Samaria ialah ibu kota Efraim, dan anak Remalya ialah kepala Samaria. Jika kamu tidak percaya, sungguh, kamu tidak teguh jaya."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 10, 'TUHAN melanjutkan firman-Nya kepada Ahas, kata-Nya:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 11, '"Mintalah suatu pertanda dari TUHAN, Allahmu, biarlah itu sesuatu dari dunia orang mati yang paling bawah atau sesuatu dari tempat tertinggi yang di atas."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 12, 'Tetapi Ahas menjawab: "Aku tidak mau meminta, aku tidak mau mencobai TUHAN."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 13, 'Lalu berkatalah nabi Yesaya: "Baiklah dengarkan, hai keluarga Daud! Belum cukupkah kamu melelahkan orang, sehingga kamu melelahkan Allahku juga?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 14, 'Sebab itu Tuhan sendirilah yang akan memberikan kepadamu suatu pertanda: Sesungguhnya, seorang perempuan muda mengandung dan akan melahirkan seorang anak laki-laki, dan ia akan menamakan Dia Imanuel.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 15, 'Ia akan makan dadih dan madu sampai ia tahu menolak yang jahat dan memilih yang baik,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 16, 'sebab sebelum anak itu tahu menolak yang jahat dan memilih yang baik, maka negeri yang kedua rajanya engkau takuti akan ditinggalkan kosong.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 17, 'TUHAN akan mendatangkan atasmu dan atas rakyatmu dan atas kaum keluargamu hari-hari seperti yang belum pernah datang sejak Efraim menjauhkan diri dari Yehuda?yakni raja Asyur."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 18, 'Pada hari itu akan terjadi: TUHAN bersuit memanggil lalat yang ada di ujung anak-anak sungai Nil, dan memanggil lebah yang ada di tanah Asyur.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 19, 'Dan semuanya akan datang hinggap di lembah-lembah yang terjal dan di celah-celah bukit-bukit batu, di segala pagar duri dan di segala tanah penggembalaan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 20, 'Pada hari itu dengan pisau cukur yang dipinjam dari seberang sungai Efrat, yakni raja Asyur, Tuhan akan mencukur kepala dan bulu paha, bahkan pisau itu akan melenyapkan janggut juga.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 21, 'Pada hari itu setiap orang akan memiara seekor lembu betina yang muda dan dua ekor domba,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 22, 'dan karena banyaknya susu yang dihasilkan, mereka akan makan dadih; sungguh, dadih dan madu akan dimakan oleh setiap orang yang masih tinggal di dalam negeri.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 23, 'Pada hari itu setiap tempat, di mana biasanya tumbuh seribu pohon anggur dan yang berharga seribu syikal perak, akan menjadi tempat puteri malu dan rumput.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 24, 'Orang pergi ke sana terpaksa membawa anak-anak panah dan busur, sebab puteri malu dan rumput belaka seluruh negeri itu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 7, 25, 'Dan engkau tidak berani pergi ke segala lereng gunung yang biasanya dicangkul, karena takut akan puteri malu dan rumput; di situ hanya lembu dan domba akan berkeliaran.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 8, 1, 'Berfirmanlah TUHAN kepadaku: "Ambillah sebuah batu tulis besar dan tuliskanlah di atasnya dengan tulisan biasa: Maher-Syalal Hash-Bas."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 8, 2, 'Maka aku memanggil dua saksi yang dapat dipercaya, yaitu imam Uria dan Zakharia bin Yeberekhya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 8, 3, 'Kemudian aku menghampiri isteriku; ia mengandung dan melahirkan seorang anak laki-laki. Lalu berfirmanlah TUHAN kepadaku: "Namailah dia: Maher-Syalal Hash-Bas,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 8, 4, 'sebab sebelum anak itu tahu memanggil: Bapa! Ibu! maka kekayaan Damsyik dan jarahan Samaria akan diangkut di depan raja Asyur."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 8, 5, 'TUHAN melanjutkan lagi firman-Nya kepadaku:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 8, 6, '"Oleh karena bangsa ini telah menolak air Syiloah yang mengalir lamban, dan telah tawar hati terhadap Rezin dan anak Remalya,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 8, 7, 'sebab itu, sesungguhnya, Tuhan akan membuat air sungai Efrat yang kuat dan besar, meluap-luap atas mereka, yaitu raja Asyur dengan segala kemuliaannya; air ini akan meluap melampaui segenap salurannya dan akan mengalir melampaui segenap tebingnya,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 8, 8, 'serta menerobos masuk ke Yehuda, ibarat banjir yang meluap-luap hingga sampai ke leher; dan sayap-sayapnya yang dikembangkan akan menutup seantero negerimu, ya Imanuel!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 8, 9, 'Ketahuilah, hai bangsa-bangsa, dan terkejutlah, perhatikanlah, ya segala pelosok bumi, berikatpingganglah, dan terkejutlah; berikatpingganglah dan terkejutlah!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 8, 10, 'Buatlah rancangan, tetapi akan gagal juga; ambillah keputusan, tetapi tidak terlaksana juga, sebab Allah menyertai kami!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 8, 11, 'Sebab beginilah firman TUHAN kepadaku, ketika tangan-Nya menguasai aku, dan ketika Ia memperingatkan aku, supaya jangan mengikuti tingkah laku bangsa ini:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 8, 12, '"Jangan sebut persepakatan segala apa yang disebut bangsa ini persepakatan, dan apa yang mereka takuti janganlah kamu takuti dan janganlah gentar melihatnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 8, 13, 'Tetapi TUHAN semesta alam, Dialah yang harus kamu akui sebagai Yang Kudus; kepada-Nyalah harus kamu takut dan terhadap Dialah harus kamu gentar.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 8, 14, 'Ia akan menjadi tempat kudus, tetapi juga menjadi batu sentuhan dan batu sandungan bagi kedua kaum Israel itu, serta menjadi jerat dan perangkap bagi penduduk Yerusalem.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 8, 15, 'Dan banyak di antara mereka akan tersandung, jatuh dan luka parah, tertangkap dan tertawan."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 8, 16, 'Aku harus menyimpan kesaksian ini dan memeteraikan pengajaran ini di antara murid-muridku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 8, 17, 'Dan aku hendak menanti-nantikan TUHAN yang menyembunyikan wajah-Nya terhadap kaum keturunan Yakub; aku hendak mengharapkan Dia.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 8, 18, 'Sesungguhnya, aku dan anak-anak yang telah diberikan TUHAN kepadaku adalah tanda dan alamat di antara orang Israel dari TUHAN semesta alam yang diam di gunung Sion.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 8, 19, 'Dan apabila orang berkata kepada kamu: "Mintalah petunjuk kepada arwah dan roh-roh peramal yang berbisik-bisik dan komat-kamit," maka jawablah: "Bukankah suatu bangsa patut meminta petunjuk kepada allahnya? Atau haruskah mereka meminta petunjuk kepada orang-orang mati bagi orang-orang hidup?"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 8, 20, '"Carilah pengajaran dan kesaksian!" Siapa yang tidak berbicara sesuai dengan perkataan itu, maka baginya tidak terbit fajar.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 8, 21, 'Mereka akan lalu lalang di negeri itu, melarat dan lapar, dan apabila mereka lapar, mereka akan gusar dan akan mengutuk rajanya dan Allahnya; mereka akan menengadah ke langit,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 8, 22, 'dan akan melihat ke bumi, dan sesungguhnya, hanya kesesakan dan kegelapan, kesuraman yang mengimpit, dan mereka akan dibuang ke dalam kabut.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 9, 1, '(8-23) Tetapi tidak selamanya akan ada kesuraman untuk negeri yang terimpit itu. Kalau dahulu TUHAN merendahkan tanah Zebulon dan tanah Naftali, maka di kemudian hari Ia akan memuliakan jalan ke laut, daerah seberang sungai Yordan, wilayah bangsa-bangsa lain.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 9, 2, '(9-1) Bangsa yang berjalan di dalam kegelapan telah melihat terang yang besar; mereka yang diam di negeri kekelaman, atasnya terang telah bersinar.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 9, 3, '(9-2) Engkau telah menimbulkan banyak sorak-sorak, dan sukacita yang besar; mereka telah bersukacita di hadapan-Mu, seperti sukacita di waktu panen, seperti orang bersorak-sorak di waktu membagi-bagi jarahan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 9, 4, '(9-3) Sebab kuk yang menekannya dan gandar yang di atas bahunya serta tongkat si penindas telah Kaupatahkan seperti pada hari kekalahan Midian.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 9, 5, '(9-4) Sebab setiap sepatu tentara yang berderap-derap dan setiap jubah yang berlumuran darah akan menjadi umpan api.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 9, 6, '(9-5) Sebab seorang anak telah lahir untuk kita, seorang putera telah diberikan untuk kita; lambang pemerintahan ada di atas bahunya, dan namanya disebutkan orang: Penasihat Ajaib, Allah yang Perkasa, Bapa yang Kekal, Raja Damai.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 9, 7, '(9-6) Besar kekuasaannya, dan damai sejahtera tidak akan berkesudahan di atas takhta Daud dan di dalam kerajaannya, karena ia mendasarkan dan mengokohkannya dengan keadilan dan kebenaran dari sekarang sampai selama-lamanya. Kecemburuan TUHAN semesta alam akan melakukan hal ini.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 9, 8, '(9-7) Tuhan telah melontarkan firman kepada Yakub, dan firman-Nya itu menimpa Israel.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 9, 9, '(9-8) Biarlah seluruh bangsa itu mengetahuinya, yakni Efraim dan penduduk Samaria, yang berkata dengan congkaknya dan tinggi hatinya:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 9, 10, '(9-9) "Tembok batu bata jatuh, akan kita dirikan dari batu pahat; pohon-pohon ara ditebang, akan kita ganti dengan pohon-pohon aras."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 9, 11, '(9-10) Maka TUHAN membangkitkan para panglima Rezin melawan mereka, dan menggerakkan musuh-musuh mereka:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 9, 12, '(9-11) Orang Aram dari timur, dan orang Filistin dari barat, mereka menelan Israel dengan mulut yang lebar. Sekalipun semuanya ini terjadi, murka-Nya belum surut, dan tangan-Nya masih teracung.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 9, 13, '(9-12) Tetapi bangsa itu tidak kembali kepada Dia yang menghajarnya, dan mereka tidak mencari TUHAN semesta alam.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 9, 14, '(9-13) Maka TUHAN mengerat dari Israel kepala dan ekor, batang dan ranting pada satu hari juga.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 9, 15, '(9-14) Tua-tua dan orang yang terpandang, itulah kepala, dan nabi yang mengajarkan dusta, itulah ekor.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 9, 16, '(9-15) Sebab orang-orang yang mengendalikan bangsa ini adalah penyesat, dan orang-orang yang dikendalikan mereka menjadi kacau.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 9, 17, '(9-16) Sebab itu Tuhan tidak bersukacita karena teruna-teruna mereka, dan tidak sayang kepada anak-anak yatim dan janda-janda mereka, sebab sekaliannya mereka murtad dan berbuat jahat, dan setiap mulut berbicara bebal. Sekalipun semuanya ini terjadi, murka-Nya belum surut, dan tangan-Nya masih teracung.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 9, 18, '(9-17) Sebab kefasikan itu menyala seperti api yang memakan habis puteri malu dan rumput, lalu membakar belukar di hutan sehingga tonggak asap berkepul-kepul ke atas.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 9, 19, '(9-18) Oleh karena murka TUHAN semesta alam, terbakarlah tanah itu, dan bangsa itu menjadi makanan api; seorangpun tidak mengasihani saudaranya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 9, 20, '(9-19) Mereka mencakup ke sebelah kanan, tetapi masih lapar, mereka memakan ke sebelah kiri, tetapi tidak kenyang, setiap orang memakan daging temannya:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 9, 21, '(9-20) Manasye memakan Efraim, dan Efraim memakan Manasye, dan bersama-sama mereka melawan Yehuda. Sekalipun semuanya ini terjadi, murka-Nya belum surut, dan tangan-Nya masih teracung.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 1, 'Celakalah mereka yang menentukan ketetapan-ketetapan yang tidak adil, dan mereka yang mengeluarkan keputusan-keputusan kelaliman,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 2, 'untuk menghalang-halangi orang-orang lemah mendapat keadilan dan untuk merebut hak orang-orang sengsara di antara umat-Ku, supaya mereka dapat merampas milik janda-janda, dan dapat menjarah anak-anak yatim!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 3, 'Apakah yang akan kamu lakukan pada hari penghukuman, dan pada waktu kebinasaan yang datang dari jauh? Kepada siapakah kamu hendak lari minta tolong, dan di manakah hendak kamu tinggalkan kekayaanmu?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 4, 'Tak dapat kamu lakukan apa-apa selain dari meringkuk di antara orang-orang yang terkurung, dan tewas di antara orang-orang yang terbunuh! Sekalipun semuanya ini terjadi, murka TUHAN belum surut, dan tangan-Nya masih teracung.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 5, 'Celakalah Asyur, yang menjadi cambuk murka-Ku dan yang menjadi tongkat amarah-Ku!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 6, 'Aku akan menyuruhnya terhadap bangsa yang murtad, dan Aku akan memerintahkannya melawan umat sasaran murka-Ku, untuk melakukan perampasan dan penjarahan, dan untuk menginjak-injak mereka seperti lumpur di jalan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 7, 'Tetapi dia sendiri tidak demikian maksudnya dan tidak demikian rancangan hatinya, melainkan niat hatinya ialah hendak memunahkan dan hendak melenyapkan tidak sedikit bangsa-bangsa.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 8, 'Sebab ia berkata: "Bukankah panglima-panglimaku itu raja-raja semua?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 9, 'Bukankah Kalno sama halnya seperti Karkemis, atau bukankah Hamat seperti Arpad, atau Samaria seperti Damsyik?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 10, 'Seperti tanganku telah menyergap kerajaan-kerajaan para berhala, padahal patung-patung mereka melebihi yang di Yerusalem dan yang di Samaria,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 11, 'masakan tidak akan kulakukan kepada Yerusalem dan patung-patung berhalanya, seperti yang telah kulakukan kepada Samaria dan berhala-berhalanya?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 12, 'Tetapi apabila Tuhan telah menyelesaikan segala pekerjaan-Nya di gunung Sion dan di Yerusalem, maka Ia akan menghukum perbuatan ketinggian hati raja Asyur dan sikapnya yang angkuh sombong.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 13, 'Sebab ia telah berkata: "Dengan kekuatan tanganku aku telah melakukannya dan dengan kebijaksanaanku, sebab aku berakal budi; aku telah meniadakan batas-batas antara bangsa, dan telah merampok persediaan-persediaan mereka, dengan perkasa aku telah menurunkan orang-orang yang duduk di atas takhta.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 14, 'Seperti kepada sarang burung, demikianlah tanganku telah menjangkau kepada kekayaan bangsa-bangsa, dan seperti orang meraup telur-telur yang ditinggalkan induknya, demikianlah aku telah meraup seluruh bumi, dan tidak seekorpun yang menggerakkan sayap, yang mengangakan paruh atau yang menciap-ciap."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 15, 'Adakah kapak memegahkan diri terhadap orang yang memakainya, atau gergaji membesarkan diri terhadap orang yang mempergunakannya? seolah-olah gada menggerakkan orang yang mengangkatnya, dan seolah-olah tongkat mengangkat orangnya yang bukan kayu!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 16, 'Sebab itu Tuhan, TUHAN semesta alam, akan membuat orang-orangnya yang tegap menjadi kurus kering, dan segala kekayaannya akan dibakar habis, dengan api yang menyala-nyala.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 17, 'Maka Terang Israel akan menjadi api, dan Allahnya, Yang Mahakudus, akan menyala-nyala dan akan membakar dan memakan habis puteri malu dan rumputnya pada satu hari juga.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 18, 'Keindahan hutan Asyur dan kebun buah-buahannya akan dihabiskan-Nya, dari batangnya sampai rantingnya, sehingga akan menjadi seperti seorang sakit yang merana sampai mati;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 19, 'dan sisa pohon-pohon hutannya akan dapat dihitung banyaknya, sehingga seorang anak dapat mencatatnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 20, 'Tetapi pada waktu itu sisa orang Israel dan orang yang terluput di antara kaum keturunan Yakub, tidak akan bersandar lagi kepada yang mengalahkannya, tetapi akan bersandar kepada TUHAN, Yang Mahakudus, Allah Israel, dan tetap setia.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 21, 'Suatu sisa akan kembali, sisa Yakub akan bertobat di hadapan Allah yang perkasa.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 22, 'Sebab sekalipun bangsamu, hai Israel, seperti pasir di laut banyaknya, namun hanya sisanya akan kembali. TUHAN telah memastikan datangnya kebinasaan dan dari situ timbul keadilan yang meluap-luap.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 23, 'Sungguh, kebinasaan yang sudah pasti akan dilaksanakan di atas seluruh bumi oleh Tuhan, TUHAN semesta alam.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 24, 'Sebab itu beginilah firman Tuhan, TUHAN semesta alam: "Hai umat-Ku yang diam di Sion, janganlah takut terhadap Asyur, apabila mereka memukul engkau dengan gada dan menghantam engkau dengan tongkatnya, seperti yang dilakukan Mesir dahulu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 25, 'Sebab sedikit waktu lagi amarah-Ku atasmu akan berakhir, dan murka-Ku akan menyebabkan kehancuran mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 26, 'TUHAN semesta alam akan mencambuk mereka dengan cemeti, seperti Ia menghajar Midian di gunung batu Oreb, dan mengayunkan tongkat-Nya ke atas laut Teberau dan mengangkatnya seperti di Mesir dahulu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 27, 'Pada waktu itu beban yang ditimpakan mereka atas bahumu akan terbuang, dan kuk yang diletakkan mereka atas tengkukmu akan lenyap."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 28, '(10-27b) Asyur telah muncul dari Rimon (10-28) dan telah datang menyerang Ayat; ia telah lewat dari Migron, dan di Mikhmas diaturnya perbekalannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 29, 'Mereka telah menyeberang dari jurang penyeberangan, sambil berteriak: "Geba tempat permalaman kita!" Penduduk Rama gemetar, penghuni Gibea-Saul melarikan diri.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 30, 'Keluarkanlah jeritanmu, hai puteri Galim! Perhatikanlah, hai Laisya! Jawablah dia, hai Anatot!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 31, 'Penghuni Madmena lari jauh-jauh, penduduk Gebim pergi mengungsi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 32, 'Hari ini juga Asyur akan berhenti di Nob, mengacung-acungkan tangannya ke arah gunung puteri Sion, bukit Yerusalem.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 10, 33, 'Lihat, Tuhan, TUHAN semesta alam akan memotong dahan-dahan pohon dengan kekuatan yang menakutkan; yang tinggi-tinggi tumbuhnya akan ditebang, dan yang menjulang ke atas akan direndahkan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 11, 1, 'Suatu tunas akan keluar dari tunggul Isai, dan taruk yang akan tumbuh dari pangkalnya akan berbuah.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 11, 2, 'Roh TUHAN akan ada padanya, roh hikmat dan pengertian, roh nasihat dan keperkasaan, roh pengenalan dan takut akan TUHAN;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 11, 3, 'ya, kesenangannya ialah takut akan TUHAN. Ia tidak akan menghakimi dengan sekilas pandang saja atau menjatuhkan keputusan menurut kata orang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 11, 4, 'Tetapi ia akan menghakimi orang-orang lemah dengan keadilan, dan akan menjatuhkan keputusan terhadap orang-orang yang tertindas di negeri dengan kejujuran; ia akan menghajar bumi dengan perkataannya seperti dengan tongkat, dan dengan nafas mulutnya ia akan membunuh orang fasik.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 11, 5, 'Ia tidak akan menyimpang dari kebenaran dan kesetiaan, seperti ikat pinggang tetap terikat pada pinggang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 11, 6, 'Serigala akan tinggal bersama domba dan macan tutul akan berbaring di samping kambing. Anak lembu dan anak singa akan makan rumput bersama-sama, dan seorang anak kecil akan menggiringnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 11, 7, 'Lembu dan beruang akan sama-sama makan rumput dan anaknya akan sama-sama berbaring, sedang singa akan makan jerami seperti lembu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 11, 8, 'Anak yang menyusu akan bermain-main dekat liang ular tedung dan anak yang cerai susu akan mengulurkan tangannya ke sarang ular beludak.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 11, 9, 'Tidak ada yang akan berbuat jahat atau yang berlaku busuk di seluruh gunung-Ku yang kudus, sebab seluruh bumi penuh dengan pengenalan akan TUHAN, seperti air laut yang menutupi dasarnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 11, 10, 'Maka pada waktu itu taruk dari pangkal Isai akan berdiri sebagai panji-panji bagi bangsa-bangsa; dia akan dicari oleh suku-suku bangsa dan tempat kediamannya akan menjadi mulia.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 11, 11, 'Pada waktu itu Tuhan akan mengangkat pula tangan-Nya untuk menebus sisa-sisa umat-Nya yang tertinggal di Asyur dan di Mesir, di Patros, di Etiopia dan di Elam, di Sinear, di Hamat dan di pulau-pulau di laut.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 11, 12, 'Ia akan menaikkan suatu panji-panji bagi bangsa-bangsa, akan mengumpulkan orang-orang Israel yang terbuang, dan akan menghimpunkan orang-orang Yehuda yang terserak dari keempat penjuru bumi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 11, 13, 'Kecemburuan Efraim akan berlalu, dan yang menyesakkan Yehuda akan lenyap. Efraim tidak akan cemburu lagi kepada Yehuda, dan Yehuda tidak akan menyesakkan Efraim lagi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 11, 14, 'Tetapi mereka akan terbang ke barat, ke atas lereng gunung Filistin, bersama-sama mereka akan menjarah bani Timur; mereka akan merampas Edom dan Moab, dan orang Amon akan patuh kepada mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 11, 15, 'TUHAN akan mengeringkan teluk Mesir dengan nafas-Nya yang menghanguskan, serta mengacungkan tangan-Nya terhadap sungai Efrat dan memukulnya pecah menjadi tujuh batang air, sehingga orang dapat melaluinya dengan berkasut.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 11, 34, 'Belukar rimba akan ditebas dengan kapak, dan Libanon dengan pohon-pohonnya yang hebat akan jatuh.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 12, 1, 'Pada waktu itu engkau akan berkata: "Aku mau bersyukur kepada-Mu, ya TUHAN, karena sungguhpun Engkau telah murka terhadap aku: tetapi murka-Mu telah surut dan Engkau menghibur aku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 12, 2, 'Sungguh, Allah itu keselamatanku; aku percaya dengan tidak gementar, sebab TUHAN ALLAH itu kekuatanku dan mazmurku, Ia telah menjadi keselamatanku."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 12, 3, 'Maka kamu akan menimba air dengan kegirangan dari mata air keselamatan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 12, 4, 'Pada waktu itu kamu akan berkata: "Bersyukurlah kepada TUHAN, panggillah nama-Nya, beritahukanlah perbuatan-Nya di antara bangsa-bangsa, masyhurkanlah, bahwa nama-Nya tinggi luhur!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 12, 5, 'Bermazmurlah bagi TUHAN, sebab perbuatan-Nya mulia; baiklah hal ini diketahui di seluruh bumi!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 12, 6, 'Berserulah dan bersorak-sorailah, hai penduduk Sion, sebab Yang Mahakudus, Allah Israel, agung di tengah-tengahmu!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 12, 16, 'Maka akan ada jalan raya bagi sisa-sisa umat-Nya yang tertinggal di Asyur, seperti yang telah ada untuk Israel dahulu, pada waktu mereka keluar dari tanah Mesir.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 13, 1, 'Ucapan ilahi terhadap Babel yang dinyatakan kepada Yesaya bin Amos.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 13, 2, 'Naikkanlah panji-panji di atas gunung yang gundul, berserulah terhadap mereka dengan suara nyaring; lambaikanlah tangan supaya mereka masuk ke pintu-pintu gerbang para bangsawan!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 13, 3, 'Aku ini telah memerintahkan orang-orang yang Kukuduskan, telah memanggil orang-orang perkasa-Ku untuk melaksanakan hukuman murka-Ku, orang-orang-Ku yang beria-ria dan bangga.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 13, 4, 'Ada suara keramaian di atas gunung-gunung, seperti suara kumpulan orang yang besar jumlahnya! Suara kegaduhan dari kerajaan-kerajaan, dari bangsa-bangsa yang berkumpul! TUHAN semesta alam sedang memeriksa pasukan perang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 13, 5, 'Mereka datang dari negeri yang jauh, ya dari ujung langit, yaitu TUHAN serta yang melaksanakan amarah-Nya untuk merusakkan seluruh bumi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 13, 6, 'Merataplah, sebab hari TUHAN sudah dekat, datangnya sebagai pemusnahan dari Yang Mahakuasa.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 13, 7, 'Sebab itu semua tangan akan menjadi lemah lesu, setiap hati manusia akan menjadi tawar,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 13, 8, 'dan mereka akan terkejut. Sakit mulas dan sakit beranak akan menyerang mereka, mereka akan menggeliat kesakitan seperti perempuan yang melahirkan. Mereka akan berpandang-pandangan dengan tercengang-cengang, muka mereka seperti orang yang demam.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 13, 9, 'Sungguh, hari TUHAN datang dengan kebengisan, dengan gemas dan dengan murka yang menyala-nyala, untuk membuat bumi menjadi sunyi sepi dan untuk memunahkan dari padanya orang-orang yang berdosa.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 13, 10, 'Sebab bintang-bintang dan gugusan-gugusannya di langit tidak akan memancarkan cahayanya; matahari akan menjadi gelap pada waktu terbit, dan bulan tidak akan memancarkan sinarnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 13, 11, 'Kepada dunia akan Kubalaskan kejahatannya, dan kepada orang-orang fasik kesalahan mereka; kesombongan orang-orang pemberani akan Kuhentikan, dan kecongkakan orang-orang yang gagah akan Kupatahkan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 13, 12, 'Aku akan membuat orang lebih jarang dari pada emas tua, dan manusia lebih jarang dari pada emas Ofir.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 13, 13, 'Sebab itu Aku akan membuat langit gemetar, dan bumipun akan bergoncang dari tempatnya, pada waktu amarah TUHAN semesta alam, dan pada hari murka-Nya yang menyala-nyala.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 13, 14, 'Seperti kijang yang dikejar-kejar dan seperti domba yang tidak digembalakan, demikianlah mereka akan berpaling, masing-masing kepada bangsanya, dan melarikan diri, masing-masing ke negerinya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 13, 15, 'Setiap orang yang didapati akan ditikam, dan setiap orang yang tertangkap akan rebah mati oleh pedang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 13, 16, 'Bayi-bayi mereka akan diremukkan di depan mata mereka, rumah-rumah mereka akan dirampoki, dan isteri-isteri mereka akan ditiduri.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 13, 17, 'Lihat, Aku menggerakkan orang Madai melawan mereka, orang-orang yang tidak menghiraukan perak dan tidak suka kepada emas.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 13, 18, 'Panah-panah mereka akan menembus orang-orang muda; mereka tidak akan sayang kepada buah kandungan, dan mereka tidak menaruh kasihan kepada anak-anak.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 13, 19, 'Dan Babel, yang permai di antara kerajaan-kerajaan, perhiasan orang Kasdim yang megah, akan sama seperti Sodom dan Gomora pada waktu Allah menunggangbalikkannya:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 13, 20, 'tidak ada penduduk untuk seterusnya, dan tidak ada penghuni turun-temurun; orang Arab tidak akan berkemah di sana, dan gembala-gembala tidak akan membiarkan hewannya berbaring di sana;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 13, 21, 'tetapi yang akan berbaring di sana ialah binatang gurun, dan rumah-rumah mereka akan penuh dengan burung hantu; burung-burung unta akan diam di sana, dan jin-jin akan melompat-lompat;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 13, 22, 'anjing-anjing hutan akan menyalak di dalam puri-purinya, dan serigala-serigala di dalam istana-istana kesenangan. Waktunya akan datang segera, dan usianya tidak akan diperpanjang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 1, 'Sebab TUHAN akan menyayangi Yakub dan akan memilih Israel sekali lagi dan akan membiarkan mereka tinggal di tanah mereka, maka orang asing akan menggabungkan diri kepada mereka dan akan berpadu dengan kaum keturunan Yakub.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 2, 'Bangsa-bangsa lain akan mengantar Israel pulang ke tempatnya, lalu kaum Israel akan memiliki bangsa-bangsa itu di tanah TUHAN sebagai hamba-hamba lelaki dan hamba-hamba perempuan. Demikianlah mereka akan menawan orang-orang yang menawan mereka dan akan berkuasa atas para penindas mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 3, 'Maka pada hari TUHAN mengakhiri kesakitan dan kegelisahanmu dan kerja paksa yang berat yang dipaksakan kepadamu,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 4, 'maka engkau akan memperdengarkan ejekan ini tentang raja Babel, dan berkata: "Wah, sudah berakhir si penindas sudah berakhir orang lalim!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 5, 'TUHAN telah mematahkan tongkat orang-orang fasik, gada orang-orang yang memerintah,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 6, 'yang memukul bangsa-bangsa dengan gemas, dengan pukulan yang tidak putus-putusnya; yang menginjak-injak bangsa-bangsa dalam murka dengan tiada henti-hentinya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 7, 'Segenap bumi sudah aman dan tenteram; orang bergembira dengan sorak-sorai.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 8, 'Juga pohon-pohon sanobar dan pohon-pohon aras di Libanon bersukacita karena kejatuhanmu, katanya: ?Dari sejak engkau rebah terbaring, tidak ada lagi orang yang naik untuk menebang kami!?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 9, 'Dunia orang mati yang di bawah gemetar untuk menyongsong kedatanganmu, dijagakannya arwah-arwah bagimu, yaitu semua bekas pemimpin di bumi; semua bekas raja bangsa-bangsa dibangunkannya dari takhta mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 10, 'Sekaliannya mereka mulai berbicara dan berkata kepadamu: ?Engkau juga telah menjadi lemah seperti kami, sudah menjadi sama seperti kami!?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 11, 'Ke dunia orang mati sudah diturunkan kemegahanmu dan bunyi gambus-gambusmu; ulat-ulat dibentangkan sebagai lapik tidurmu, dan cacing-cacing sebagai selimutmu."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 12, '"Wah, engkau sudah jatuh dari langit, hai Bintang Timur, putera Fajar, engkau sudah dipecahkan dan jatuh ke bumi, hai yang mengalahkan bangsa-bangsa!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 13, 'Engkau yang tadinya berkata dalam hatimu: Aku hendak naik ke langit, aku hendak mendirikan takhtaku mengatasi bintang-bintang Allah, dan aku hendak duduk di atas bukit pertemuan, jauh di sebelah utara.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 14, 'Aku hendak naik mengatasi ketinggian awan-awan, hendak menyamai Yang Mahatinggi!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 15, 'Sebaliknya, ke dalam dunia orang mati engkau diturunkan, ke tempat yang paling dalam di liang kubur.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 16, 'Orang-orang yang melihat engkau akan memperhatikan dan mengamat-amati engkau, katanya: Inikah dia yang telah membuat bumi gemetar, dan yang telah membuat kerajaan-kerajaan bergoncang,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 17, 'yang telah membuat dunia seperti padang gurun, dan menghancurkan kota-kotanya, yang tidak melepaskan orang-orangnya yang terkurung pulang ke rumah?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 18, 'Semua bekas raja bangsa-bangsa berbaring dalam kemuliaan, masing-masing dalam rumah kuburnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 19, 'Tetapi engkau ini telah terlempar, jauh dari kuburmu, seperti taruk yang jijik, ditutupi dengan mayat orang-orang yang tertikam oleh pedang dan jatuh tercampak ke batu-batu liang kubur seperti bangkai yang terinjak-injak.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 20, 'Engkau tidak akan bersama-sama dengan raja-raja itu di dalam kubur, sebab engkau telah merusak negerimu dan membunuh rakyatmu. Anak cucu orang yang berbuat jahat tidak akan disebut-sebut untuk selama-lamanya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 21, 'Dirikanlah bagi anak-anaknya tempat pembantaian, oleh karena kesalahan nenek moyang mereka, supaya mereka jangan bangun dan menduduki bumi dan memenuhi dunia dengan kota-kota."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 22, '"Aku akan bangkit melawan mereka," demikianlah firman TUHAN semesta alam, "Aku akan melenyapkan nama Babel dan sisanya, anak cucu dan anak cicitnya," demikianlah firman TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 23, '"Aku akan membuat Babel menjadi milik landak dan menjadi air rawa-rawa, dan kota itu akan Kusapu bersih dan Kupunahkan," demikianlah firman TUHAN semesta alam.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 24, 'TUHAN semesta alam telah bersumpah, firman-Nya: "Sesungguhnya seperti yang Kumaksud, demikianlah akan terjadi, dan seperti yang Kurancang, demikianlah akan terlaksana:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 25, 'Aku akan membinasakan orang Asyur dalam negeri-Ku dan menginjak-injak mereka di atas gunung-Ku; kuk yang diletakkan mereka atas umat-Ku akan terbuang dan demikian juga beban yang ditimpakan mereka atas bahunya."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 26, 'Itulah rancangan yang telah dibuat mengenai seluruh bumi, dan itulah tangan yang teracung terhadap segala bangsa.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 27, 'TUHAN semesta alam telah merancang, siapakah yang dapat menggagalkannya? Tangan-Nya telah teracung, siapakah yang dapat membuatnya ditarik kembali?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 28, 'Dalam tahun matinya raja Ahas datanglah ucapan ilahi ini:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 29, 'Janganlah bersukaria, hai segenap Filistea, karena walaupun gada orang yang memukul engkau sudah patah, tetapi dari keturunan ular itu akan keluar ular beludak, dan anaknya akan menjadi ular naga terbang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 30, 'Yang paling hina dari umat-Ku akan mendapat makanan dan orang-orang miskin akan diam dengan tenteram, tetapi keturunanmu akan Kumatikan dengan kelaparan, dan sisa-sisamu akan Kubunuh.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 31, 'Merataplah, hai pintu gerbang! Berteriaklah, hai kota! Gemetarlah, hai segenap Filistea! Sebab di sebelah utara sudah mengepul asap perang, dan barisan musuh maju tanpa ada yang mundur.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 14, 32, 'Dan apakah jawab yang akan diberi kepada utusan-utusan bangsa itu? "TUHAN yang meletakkan dasar Sion, dan di sanalah orang-orang yang sengsara dari umat-Nya mendapat perlindungan."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 15, 1, 'Ucapan ilahi tentang Moab. Sungguh, dalam suatu malam Ar-Moab sudah dirusakkan, dibinasakan; sungguh, dalam suatu malam Kir-Moab sudah dirusakkan, dibinasakan!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 15, 2, 'Puteri Dibon naik ke bukit-bukit pengorbanan untuk menangis; Moab meratap karena Nebo dan karena Medeba. Di situ semua orang menggundul kepalanya dan memotong janggutnya sebagai tanda berkabung.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 15, 3, 'Di jalan-jalan orang berlilitkan kain kabung, di atas sotoh dan di tanah-tanah lapang sekaliannya meratap, sedang air mata bercucuran.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 15, 4, 'Hesybon dan Eleale meraung-raung, suara mereka kedengaran sampai ke Yahas. Sebab itu orang-orang bersenjata di Moab berseru-seru, jiwanyapun gemetar.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 15, 5, 'Aku berteriak karena Moab, pengungsi-pengungsi sudah sampai ke Zoar, ke Eglat-Selisia. Sungguh, orang mendaki pendakian Luhit sambil menangis; dan di jalan ke Horonaim orang berteriak karena ditimpa bencana.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 15, 6, 'Sungguh, air di Nimrim menjadi kering dan tandus dan rumput sudah kering, rumput muda sudah habis, tidak ada lagi tumbuh-tumbuhan hijau.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 15, 7, 'Sebab itu segala harta yang mereka tumpuk dan segala yang mereka simpan mereka bawa ke seberang sungai Haarabim.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 15, 8, 'Sungguh, teriak itu akan kedengaran di seluruh daerah Moab, ratapnya terdengar sampai ke Eglaim, bahkan sampai ke Beer-Elim.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 15, 9, 'Sungguh, air Dibon telah penuh dengan darah, tetapi yang menimpa Dibon akan Kutambah lagi, yaitu singa akan menerkam orang-orang yang terluput dari Moab dan yang tersisa di tanah itu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 16, 1, 'Mereka mengirim anak domba kepada pemerintah negeri, dari Sela melalui padang gurun ke gunung puteri Sion.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 16, 2, 'Seperti burung yang lari terbang, dan isi sarang yang diusir, demikianlah anak-anak perempuan Moab di tempat-tempat penyeberangan sungai Arnon.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 16, 3, '"Berilah nasihat, pertahankanlah hak, jadilah naungan yang teduh di waktu rembang tengah hari; sembunyikanlah orang-orang yang terbuang, janganlah khianati orang-orang pelarian!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 16, 4, 'Biarkanlah orang-orang yang terbuang dari Moab menumpang padamu, jadilah tempat persembunyian baginya terhadap si pembinasa! Apabila penggagahan sudah berakhir, pembinasaan sudah lewat dan orang lalim sudah habis lenyap dari negeri,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 16, 5, 'maka suatu takhta akan ditegakkan dalam kasih setia dan di atasnya, dalam kemah Daud, akan duduk senantiasa seorang hakim yang menegakkan keadilan, dan yang segera melakukan kebenaran."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 16, 6, 'Kami telah mendengar tentang keangkuhan Moab, alangkah angkuhnya dia, tentang kecongkakannya, keangkuhannya dan kegemasannya, dan tentang cakap anginnya yang tidak benar.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 16, 7, 'Sebab itu biarlah orang Moab meratap, seorang karena yang lain, biarlah sekaliannya meratap. Mengingat kue kismis Kir-Hareset biarlah mereka mengaduh dan hancur luluh sama sekali!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 16, 8, 'Sebab kebun-kebun Hesybon dan pohon anggur Sibma telah merana; para penguasa bangsa-bangsa telah memotong pohon-pohon anggurnya yang terbaik, yang dahulu meluas sampai ke Yaezer dan merambat ke padang gurun; ranting-rantingnya berserak sampai ke seberang laut.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 16, 9, 'Sebab itu aku turut menangis dengan Yaezer karena pohon anggur Sibma; aku mau membasahi engkau dengan air mataku, hai Hesybon dan Eleale, sebab pada musim kemarau tepat waktu panen musuhmu menyerbu dengan pekik pertempuran.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 16, 10, 'Telah lenyap sukaria dan sorak-sorak dari kebun buah-buahan; telah menghilang dari kebun-kebun anggur tempik sorak dan sorak-sorai; tiada pengirik anggur di tempat pemerasan, pekik mereka sudah berhenti.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 16, 11, 'Oleh karena itu, seperti kecapi mendengking, begitulah hatiku menjerit melihat keadaan Moab, dan batinku tergerak melihat keadaan Kir-Heres.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 16, 12, 'Maka sekalipun Moab pergi beribadah dan bersusah payah di atas bukit pengorbanan dan masuk ke tempat kudusnya untuk berdoa, ia tidak akan mencapai apa-apa.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 16, 13, 'Itulah firman yang diucapkan TUHAN tentang Moab pada waktu yang lalu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 16, 14, 'Maka sekarang TUHAN berfirman: "Dalam tiga tahun, menurut masa kerja prajurit upahan, maka kemuliaan Moab, serta dengan keramaiannya yang besar, akan menjadi kehinaan, dan orang yang tertinggal akan sangat sedikit dan tiada berkuasa."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 17, 1, 'Ucapan ilahi terhadap Damsyik. Sesungguhnya, Damsyik tidak akan tetap sebagai kota, nanti menjadi suatu timbunan reruntuhan;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 17, 2, 'kampung-kampungnya akan ditinggalkan selama-lamanya dan menjadi tempat bagi kawanan-kawanan ternak, yang berbaring dengan tidak diganggu oleh siapapun.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 17, 3, 'Kubu-kubu akan hilang dari Efraim dan kuasa kerajaan akan lenyap dari Damsyik, juga sisa-sisa Aram, semuanya akan lenyap sama seperti kemuliaan orang Israel, demikianlah firman TUHAN semesta alam.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 17, 4, 'Maka pada waktu itu kemuliaan Yakub akan berkurang, dan kemakmurannya akan susut;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 17, 5, 'keadaannya seperti gandum yang digenggam orang untuk dituai dan tangannya memetik bulir-bulir; atau seperti bulir-bulir yang dipungut orang di lembah orang Refaim.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 17, 6, 'Dari padanya akan tertinggal sisa untuk pemetikan susulan seperti pada waktu orang menjolok buah zaitun, tertinggal satu dua di sebelah pucuknya dan beberapa di dahan-dahannya, demikianlah firman TUHAN, Allah Israel.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 17, 7, 'Pada waktu itu manusia akan memandang kepada Dia yang menjadikannya, dan matanya akan melihat kepada Yang Mahakudus, Allah Israel;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 17, 8, 'ia tidak akan memandang kepada mezbah-mezbah buatan tangannya sendiri, dan tidak akan melihat kepada yang dikerjakan oleh tangannya, yakni tiang-tiang berhala dan pedupaan-pedupaan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 17, 9, 'Pada waktu itu kota-kotamu akan ditinggalkan seperti kota-kota orang Hewi dan orang Amori yang mereka tinggalkan karena orang Israel, sehingga menjadi sunyi sepi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 17, 10, 'Sebab engkau telah melupakan Allah yang menyelamatkan engkau, dan tidak mengingat gunung batu kekuatanmu. Sebab itu sekalipun engkau membuat taman yang permai dan menanaminya dengan cangkokan luar negeri,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 17, 11, 'sekalipun pada hari menanamnya engkau membuatnya tumbuh subur, dan pada pagi mencangkokkannya engkau membuatnya berbunga, namun panen akan segera lenyap pada hari kesakitan dan hari penderitaan yang sangat payah.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 17, 12, 'Wahai! Ributnya banyak bangsa-bangsa, mereka ribut seperti ombak laut menderu! Gaduhnya suku-suku bangsa, mereka gaduh seperti gaduhnya air yang hebat!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 17, 13, 'Suku-suku bangsa gaduh seperti gaduhnya air yang besar; tetapi TUHAN menghardiknya, sehingga mereka lari jauh-jauh, terburu-buru seperti sekam di tempat penumbukan dihembus angin, dan seperti dedak ditiup puting beliung.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 17, 14, 'Menjelang waktu senja, sesungguhnya ada kedahsyatan! Sebelum hari pagi, mereka sudah tidak ada lagi! Itulah bagian orang-orang yang merampoki kita, dan itulah yang ditentukan bagi orang-orang yang merampasi kita.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 18, 1, 'Wahai! Negeri dengingan sayap di seberang sungai-sungai Etiopia,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 18, 2, 'yang mengirim duta-duta melalui laut dalam perahu-perahu pandan mengarungi permukaan air! Pergilah, hai utusan-utusan yang tangkas, kepada bangsa yang jangkung dan berkulit mengkilap, kepada kaum yang ditakuti dekat dan jauh, yakni bangsa yang berkekuatan ulet dan lalim, yang negerinya dilintasi sungai-sungai!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 18, 3, 'Hai semua penduduk dunia, hai orang-orang yang mendiami bumi! Apabila panji-panji dinaikkan di gunung-gunung, lihatlah; apabila sangkakala ditiup, dengarlah!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 18, 4, 'Sebab beginilah firman TUHAN kepadaku: "Aku akan menjenguk dari tempat kediaman-Ku dengan tidak bergerak, seperti hawa panas yang mendidih waktu panas terik, seperti kabut embun di panas musim menuai."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 18, 5, 'Sebab sebelum musim buah, apabila waktu berbunga sudah berakhir, dan gugusan putik menjadi buah anggur yang hendak masak, maka TUHAN akan mengerat ranting-rantingnya dengan pisau pemangkas, dan menyisihkan carang-carangnya dengan memancungnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 18, 6, 'Semuanya itu akan ditinggalkan bertumpuk-tumpuk bagi burung-burung buas di pegunungan, dan bagi binatang-binatang di hutan. Pada musim panas burung-burung buas akan bermukim di situ dan segala binatang hutan pada musim dingin.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 18, 7, 'Pada waktu itu juga persembahan akan disampaikan kepada TUHAN semesta alam dari kaum yang jangkung dan berkulit mengkilap, dan dari kaum yang ditakuti dekat dan jauh, yakni bangsa yang berkekuatan ulet dan lalim, yang negerinya dilintasi sungai-sungai, ke tempat nama TUHAN semesta alam, yaitu gunung Sion.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 1, 'Ucapan ilahi terhadap Mesir. Lihat, TUHAN mengendarai awan yang cepat dan datang ke Mesir, maka berhala-berhala Mesir gemetar di hadapan-Nya, dan hati orang Mesir, merana hancur dalam diri mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 2, 'Aku akan menggerakkan orang Mesir melawan orang Mesir, supaya mereka berperang, setiap orang melawan saudaranya, dan setiap orang melawan temannya, kota melawan kota, kerajaan melawan kerajaan;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 3, 'semangat orang Mesir menjadi hilang, dan rancangannya akan Kukacaukan; maka mereka akan meminta petunjuk kepada berhala-berhala dan kepada tukang-tukang jampi, kepada arwah dan kepada roh-roh peramal.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 4, 'Aku akan menyerahkan orang Mesir ke dalam tangan seorang tuan yang kejam, dan seorang raja yang bengis akan memerintah mereka; demikianlah firman Tuhan, TUHAN semesta alam.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 5, 'Air dari sungai Nil akan habis, dan sungai itu akan menjadi tohor dan kering,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 6, 'sehingga terusan-terusan akan berbau busuk, dan anak-anak sungai Nil akan menjadi dangkal dan tohor, gelagah dan teberau akan mati rebah.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 7, 'Rumput di tepi sungai Nil dan seluruh tanah pesemaian pada sungai Nil akan menjadi kering ditiup angin dan tidak ada lagi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 8, 'Para nelayan akan mengaduh dan berkabung, yaitu semua orang yang memancing di sungai Nil; semua orang yang menjala di situ akan merana juga.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 9, 'Orang-orang yang mengolah lenan akan mendapat malu, demikian juga tukang-tukang tenun kain putih.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 10, 'Mereka yang menenun akan remuk hatinya, segala pekerja upahan akan bersedih hati.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 11, 'Para pembesar Zoan adalah orang-orang bodoh belaka; para penasihat Firaun yang paling bijaksana memberi nasihat yang dungu. Bagaimanakah kamu dapat berkata kepada Firaun: "Aku ini anak orang-orang bijaksana, anak raja-raja zaman purbakala?"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 12, 'Di manakah orang-orang bijaksanamu? Biarlah mereka mengumumkan kepadamu serta memberitahukan apa yang diputuskan TUHAN semesta alam tentang Mesir.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 13, 'Para pembesar Zoan bertindak tolol, para pembesar Memfis sudah teperdaya; para pemuka suku-suku mereka telah memusingkan Mesir.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 14, 'TUHAN telah mencurahkan di antara mereka suatu roh kekacauan, dan mereka memusingkan Mesir dalam segala usahanya, sehingga seperti seorang mabuk yang pusing waktu muntah-muntah.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 15, 'Dan tidak ada usaha Mesir yang akan berhasil yang dilakukan oleh pemimpin dan pengikut, oleh pemuka dan orang biasa.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 16, 'Pada waktu itu orang-orang Mesir akan seperti orang-orang perempuan; mereka akan gemetar dan terkejut terhadap tangan TUHAN semesta alam yang diacungkan-Nya kepada mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 17, 'Maka tanah Yehuda akan menimbulkan kegemparan di antara orang Mesir, dan siapapun yang teringat kepadanya akan terkejut mendengar keputusan TUHAN semesta alam yang diambil-Nya mengenai mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 18, 'Pada waktu itu akan ada lima kota di tanah Mesir yang berbicara bahasa Kanaan dan yang bersumpah demi TUHAN semesta alam. Satu di antaranya akan disebutkan Ir-Heres.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 19, 'Pada waktu itu akan ada mezbah bagi TUHAN di tengah-tengah tanah Mesir dan tugu peringatan bagi TUHAN pada perbatasannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 20, 'Itu akan menjadi tanda kesaksian bagi TUHAN semesta alam di tanah Mesir: apabila mereka berseru kepada TUHAN oleh karena orang-orang penindas, maka Ia akan mengirim seorang juruselamat kepada mereka, yang akan berjuang dan akan melepaskan mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 21, 'TUHAN akan menyatakan diri kepada orang Mesir, dan orang Mesir akan mengenal TUHAN pada waktu itu; mereka akan beribadah dengan korban sembelihan dan korban sajian, dan mereka akan bernazar kepada TUHAN serta membayar nazar itu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 22, 'TUHAN akan menghajar orang Mesir, akan menghajar dan menyembuhkan; dan mereka akan berbalik kepada TUHAN dan Ia akan mengabulkan doa mereka serta menyembuhkan mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 23, 'Pada waktu itu akan ada jalan raya dari Mesir ke Asyur, sehingga orang Asyur dapat masuk ke Mesir dan orang Mesir ke Asyur, dan Mesir akan beribadah bersama-sama Asyur.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 24, 'Pada waktu itu Israel akan menjadi yang ketiga di samping Mesir dan di samping Asyur, suatu berkat di atas bumi,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 19, 25, 'yang diberkati oleh TUHAN semesta alam dengan berfirman: "Diberkatilah Mesir, umat-Ku, dan Asyur, buatan tangan-Ku, dan Israel, milik pusaka-Ku."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 20, 1, 'Pada tahun ketika panglima yang dikirim oleh Sargon, raja Asyur, tiba di Asdod lalu memerangi dan merebutnya,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 20, 2, 'pada waktu itu berfirmanlah TUHAN melalui Yesaya bin Amos. Firman-Nya: "Pergilah dan bukalah kain kabung dari pinggangmu dan tanggalkanlah kasut dari kakimu," lalu iapun berbuat demikian, maka berjalanlah ia telanjang dan tidak berkasut.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 20, 3, 'Berfirmanlah TUHAN: "Seperti hamba-Ku Yesaya berjalan telanjang dan tidak berkasut tiga tahun lamanya sebagai tanda dan alamat terhadap Mesir dan terhadap Etiopia,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 20, 4, 'demikianlah raja Asyur akan menggiring orang Mesir sebagai tawanan dan orang Etiopia sebagai buangan, tua dan muda, telanjang dan tidak berkasut dengan pantatnya kelihatan, suatu penghinaan bagi Mesir.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 20, 5, 'Maka orang akan terkejut dan malu karena Etiopia, pokok pengharapan mereka, dan karena Mesir, kebanggaan mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 20, 6, 'Dan penduduk tanah pesisir ini akan berkata pada waktu itu: Lihat, beginilah nasib orang-orang yang kami harapkan, kepada siapa kami melarikan diri minta pertolongan supaya diselamatkan dari raja Asyur. Bagaimana mungkin kami terluput?"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 21, 1, 'Ucapan ilahi terhadap "padang gurun di tepi laut". Seperti puting beliung mendesing lewat di Tanah Negeb, demikianlah datangnya dari padang gurun, dari negeri yang dahsyat.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 21, 2, 'Suatu penglihatan yang kejam telah diberitakan kepadaku: "Penggarong menggarong, perusak merusak! Majulah, hai Elam, kepunglah, hai Madai! Aku hentikan semua keluh yang ditimbulkannya."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 21, 3, 'Sebab itu pinggangku amat sakit, sakit mulas menimpa aku seperti sakit mulas perempuan yang melahirkan; aku terbungkuk-bungkuk, tidak mendengar lagi, aku terkejut, tidak melihat lagi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 21, 4, 'Hatiku gelisah, kekejutan meliputi aku, malam hari yang selalu kurindukan itu sekarang menggentarkan aku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 21, 5, 'Orang sibuk menyajikan hidangan, mengatur tempat-tempat duduk, makan, minum?Tiba-tiba kedengaran: "Hai para panglima! Siaplah tempur, minyakilah perisai!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 21, 6, 'Sebab beginilah firman Tuhan kepadaku: "Pergilah, tempatkanlah seorang peninjau, apa yang dilihatnya haruslah diberitahukannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 21, 7, 'Apabila dilihatnya pasukan, pasang-pasangan orang berkuda, pasukan keledai, pasukan unta, maka haruslah diperhatikannya sungguh-sungguh, dengan penuh perhatian."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 21, 8, 'Kemudian berserulah orang yang melihat itu: "Di tempat peninjauan, ya tuanku, aku berdiri senantiasa sehari suntuk, dan di tempat pengawalanku aku terpancang setiap malam."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 21, 9, 'Lihat, itu sudah datang sepasukan orang, pasang-pasangan orang berkuda! Lalu berserulah ia, katanya: "Sudah jatuh, sudah jatuh Babel, dan segala patung berhalanya telah diremukkan dan bertaburan di tanah."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 21, 10, 'Hai bangsaku yang telah dipijak-pijak dan diinjak-injak! Apa yang kudengar dari TUHAN semesta alam, Allah Israel, telah kuberitahukan kepadamu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 21, 11, 'Ucapan ilahi terhadap Duma. Ada seorang berseru kepadaku dari Seir: "Hai pengawal, masih lama malam ini? Hai pengawal, masih lama malam ini?"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 21, 12, 'Pengawal itu berkata: "Pagi akan datang, tetapi malam juga. Jika kamu mau bertanya, datanglah bertanya sekali lagi!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 21, 13, 'Ucapan ilahi terhadap Arabia. Di belukar di Arabia kamu akan bermalam, hai kafilah-kafilah orang Dedan!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 21, 14, 'Hai penduduk tanah Tema, keluarlah, bawalah air kepada orang yang haus, pergilah, sambutlah orang pelarian dengan roti!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 21, 15, 'Sebab mereka melarikan diri terhadap pedang, ya terhadap pedang yang terhunus, terhadap busur yang dilentur, dan terhadap kehebatan peperangan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 21, 16, 'Sebab beginilah firman Tuhan kepadaku: "Dalam setahun lagi, menurut masa kerja prajurit upahan, maka segala kemuliaan Kedar akan habis.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 21, 17, 'Dan dari pemanah-pemanah yang gagah perkasa dari bani Kedar, akan tinggal sejumlah kecil saja, sebab TUHAN, Allah Israel, telah mengatakannya."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 1, 'Ucapan ilahi terhadap "lembah penglihatan". Ada apa gerangan, maka semua pendudukmu naik ke sotoh-sotoh rumah,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 2, 'hai kota yang bersorak riuh dan ribut gembira, hai negeri yang beria-ria? Orang-orangmu yang mati terbunuh bukanlah terbunuh oleh pedang, dan bukanlah gugur dalam peperangan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 3, 'Semua panglimamu sama-sama melarikan diri, mereka tertawan tanpa tembakan panah; semua orang-orang kuatmu sama-sama tertawan, biarpun mereka sudah lari jauh-jauh.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 4, 'Sebab itu aku berkata: "Buanglah mukamu terhadap aku, biarkanlah aku menangis dalam kepahitan; janganlah mendesak aku, supaya aku terhibur mengenai kebinasaan puteri bangsaku."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 5, 'Sebab Tuhan, TUHAN semesta alam telah menentukan suatu hari: Ia akan menggemparkan, menginjak-injak dan mengacaukan orang: di "lembah penglihatan" tembok akan dirombak dan teriakan minta tolong sampai ke puncak gunung!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 6, 'Elam telah memasang tabung panah, Aram datang dengan pasukan berkereta dan berkuda, dan Kir membuka sarung perisai.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 7, 'Maka lembah-lembahmu yang paling indah penuh dengan kereta, dan pasukan berkuda berbaris di hadapan pintu gerbang,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 8, 'dan Yehuda kehilangan perlindungan. Pada waktu itu engkau memandang kepada perlengkapan senjata di "Gedung Hutan";', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 9, 'kamu melihat bahwa memang sudah banyak sekali retak-retak tembok kota Daud dan kamu mengumpulkan air kolam bawah;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 10, 'kamu menghitung rumah-rumah di Yerusalem, dan kamu merobohkan rumah-rumah untuk meneguhkan tembok;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 11, 'kamu membuat tempat pengumpulan air di antara kedua tembok itu untuk menampung air dari kolam yang lama; tetapi kamu tidak memandang kepada Dia yang membuatnya, dan tidak melihat kepada Dia yang telah sejak dahulu membentuknya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 12, 'Pada waktu itu Tuhan, TUHAN semesta alam menyuruh orang menangis dan meratap dengan menggundul kepala dan melilitkan kain kabung;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 13, 'tetapi lihat, di tengah-tengah mereka ada kegirangan dan sukacita, membantai lembu dan menyembelih domba, makan daging dan minum anggur, sambil berseru: "Marilah kita makan dan minum, sebab besok kita mati!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 14, 'Tetapi TUHAN semesta alam menyatakan diri dan berfirman kepadaku: "Sungguh, kesalahanmu ini tidak akan diampuni, sampai kamu mati," firman Tuhan, TUHAN semesta alam.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 15, 'Beginilah firman Tuhan, TUHAN semesta alam: "Mari, pergilah kepada kepala istana ini, kepada Sebna yang mengurus istana, dan katakan:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 16, 'Ada apamu dan siapamu di sini, maka engkau menggali kubur bagimu di sini, hai yang menggali kuburnya di tempat tinggi, yang memahat kediaman baginya di bukit batu?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 17, 'Sesungguhnya, TUHAN akan melontarkan engkau jauh-jauh, hai orang! Ia akan memegang engkau dengan kuat-kuat', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 18, 'dan menggulung engkau keras-keras menjadi suatu gulungan dan menggulingkan engkau seperti bola ke tanah yang luas; di situlah engkau akan mati, dan di situlah akan tinggal kereta-kereta kemuliaanmu, hai engkau yang memalukan keluarga tuanmu!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 19, 'Aku akan melemparkan engkau dari jabatanmu, dan dari pangkatmu engkau akan dijatuhkan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 20, 'Maka pada waktu itu Aku akan memanggil hamba-Ku, Elyakim bin Hilkia:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 21, 'Aku akan mengenakan jubahmu kepadanya dan ikat pinggangmu akan Kuikatkan kepadanya, dan kekuasaanmu akan Kuberikan ke tangannya; maka ia akan menjadi bapa bagi penduduk Yerusalem dan bagi kaum Yehuda.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 22, 'Aku akan menaruh kunci rumah Daud ke atas bahunya: apabila ia membuka, tidak ada yang dapat menutup; apabila ia menutup, tidak ada yang dapat membuka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 23, 'Aku akan memberikan dia kedudukan yang teguh seperti gantungan yang dipasang kuat-kuat pada tembok yang kokoh; maka ia akan menjadi kursi kemuliaan bagi kaum keluarganya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 24, 'Dan padanya akan digantungkan segala tanggungan kaum keluarganya, tunas dan taruk, beserta segala perkakas yang kecil, dari piring pasu sampai periuk belanga.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 22, 25, 'Maka pada waktu itu, demikianlah firman TUHAN semesta alam, gantungan yang dipasang kuat-kuat pada tempat yang kokoh itu tidak akan kuat lagi, sehingga patah dan jatuh, dan segala tanggungannya itu hancur, sebab TUHAN telah mengatakannya."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 23, 1, 'Ucapan ilahi tentang Tirus. Merataplah, hai kapal-kapal Tarsis, sebab Tirus sudah rusak, tiada lagi rumahmu atau pangkalanmu! Ketika mereka masih di negeri orang Kitim telah dinyatakan hal itu kepada mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 23, 2, 'Berdiam dirilah, hai penduduk tanah pesisir, hai saudagar Sidon, suruhan-suruhanmu mengarungi laut, dan berlayar di samudera besar;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 23, 3, 'barang-barang yang dimasukkan ke Sidon ialah gandum dari Sihor, dan panen daerah Nil, sehingga kota itu menjadi pasar bagi bangsa-bangsa.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 23, 4, 'Tahulah malu hai Sidon, sebab laut, benteng laut, berbicara, katanya: "Aku tidak pernah menggeliat sakit dan tidak melahirkan, aku tidak pernah membesarkan anak-anak teruna, dan tidak mengasuh anak-anak dara."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 23, 5, 'Apabila kabar tentang Tirus itu sampai ke Mesir, mereka akan gemetar mendengarnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 23, 6, 'Mengungsilah ke Tarsis, merataplah, hai penduduk tanah pesisir!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 23, 7, 'Inikah kotamu yang beria-ria, yang asalnya dari zaman purbakala? Orangnya telah melawat ke tempat yang jauh untuk merantau ke sana.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 23, 8, 'Siapakah yang memutuskan ini atas Tirus, kota yang pernah menghadiahkan mahkota, yang saudagar-saudagarnya pembesar-pembesar dan pedagang-pedagangnya orang-orang mulia di bumi?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 23, 9, 'TUHAN semesta alam yang telah memutuskannya untuk mematahkan kesombongan, untuk menghinakan segala yang permai dan semua orang mulia di bumi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 23, 10, 'Kerjakanlah ladangmu seperti di tepi sungai Nil, hai puteri Tarsis, sudah tidak ada lagi galangan-galangan kapal!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 23, 11, 'TUHAN telah mengacungkan tangan-Nya terhadap laut dan membuat kerajaan-kerajaan gemetar; Ia telah memberi perintah mengenai Kanaan untuk memusnahkan benteng-bentengnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 23, 12, 'Dan ia telah berfirman: "Engkau tidak akan beria-ria lagi, hai anak dara yang digagahi, hai puteri Sidon! Bangkitlah, mengungsilah kepada orang Kitim! Di sanapun juga tidak akan ada tempat yang senang bagimu."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 23, 13, 'Lihat negeri orang Kasdim! Bangsa itulah yang melakukannya, bukan orang Asyur. Mereka telah menyerahkan Tirus kepada binatang-binatang gurun, mereka telah mendirikan menara-menara pengepungan dan telah meratakan puri-puri kota itu dan membuat kota itu menjadi reruntuhan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 23, 14, 'Merataplah, hai kapal-kapal Tarsis, sebab sudah dirusakkan bentengmu!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 23, 15, 'Pada waktu itu Tirus akan dilupakan tujuh puluh tahun lamanya, sama dengan umur seorang raja. Sesudah lewat tujuh puluh tahun, akan terjadi kepada Tirus seperti terjadi kepada perempuan sundal dalam nyanyian ini:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 23, 16, '"Ambillah kecapi, kelilingilah kota, hai sundal yang dilupakan! Petiklah baik-baik, bernyanyilah banyak-banyak, supaya engkau diingat orang."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 23, 17, 'Dan sesudah lewat tujuh puluh tahun, TUHAN akan memperhatikan Tirus, sehingga ia kembali mendapat upah sundalnya, dan ia akan bersundal dengan segala kerajaan yang ada di muka bumi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 23, 18, 'Labanya dan upah sundalnya akan kudus bagi TUHAN, tidak akan ditahan atau disimpan, tetapi dengan labanya itu akan disediakan makanan yang cukup dan pakaian yang indah bagi orang-orang yang diam di hadapan TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 1, 'Sesungguhnya, TUHAN akan menanduskan bumi dan akan menghancurkannya, akan membalikkan permukaannya, dan akan menyerakkan penduduknya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 2, 'Maka seperti nasib rakyat demikianlah nasib imam, seperti nasib hamba laki-laki demikianlah nasib tuannya, seperti nasib hamba perempuan demikianlah nasib nyonyanya, seperti nasib pembeli demikianlah nasib penjual, seperti nasib peminjam demikianlah nasib yang meminjamkan, seperti nasib orang yang berhutang demikianlah nasib orang yang berpiutang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 3, 'Bumi akan ditanduskan setandus-tandusnya, dan akan dijarah sehabis-habisnya, sebab Tuhanlah yang mengucapkan firman ini.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 4, 'Bumi berkabung dan layu, ya, dunia merana dan layu, langit dan bumi merana bersama.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 5, 'Bumi cemar karena penduduknya, sebab mereka melanggar undang-undang, mengubah ketetapan dan mengingkari perjanjian abadi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 6, 'Sebab itu sumpah serapah akan memakan bumi, dan penduduknya akan mendapat hukuman; sebab itu penduduk bumi akan hangus lenyap, dan manusia akan tinggal sedikit.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 7, 'Air anggur tidak menggirangkan lagi, pohon anggur merana, dan semua orang yang bersukahati mengeluh.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 8, 'Kegirangan suara rebana sudah berhenti, keramaian orang-orang yang beria-ria sudah diam, dan kegirangan suara kecapi sudah berhenti.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 9, 'Tiada lagi orang minum anggur dengan bernyanyi, arak menjadi pahit bagi orang yang meminumnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 10, 'Kota yang kacau riuh sudah hancur, setiap rumah sudah tertutup, tidak dapat dimasuki.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 11, 'Orang menjerit di jalan-jalan karena tiada anggur, segala sukacita sudah lenyap, kegirangan bumi sudah hilang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 12, 'Yang terdapat dalam kota hanya kerusakan, pintu gerbang telah didobrak dan runtuh.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 13, 'Sebab beginilah akan terjadi di atas bumi, di tengah-tengah bangsa-bangsa, yaitu seperti pada waktu orang menjolok buah zaitun, seperti pada waktu pemetikan susulan, apabila panen buah anggur sudah berakhir.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 14, 'Dengan suara nyaring mereka bersorak-sorai, demi kemegahan TUHAN, mereka memekik dari sebelah barat:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 15, '"Sebab itu permuliakanlah TUHAN di negeri-negeri timur, nama TUHAN, Allah Israel, di tanah-tanah pesisir laut!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 16, 'Dari ujung bumi kami dengar nyanyian pujian: "Hormat bagi Yang Mahaadil!" Tetapi aku berkata: "Kurus merana aku, kurus merana aku. Celakalah aku! Sebab para penggarong menggarong, ya, terus-menerus mereka melakukan penggarongannya!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 17, 'Hai penduduk bumi, kamu akan dikejutkan, akan masuk pelubang dan jerat!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 18, 'Maka yang lari karena bunyi yang mengejutkan akan jatuh ke dalam pelubang, dan yang naik dari dalam pelubang akan tertangkap dalam jerat. Sebab tingkap-tingkap di langit akan terbuka dan akan bergoncang dasar-dasar bumi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 19, 'Bumi remuk redam, bumi hancur luluh bumi goncang-gancing.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 20, 'Bumi terhuyung-huyung sama sekali seperti orang mabuk dan goyang seperti gubuk yang ditiup angin; dosa pemberontakannya menimpa dia dengan sangat, ia rebah dan tidak akan bangkit-bangkit lagi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 21, 'Maka pada hari itu TUHAN akan menghukum tentara langit di langit dan raja-raja bumi di atas bumi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 22, 'Mereka akan dikumpulkan bersama-sama, seperti tahanan dimasukkan dalam liang; mereka akan dimasukkan dalam penjara dan akan dihukum sesudah waktu yang lama.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 24, 23, 'Bulan purnama akan tersipu-sipu, dan matahari terik akan mendapat malu, sebab TUHAN semesta alam akan memerintah di gunung Sion dan di Yerusalem, dan Ia akan menunjukkan kemuliaan-Nya di depan tua-tua umat-Nya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 25, 1, 'Ya TUHAN, Engkaulah Allahku; aku mau meninggikan Engkau, mau menyanyikan syukur bagi nama-Mu; sebab dengan kesetiaan yang teguh Engkau telah melaksanakan rancangan-Mu yang ajaib yang telah ada sejak dahulu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 25, 2, 'Sebab Engkau telah membuat kota itu menjadi timbunan batu, dan kota yang berkubu itu menjadi reruntuhan; puri orang luar tidak lagi menjadi kota, dan tidak dibangunkan lagi untuk selama-lamanya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 25, 3, 'Oleh karena itu suatu bangsa yang kuat akan memuliakan Engkau; kota bangsa-bangsa yang gagah akan takut kepada-Mu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 25, 4, 'Sebab Engkau menjadi tempat pengungsian bagi orang lemah, tempat pengungsian bagi orang miskin dalam kesesakannya, perlindungan terhadap angin ribut, naungan terhadap panas terik, sebab amarah orang-orang yang gagah sombong itu seperti angin ribut di musim dingin,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 25, 5, 'seperti panas terik di tempat kering. Kegaduhan orang-orang luar Kaudiamkan; seperti panas terik ditiadakan oleh naungan awan, demikianlah nyanyian orang-orang yang gagah sombong ditiadakan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 25, 6, 'TUHAN semesta alam akan menyediakan di gunung Sion ini bagi segala bangsa-bangsa suatu perjamuan dengan masakan yang bergemuk, suatu perjamuan dengan anggur yang tua benar, masakan yang bergemuk dan bersumsum, anggur yang tua yang disaring endapannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 25, 7, 'Dan di atas gunung ini TUHAN akan mengoyakkan kain perkabungan yang diselubungkan kepada segala suku bangsa dan tudung yang ditudungkan kepada segala bangsa-bangsa.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 25, 8, 'Ia akan meniadakan maut untuk seterusnya; dan Tuhan ALLAH akan menghapuskan air mata dari pada segala muka; dan aib umat-Nya akan dijauhkan-Nya dari seluruh bumi, sebab TUHAN telah mengatakannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 25, 9, 'Pada waktu itu orang akan berkata: "Sesungguhnya, inilah Allah kita, yang kita nanti-nantikan, supaya kita diselamatkan. Inilah TUHAN yang kita nanti-nantikan; marilah kita bersorak-sorak dan bersukacita oleh karena keselamatan yang diadakan-Nya!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 25, 10, 'Sebab tangan TUHAN akan melindungi gunung ini, tetapi Moab akan diinjak-injak di tempatnya sendiri, sebagai jerami diinjak-injak dalam lobang kotoran.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 25, 11, 'Apabila Moab mengembangkan tangannya di dalamnya seperti cara perenang mengembangkannya untuk berenang, maka TUHAN akan mematahkan kecongkakkan mereka dengan segala daya upaya mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 25, 12, 'Maka kubu-kubu tembokmu yang tinggi akan ditumbangkan-Nya dan dirubuhkan-Nya, dan dicampakkan-Nya ke tanah dan debu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 26, 1, 'Pada waktu itu nyanyian ini akan dinyanyikan di tanah Yehuda: "Pada kita ada kota yang kuat, untuk keselamatan kita TUHAN telah memasang tembok dan benteng.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 26, 2, 'Bukalah pintu-pintu gerbang, supaya masuk bangsa yang benar dan yang tetap setia!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 26, 3, 'Yang hatinya teguh Kaujagai dengan damai sejahtera, sebab kepada-Mulah ia percaya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 26, 4, 'Percayalah kepada TUHAN selama-lamanya, sebab TUHAN ALLAH adalah gunung batu yang kekal.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 26, 5, 'Sebab Ia sudah menundukkan penduduk tempat tinggi; kota yang berbenteng telah direndahkan-Nya, direndahkan-Nya sampai ke tanah dan dicampakkan-Nya sampai ke debu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 26, 6, 'Kaki orang-orang sengsara, telapak kaki orang-orang lemah akan menginjak-injaknya."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 26, 7, 'Jejak orang benar adalah lurus, sebab Engkau yang merintis jalan lurus baginya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 26, 8, 'Ya TUHAN, kami juga menanti-nantikan saatnya Engkau menjalankan penghakiman; kesukaan kami ialah menyebut nama-Mu dan mengingat Engkau.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 26, 9, 'Dengan segenap jiwa aku merindukan Engkau pada waktu malam, juga dengan sepenuh hati aku mencari Engkau pada waktu pagi; sebab apabila Engkau datang menghakimi bumi, maka penduduk dunia akan belajar apa yang benar.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 26, 10, 'Seandainya orang fasik dikasihani, ia tidak akan belajar apa yang benar; ia akan berbuat curang di negeri di mana hukum berlaku, dan tidak akan melihat kemuliaan TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 26, 11, 'Ya TUHAN, tangan-Mu dinaikkan, tetapi mereka tidak melihatnya. Biarlah mereka melihat kecemburuan-Mu karena umat-Mu dan biarlah mereka mendapat malu! Biarlah api yang memusnahkan lawan-Mu memakan mereka habis!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 26, 12, 'Ya TUHAN, Engkau akan menyediakan damai sejahtera bagi kami, sebab segala sesuatu yang kami kerjakan, Engkaulah yang melakukannya bagi kami.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 26, 13, 'Ya TUHAN, Allah kami, tuan-tuan lain pernah berkuasa atas kami, tetapi hanya nama-Mu saja kami masyhurkan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 26, 14, 'Mereka sudah mati, tidak akan hidup pula, sudah menjadi arwah, tidak akan bangkit pula; sesungguhnya, Engkau telah menghukum dan memunahkan mereka, dan meniadakan segala ingatan kepada mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 26, 15, 'Ya TUHAN, Engkau telah membuat bangsa ini bertambah-tambah, ya, membuat bertambah-tambah umat kemuliaan-Mu; Engkau telah sangat memperluas negerinya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 26, 16, 'Ya TUHAN, dalam kesesakan mereka mencari Engkau; ketika hajaran-Mu menimpa mereka, mereka mengeluh dalam doa.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 26, 17, 'Seperti perempuan yang mengandung yang sudah dekat waktunya untuk melahirkan, menggeliat sakit, mengerang karena sakit beranak, demikianlah tadinya keadaan kami di hadapan-Mu, ya TUHAN:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 26, 18, 'Kami mengandung, kami menggeliat sakit, tetapi seakan-akan kami melahirkan angin: kami tidak dapat mengadakan keselamatan di bumi, dan tiada lahir penduduk dunia.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 26, 19, 'Ya, TUHAN, orang-orang-Mu yang mati akan hidup pula, mayat-mayat mereka akan bangkit pula. Hai orang-orang yang sudah dikubur di dalam tanah bangkitlah dan bersorak-sorai! Sebab embun TUHAN ialah embun terang, dan bumi akan melahirkan arwah kembali.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 26, 20, 'Mari bangsaku, masuklah ke dalam kamarmu, tutuplah pintumu sesudah engkau masuk, bersembunyilah barang sesaat lamanya, sampai amarah itu berlalu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 26, 21, 'Sebab sesungguhnya, TUHAN mau keluar dari tempat-Nya untuk menghukum penduduk bumi karena kesalahannya, dan bumi tidak lagi menyembunyikan darah yang tertumpah di atasnya, tidak lagi menutupi orang-orang yang mati terbunuh di sana.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 27, 1, 'Pada waktu itu TUHAN akan melaksanakan hukuman dengan pedang-Nya yang keras, besar dan kuat atas Lewiatan, ular yang meluncur, atas Lewiatan, ular yang melingkar, dan Ia akan membunuh ular naga yang di laut.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 27, 2, 'Pada waktu itu akan dikatakan: "Bernyanyilah tentang kebun anggur yang elok!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 27, 3, 'Aku, TUHAN, penjaganya; setiap saat Aku menyiraminya. Supaya jangan orang mengganggunya, siang malam Aku menjaganya;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 27, 4, 'kehangatan murka tiada pada-Ku. Sekiranya tampak kepada-Ku puteri malu dan rumput, Aku akan bertindak memeranginya dan akan membakarnya sekaligus,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 27, 5, 'kecuali kalau mereka mencari perlindungan kepada-Ku dan mencari damai dengan Aku, ya mencari damai dengan Aku!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 27, 6, 'Pada hari-hari yang akan datang, Yakub akan berakar, Israel akan berkembang dan bertunas dan memenuhi muka bumi dengan hasilnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 27, 7, 'Apakah TUHAN memusnahkan umat-Nya seperti Ia memusnahkan orang yang memusnahkan mereka? Atau apakah Ia membunuh umat-Nya seperti Ia membunuh orang yang membunuh mereka?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 27, 8, 'Dengan menghalau dan dengan mengusir mereka Engkau telah melawan mereka. Ia telah menyisihkan mereka dengan angin-Nya yang keras di waktu angin timur.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 27, 9, 'Maka beginilah akan dihapuskan kesalahan Yakub dan inilah buahnya kalau ia menjauhkan dosanya: ia akan membuat segala batu mezbah seperti batu-batu kapur yang dipecah-pecahkan, sehingga tiada lagi tiang-tiang berhala dan pedupaan-pedupaan yang tinggal berdiri.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 27, 10, 'Sebab kota yang berkubu itu terpencil, suatu tempat kediaman yang dikosongkan dan ditinggalkan seperti padang gurun; anak lembu akan makan rumput dan berbaring di situ menghabiskan dahan-dahan pohon.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 27, 11, 'Apabila ranting-rantingnya sudah kering, maka akan dipatahkan; perempuan-perempuan akan datang dan menyalakannya. Sebab inilah suatu bangsa yang tidak berakal budi, itulah sebabnya dia tidak disayangi oleh Dia yang menjadikannya dan tidak dikasihi oleh Dia yang membentuknya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 27, 12, 'Maka pada waktu itu TUHAN akan mengirik mulai dari sungai Efrat sampai sungai Mesir, dan kamu ini akan dikumpulkan satu demi satu, hai orang Israel!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 27, 13, 'Pada waktu itu sangkakala besar akan ditiup, dan akan datang mereka yang hilang di tanah Asyur serta mereka yang terbuang ke tanah Mesir untuk sujud menyembah kepada TUHAN di gunung yang kudus, di Yerusalem.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 1, 'Celaka atas mahkota kemegahan pemabuk-pemabuk Efraim, atas bunga yang sudah mulai layu di perhiasan kepala mereka yang indah-indah?yaitu kota yang terletak tinggi di atas bukit, di atas lembah yang subur yang penuh peminum anggur yang sudah pening?!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 2, 'Sesungguhnya, pada Tuhan ada seorang yang kuat dan tegap, seorang yang seperti angin ribut disertai hujan batu, yakni badai yang membinasakan, seorang yang seperti angin ribut disertai air hujan yang hebat menghanyutkan; ia akan menghempaskan mereka ke tanah dengan kekerasan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 3, 'Mahkota kemegahan pemabuk-pemabuk Efraim itu akan diinjak-injak dengan kaki,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 4, 'dan bunga yang sudah mulai layu di perhiasan kepala mereka yang indah-indah itu?yaitu kota yang terletak tinggi di atas bukit, di atas lembah yang subur?nasibnya akan seperti nasib buah ara yang masak duluan sebelum musim kemarau: baru saja dilihat orang terus dipetik dan ditelan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 5, 'Pada waktu itu TUHAN semesta alam akan menjadi mahkota kepermaian, dan perhiasan kepala yang indah-indah bagi sisa umat-Nya,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 6, 'akan menjadi roh keadilan bagi orang yang duduk mengadili, dan menjadi roh kepahlawanan bagi orang yang memukul mundur peperangan ke arah pintu gerbang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 7, 'Tetapi orang-orang di sinipun pening karena anggur dan pusing karena arak. Baik imam maupun nabi pening karena arak, kacau oleh anggur; mereka pusing oleh arak, pening pada waktu melihat penglihatan, goyang pada waktu memberi keputusan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 8, 'Sungguh, segala meja penuh dengan muntah, kotoran, sehingga tidak ada tempat yang bersih lagi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 9, 'Dan orang berkata: "Kepada siapakah dia ini mau mengajarkan pengetahuannya dan kepada siapakah ia mau menjelaskan nubuat-nubuatnya? Seolah-olah kepada anak yang baru disapih, dan yang baru cerai susu!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 10, 'Sebab harus ini harus itu, mesti begini mesti begitu, tambah ini, tambah itu!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 11, 'Sungguh, oleh orang-orang yang berlogat ganjil dan oleh orang-orang yang berbahasa asing akan berbicara kepada bangsa ini', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 12, 'Dia yang telah berfirman kepada mereka: "Inilah tempat perhentian, berilah perhentian kepada orang yang lelah; inilah tempat peristirahatan!" Tetapi mereka tidak mau mendengarkan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 13, 'Maka mereka akan mendengarkan firman TUHAN yang begini: "Harus ini harus itu, mesti begini mesti begitu, tambah ini tambah itu!" supaya dalam berjalan mereka jatuh telentang, sehingga luka, tertangkap dan tertawan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 14, 'Sebab itu dengarlah firman TUHAN, hai orang-orang pencemooh, hai orang-orang yang memerintah rakyat yang ada di Yerusalem ini!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 15, 'Karena kamu telah berkata: "Kami telah mengikat perjanjian dengan maut, dan dengan dunia maut kami telah mengadakan persetujuan; biarpun cemeti berdesik-desik dengan kerasnya, kami tidak akan kena; sebab kami telah membuat bohong sebagai perlindungan kami, dan dalam dusta kami menyembunyikan diri,"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 16, 'sebab itu beginilah firman Tuhan ALLAH: "Sesungguhnya, Aku meletakkan sebagai dasar di Sion sebuah batu, batu yang teruji, sebuah batu penjuru yang mahal, suatu dasar yang teguh: Siapa yang percaya, tidak akan gelisah!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 17, 'Dan Aku akan membuat keadilan menjadi tali pengukur, dan kebenaran menjadi tali sipat; hujan batu akan menyapu bersih perlindungan bohong, dan air lebat akan menghanyutkan persembunyian."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 18, 'Perjanjianmu dengan maut itu akan ditiadakan, dan persetujuanmu dengan dunia orang mati itu tidak akan tetap berlaku; apabila cemeti berdesik-desik dengan kerasnya, kamu akan hancur diinjak-injak.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 19, 'Seberapa kali ia datang, ia akan menyeret kamu, sebab pagi demi pagi ia akan datang, pada waktu siang dan pada waktu malam; maka adalah semata-mata kengerian untuk mengerti firman yang didengar itu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 20, 'Sebab tempat tidur akan kurang panjang untuk dipakai membujurkan diri dan selimut akan kurang lebar untuk dipakai menyelubungi diri.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 21, 'Sebab TUHAN akan bangkit seperti di gunung Perasim, Ia akan mengamuk seperti di lembah dekat Gibeon, untuk melakukan perbuatan-Nya?ganjil perbuatan-Nya itu; dan untuk mengerjakan pekerjaan-Nya?ajaib pekerjaan-Nya itu!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 22, 'Oleh sebab itu, janganlah kamu mencemooh, supaya tali belenggumu jangan semakin keras, sebab kudengar tentang kebinasaan yang sudah pasti yang datang dari Tuhan ALLAH semesta alam atas seluruh negeri itu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 23, 'Pasanglah telinga dan dengarkanlah suaraku; perhatikanlah dan dengarkanlah perkataanku!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 24, 'Setiap harikah orang membajak, mencangkul dan menyisir tanahnya untuk menabur?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 25, 'Bukankah setelah meratakan tanahnya, ia menyerakkan jintan hitam dan menebarkan jintan putih, menaruh gandum jawawut dan jelai kehitam-hitaman dan sekoi di pinggirnya?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 26, 'Mengenai adat kebiasaan ia telah diajari, diberi petunjuk oleh Allahnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 27, 'Sebab jintan hitam tidak diirik dengan eretan pengirik, dan roda gerobak tidak dipakai untuk menggiling jintan putih, tetapi jintan hitam diirik dengan memukul-mukulnya dengan galah, dan jintan putih dengan tongkat.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 28, 'Apakah orang waktu mengirik memukul gandum sampai hancur? sungguh tidak, orang tidak terus-menerus memukulnya sampai hancur! Dan sekalipun orang menjalankan di atas gandum itu jentera gerobak dengan kudanya, namun orang tidak akan menggilingnya sampai hancur.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 28, 29, 'Dan inipun datangnya dari TUHAN semesta alam; Ia ajaib dalam keputusan dan agung dalam kebijaksanaan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 1, 'Celakalah Ariel, Ariel, kota tempat Daud berkemah! Biarlah tahun demi tahun perayaan-perayaan silih berganti!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 2, 'Aku akan menyesakkan Ariel, sehingga orang mengerang dan mengaduh, dan kota itu akan seperti perapian bagi-Ku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 3, 'Aku akan berkemah di segala penjuru mengepung engkau, dan akan membuat tempat-tempat pengintaian untuk mengimpit engkau, dan akan mendirikan pagar-pagar pengepungan terhadap engkau.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 4, 'Maka engkau akan merendahkan diri dan engkau bersuara dari dalam tanah, perkataanmu kedengaran samar-samar dari dalam debu; suaramu akan berbunyi seperti suara arwah dari dalam tanah, dan perkataanmu akan kedengaran seperti bisikan dari dalam debu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 5, 'Akan tetapi segala pasukan lawanmu akan hilang lenyap seperti abu halus, dan semua orang yang gagah sombong akan menjadi seperti sekam yang melintas terbang. Sebab dengan tiba-tiba, dalam sekejap mata,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 6, 'engkau akan melihat kedatangan TUHAN semesta alam dalam guntur, gempa dan suara hebat, dalam puting beliung dan badai dan dalam nyala api yang memakan habis.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 7, 'Maka segala pasukan bangsa-bangsa yang berperang melawan Ariel, dan semua orang yang memerangi dia dan kubu pertahanannya dan orang-orang yang menyesakkan dia akan seperti mimpi dan seperti penglihatan malam-malam:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 8, 'seumpama seorang yang lapar bermimpi ia sedang makan, pada waktu terjaga, perutnya masih kosong, atau seumpama seorang yang haus bermimpi ia sedang minum, pada waktu terjaga, sesungguhnya ia masih lelah, kerongkongannya masih dahaga, demikianlah halnya dengan segala pasukan bangsa-bangsa yang berperang melawan gunung Sion.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 9, 'Tercengang-cenganglah, penuh keheranan, biarlah matamu tertutup, buta semata-mata! Jadilah mabuk, tetapi bukan karena anggur, jadilah pusing, tetapi bukan karena arak!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 10, 'Sebab TUHAN telah membuat kamu tidur nyenyak; matamu?yakni para nabi?telah dipejamkan-Nya dan mukamu?yaitu para pelihat?telah ditudungi-Nya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 11, 'Maka bagimu penglihatan dari semuanya itu seperti isi sebuah kitab yang termeterai, apabila itu diberikan kepada orang yang tahu membaca dengan mengatakan: "Baiklah baca ini," maka ia akan menjawab: "Aku tidak dapat, sebab kitab itu termeterai";', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 12, 'dan apabila kitab itu diberikan kepada seorang yang tidak dapat membaca dengan mengatakan: "Baiklah baca ini," maka ia akan menjawab: "Aku tidak dapat membaca."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 13, 'Dan Tuhan telah berfirman: "Oleh karena bangsa ini datang mendekat dengan mulutnya dan memuliakan Aku dengan bibirnya, padahal hatinya menjauh dari pada-Ku, dan ibadahnya kepada-Ku hanyalah perintah manusia yang dihafalkan,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 14, 'maka sebab itu, sesungguhnya, Aku akan melakukan pula hal-hal yang ajaib kepada bangsa ini, keajaiban yang menakjubkan; hikmat orang-orangnya yang berhikmat akan hilang, dan kearifan orang-orangnya yang arif akan bersembunyi."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 15, 'Celakalah orang yang menyembunyikan dalam-dalam rancangannya terhadap TUHAN, yang pekerjaan-pekerjaannya terjadi dalam gelap sambil berkata: "Siapakah yang melihat kita dan siapakah yang mengenal kita?"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 16, 'Betapa kamu memutarbalikkan segala sesuatu! Apakah tanah liat dapat dianggap sama seperti tukang periuk, sehingga apa yang dibuat dapat berkata tentang yang membuatnya: "Bukan dia yang membuat aku"; dan apa yang dibentuk berkata tentang yang membentuknya: "Ia tidak tahu apa-apa"?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 17, 'Bukankah hanya sedikit waktu lagi, Libanon akan berubah menjadi kebun buah-buahan, dan kebun buah-buahan itu akan dianggap hutan?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 18, 'Pada waktu itu orang-orang tuli akan mendengar perkataan-perkataan sebuah kitab, dan lepas dari kekelaman dan kegelapan mata orang-orang buta akan melihat.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 19, 'Orang-orang yang sengsara akan tambah bersukaria di dalam TUHAN, dan orang-orang miskin di antara manusia akan bersorak-sorak di dalam Yang Mahakudus, Allah Israel!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 20, 'Sebab orang yang gagah sombong akan berakhir dan orang pencemooh akan habis, dan semua orang yang berniat jahat akan dilenyapkan,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 21, 'yaitu mereka yang begitu saja menyatakan seseorang berdosa di dalam suatu perkara, dan yang memasang jerat terhadap orang yang menegor mereka di pintu gerbang, dan yang mendesak orang benar dengan alasan yang tidak-tidak.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 22, 'Sebab itu beginilah firman TUHAN, Allah kaum keturunan Yakub, Dia yang telah membebaskan Abraham: "Mulai sekarang Yakub tidak lagi mendapat malu, dan mukanya tidak lagi pucat.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 23, 'Sebab pada waktu mereka, keturunan Yakub itu, melihat apa yang dibuat tangan-Ku di tengah-tengahnya, mereka akan menguduskan nama-Ku; mereka akan menguduskan Yang Kudus, Allah Yakub, dan mereka akan gentar kepada Allah Israel;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 29, 24, 'orang-orang yang sesat pikiran akan mendapat pengertian, dan orang-orang yang bersungut-sungut akan menerima pengajaran."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 1, 'Celakalah anak-anak pemberontak, demikianlah firman TUHAN, yang melaksanakan suatu rancangan yang bukan dari pada-Ku, yang memasuki suatu persekutuan, yang bukan oleh dorongan Roh-Ku, sehingga dosa mereka bertambah-tambah,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 2, 'yang berangkat ke Mesir dengan tidak meminta keputusan-Ku, untuk berlindung pada Firaun dan untuk berteduh di bawah naungan Mesir.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 3, 'Tetapi perlindungan Firaun akan memalukan kamu, dan perteduhan di bawah naungan Mesir akan menodai kamu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 4, 'Sebab sekalipun pembesar-pembesar Yerusalem sudah ada di Zoan, dan utusan-utusannya sudah sampai ke Hanes,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 5, 'sekaliannya akan mendapat malu karena bangsa itu tidak dapat memberi faedah kepada mereka, dan tidak dapat memberi pertolongan atau faedah; melainkan hanya memalukan, bahkan mengaibkan mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 6, 'Ucapan ilahi tentang binatang-binatang di Tanah Negeb. Melalui suatu negeri yang penuh kesesakan dan kesempitan, tempat singa betina dan singa jantan yang mengaum, tempat ular beludak dan ular naga terbang, mereka mengangkut harta kekayaan mereka di atas punggung keledai, dan barang-barang perbendaharaan mereka di atas ponok unta, kepada suatu bangsa yang tidak dapat memberi faedah,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 7, 'yakni Mesir yang memberi pertolongan yang tak berguna dan percuma; sebab itu Aku menamainya begini: "Rahab yang dibuat menganggur."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 8, 'Maka sekarang, pergilah, tulislah itu di depan mata mereka di suatu loh, dan cantumkanlah di suatu kitab, supaya itu menjadi kesaksian untuk waktu yang kemudian, sampai selama-lamanya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 9, 'Sebab mereka itu suatu bangsa pemberontak, anak-anak yang suka bohong anak-anak yang enggan mendengar akan pengajaran TUHAN;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 10, 'yang mengatakan kepada para tukang tilik: "Jangan menilik," dan kepada para pelihat: "Janganlah lihat bagi kami hal-hal yang benar, tetapi katakanlah kepada kami hal-hal yang manis, lihatlah bagi kami hal-hal yang semu,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 11, 'menyisihlah dari jalan dan ambillah jalan lain, janganlah susahi kami dengan Yang Mahakudus, Allah Israel."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 12, 'Sebab itu beginilah firman Yang Mahakudus, Allah Israel: "Oleh karena kamu menolak firman ini, dan mempercayakan diri kepada orang-orang pemeras dan yang berlaku serong dan bersandar kepadanya,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 13, 'maka sebab itu bagimu dosa ini akan seperti pecahan tembok yang mau jatuh, tersembul ke luar pada tembok yang tinggi, yang kehancurannya datang dengan tiba-tiba, dalam sekejap mata,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 14, 'seperti kehancuran tempayan tukang periuk yang diremukkan dengan tidak kenal sayang, sehingga di antara remukannya tiada terdapat satu kepingpun yang dapat dipakai untuk mengambil api dari dalam tungku atau mencedok air dari dalam bak."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 15, 'Sebab beginilah firman Tuhan ALLAH, Yang Mahakudus, Allah Israel: "Dengan bertobat dan tinggal diam kamu akan diselamatkan, dalam tinggal tenang dan percaya terletak kekuatanmu." Tetapi kamu enggan,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 16, 'kamu berkata: "Bukan, kami mau naik kuda dan lari cepat," maka kamu akan lari dan lenyap. Katamu pula: "Kami mau mengendarai kuda tangkas," maka para pengejarmu akan lebih tangkas lagi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 17, 'Seribu orang akan lari melihat ancaman satu orang, terhadap ancaman lima orang kamu akan lari, sampai kamu ditinggalkan seperti tonggak isyarat di atas puncak gunung dan seperti panji-panji di atas bukit.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 18, 'Sebab itu TUHAN menanti-nantikan saatnya hendak menunjukkan kasih-Nya kepada kamu; sebab itu Ia bangkit hendak menyayangi kamu. Sebab TUHAN adalah Allah yang adil; berbahagialah semua orang yang menanti-nantikan Dia!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 19, 'Sungguh, hai bangsa di Sion yang diam di Yerusalem, engkau tidak akan terus menangis. Tentulah Tuhan akan mengasihani engkau, apabila engkau berseru-seru; pada saat Ia mendengar teriakmu, Ia akan menjawab.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 20, 'Dan walaupun Tuhan memberi kamu roti dan air serba sedikit, namun Pengajarmu tidak akan menyembunyikan diri lagi, tetapi matamu akan terus melihat Dia,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 21, 'dan telingamu akan mendengar perkataan ini dari belakangmu: "Inilah jalan, berjalanlah mengikutinya," entah kamu menganan atau mengiri.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 22, 'Engkau akan menganggap najis patung-patungmu yang disalut dengan perak atau yang dilapis dengan emas; engkau akan membuangnya seperti kain cemar sambil berkata kepadanya: "Keluar!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 23, 'Lalu TUHAN akan memberi hujan bagi benih yang baru kamu taburkan di ladangmu, dan dari hasil tanah itu kamu akan makan roti yang lezat dan berlimpah-limpah. Pada waktu itu ternakmu akan makan rumput di padang rumput yang luas;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 24, 'sapi-sapi dan keledai-keledai yang mengerjakan tanah akan memakan makanan campuran yang sedap, yang sudah ditampi dan diayak.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 25, 'Dari setiap gunung yang tinggi dan dari setiap bukit yang menjulang akan memancar sungai-sungai pada hari pembunuhan yang besar, apabila menara-menara runtuh.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 26, 'Maka terang bulan purnama akan seperti terang matahari terik dan terang matahari terik akan tujuh kali ganda, yaitu seperti terangnya tujuh hari, pada waktu TUHAN membalut luka umat-Nya dan menyembuhkan bekas pukulan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 27, 'TUHAN datang menyatakan diri-Nya dari tempat-Nya yang jauh?murka-Nya menyala-nyala, Ia datang dalam awan gelap yang bergumpal-gumpal, bibir-Nya penuh dengan amarah, dan lidah-Nya seperti api yang memakan habis;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 28, 'hembusan nafas-Nya seperti sungai yang menghanyutkan, yang airnya sampai ke leher?Ia datang untuk mengayak bangsa-bangsa dengan ayak kebinasaan dan untuk memasang suatu kekang yang menyesatkan di mulut suku-suku bangsa.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 29, 'Kamu akan menyanyikan suatu nyanyian seperti pada waktu malam ketika orang menguduskan diri untuk perayaan, dan kamu akan bersuka hati seperti pada waktu orang berjalan diiringi suling hendak naik ke gunung TUHAN, ke Gunung Batu Israel.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 30, 'Dan TUHAN akan memperdengarkan suara-Nya yang mulia, akan memperlihatkan tangan-Nya yang turun menimpa dengan murka yang hebat dan nyala api yang memakan habis, dengan hujan lebat, angin ribut dan hujan batu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 31, 'Sebab Asyur akan terkejut oleh suara TUHAN, pada waktu Ia memukul mereka dengan gada.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 32, 'Sebab setiap pukulan dengan tongkat penghajar yang ditimpakan TUHAN ke atasnya, akan diiringi rebana dan kecapi, dan Ia akan berperang melawan Asyur dengan tangan yang diayunkan untuk peperangan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 30, 33, 'Sebab dari dahulu sudah diatur tempat pembakaran?bukankah itu untuk raja?dasarnya dibuat dalam dan lapang, pancakanya penuh api dan kayu; nafas TUHAN menghanguskannya seperti sungai belerang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 31, 1, 'Celakalah orang-orang yang pergi ke Mesir minta pertolongan, yang mengandalkan kuda-kuda, yang percaya kepada keretanya yang begitu banyak, dan kepada pasukan berkuda yang begitu besar jumlahnya, tetapi tidak memandang kepada Yang Mahakudus, Allah Israel, dan tidak mencari TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 31, 2, 'Akan tetapi Dia yang bijaksana akan mendatangkan malapetaka, dan tidak menarik firman-Nya; Ia akan bangkit melawan kaum penjahat, dan melawan bala bantuan orang-orang lalim.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 31, 3, 'Sebab orang Mesir adalah manusia, bukan allah, dan kuda-kuda mereka adalah makhluk yang lemah, bukan roh yang berkuasa. Apabila TUHAN mengacungkan tangan-Nya, tergelincirlah yang membantu dan jatuhlah yang dibantu, dan mereka sekaliannya habis binasa bersama-sama.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 31, 4, 'Sebab beginilah firman TUHAN kepadaku: Seperti seekor singa atau singa muda menggeram untuk mempertahankan mangsanya, dan tidak terkejut mendengar teriakan seluruh pasukan gembala yang dikerahkan melawan dia, dan tidak mengalah terhadap keributan mereka, demikianlah TUHAN semesta alam akan turun berperang untuk mempertahankan gunung Sion dan bukitnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 31, 5, 'Seperti burung yang berkepak-kepak melindungi sarangnya, demikianlah TUHAN semesta alam akan melindungi Yerusalem, ya, melindungi dan menyelamatkannya, memeliharanya dan menjauhkan celaka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 31, 6, 'Bertobatlah, hai orang Israel, kepada Dia yang sudah kamu tinggalkan jauh-jauh!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 31, 7, 'Sungguh pada hari itu kamu masing-masing akan membuang berhala-berhala peraknya dan berhala-berhala emasnya yang dibuat oleh tanganmu sendiri dengan penuh dosa.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 31, 8, 'Asyur akan rebah oleh pedang, tetapi bukan pedang orang, dan akan dimakan habis oleh pedang, tetapi bukan pedang manusia; mereka akan melarikan diri terhadap pedang, dan teruna-terunanya akan menjadi orang rodi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 31, 9, 'Pelindung mereka akan lenyap karena gentar, dan panglimanya akan lari terkejut meninggalkan panji-panji, demikianlah firman TUHAN yang mempunyai api di Sion dan dapur perapian di Yerusalem.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 32, 1, 'Sesungguhnya, seorang raja akan memerintah menurut kebenaran, dan pemimpin-pemimpin akan memimpin menurut keadilan,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 32, 2, 'dan mereka masing-masing akan seperti tempat perteduhan terhadap angin dan tempat perlindungan terhadap angin ribut, seperti aliran-aliran air di tempat kering, seperti naungan batu yang besar, di tanah yang tandus.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 32, 3, 'Mata orang-orang yang melihat tidak lagi akan tertutup, dan telinga orang-orang yang mendengar akan memperhatikan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 32, 4, 'Hati orang-orang yang terburu nafsu akan tahu menimbang-nimbang, dan lidah orang-orang yang gagap akan dapat berbicara jelas.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 32, 5, 'Orang bebal tidak akan disebutkan lagi orang yang berbudi luhur, dan orang penipu tidak akan dikatakan terhormat.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 32, 6, 'Sebab orang bebal mengatakan kebebalan, dan hatinya merencanakan yang jahat, yaitu bermaksud murtad dan mengatakan yang menyesatkan tentang TUHAN, membiarkan kosong perut orang lapar dan orang haus kekurangan minuman.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 32, 7, 'Kalau penipu, akal-akalnya adalah jahat, ia merancang perbuatan-perbuatan keji untuk mencelakakan orang sengsara dengan perkataan dusta, sekalipun orang miskin itu membela haknya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 32, 8, 'Tetapi orang yang berbudi luhur merancang hal-hal yang luhur, dan ia selalu bertindak demikian.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 32, 9, 'Hai perempuan-perempuan yang hidup aman, bangunlah, dengarkanlah suaraku, hai anak-anak perempuan yang hidup tenteram, perhatikanlah perkataanku!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 32, 10, 'Dalam waktu setahun lebih kamu akan gemetar, hai orang-orang yang hidup tenteram, sebab panen buah anggur sudah habis binasa, dan panen buah-buah lain juga tidak ada.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 32, 11, 'Gentarlah, hai perempuan-perempuan yang hidup aman, gemetarlah, hai perempuan-perempuan yang hidup tenteram, tanggalkanlah dan bukalah pakaianmu, kenakanlah kain kabung pada pinggangmu!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 32, 12, 'Ratapilah ladangmu yang permai, dan pohon anggurmu yang selalu berbuah lebat,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 32, 13, 'ratapilah tanah bangsaku yang ditumbuhi semak duri dan puteri malu, bahkan juga segala rumahmu tempat bergirang-girang di kota yang penuh keriaan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 32, 14, 'Sebab purimu sudah ditinggalkan dan keramaian kotamu sudah berubah menjadi kesepian. Bukit dan Menara sudah menjadi tanah rata untuk selama-lamanya, menjadi tempat kegirangan bagi keledai hutan dan tempat makan rumput bagi kawanan binatang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 32, 15, 'Sampai dicurahkan kepada kita Roh dari atas: Maka padang gurun akan menjadi kebun buah-buahan, dan kebun buah-buahan itu akan dianggap hutan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 32, 16, 'Di padang gurun selalu akan berlaku keadilan dan di kebun buah-buahan akan tetap ada kebenaran.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 32, 17, 'Di mana ada kebenaran di situ akan tumbuh damai sejahtera, dan akibat kebenaran ialah ketenangan dan ketenteraman untuk selama-lamanya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 32, 18, 'Bangsaku akan diam di tempat yang damai, di tempat tinggal yang tenteram di tempat peristirahatan yang aman.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 32, 19, 'Hutan akan runtuh seluruhnya dan kota akan direndahkan serendah-rendahnya', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 32, 20, 'Berbahagialah kamu yang boleh menabur di segala tempat di mana terdapat air, yang dapat membiarkan sapi dan keledainya pergi ke mana-mana!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 1, 'Celakalah engkau, hai perusak yang tidak dirusak sendiri, dan engkau, hai penggarong yang tidak digarong sendiri! Apabila engkau selesai merusak, engkau sendiri akan dirusak; apabila engkau habis menggarong, engkau sendiri akan digarong.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 2, 'TUHAN, kasihanilah kami, Engkau kami nanti-nantikan! Lindungilah kami setiap pagi dengan tangan-Mu, ya, selamatkanlah kami di waktu kesesakan!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 3, 'Waktu mendengar suara gemuruh ketika Engkau bangkit, larilah bangsa-bangsa dan berceraiberailah suku-suku bangsa.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 4, 'Orang mengumpulkan jarahan seperti belalang pelahap menelan makanannya; mereka menyerbunya seperti serbuan kawanan belalang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 5, 'TUHAN tinggi luhur, sebab Ia tinggal di tempat tinggi; Ia membuat Sion penuh keadilan dan kebenaran.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 6, 'Masa keamanan akan tiba bagimu; kekayaan yang menyelamatkan ialah hikmat dan pengetahuan; takut akan TUHAN, itulah harta benda Sion.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 7, 'Lihat, orang-orang Ariel menjerit di jalan, utusan-utusan yang mencari damai menangis dengan pedih.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 8, 'Jalan-jalan raya menjadi sunyi dan seorangpun tiada lagi yang lintas di jalan. Perjanjian sudah diingkari, saksi-saksi sudah ditolak, dan manusia tidak dihiraukan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 9, 'Negeri berkabung dan merana; Libanon tersipu-sipu dan mati rebah; Saron sudah seperti padang belantara, Basan dan Karmel meluruh daun.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 10, 'Sekarang, Aku akan bangkit, firman TUHAN, sekarang, Aku akan bangkit berdiri, sekarang, Aku akan berdiri tegak!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 11, 'Kamu mengandung rumput kering, dan melahirkan jerami; amarahmu seperti api yang memakan kamu sendiri.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 12, 'Bangsa-bangsa akan dibakar menjadi kapur dan akan dibakar dalam api seperti semak duri yang ditebang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 13, 'Hai orang-orang yang jauh, dengarlah apa yang telah Kulakukan, hai orang-orang yang dekat, ketahuilah keperkasaan-Ku!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 14, 'Orang-orang yang berdosa terkejut di Sion orang-orang murtad diliputi kegentaran. Mereka berkata: "Siapakah di antara kita yang dapat tinggal dalam api yang menghabiskan ini? Siapakah di antara kita yang dapat tinggal di perapian yang abadi ini?"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 15, 'Orang yang hidup dalam kebenaran, yang berbicara dengan jujur, yang menolak untung hasil pemerasan, yang mengebaskan tangannya, supaya jangan menerima suap, yang menutup telinganya, supaya jangan mendengarkan rencana penumpahan darah, yang menutup matanya, supaya jangan melihat kejahatan,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 16, 'dialah seperti orang yang tinggal aman di tempat-tempat tinggi, bentengnya ialah kubu di atas bukit batu; rotinya disediakan air minumnya terjamin.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 17, 'Engkau akan memandang raja dalam semaraknya, akan melihat negeri yang terbentang jauh.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 18, 'Dalam hatimu engkau akan memikirkan kengerian yang sudah-sudah: "Sudah lenyapkah juru hitung, sudah lenyapkah juru timbang, dan sudah lenyapkah orang yang menghitung menara-menara?"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 19, 'Tidak lagi akan kaulihat bangsa yang biadab itu, bangsa yang logatnya samar, sehingga tidak dapat dipahami, yang bahasanya gagap, sehingga tiada yang mengerti.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 20, 'Pandanglah Sion, kota pertemuan raya kita! Matamu akan melihat Yerusalem, tempat kediaman yang aman, kemah yang tidak berpindah-pindah, yang patoknya tidak dicabut untuk seterusnya, dan semua talinya tidak akan putus.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 21, 'Di situ kita akan melihat betapa mulia TUHAN kita: seperti tempat yang penuh sungai dan aliran yang lebar; perahu dayung tidak melaluinya, dan kapal besar tidak menyeberanginya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 22, 'Sebab TUHAN ialah Hakim kita, TUHAN ialah yang memberi hukum bagi kita; TUHAN ialah Raja kita, Dia akan menyelamatkan kita.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 23, 'Tali-talimu sudah kendor, tidak dapat mengikat teguh tiang layar di tempatnya, tidak dapat membentangkan layar. Pada waktu itu orang akan membagi-bagi rampasan banyak-banyak, dan orang-orang lumpuh akan menjarah jarahan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 33, 24, 'Tidak seorangpun yang tinggal di situ akan berkata: "Aku sakit," dan semua penduduknya akan diampuni kesalahannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 34, 1, 'Marilah mendekat, hai bangsa-bangsa, dengarlah, dan perhatikanlah, hai suku-suku bangsa! Baiklah bumi serta segala isinya mendengar, dunia dan segala yang terpancar dari padanya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 34, 2, 'Sebab TUHAN murka atas segala bangsa, dan hati-Nya panas atas segenap tentara mereka. Ia telah mengkhususkan mereka untuk ditumpas dan menyerahkan mereka untuk dibantai.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 34, 3, 'Orang-orangnya yang mati terbunuh akan dilemparkan, dan dari bangkai-bangkai mereka akan naik bau busuk; gunung-gunung akan kebanjiran darah mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 34, 4, 'Segenap tentara langit akan hancur, dan langit akan digulung seperti gulungan kitab, segala tentara mereka akan gugur seperti daun yang gugur dari pohon anggur, dan seperti gugurnya daun pohon ara.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 34, 5, 'Sebab pedang-Ku yang di langit sudah mengamuk, lihat, ia turun menghakimi Edom, bangsa yang Kukhususkan untuk ditumpas.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 34, 6, 'TUHAN mempunyai sebilah pedang yang berlumuran darah dan yang penuh lemak, yaitu darah anak-anak domba dan kambing-kambing jantan dan lemak buah pinggang domba-domba jantan. Sebab TUHAN mengadakan penyembelihan korban di Bozra dan pembantaian besar di tanah Edom.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 34, 7, 'Banteng-banteng akan rebah mati bersama-sama domba dan kambing itu, dan lembu-lembu jantan yang muda bersama-sama lembu-lembu jantan yang gagah, seluruh negerinya diresapi oleh darah, dan tanah mereka penuh dengan lemak.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 34, 8, 'Sebab TUHAN mendatangkan hari pembalasan dan tahun pengganjaran karena perkara Sion.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 34, 9, 'Sungai-sungai Edom akan berubah menjadi ter, dan tanahnya menjadi belerang; negerinya akan menjadi ter yang menyala-nyala.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 34, 10, 'Siang dan malam negeri itu tidak akan padam-padam, asapnya naik untuk selama-lamanya. Negeri itu akan menjadi reruntuhan turun-temurun, tidak ada orang yang melintasinya untuk seterusnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 34, 11, 'Burung undan dan landak akan mendudukinya, burung hantu dan burung gagak akan tinggal di dalamnya. TUHAN menjadikannya campur baur dan kosong tepat menurut rencana-Nya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 34, 12, 'Jin-jin akan diam di dalamnya, dan para pemukanya akan tidak ada lagi; tidak ada lagi di sana yang dimaklumkan sebagai raja, dan semua pemimpinnya sudah lenyap.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 34, 13, 'Duri-duri akan tumbuh di puri-purinya, rumput dan puteri malu di tempat-tempatnya yang berkubu, sehingga menjadi tempat kediaman serigala, dan lapangan bagi burung unta.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 34, 14, 'Di sana berpapasan binatang gurun dengan anjing hutan, dan jin bertemu dengan temannya; hantu malam saja ada di sana dan mendapat tempat perhentian.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 34, 15, 'Di sana ular pohon bersarang dan bertelur, mengeram sampai telurnya menetas; burung-burung dendang saja berkumpul di sana, masing-masing dengan pasangannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 34, 16, 'Carilah di dalam kitab TUHAN dan bacalah: Satupun dari semua makhluk itu tidak ada yang ketinggalan dan yang satu tidak kehilangan yang lain; sebab begitulah perintah yang keluar dari mulut TUHAN, dan Roh TUHAN sendiri telah mengumpulkan mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 34, 17, 'Ia sendiri telah membuang undi dan membagi-bagi negeri itu di antara mereka dengan tali pengukur; mereka akan mendudukinya sampai selama-lamanya dan akan tinggal di situ turun-temurun.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 35, 1, 'Padang gurun dan padang kering akan bergirang, padang belantara akan bersorak-sorak dan berbunga;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 35, 2, 'seperti bunga mawar ia akan berbunga lebat, akan bersorak-sorak, ya bersorak-sorak dan bersorak-sorai. Kemuliaan Libanon akan diberikan kepadanya, semarak Karmel dan Saron; mereka itu akan melihat kemuliaan TUHAN, semarak Allah kita.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 35, 3, 'Kuatkanlah tangan yang lemah lesu dan teguhkanlah lutut yang goyah.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 35, 4, 'Katakanlah kepada orang-orang yang tawar hati: "Kuatkanlah hati, janganlah takut! Lihatlah, Allahmu akan datang dengan pembalasan dan dengan ganjaran Allah. Ia sendiri datang menyelamatkan kamu!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 35, 5, 'Pada waktu itu mata orang-orang buta akan dicelikkan, dan telinga orang-orang tuli akan dibuka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 35, 6, 'Pada waktu itu orang lumpuh akan melompat seperti rusa, dan mulut orang bisu akan bersorak-sorai; sebab mata air memancar di padang gurun, dan sungai di padang belantara;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 35, 7, 'tanah pasir yang hangat akan menjadi kolam, dan tanah kersang menjadi sumber-sumber air; di tempat serigala berbaring akan tumbuh tebu dan pandan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 35, 8, 'Di situ akan ada jalan raya, yang akan disebutkan Jalan Kudus; orang yang tidak tahir tidak akan melintasinya, dan orang-orang pandir tidak akan mengembara di atasnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 35, 9, 'Di situ tidak akan ada singa, binatang buas tidak akan menjalaninya dan tidak akan terdapat di sana; orang-orang yang diselamatkan akan berjalan di situ,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 35, 10, 'dan orang-orang yang dibebaskan TUHAN akan pulang dan masuk ke Sion dengan bersorak-sorai, sedang sukacita abadi meliputi mereka; kegirangan dan sukacita akan memenuhi mereka, kedukaan dan keluh kesah akan menjauh.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 36, 1, 'Maka dalam tahun keempat belas zaman raja Hizkia majulah Sanherib, raja Asyur, menyerang segala kota berkubu negeri Yehuda, lalu merebutnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 36, 2, 'Raja Asyur mengutus juru minuman agung dari Lakhis ke Yerusalem kepada raja Hizkia disertai suatu tentara yang besar. Ia mengambil tempat dekat saluran kolam atas di jalan raya pada Padang Tukang Penatu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 36, 3, 'Keluarlah mendapatkan dia Elyakim bin Hilkia, kepala istana, dan Sebna, panitera negara, serta Yoab bin Asaf, bendahara negara.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 36, 4, 'Lalu berkatalah juru minuman agung kepada mereka: "Baiklah katakan kepada Hizkia: Beginilah kata raja agung, raja Asyur: Kepercayaan macam apakah yang kaupegang ini?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 36, 5, 'Kaukira bahwa hanya ucapan bibir saja dapat merupakan rencana dan kekuatan untuk perang! Sekarang, kepada siapa engkau berharap, maka engkau memberontak terhadap aku?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 36, 6, 'Sesungguhnya, engkau berharap kepada tongkat bambu yang patah terkulai itu, yaitu Mesir, yang akan menusuk dan menembus tangan orang yang bertopang kepadanya. Begitulah keadaan Firaun, raja Mesir, bagi semua orang yang berharap kepadanya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 36, 7, 'Dan apabila engkau berkata kepadaku: Kami berharap kepada TUHAN, Allah kami, ?bukankah Dia itu yang bukit-bukit pengorbanan-Nya dan mezbah-mezbah-Nya telah dijauhkan oleh Hizkia sambil berkata kepada Yehuda dan Yerusalem: Di depan mezbah inilah kamu harus sujud menyembah!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 36, 8, 'Maka sekarang, baiklah bertaruh dengan tuanku, raja Asyur: Aku akan memberikan dua ribu ekor kuda kepadamu, jika engkau sanggup memberikan dari pihakmu orang-orang yang mengendarainya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 36, 9, 'Bagaimanakah mungkin engkau memukul mundur satu orang perwira tuanku yang paling kecil? Padahal engkau berharap kepada Mesir dalam hal kereta dan orang-orang berkuda!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 36, 10, 'Sekarangpun, adakah di luar kehendak TUHAN aku maju melawan negeri ini untuk memusnahkannya? TUHAN telah berfirman kepadaku: Majulah menyerang negeri itu dan musnahkanlah itu!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 36, 11, 'Lalu berkatalah Elyakim, Sebna dan Yoah kepada juru minuman agung: "Silakan berbicara dalam bahasa Aram kepada hamba-hambamu ini, sebab kami mengerti; tetapi janganlah berbicara dengan kami dalam bahasa Yehuda sambil didengar oleh rakyat yang ada di atas tembok."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 36, 12, 'Tetapi juru minuman agung berkata: "Adakah tuanku mengutus aku untuk mengucapkan perkataan-perkataan ini hanya kepada tuanmu dan kepadamu saja? Bukankah juga kepada orang-orang yang duduk di atas tembok, yang memakan tahinya dan meminum air kencingnya bersama-sama dengan kamu?"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 36, 13, 'Kemudian berdirilah juru minuman agung dan berserulah ia dengan suara nyaring dalam bahasa Yehuda. Ia berkata: "Dengarlah perkataan raja agung, raja Asyur!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 36, 14, 'Beginilah kata raja: Janganlah Hizkia memperdayakan kamu, sebab ia tidak sanggup melepaskan kamu!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 36, 15, 'Janganlah Hizkia mengajak kamu berharap kepada TUHAN dengan mengatakan: Tentulah TUHAN akan melepaskan kita; kota ini tidak akan diserahkan ke dalam tangan raja Asyur.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 36, 16, 'Janganlah dengarkan Hizkia, sebab beginilah kata raja Asyur: Adakanlah perjanjian penyerahan dengan aku dan datanglah ke luar kepadaku, maka setiap orang dari padamu akan makan dari pohon anggurnya dan dari pohon aranya serta minum dari sumurnya,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 36, 17, 'sampai aku datang dan membawa kamu ke suatu negeri seperti negerimu, suatu negeri yang bergandum dan berair anggur, suatu negeri yang beroti dan berkebun anggur.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 36, 18, 'Jangan sampai Hizkia membujuk kamu dengan mengatakan: TUHAN akan melepaskan kita! Apakah pernah para allah bangsa-bangsa melepaskan negerinya masing-masing dari tangan raja Asyur?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 36, 19, 'Di manakah para allah negeri Hamat dan Arpad? Di manakah para allah negeri Sefarwaim? Apakah mereka telah melepaskan Samaria dari tanganku?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 36, 20, 'Siapakah di antara semua allah negeri-negeri ini yang telah melepaskan negeri mereka dari tanganku, sehingga TUHAN sanggup melepaskan Yerusalem dari tanganku?"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 36, 21, 'Tetapi orang berdiam diri dan tidak menjawab dia sepatah katapun, sebab ada perintah raja, bunyinya: "Jangan kamu menjawab dia!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 36, 22, 'Kemudian pergilah Elyakim bin Hilkia, kepala istana, dan Sebna, panitera negara, dan Yoah bin Asaf, bendahara negara, menghadap Hizkia, dengan pakaian yang dikoyakkan, lalu memberitahukan kepada raja perkataan juru minuman agung.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 1, 'Segera sesudah raja Hizkia mendengar itu, dikoyakkannyalah pakaiannya dan diselubunginyalah badannya dengan kain kabung, lalu masuklah ia ke rumah TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 2, 'Disuruhnyalah juga Elyakim, kepala istana, Sebna, panitera negara, dan yang tua-tua di antara para imam, dengan berselubungkan kain kabung, kepada nabi Yesaya bin Amos.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 3, 'Berkatalah mereka kepadanya: "Beginilah kata Hizkia: Hari ini hari kesesakan, hari hukuman dan penistaan; sebab sudah datang waktunya untuk melahirkan anak, tetapi tidak ada kekuatan untuk melahirkannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 4, 'Mungkin TUHAN, Allahmu, sudah mendengar perkataan juru minuman agung yang telah diutus oleh raja Asyur, tuannya, untuk mencela Allah yang hidup, sehingga TUHAN, Allahmu, mau memberi hukuman karena perkataan-perkataan yang telah didengar-Nya. Maka baiklah engkau menaikkan doa untuk sisa yang masih tinggal ini!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 5, 'Ketika pegawai-pegawai raja Hizkia sampai kepada Yesaya,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 6, 'berkatalah Yesaya kepada mereka: "Beginilah kamu katakan kepada tuanmu: Beginilah firman TUHAN: Janganlah engkau takut terhadap perkataan yang kaudengar yang telah diucapkan oleh budak-budak raja Asyur untuk menghujat Aku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 7, 'Sesungguhnya, Aku akan menyuruh suatu roh masuk di dalamnya, sehingga ia mendengar suatu kabar dan pulang ke negerinya; Aku akan membuat dia mati rebah oleh pedang di negerinya sendiri."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 8, 'Ketika juru minuman agung pulang, didapatinyalah raja Asyur berperang melawan Libna; sebab sudah didengarnya bahwa raja telah berangkat dari Lakhis.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 9, 'Dalam pada itu raja mendengar tentang Tirhaka, raja Etiopia, berita yang demikian: "Ia telah keluar berperang melawan engkau," dan ketika mendengar itu, disuruhnyalah utusan-utusan kepada Hizkia dengan pesan:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 10, '"Beginilah harus kamu katakan kepada Hizkia, raja Yehuda: Janganlah Allahmu yang kaupercayai itu memperdayakan engkau dengan menjanjikan: Yerusalem tidak akan diserahkan ke tangan raja Asyur.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 11, 'Sesungguhnya, engkau ini telah mendengar tentang yang dilakukan raja-raja Asyur kepada segala negeri, yakni bahwa mereka telah menumpasnya; masakan engkau ini akan dilepaskan?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 12, 'Sudahkah para allah dari bangsa-bangsa yang telah dimusnahkan oleh nenek moyangku, dapat melepaskan mereka, yakni Gozan, Haran, Rezef dan bani Eden yang di Telasar?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 13, 'Di manakah raja negeri Hamat dan Arpad raja kota Sefarwaim, raja negeri Hena dan Iwa?"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 14, 'Hizkia menerima surat itu dari tangan para utusan, lalu membacanya; kemudian pergilah ia ke rumah TUHAN dan membentangkan surat itu di hadapan TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 15, 'Hizkia berdoa di hadapan TUHAN, katanya:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 16, '"Ya TUHAN semesta alam, Allah Israel, yang bertakhta di atas kerubim! Hanya Engkau sendirilah Allah segala kerajaan di bumi; Engkaulah yang menjadikan langit dan bumi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 17, 'Sendengkanlah telinga-Mu, ya TUHAN, dan dengarlah; bukalah mata-Mu, ya TUHAN, dan lihatlah; dengarlah segala perkataan Sanherib yang telah dikirimnya untuk mencela Allah yang hidup.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 18, 'Ya TUHAN, memang raja-raja Asyur telah memusnahkan semua bangsa dan negeri-negeri mereka', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 19, 'dan menaruh para allah mereka ke dalam api, sebab mereka bukanlah Allah, hanya buatan tangan manusia, kayu dan batu; sebab itu dapat dibinasakan orang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 20, 'Maka sekarang, ya TUHAN, Allah kami, selamatkanlah kami dari tangannya, supaya segala kerajaan di bumi mengetahui, bahwa hanya Engkau sendirilah TUHAN."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 21, 'Lalu Yesaya bin Amos menyuruh orang kepada Hizkia mengatakan: "Beginilah firman TUHAN, Allah Israel: Tentang yang telah kaudoakan kepada-Ku mengenai Sanherib, raja Asyur,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 22, 'inilah firman yang telah diucapkan TUHAN mengenai dia: Anak dara, yaitu puteri Sion, telah menghina engkau, telah mengolok-olokkan engkau; dan puteri Yerusalem telah geleng-geleng kepala di belakangmu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 23, 'Siapakah yang engkau cela dan engkau hujat? terhadap siapakah engkau menyaringkan suaramu, dan memandang dengan sombong-sombong? Terhadap Yang Mahakudus, Allah Israel!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 24, 'Dengan perantaraan hamba-hambamu engkau telah mencela Tuhan, dan engkau telah berkata: Dengan banyaknya keretaku aku naik ke tempat-tempat tinggi di pegunungan, ke tempat yang paling jauh di gunung Libanon; aku telah menebang pohon-pohon arasnya yang tinggi besar, pohon-pohon sanobarnya yang terpilih; aku telah masuk ke tempat tinggi yang paling ujung, ke hutan pohon-pohonannya yang lebat.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 25, 'Aku ini telah menggali air dan telah minum air; aku telah mengeringkan dengan telapak kakiku segala sungai di Mesir!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 26, 'Bukankah telah kaudengar, bahwa Aku telah menentukannya dari jauh hari dan telah merancangnya dari zaman purbakala? Sekarang Aku mewujudkannya, bahwa engkau membuat sunyi senyap kota-kota yang berkubu menjadi timbunan batu,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 27, 'sedang penduduknya yang tak berdaya menjadi terkejut dan malu; mereka menjadi seperti tumbuh-tumbuhan di padang dan seperti rumput hijau, seperti rumput di atas sotoh, atau gandum yang layu sebelum ia masak.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 28, 'Aku tahu, jika engkau bangun atau duduk, jika keluar atau masuk, atau jika engkau mengamuk terhadap Aku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 29, 'Oleh karena engkau telah mengamuk terhadap Aku, dan kata-kata keangkuhanmu telah naik sampai ke telinga-Ku, maka Aku akan menaruh kelikir-Ku pada hidungmu dan kekang-Ku pada bibirmu, dan Aku akan memulangkan engkau melalui jalan, dari mana engkau datang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 30, 'Dan inilah yang akan menjadi tanda bagimu, hai Hizkia: Dalam tahun ini orang makan apa yang tumbuh sendiri, dan dalam tahun yang kedua, apa yang tumbuh dari tanaman yang pertama, tetapi dalam tahun yang ketiga, menaburlah kamu, menuai, membuat kebun anggur dan memakan buahnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 31, 'Dan orang-orang yang terluput di antara kaum Yehuda, yaitu orang-orang yang masih tertinggal, akan berakar pula ke bawah dan menghasilkan buah ke atas.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 32, 'Sebab dari Yerusalem akan keluar orang-orang yang tertinggal dan dari gunung Sion orang-orang yang terluput; giat cemburu TUHAN semesta alam akan melakukan hal ini.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 33, 'Sebab itu beginilah firman TUHAN mengenai raja Asyur: Ia tidak akan masuk ke kota ini dan tidak akan menembakkan panah ke sana; juga ia tidak akan mendatanginya dengan perisai dan tidak akan menimbun tanah menjadi tembok untuk mengepungnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 34, 'Melalui jalan, dari mana ia datang, ia akan pulang, tetapi ke kota ini ia tidak akan masuk, demikianlah firman TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 35, 'Dan Aku akan memagari kota ini untuk menyelamatkannya, oleh karena Aku dan oleh karena Daud, hamba-Ku."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 36, 'Keluarlah Malaikat TUHAN, lalu dibunuh-Nyalah seratus delapan puluh lima ribu orang di dalam perkemahan Asyur. Keesokan harinya pagi-pagi tampaklah, semuanya bangkai orang-orang mati belaka!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 37, 'Sebab itu berangkatlah Sanherib, raja Asyur dan pulang, lalu tinggallah ia di Niniwe.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 37, 38, 'Pada suatu kali ketika ia sujud menyembah di dalam kuil Nisrokh, allahnya, maka Adramelekh dan Sarezer, anak-anaknya, membunuh dia dengan pedang, dan mereka meloloskan diri ke tanah Ararat. Kemudian Esarhadon, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 38, 1, 'Pada hari-hari itu Hizkia jatuh sakit dan hampir mati. Lalu datanglah nabi Yesaya bin Amos dan berkata kepadanya: "Beginilah firman TUHAN: Sampaikanlah pesan terakhir kepada keluargamu, sebab engkau akan mati, tidak akan sembuh lagi."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 38, 2, 'Lalu Hizkia memalingkan mukanya ke arah dinding dan ia berdoa kepada TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 38, 3, 'Ia berkata: "Ah TUHAN, ingatlah kiranya, bahwa aku telah hidup di hadapan-Mu dengan setia dan dengan tulus hati dan bahwa aku telah melakukan apa yang baik di mata-Mu." Kemudian menangislah Hizkia dengan sangat.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 38, 4, 'Maka berfirmanlah TUHAN kepada Yesaya:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 38, 5, '"Pergilah dan katakanlah kepada Hizkia: Beginilah firman TUHAN, Allah Daud, bapa leluhurmu: Telah Kudengar doamu dan telah Kulihat air matamu. Sesungguhnya Aku akan memperpanjang hidupmu lima belas tahun lagi,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 38, 6, 'dan Aku akan melepaskan engkau dan kota ini dari tangan raja Asyur dan Aku akan memagari kota ini.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 38, 7, 'Inilah yang akan menjadi tanda bagimu dari TUHAN, bahwa TUHAN akan melakukan apa yang telah dijanjikan-Nya:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 38, 8, 'Sesungguhnya, bayang-bayang pada penunjuk matahari buatan Ahas akan Kubuat mundur ke belakang sepuluh tapak yang telah dijalaninya." Maka pada penunjuk matahari itu mataharipun mundurlah ke belakang sepuluh tapak dari jarak yang telah dijalaninya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 38, 9, 'Karangan Hizkia, raja Yehuda, sesudah ia sakit dan sembuh dari penyakitnya:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 38, 10, 'Aku ini berkata: Dalam pertengahan umurku aku harus pergi, ke pintu gerbang dunia orang mati aku dipanggil untuk selebihnya dari hidupku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 38, 11, 'Aku berkata: aku tidak akan melihat TUHAN lagi di negeri orang-orang yang hidup; aku tidak akan melihat seorangpun lagi di antara penduduk dunia.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 38, 12, 'Pondok kediamanku dibongkar dan dibuka seperti kemah gembala; seperti tukang tenun menggulung tenunannya aku mengakhiri hidupku; TUHAN memutus nyawaku dari benang hidup. Dari siang sampai malam Engkau membiarkan aku begitu saja,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 38, 13, 'aku berteriak minta tolong sampai pagi; seperti singa demikianlah TUHAN menghancurkan segala tulang-tulangku; dari siang sampai malam Engkau membiarkan aku begitu saja.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 38, 14, 'Seperti burung layang-layang demikianlah aku menciap-ciap, suaraku redup seperti suara merpati. Mataku habis menengadah ke atas, ya Tuhan, pemerasan terjadi kepadaku; jadilah jaminan bagiku!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 38, 15, 'Apakah yang akan kukatakan dan kuucapkan kepada TUHAN; bukankah Dia yang telah melakukannya? Aku sama sekali tidak dapat tidur karena pahit pedihnya perasaanku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 38, 16, 'Ya Tuhan, karena inilah hatiku mengharapkan Engkau; tenangkanlah rohku, buatlah aku sehat, buatlah aku sembuh!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 38, 17, 'Sesungguhnya, penderitaan yang pahit menjadi keselamatan bagiku; Engkaulah yang mencegah jiwaku dari lobang kebinasaan. Sebab Engkau telah melemparkan segala dosaku jauh dari hadapan-Mu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 38, 18, 'Sebab dunia orang mati tidak dapat mengucap syukur kepada-Mu, dan maut tidak dapat memuji-muji Engkau; orang-orang yang turun ke liang kubur tidak menanti-nanti akan kesetiaan-Mu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 38, 19, 'Tetapi hanyalah orang yang hidup, dialah yang mengucap syukur kepada-Mu, seperti aku pada hari ini; seorang bapa memberitahukan kesetiaan-Mu kepada anak-anaknya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 38, 20, 'TUHAN telah datang menyelamatkan aku! Kami hendak main kecapi, seumur hidup kami di rumah TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 38, 21, 'Kemudian berkatalah Yesaya: "Baiklah diambil sebuah kue ara dan ditaruh pada barah itu, supaya sembuh!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 38, 22, 'Sebelum itu Hizkia telah berkata: "Apakah yang akan menjadi tanda, bahwa aku akan pergi ke rumah TUHAN?"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 39, 1, 'Pada waktu itu Merodakh-Baladan bin Baladan, raja Babel, menyuruh orang membawa surat dan pemberian kepada Hizkia, sebab telah didengarnya bahwa Hizkia sakit tadinya dan sudah kuat kembali.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 39, 2, 'Hizkia bersukacita atas kedatangan mereka, lalu diperlihatkannyalah kepada mereka gedung harta bendanya, emas dan perak, rempah-rempah dan minyak yang berharga, segenap gedung persenjataannya dan segala yang terdapat dalam perbendaharaannya. Tidak ada barang yang tidak diperlihatkan Hizkia kepada mereka di istananya dan di seluruh daerah kekuasaannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 39, 3, 'Kemudian datanglah nabi Yesaya kepada raja Hizkia dan bertanya kepadanya: "Apakah yang telah dikatakan orang-orang ini? Dan dari manakah mereka datang?" Jawab Hizkia: "Mereka datang dari negeri yang jauh, dari Babel!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 39, 4, 'Lalu tanyanya lagi: "Apakah yang telah dilihat mereka di istanamu?" Jawab Hizkia: "Semua yang ada di istanaku telah mereka lihat. Tidak ada barang yang tidak kuperlihatkan kepada mereka di perbendaharaanku."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 39, 5, 'Lalu Yesaya berkata kepada Hizkia: "Dengarkanlah firman TUHAN semesta alam!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 39, 6, 'Sesungguhnya, suatu masa akan datang, bahwa segala yang ada dalam istanamu dan yang disimpan oleh nenek moyangmu sampai hari ini akan diangkut ke Babel. Tidak ada barang yang akan ditinggalkan, demikianlah firman TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 39, 7, 'Dan dari keturunanmu yang akan kauperoleh, akan diambil orang untuk menjadi sida-sida di istana raja Babel."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 39, 8, 'Hizkia menjawab kepada Yesaya: "Sungguh baik firman TUHAN yang engkau ucapkan itu!" Tetapi pikirnya: "Asal ada damai dan keamanan seumur hidupku!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 1, 'Hiburkanlah, hiburkanlah umat-Ku, demikian firman Allahmu,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 2, 'tenangkanlah hati Yerusalem dan serukanlah kepadanya, bahwa perhambaannya sudah berakhir, bahwa kesalahannya telah diampuni, sebab ia telah menerima hukuman dari tangan TUHAN dua kali lipat karena segala dosanya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 3, 'Ada suara yang berseru-seru: "Persiapkanlah di padang gurun jalan untuk TUHAN, luruskanlah di padang belantara jalan raya bagi Allah kita!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 4, 'Setiap lembah harus ditutup, dan setiap gunung dan bukit diratakan; tanah yang berbukit-bukit harus menjadi tanah yang rata, dan tanah yang berlekuk-lekuk menjadi dataran;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 5, 'maka kemuliaan TUHAN akan dinyatakan dan seluruh umat manusia akan melihatnya bersama-sama; sungguh, TUHAN sendiri telah mengatakannya."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 6, 'Ada suara yang berkata: "Berserulah!" Jawabku: "Apakah yang harus kuserukan?" "Seluruh umat manusia adalah seperti rumput dan semua semaraknya seperti bunga di padang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 7, 'Rumput menjadi kering, bunga menjadi layu, apabila TUHAN menghembusnya dengan nafas-Nya. Sesungguhnyalah bangsa itu seperti rumput.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 8, 'Rumput menjadi kering, bunga menjadi layu, tetapi firman Allah kita tetap untuk selama-lamanya."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 9, 'Hai Sion, pembawa kabar baik, naiklah ke atas gunung yang tinggi! Hai Yerusalem, pembawa kabar baik, nyaringkanlah suaramu kuat-kuat, nyaringkanlah suaramu, jangan takut! Katakanlah kepada kota-kota Yehuda: "Lihat, itu Allahmu!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 10, 'Lihat, itu Tuhan ALLAH, Ia datang dengan kekuatan dan dengan tangan-Nya Ia berkuasa. Lihat, mereka yang menjadi upah jerih payah-Nya ada bersama-sama Dia, dan mereka yang diperoleh-Nya berjalan di hadapan-Nya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 11, 'Seperti seorang gembala Ia menggembalakan kawanan ternak-Nya dan menghimpunkannya dengan tangan-Nya; anak-anak domba dipangku-Nya, induk-induk domba dituntun-Nya dengan hati-hati.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 12, 'Siapa yang menakar air laut dengan lekuk tangannya dan mengukur langit dengan jengkal, menyukat debu tanah dengan takaran, menimbang gunung-gunung dengan dacing, atau bukit-bukit dengan neraca?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 13, 'Siapa yang dapat mengatur Roh TUHAN atau memberi petunjuk kepada-Nya sebagai penasihat?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 14, 'Kepada siapa TUHAN meminta nasihat untuk mendapat pengertian, dan siapa yang mengajar TUHAN untuk menjalankan keadilan, atau siapa mengajar Dia pengetahuan dan memberi Dia petunjuk supaya Ia bertindak dengan pengertian?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 15, 'Sesungguhnya, bangsa-bangsa adalah seperti setitik air dalam timba dan dianggap seperti sebutir debu pada neraca. Sesungguhnya, pulau-pulau tidak lebih dari abu halus beratnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 16, 'Libanon tidak mencukupi bagi kayu api dan margasatwanya tidak mencukupi bagi korban bakaran.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 17, 'Segala bangsa seperti tidak ada di hadapan-Nya mereka dianggap-Nya hampa dan sia-sia saja.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 18, 'Jadi dengan siapa hendak kamu samakan Allah, dan apa yang dapat kamu anggap serupa dengan Dia?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 19, 'Patungkah? Tukang besi menuangnya, dan pandai emas melapisinya dengan emas, membuat rantai-rantai perak untuknya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 20, 'Orang yang mendirikan arca, memilih kayu yang tidak lekas busuk, mencari tukang yang ahli untuk menegakkan patung yang tidak lekas goyang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 21, 'Tidakkah kamu tahu? Tidakkah kamu dengar? Tidakkah diberitahukan kepadamu dari mulanya? Tidakkah kamu mengerti dari sejak dasar bumi diletakkan?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 22, 'Dia yang bertakhta di atas bulatan bumi yang penduduknya seperti belalang; Dia yang membentangkan langit seperti kain dan memasangnya seperti kemah kediaman!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 23, 'Dia yang membuat pembesar-pembesar menjadi tidak ada dan yang menjadikan hakim-hakim dunia sia-sia saja!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 24, 'Baru saja mereka ditanam, baru saja mereka ditaburkan, baru saja cangkok mereka berakar di dalam tanah, sudah juga Ia meniup kepada mereka, sehingga mereka kering dan diterbangkan oleh badai seperti jerami.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 25, 'Dengan siapa hendak kamu samakan Aku, seakan-akan Aku seperti dia? firman Yang Mahakudus.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 26, 'Arahkanlah matamu ke langit dan lihatlah: siapa yang menciptakan semua bintang itu dan menyuruh segenap tentara mereka keluar, sambil memanggil nama mereka sekaliannya? Satupun tiada yang tak hadir, oleh sebab Ia maha kuasa dan maha kuat.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 27, 'Mengapakah engkau berkata demikian, hai Yakub, dan berkata begini, hai Israel: "Hidupku tersembunyi dari TUHAN, dan hakku tidak diperhatikan Allahku?"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 28, 'Tidakkah kautahu, dan tidakkah kaudengar? TUHAN ialah Allah kekal yang menciptakan bumi dari ujung ke ujung; Ia tidak menjadi lelah dan tidak menjadi lesu, tidak terduga pengertian-Nya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 29, 'Dia memberi kekuatan kepada yang lelah dan menambah semangat kepada yang tiada berdaya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 30, 'Orang-orang muda menjadi lelah dan lesu dan teruna-teruna jatuh tersandung,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 40, 31, 'tetapi orang-orang yang menanti-nantikan TUHAN mendapat kekuatan baru: mereka seumpama rajawali yang naik terbang dengan kekuatan sayapnya; mereka berlari dan tidak menjadi lesu, mereka berjalan dan tidak menjadi lelah.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 1, 'Dengarkanlah Aku dengan berdiam diri, hai pulau-pulau; hendaklah bangsa-bangsa mendapat kekuatan baru! Biarlah mereka datang mendekat, kemudian berbicara; baiklah kita tampil bersama-sama untuk berperkara!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 2, 'Siapakah yang menggerakkan dia dari timur, menggerakkan dia yang mendapat kemenangan di setiap langkahnya, yang menaklukkan bangsa-bangsa ke depannya dan menurunkan raja-raja? Pedangnya membuat mereka seperti debu dan panahnya membuat mereka seperti jerami yang tertiup.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 3, 'Ia mengejar mereka dan dengan selamat ia melalui jalan yang belum pernah diinjak kakinya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 4, 'Siapakah yang melakukan dan mengerjakan semuanya itu? Dia yang dari dahulu memanggil bangkit keturunan-keturunan, Aku, TUHAN, yang terdahulu, dan bagi mereka yang terkemudian Aku tetap Dia juga.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 5, 'Pulau-pulau telah melihatnya dan menjadi takut, ujung-ujung bumipun menjadi gemetar; mereka datang dan makin mendekat.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 6, 'Yang seorang menolong yang lain dan berkata kepada temannya: "Kuatkanlah hatimu!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 7, 'Tukang besi menguatkan hati tukang emas, dan orang yang memipihkan logam dengan martil menguatkan hati orang yang menempa di atas landasan; ia berkata tentang patrian: "Itu baik," lalu menguatkannya dengan paku-paku, sehingga tidak goyang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 8, 'Tetapi engkau, hai Israel, hamba-Ku, hai Yakub, yang telah Kupilih, keturunan Abraham, yang Kukasihi;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 9, 'engkau yang telah Kuambil dari ujung-ujung bumi dan yang telah Kupanggil dari penjuru-penjurunya, Aku berkata kepadamu: "Engkau hamba-Ku, Aku telah memilih engkau dan tidak menolak engkau";', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 10, 'janganlah takut, sebab Aku menyertai engkau, janganlah bimbang, sebab Aku ini Allahmu; Aku akan meneguhkan, bahkan akan menolong engkau; Aku akan memegang engkau dengan tangan kanan-Ku yang membawa kemenangan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 11, 'Sesungguhnya, semua orang yang bangkit amarahnya terhadap engkau akan mendapat malu dan kena noda; orang-orang yang membantah engkau akan seperti tidak ada dan akan binasa;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 12, 'engkau akan mencari orang-orang yang berkelahi dengan engkau, tetapi tidak akan menemui mereka; orang-orang yang berperang melawan engkau akan seperti tidak ada dan hampa.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 13, 'Sebab Aku ini, TUHAN, Allahmu, memegang tangan kananmu dan berkata kepadamu: "Janganlah takut, Akulah yang menolong engkau."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 14, 'Janganlah takut, hai si cacing Yakub, hai si ulat Israel! Akulah yang menolong engkau, demikianlah firman TUHAN, dan yang menebus engkau ialah Yang Mahakudus, Allah Israel.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 15, 'Sesungguhnya, Aku membuat engkau menjadi papan pengirik yang tajam dan baru, dengan gigi dua jajar; engkau akan mengirik gunung-gunung dan menghancurkannya, dan bukit-bukitpun akan kaubuat seperti sekam.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 16, 'Engkau akan menampi mereka, lalu angin akan menerbangkan mereka, dan badai akan menyerakkan mereka. Tetapi engkau ini akan bersorak-sorak di dalam TUHAN dan bermegah di dalam Yang Mahakudus, Allah Israel.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 17, 'Orang-orang sengsara dan orang-orang miskin sedang mencari air, tetapi tidak ada, lidah mereka kering kehausan; tetapi Aku, TUHAN, akan menjawab mereka, dan sebagai Allah orang Israel Aku tidak akan meninggalkan mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 18, 'Aku akan membuat sungai-sungai memancar di atas bukit-bukit yang gundul, dan membuat mata-mata air membual di tengah dataran; Aku akan membuat padang gurun menjadi telaga dan memancarkan air dari tanah kering.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 19, 'Aku akan menanam pohon aras di padang gurun, pohon penaga, pohon murad dan pohon minyak; Aku akan menumbuhkan pohon sanobar di padang belantara dan pohon berangan serta pohon cemara di sampingnya,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 20, 'supaya semua orang melihat dan mengetahui, memperhatikan dan memahami, bahwa tangan TUHAN yang membuat semuanya ini dan Yang Mahakudus, Allah Israel, yang menciptakannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 21, 'Ajukanlah perkaramu, firman TUHAN, kemukakanlah alasan-alasanmu, firman Raja, Allah Yakub.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 22, 'Biarlah mereka maju dan memberitahukan kepada kami apa yang akan terjadi! Nubuat yang dahulu, beritahukanlah apa artinya, supaya kami memperhatikannya, atau hal-hal yang akan datang, kabarkanlah kepada kami, supaya kami mengetahui kesudahannya!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 23, 'Beritahukanlah hal-hal yang akan datang kemudian, supaya kami mengetahui, bahwa kamu ini sungguh allah; bertindak sajalah, biar secara baik ataupun secara buruk, supaya kami bersama-sama tercengang melihatnya!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 24, 'Sesungguhnya, kamu ini adalah seperti tidak ada dan perbuatan-perbuatanmu adalah hampa; orang yang memilih kamu adalah kejijikan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 25, 'Aku telah menggerakkan seorang dari utara dan ia telah datang, dari sebelah matahari terbit Aku telah memanggil dia dengan namanya. Seperti tukang periuk menginjak-injak tanah liat, demikian dia akan menginjak-injak penguasa-penguasa seperti lumpur.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 26, 'Siapakah yang memberitahukannya dari mulanya, sehingga kami mengetahuinya, dan dari dahulu, sehingga kami mengatakan: "Benarlah dia?" Sungguh, tidak ada orang yang memberitahukannya, tidak ada orang yang mengabarkannya, tidak ada orang yang mendengar sepatah katapun dari padamu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 27, 'Sebagai yang pertama Aku memberitahukannya kepada Sion, dan Aku memberikan orang yang membawa kabar baik kepada Yerusalem.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 28, 'Apabila Aku melihat berkeliling, maka tidak ada seorangpun, dan di antara semua mereka ini tidak ada yang dapat memberi petunjuk, atau yang dapat memberi jawab kalau Aku menanyakan mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 41, 29, 'Sesungguhnya, sekaliannya mereka seperti tidak ada, perbuatan-perbuatan mereka hampa, patung-patung tuangan mereka angin dan kesia-siaan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 1, 'Lihat, itu hamba-Ku yang Kupegang, orang pilihan-Ku, yang kepadanya Aku berkenan. Aku telah menaruh Roh-Ku ke atasnya, supaya ia menyatakan hukum kepada bangsa-bangsa.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 2, 'Ia tidak akan berteriak atau menyaringkan suara atau memperdengarkan suaranya di jalan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 3, 'Buluh yang patah terkulai tidak akan diputuskannya, dan sumbu yang pudar nyalanya tidak akan dipadamkannya, tetapi dengan setia ia akan menyatakan hukum.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 4, 'Ia sendiri tidak akan menjadi pudar dan tidak akan patah terkulai, sampai ia menegakkan hukum di bumi; segala pulau mengharapkan pengajarannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 5, 'Beginilah firman Allah, TUHAN, yang menciptakan langit dan membentangkannya, yang menghamparkan bumi dengan segala yang tumbuh di atasnya, yang memberikan nafas kepada umat manusia yang mendudukinya dan nyawa kepada mereka yang hidup di atasnya:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 6, '"Aku ini, TUHAN, telah memanggil engkau untuk maksud penyelamatan, telah memegang tanganmu; Aku telah membentuk engkau dan memberi engkau menjadi perjanjian bagi umat manusia, menjadi terang untuk bangsa-bangsa,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 7, 'untuk membuka mata yang buta, untuk mengeluarkan orang hukuman dari tempat tahanan dan mengeluarkan orang-orang yang duduk dalam gelap dari rumah penjara.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 8, 'Aku ini TUHAN, itulah nama-Ku; Aku tidak akan memberikan kemuliaan-Ku kepada yang lain atau kemasyhuran-Ku kepada patung.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 9, 'Nubuat-nubuat yang dahulu sekarang sudah menjadi kenyataan, hal-hal yang baru hendak Kuberitahukan. Sebelum hal-hal itu muncul, Aku mengabarkannya kepadamu."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 10, 'Nyanyikanlah nyanyian baru bagi TUHAN dan pujilah Dia dari ujung bumi! Baiklah laut bergemuruh serta segala isinya dan pulau-pulau dengan segala penduduknya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 11, 'Baiklah padang gurun menyaringkan suara dengan kota-kotanya dan dengan desa-desa yang didiami Kedar! Baiklah bersorak-sorai penduduk Bukit Batu, baiklah mereka berseru-seru dari puncak gunung-gunung!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 12, 'Baiklah mereka memberi penghormatan kepada TUHAN, dan memberitakan pujian yang kepada-Nya di pulau-pulau.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 13, 'TUHAN keluar berperang seperti pahlawan, seperti orang perang Ia membangkitkan semangat-Nya untuk bertempur; Ia bertempik sorak, ya, Ia memekik, terhadap musuh-musuh-Nya Ia membuktikan kepahlawanan-Nya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 14, 'Aku membisu dari sejak dahulu kala, Aku berdiam diri, Aku menahan hati-Ku; sekarang Aku mau mengerang seperti perempuan yang melahirkan, Aku mau mengah-mengah dan megap-megap.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 15, 'Aku mau membuat tandus gunung-gunung dan bukit-bukit, dan mau membuat layu segala tumbuh-tumbuhannya; Aku mau membuat sungai-sungai menjadi tanah kering dan mau membuat kering telaga-telaga.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 16, 'Aku mau memimpin orang-orang buta di jalan yang tidak mereka kenal, dan mau membawa mereka berjalan di jalan-jalan yang tidak mereka kenal. Aku mau membuat kegelapan yang di depan mereka menjadi terang dan tanah yang berkeluk-keluk menjadi tanah yang rata. Itulah hal-hal yang hendak Kulakukan kepada mereka, yang pasti akan Kulaksanakan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 17, 'Orang-orang yang percaya kepada patung pahatan akan berpaling ke belakang dan mendapat malu, yaitu orang-orang yang berkata kepada patung tuangan: "Kamulah allah kami!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 18, 'Dengarkanlah, hai orang-orang tuli pandanglah dan lihatlah, hai orang-orang buta!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 19, 'Siapakah yang buta selain dari hamba-Ku, dan yang tuli seperti utusan yang Kusuruh? Siapakah yang buta seperti suruhan-Ku dan yang tuli seperti hamba TUHAN?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 20, 'Engkau melihat banyak, tetapi tidak memperhatikan, engkau memasang telinga, tetapi tidak mendengar.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 21, 'TUHAN telah berkenan demi penyelamatan-Nya untuk memberi pengajaran-Nya yang besar dan mulia;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 22, 'namun mereka suatu bangsa yang dijarah dan dirampok, mereka semua terjebak dalam geronggang-geronggang dan disembunyikan dalam rumah-rumah penjara; mereka telah menjadi jarahan dan tidak ada yang melepaskan, menjadi rampasan dan tidak ada yang berkata: "Kembalikanlah!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 23, 'Siapakah di antara kamu yang mau memasang telinga kepada hal ini, yang mau memperhatikan dan mendengarkannya untuk masa yang kemudian?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 24, 'Siapakah yang menyerahkan Yakub untuk dirampas, dan Israel kepada penjarah? Bukankah itu TUHAN? Sebab kepada-Nya kita telah berdosa, dan orang tidak mau mengikuti jalan yang telah ditunjuk-Nya, dan kepada pengajaran-Nya orang tidak mau mendengar.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 42, 25, 'Maka Ia telah menumpahkan kepadanya kepanasan amarah-Nya dan peperangan yang hebat, yang menghanguskan dia dari sekeliling, tetapi ia tidak menginsafinya, dan yang membakar dia, tetapi ia tidak memperhatikannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 1, 'Tetapi sekarang, beginilah firman TUHAN yang menciptakan engkau, hai Yakub, yang membentuk engkau, hai Israel: "Janganlah takut, sebab Aku telah menebus engkau, Aku telah memanggil engkau dengan namamu, engkau ini kepunyaan-Ku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 2, 'Apabila engkau menyeberang melalui air, Aku akan menyertai engkau, atau melalui sungai-sungai, engkau tidak akan dihanyutkan; apabila engkau berjalan melalui api, engkau tidak akan dihanguskan, dan nyala api tidak akan membakar engkau.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 3, 'Sebab Akulah TUHAN, Allahmu, Yang Mahakudus, Allah Israel, Juruselamatmu. Aku menebus engkau dengan Mesir, dan memberikan Etiopia dan Syeba sebagai gantimu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 4, 'Oleh karena engkau berharga di mata-Ku dan mulia, dan Aku ini mengasihi engkau, maka Aku memberikan manusia sebagai gantimu, dan bangsa-bangsa sebagai ganti nyawamu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 5, 'Janganlah takut, sebab Aku ini menyertai engkau, Aku akan mendatangkan anak cucumu dari timur, dan Aku akan menghimpun engkau dari barat.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 6, 'Aku akan berkata kepada utara: Berikanlah! dan kepada selatan: Janganlah tahan-tahan! Bawalah anak-anak-Ku laki-laki dari jauh, dan anak-anak-Ku perempuan dari ujung-ujung bumi,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 7, 'semua orang yang disebutkan dengan nama-Ku yang Kuciptakan untuk kemuliaan-Ku, yang Kubentuk dan yang juga Kujadikan!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 8, 'Biarlah orang membawa tampil bangsa yang buta sekalipun ada matanya, yang tuli sekalipun ada telinganya!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 9, 'Biarlah berhimpun bersama-sama segala bangsa-bangsa, dan biarlah berkumpul suku-suku bangsa! Siapakah di antara mereka yang dapat memberitahukan hal-hal ini, yang dapat mengabarkan kepada kita hal-hal yang dahulu? Biarlah mereka membawa saksi-saksinya, supaya mereka nyata benar; biarlah orang mendengarnya dan berkata: "Benar demikian!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 10, '"Kamu inilah saksi-saksi-Ku," demikianlah firman TUHAN, "dan hamba-Ku yang telah Kupilih, supaya kamu tahu dan percaya kepada-Ku dan mengerti, bahwa Aku tetap Dia. Sebelum Aku tidak ada Allah dibentuk, dan sesudah Aku tidak akan ada lagi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 11, 'Aku, Akulah TUHAN dan tidak ada juruselamat selain dari pada-Ku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 12, 'Akulah yang memberitahukan, menyelamatkan dan mengabarkan, dan bukannya allah asing yang ada di antaramu. Kamulah saksi-saksi-Ku," demikianlah firman TUHAN, "dan Akulah Allah.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 13, 'Juga seterusnya Aku tetap Dia, dan tidak ada yang dapat melepaskan dari tangan-Ku; Aku melakukannya, siapakah yang dapat mencegahnya?"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 14, 'Beginilah firman TUHAN, Penebusmu, Yang Mahakudus, Allah Israel: "Oleh karena kamu Aku mau menyuruh orang ke Babel dan mau membuka semua palang-palang pintu penjara, dan sorak-sorai orang Kasdim menjadi keluh kesah.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 15, 'Akulah TUHAN, Yang Mahakudus, Allahmu, Rajamu, yang menciptakan Israel."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 16, 'Beginilah firman TUHAN, yang telah membuat jalan melalui laut dan melalui air yang hebat,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 17, 'yang telah menyuruh kereta dan kuda keluar untuk berperang, juga tentara dan orang gagah?mereka terbaring, tidak dapat bangkit, sudah mati, sudah padam sebagai sumbu?,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 18, 'firman-Nya: "Janganlah ingat-ingat hal-hal yang dahulu, dan janganlah perhatikan hal-hal yang dari zaman purbakala!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 19, 'Lihat, Aku hendak membuat sesuatu yang baru, yang sekarang sudah tumbuh, belumkah kamu mengetahuinya? Ya, Aku hendak membuat jalan di padang gurun dan sungai-sungai di padang belantara.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 20, 'Binatang hutan akan memuliakan Aku, serigala dan burung unta, sebab Aku telah membuat air memancar di padang gurun dan sungai-sungai di padang belantara, untuk memberi minum umat pilihan-Ku;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 21, 'umat yang telah Kubentuk bagi-Ku akan memberitakan kemasyhuran-Ku."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 22, '"Sungguh, engkau tidak memanggil Aku, hai Yakub, dan engkau tidak bersusah-susah karena Aku, hai Israel.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 23, 'Engkau tidak membawa domba korban bakaranmu bagi-Ku, dan tidak memuliakan Aku dengan korban sembelihanmu. Aku tidak memberati engkau dengan menuntut korban sajian atau menyusahi engkau dengan menuntut kemenyan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 24, 'Engkau tidak membeli tebu wangi bagi-Ku dengan uang atau mengenyangkan Aku dengan lemak korban sembelihanmu. Tetapi engkau memberati Aku dengan dosamu, engkau menyusahi Aku dengan kesalahanmu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 25, 'Aku, Akulah Dia yang menghapus dosa pemberontakanmu oleh karena Aku sendiri, dan Aku tidak mengingat-ingat dosamu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 26, 'Ingatkanlah Aku, marilah kita berperkara, kemukakanlah segala sesuatu, supaya engkau nyata benar!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 27, 'Bapa leluhurmu yang pertama sudah berdosa, dan jurubicaramu telah memberontak terhadap Aku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 43, 28, 'Jadi Aku terpaksa menajiskan pemimpin-pemimpin tempat kudus, dan terpaksa menyerahkan Yakub untuk ditumpas dan Israel untuk dinista."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 1, '"Tetapi sekarang, dengarlah, hai Yakub, hamba-Ku, dan hai Israel, yang telah Kupilih!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 2, 'Beginilah firman TUHAN yang menjadikan engkau, yang membentuk engkau sejak dari kandungan dan yang menolong engkau: Janganlah takut, hai hamba-Ku Yakub, dan hai Yesyurun, yang telah Kupilih!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 3, 'Sebab Aku akan mencurahkan air ke atas tanah yang haus, dan hujan lebat ke atas tempat yang kering. Aku akan mencurahkan Roh-Ku ke atas keturunanmu, dan berkat-Ku ke atas anak cucumu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 4, 'Mereka akan tumbuh seperti rumput di tengah-tengah air, seperti pohon-pohon gandarusa di tepi sungai.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 5, 'Yang satu akan berkata: Aku kepunyaan TUHAN, yang lain akan menyebut dirinya dengan nama Yakub, dan yang ketiga akan menuliskan pada tangannya: Kepunyaan TUHAN, dan akan menggelari dirinya dengan nama Israel."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 6, 'Beginilah firman TUHAN, Raja dan Penebus Israel, TUHAN semesta alam: "Akulah yang terdahulu dan Akulah yang terkemudian; tidak ada Allah selain dari pada-Ku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 7, 'Siapakah seperti Aku? Biarlah ia menyerukannya, biarlah ia memberitahukannya dan membentangkannya kepada-Ku! Siapakah yang mengabarkan dari dahulu kala hal-hal yang akan datang? Apa yang akan tiba, biarlah mereka memberitahukannya kepada kami!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 8, 'Janganlah gentar dan janganlah takut, sebab memang dari dahulu telah Kukabarkan dan Kuberitahukan hal itu kepadamu. Kamulah saksi-saksi-Ku! Adakah Allah selain dari pada-Ku? Tidak ada Gunung Batu yang lain, tidak ada Kukenal!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 9, 'Orang-orang yang membentuk patung, semuanya adalah kesia-siaan, dan barang-barang kesayangan mereka itu tidaklah memberi faedah. Penyembah-penyembah patung itu tidaklah melihat dan tidaklah mengetahui apa-apa; oleh karena itu mereka akan mendapat malu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 10, 'Siapakah yang membentuk allah dan menuang patung yang tidak memberi faedah?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 11, 'Sesungguhnya, semua pengikutnya akan mendapat malu, dan tukang-tukangnya adalah manusia belaka. Biarlah mereka semua berkumpul dan bangkit berdiri! Mereka akan gentar dan mendapat malu bersama-sama.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 12, 'Tukang besi membuatnya dalam bara api dan menempanya dengan palu, ia mengerjakannya dengan segala tenaga yang ada di tangannya. Bahkan ia menahan lapar sehingga habislah tenaganya, dan ia tidak minum air sehingga ia letih lesu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 13, 'Tukang kayu merentangkan tali pengukur dan membuat bagan sebuah patung dengan kapur merah; ia mengerjakannya dengan pahat dan menggarisinya dengan jangka, lalu ia memberi bentuk seorang laki-laki kepadanya, seperti seorang manusia yang tampan, dan selanjutnya ditempatkan dalam kuil.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 14, 'Mungkin ia menebang pohon-pohon aras atau ia memilih pohon saru atau pohon tarbantin, lalu membiarkannya tumbuh menjadi besar di antara pohon-pohon di hutan, atau ia menanam pohon salam, lalu hujan membuatnya besar.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 15, 'Dan kayunya menjadi kayu api bagi manusia, yang memakainya untuk memanaskan diri; lagipula ia menyalakannya untuk membakar roti. Tetapi juga ia membuatnya menjadi allah lalu menyembah kepadanya; ia mengerjakannya menjadi patung lalu sujud kepadanya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 16, 'Setengahnya dibakarnya dalam api dan di atasnya dipanggangnya daging. Lalu ia memakan daging yang dipanggang itu sampai kenyang; ia memanaskan diri sambil berkata: "Ha, aku sudah menjadi panas, aku telah merasakan kepanasan api."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 17, 'Dan sisa kayu itu dikerjakannya menjadi allah, menjadi patung sembahannya; ia sujud kepadanya, ia menyembah dan berdoa kepadanya, katanya: "Tolonglah aku, sebab engkaulah allahku!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 18, 'Orang seperti itu tidak mengetahui apa-apa dan tidak mengerti apa-apa, sebab matanya melekat tertutup, sehingga tidak dapat melihat, dan hatinya tertutup juga, sehingga tidak dapat memahami.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 19, 'Tidak ada yang mempertimbangkannya, tidak ada cukup pengetahuan atau pengertian untuk mengatakan: "Setengahnya sudah kubakar dalam api dan di atas baranya juga sudah kubakar roti, sudah kupanggang daging, lalu kumakan. Masakan sisanya akan kubuat menjadi dewa kekejian? Masakan aku akan menyembah kepada kayu kering?"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 20, 'Orang yang sibuk dengan abu belaka, disesatkan oleh hatinya yang tertipu; ia tidak dapat menyelamatkan jiwanya atau mengatakan: "Bukankah dusta yang menjadi peganganku?"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 21, 'Ingatlah semuanya ini, hai Yakub, sebab engkaulah hamba-Ku, hai Israel. Aku telah membentuk engkau, engkau adalah hamba-Ku; hai Israel, engkau tidak Kulupakan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 22, 'Aku telah menghapus segala dosa pemberontakanmu seperti kabut diterbangkan angin dan segala dosamu seperti awan yang tertiup. Kembalilah kepada-Ku, sebab Aku telah menebus engkau!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 23, 'Bersorak-sorailah, hai langit, sebab TUHAN telah bertindak, bertempiksoraklah, hai rahim bumi! Bergembiralah dengan sorak-sorai, hai gunung-gunung, hai hutan serta segala pohon di dalamnya! Sebab TUHAN telah menebus Yakub, dan Ia telah memperlihatkan keagungan-Nya dalam hal Israel.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 24, 'Beginilah firman TUHAN, Penebusmu, yang membentuk engkau sejak dari kandungan; "Akulah TUHAN, yang menjadikan segala sesuatu, yang seorang diri membentangkan langit, yang menghamparkan bumi?siapakah yang mendampingi Aku? ?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 25, 'Akulah yang meniadakan tanda-tanda peramal pembohong dan mempermain-mainkan tukang-tukang tenung; yang membuat orang-orang bijaksana mundur ke belakang, dan membalikkan pengetahuan mereka menjadi kebodohan;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 26, 'Akulah yang menguatkan perkataan hamba-hamba-Ku dan melaksanakan keputusan-keputusan yang diberitakan utusan-utusan-Ku; yang berkata tentang Yerusalem: Baiklah ia didiami! dan tentang kota-kota Yehuda: Baiklah ia dibangun, Aku mau mendirikan kembali reruntuhannya!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 27, 'Akulah yang berkata kepada tubir lautan: Jadilah kering, Aku mau mengeringkan sungai-sungaimu!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 44, 28, 'Akulah yang berkata tentang Koresh: Dia gembala-Ku; segala kehendak-Ku akan digenapinya dengan mengatakan tentang Yerusalem: Baiklah ia dibangun! dan tentang Bait Suci: Baiklah diletakkan dasarnya!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 1, 'Beginilah firman TUHAN: "Inilah firman-Ku kepada orang yang Kuurapi, kepada Koresh yang tangan kanannya Kupegang supaya Aku menundukkan bangsa-bangsa di depannya dan melucuti raja-raja, supaya Aku membuka pintu-pintu di depannya dan supaya pintu-pintu gerbang tidak tinggal tertutup:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 2, 'Aku sendiri hendak berjalan di depanmu dan hendak meratakan gunung-gunung, hendak memecahkan pintu-pintu tembaga dan hendak mematahkan palang-palang besi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 3, 'Aku akan memberikan kepadamu harta benda yang terpendam dan harta kekayaan yang tersembunyi, supaya engkau tahu, bahwa Akulah TUHAN, Allah Israel, yang memanggil engkau dengan namamu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 4, 'Oleh karena hamba-Ku Yakub dan Israel, pilihan-Ku, maka Aku memanggil engkau dengan namamu, menggelari engkau, sekalipun engkau tidak mengenal Aku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 5, 'Akulah TUHAN dan tidak ada yang lain; kecuali Aku tidak ada Allah. Aku telah mempersenjatai engkau, sekalipun engkau tidak mengenal Aku,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 6, 'supaya orang tahu dari terbitnya matahari sampai terbenamnya, bahwa tidak ada yang lain di luar Aku. Akulah TUHAN dan tidak ada yang lain,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 7, 'yang menjadikan terang dan menciptakan gelap, yang menjadikan nasib mujur dan menciptakan nasib malang; Akulah TUHAN yang membuat semuanya ini.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 8, 'Hai langit, teteskanlah keadilan dari atas, dan baiklah awan-awan mencurahkannya! Baiklah bumi membukakan diri dan bertunaskan keselamatan, dan baiklah ditumbuhkannya keadilan! Akulah TUHAN yang menciptakan semuanya ini."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 9, 'Celakalah orang yang berbantah dengan Pembentuknya; dia tidak lain dari beling periuk saja! Adakah tanah liat berkata kepada pembentuknya: "Apakah yang kaubuat?" atau yang telah dibuatnya: "Engkau tidak punya tangan!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 10, 'Celakalah orang yang berkata kepada ayahnya: "Apakah yang kauperanakkan?" dan kepada ibunya: "Apakah yang kaulahirkan?"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 11, 'Beginilah firman TUHAN, Yang Mahakudus, Allah dan Pembentuk Israel: "Kamukah yang mengajukan pertanyaan kepada-Ku mengenai anak-anak-Ku, atau memberi perintah kepada-Ku mengenai yang dibuat tangan-Ku?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 12, 'Akulah yang menjadikan bumi dan yang menciptakan manusia di atasnya; tangan-Kulah yang membentangkan langit, dan Akulah yang memberi perintah kepada seluruh tentaranya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 13, 'Akulah yang menggerakkan Koresh untuk maksud penyelamatan, dan Aku akan meratakan segala jalannya; dialah yang akan membangun kota-Ku dan yang akan melepaskan orang-orang-Ku yang ada dalam pembuangan, tanpa bayaran dan tanpa suap," firman TUHAN semesta alam.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 14, 'Beginilah firman TUHAN: "Hasil tanah dari Mesir dan segala laba dari Etiopia dan orang-orang Syeba, orang-orang yang tinggi perawakannya, akan pindah kepadamu dan menjadi kepunyaanmu, mereka akan berjalan di belakangmu dengan dirantai; mereka akan sujud kepadamu dan akan membujuk engkau, katanya: Hanya di tengah-tengahmu ada Allah, dan tidak ada yang lain; di samping Dia tidak ada Allah!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 15, 'Sungguh, Engkau Allah yang menyembunyikan diri, Allah Israel, Juruselamat.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 16, 'Tetapi tukang-tukang berhala harus mundur dengan penuh noda, semuanya akan mendapat malu dan kena noda juga.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 17, 'Sedangkan Israel diselamatkan oleh TUHAN dengan keselamatan yang selama-lamanya; kamu tidak akan mendapat malu dan tidak akan kena noda sampai selamanya dan seterusnya."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 18, 'Sebab beginilah firman TUHAN, yang menciptakan langit, ?Dialah Allah?yang membentuk bumi dan menjadikannya dan yang menegakkannya, ?dan Ia menciptakannya bukan supaya kosong, tetapi Ia membentuknya untuk didiami?:"Akulah TUHAN dan tidak ada yang lain.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 19, 'Tidak pernah Aku berkata dengan sembunyi atau di tempat bumi yang gelap. Tidak pernah Aku menyuruh keturunan Yakub untuk mencari Aku dengan sia-sia! Aku, TUHAN, selalu berkata benar, selalu memberitakan apa yang lurus."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 20, '"Berhimpunlah dan datanglah, tampillah bersama-sama, hai kamu sekalian yang terluput di antara bangsa-bangsa! Tiada berpengetahuan orang-orang yang mengarak patung dari kayu dan yang berdoa kepada allah yang tidak dapat menyelamatkan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 21, 'Beritahukanlah dan kemukakanlah alasanmu, ya, biarlah mereka berunding bersama-sama: Siapakah yang mengabarkan hal ini dari zaman purbakala, dan memberitahukannya dari sejak dahulu? Bukankah Aku, TUHAN? Tidak ada yang lain, tidak ada Allah selain dari pada-Ku! Allah yang adil dan Juruselamat, tidak ada yang lain kecuali Aku!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 22, 'Berpalinglah kepada-Ku dan biarkanlah dirimu diselamatkan, hai ujung-ujung bumi! Sebab Akulah Allah dan tidak ada yang lain.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 23, 'Demi Aku sendiri Aku telah bersumpah, dari mulut-Ku telah keluar kebenaran, suatu firman yang tidak dapat ditarik kembali: dan semua orang akan bertekuk lutut di hadapan-Ku, dan akan bersumpah setia dalam segala bahasa,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 24, 'sambil berkata: Keadilan dan kekuatan hanya ada di dalam TUHAN. Semua orang yang telah bangkit amarahnya terhadap Dia akan datang kepada-Nya dan mendapat malu,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 45, 25, 'tetapi seluruh keturunan Israel akan nyata benar dan akan bermegah di dalam TUHAN."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 46, 1, 'Dewa Bel sudah ditundukkan, dewa Nebo sudah direbahkan, patung-patungnya sudah diangkut di atas binatang, di atas hewan; yang pernah kamu arak, sekarang telah dimuatkan sebagai beban pada binatang yang lelah,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 46, 2, 'yang tidak dapat menyelamatkan bebannya itu. Dewa-dewa itu bersama-sama direbahkan dan ditundukkan dan mereka sendiri harus pergi sebagai tawanan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 46, 3, '"Dengarkanlah Aku, hai kaum keturunan Yakub, hai semua orang yang masih tinggal dari keturunan Israel, hai orang-orang yang Kudukung sejak dari kandungan, hai orang-orang yang Kujunjung sejak dari rahim.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 46, 4, 'Sampai masa tuamu Aku tetap Dia dan sampai masa putih rambutmu Aku menggendong kamu. Aku telah melakukannya dan mau menanggung kamu terus; Aku mau memikul kamu dan menyelamatkan kamu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 46, 5, 'Kepada siapakah kamu hendak menyamakan Aku, hendak membandingkan dan mengumpamakan Aku, sehingga kami sama?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 46, 6, 'Orang mengeluarkan emas dari dalam kantongnya dan menimbang perak dengan dacing, mereka mengupah tukang emas untuk membuat allah dari bahan itu, lalu mereka menyembahnya, juga sujud kepadanya!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 46, 7, 'Mereka mengangkatnya ke atas bahu dan memikulnya, lalu menaruhnya di tempatnya; di situ ia berdiri dan tidak dapat beralih dari tempatnya. Sekalipun orang berseru kepadanya, ia tidak menjawab dan ia tidak menyelamatkan mereka dari kesesakannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 46, 8, 'Ingatlah hal itu dan jadilah malu, pertimbangkanlah dalam hati, hai orang-orang pemberontak!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 46, 9, 'Ingatlah hal-hal yang dahulu dari sejak purbakala, bahwasanya Akulah Allah dan tidak ada yang lain, Akulah Allah dan tidak ada yang seperti Aku,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 46, 10, 'yang memberitahukan dari mulanya hal yang kemudian dan dari zaman purbakala apa yang belum terlaksana, yang berkata: Keputusan-Ku akan sampai, dan segala kehendak-Ku akan Kulaksanakan,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 46, 11, 'yang memanggil burung buas dari timur, dan orang yang melaksanakan putusan-Ku dari negeri yang jauh. Aku telah mengatakannya, maka Aku hendak melangsungkannya, Aku telah merencanakannya, maka Aku hendak melaksanakannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 46, 12, 'Dengarkanlah Aku hai orang-orang yang congkak, orang-orang yang jauh dari kebenaran:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 46, 13, 'Keselamatan yang dari pada-Ku tidak jauh lagi, sebab Aku telah mendekatkannya dan kelepasan yang Kuberikan tidak bertangguh lagi; Aku akan memberikan kelepasan di Sion dan keagungan-Ku kepada Israel."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 47, 1, 'Turunlah dan duduklah di atas debu, hai anak dara, puteri Babel! Duduklah di tanah dengan tidak bertakhta, hai puteri Kasdim! Sebab engkau tidak akan disebutkan lagi manis dan genit.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 47, 2, 'Ambillah batu kilangan dan gilinglah tepung, bukalah kerudungmu; angkatlah sarungmu, singkapkanlah paha, seberangilah sungai-sungai!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 47, 3, 'Biarlah auratmu tersingkap dan aibmu kelihatan! Aku akan mengadakan pembalasan dan tidak menyayangkan seorangpun,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 47, 4, 'kata Penebus kami, TUHAN semesta alam nama-Nya, Yang Mahakudus, Allah Israel.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 47, 5, 'Duduklah dengan berdiam diri dan masuklah ke dalam gelap, hai puteri Kasdim! Sebab engkau tidak akan disebutkan lagi ratu atas kerajaan-kerajaan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 47, 6, 'Aku tadinya murka terhadap umat-Ku, menajiskan milik pusaka-Ku, dan menyerahkannya ke dalam tanganmu; dan engkau tidak menaruh belas kasihan kepada mereka, bahkan sangat memberatkan kukmu kepada orang yang tua.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 47, 7, 'Katamu tadinya: "Untuk selama-lamanya aku tetap menjadi ratu!" sedang engkau tidak menyadari dan tidak memikirkan kesudahan semuanya itu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 47, 8, 'Oleh sebab itu, dengarlah ini, hai orang yang hidup bermanja-manja, yang duduk-duduk dengan tenang, yang berkata dalam hatimu: "Tiada yang lain di sampingku! Aku tidak akan jadi janda dan tidak akan menjadi punah!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 47, 9, 'Kedua hal itu akan menimpa engkau dalam sekejap mata, pada satu hari juga. Kepunahan dan kejandaan dengan sepenuhnya akan menimpa engkau, sekalipun banyak sihirmu dan sangat kuat manteramu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 47, 10, 'Engkau tadinya merasa aman dalam kejahatanmu, katamu: "Tiada yang melihat aku!" Kebijaksanaanmu dan pengetahuanmu itulah yang menyesatkan engkau, sehingga engkau berkata dalam hatimu: "Tiada yang lain di sampingku!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 47, 11, 'Tetapi malapetaka akan menimpa engkau, engkau tidak tahu mempergunakan jampimu terhadapnya; bencana akan jatuh atasmu, engkau tidak sanggup menampiknya dengan mempersembahkan korban; kebinasaan akan menimpa engkau dengan sekonyong-konyong, yang tidak terduga olehmu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 47, 12, 'Bertahan sajalah dengan segala manteramu dan sihirmu yang banyak itu, yang telah kaurepotkan dari sejak kecilmu; mungkin engkau sanggup mendatangkan bantuan, mungkin engkau dapat menimbulkan ketakutan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 47, 13, 'Engkau telah payah karena banyaknya nasihat! Biarlah tampil dan menyelamatkan engkau orang-orang yang meneliti segala penjuru langit, yang menilik bintang-bintang dan yang pada setiap bulan baru memberitahukan apa yang akan terjadi atasmu!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 47, 14, 'Sesungguhnya, mereka sebagai jerami yang dibakar api; mereka tidak dapat melepaskan nyawanya dari kuasa nyala api; api itu bukan bara api untuk memanaskan diri, bukan api untuk berdiang!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 47, 15, 'Demikianlah faedahnya bagimu dari tukang-tukang jampi itu, yang telah kaurepotkan dari sejak kecilmu; masing-masing mereka terhuyung-huyung ke segala jurusan, tidak ada yang dapat menyelamatkan engkau.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 48, 1, 'Dengarlah firman ini, hai kaum keturunan Yakub, yang menyebutkan dirinya dengan nama Israel dan yang adalah keturunan Yehuda, yang bersumpah demi nama TUHAN dan mengakui Allah Israel?tetapi bukan dengan sungguh-sungguh dan dengan tulus hati?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 48, 2, 'bahkan mereka menyebutkan dirinya menurut kota kudus dan mereka bertopang kepada Allah Israel, TUHAN semesta alam nama-Nya;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 48, 3, 'firman TUHAN: "Hal-hal yang terjadi di masa yang lampau telah Kuberitahukan dari sejak dahulu, Aku telah mengucapkannya dan telah mengabarkannya. Kemudian dengan sekonyong-konyong Aku melaksanakannya juga dan semuanya itu sudah menjadi kenyataan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 48, 4, 'Oleh karena Aku tahu, bahwa engkau tegar tengkuk, keras kepala dan berkepala batu,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 48, 5, 'maka Aku memberitahukannya kepadamu dari sejak dahulu; sebelum hal itu menjadi kenyataan, Aku mengabarkannya kepadamu, supaya jangan engkau berkata: Berhalaku yang melakukannya, patung pahatanku dan patung tuanganku yang memerintahkannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 48, 6, 'Engkau telah mendengar semuanya itu dan sekarang engkau harus melihatnya; tidakkah kamu sendiri mau mengakuinya? Aku mengabarkan kepadamu hal-hal yang baru dari sejak sekarang, dan hal-hal yang tersimpan yang belum kauketahui.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 48, 7, 'Baru sekarang hal-hal itu diciptakan dan bukan dari sejak dahulu, dan sebelumnya engkau tidak mendengarnya, supaya jangan engkau berkata: Memang aku telah mengetahuinya!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 48, 8, 'Engkau tidak mendengarnya ataupun mengetahuinya, juga telingamu tidak terbuka dari sejak dahulu; tetapi Aku telah mengetahui, bahwa engkau berbuat khianat sekeji-kejinya, dan bahwa orang menyebutkan engkau: pemberontak sejak dari kandungan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 48, 9, 'Oleh karena nama-Ku Aku menahan amarah-Ku dan oleh karena kemasyhuran-Ku Aku mengasihani engkau, sehingga Aku tidak melenyapkan engkau.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 48, 10, 'Sesungguhnya, Aku telah memurnikan engkau, namun bukan seperti perak, tetapi Aku telah menguji engkau dalam dapur kesengsaraan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 48, 11, 'Aku akan melakukannya oleh karena Aku, ya oleh karena Aku sendiri, sebab masakan nama-Ku akan dinajiskan? Aku tidak akan memberikan kemuliaan-Ku kepada yang lain!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 48, 12, '"Dengarkanlah Aku, hai Yakub, dan engkau Israel yang Kupanggil! Akulah yang tetap sama, Akulah yang terdahulu, Akulah juga yang terkemudian!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 48, 13, 'Tangan-Ku juga meletakkan dasar bumi, dan tangan kanan-Ku membentangkan langit. Ketika Aku menyebut namanya, semuanya bermunculan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 48, 14, 'Berhimpunlah kamu sekalian dan dengarlah! Siapakah di antara mereka memberitahukan semuanya ini? Dia yang dikasihi TUHAN akan melaksanakan kehendak TUHAN terhadap Babel dan menunjukkan kekuatan tangan TUHAN kepada orang Kasdim.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 48, 15, 'Aku, Akulah yang mengatakannya dan yang memanggil dia juga, Akulah yang mendatangkan dia, dan segala usahanya akan berhasil.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 48, 16, 'Mendekatlah kepada-Ku, dengarlah ini: Dari dahulu tidak pernah Aku berkata dengan sembunyi dan pada waktu hal itu terjadi Aku ada di situ." Dan sekarang, Tuhan ALLAH mengutus aku dengan Roh-Nya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 48, 17, 'Beginilah firman TUHAN, Penebusmu, Yang Mahakudus, Allah Israel: "Akulah TUHAN, Allahmu, yang mengajar engkau tentang apa yang memberi faedah, yang menuntun engkau di jalan yang harus kautempuh.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 48, 18, 'Sekiranya engkau memperhatikan perintah-perintah-Ku, maka damai sejahteramu akan seperti sungai yang tidak pernah kering, dan kebahagiaanmu akan terus berlimpah seperti gelombang-gelombang laut yang tidak pernah berhenti,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 48, 19, 'maka keturunanmu akan seperti pasir dan anak cucumu seperti kersik banyaknya; nama mereka tidak akan dilenyapkan atau ditiadakan dari hadapan-Ku."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 48, 20, 'Keluarlah dari Babel, larilah dari Kasdim! Beritahukanlah dengan suara sorak-sorai dan kabarkanlah hal ini! Siarkanlah itu sampai ke ujung bumi! Katakanlah: "TUHAN telah menebus Yakub, hamba-Nya!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 48, 21, 'Mereka tidak menderita haus, ketika Ia memimpin mereka melalui tempat-tempat yang tandus; Ia mengeluarkan air dari gunung batu bagi mereka; Ia membelah gunung batu, maka memancarlah air.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 48, 22, '"Tidak ada damai sejahtera bagi orang-orang fasik!" firman TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 1, 'Dengarkanlah aku, hai pulau-pulau, perhatikanlah, hai bangsa-bangsa yang jauh! TUHAN telah memanggil aku sejak dari kandungan telah menyebut namaku sejak dari perut ibuku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 2, 'Ia telah membuat mulutku sebagai pedang yang tajam dan membuat aku berlindung dalam naungan tangan-Nya. Ia telah membuat aku menjadi anak panah yang runcing dan menyembunyikan aku dalam tabung panah-Nya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 3, 'Ia berfirman kepadaku: "Engkau adalah hamba-Ku, Israel, dan olehmu Aku akan menyatakan keagungan-Ku."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 4, 'Tetapi aku berkata: "Aku telah bersusah-susah dengan percuma, dan telah menghabiskan kekuatanku dengan sia-sia dan tak berguna; namun, hakku terjamin pada TUHAN dan upahku pada Allahku."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 5, 'Maka sekarang firman TUHAN, yang membentuk aku sejak dari kandungan untuk menjadi hamba-Nya, untuk mengembalikan Yakub kepada-Nya, dan supaya Israel dikumpulkan kepada-Nya?maka aku dipermuliakan di mata TUHAN, dan Allahku menjadi kekuatanku?,firman-Nya:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 6, '"Terlalu sedikit bagimu hanya untuk menjadi hamba-Ku, untuk menegakkan suku-suku Yakub dan untuk mengembalikan orang-orang Israel yang masih terpelihara. Tetapi Aku akan membuat engkau menjadi terang bagi bangsa-bangsa supaya keselamatan yang dari pada-Ku sampai ke ujung bumi."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 7, 'Beginilah firman TUHAN, Penebus Israel, Allahnya yang Mahakudus, kepada dia yang dihinakan orang, kepada dia yang dijijikkan bangsa-bangsa, kepada hamba penguasa-penguasa: "Raja-raja akan melihat perbuatan-Ku, lalu bangkit memberi hormat, dan pembesar-pembesar akan sujud menyembah, oleh karena TUHAN yang setia oleh karena Yang Mahakudus, Allah Israel, yang memilih engkau."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 8, 'Beginilah firman TUHAN: "Pada waktu Aku berkenan, Aku akan menjawab engkau, dan pada hari Aku menyelamatkan, Aku akan menolong engkau; Aku telah membentuk dan memberi engkau, menjadi perjanjian bagi umat manusia, untuk membangunkan bumi kembali dan untuk membagi-bagikan tanah pusaka yang sudah sunyi sepi,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 9, 'untuk mengatakan kepada orang-orang yang terkurung: Keluarlah! kepada orang-orang yang ada di dalam gelap: Tampillah! Di sepanjang jalan mereka seperti domba yang tidak pernah kekurangan rumput, dan di segala bukit gundulpun tersedia rumput bagi mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 10, 'Mereka tidak menjadi lapar atau haus; angin hangat dan terik matahari tidak akan menimpa mereka, sebab Penyayang mereka akan memimpin mereka dan akan menuntun mereka ke dekat sumber-sumber air.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 11, 'Aku akan membuat segala gunung-Ku menjadi jalan dan segala jalan raya-Ku akan Kuratakan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 12, 'Lihat, ada orang yang datang dari jauh, ada dari utara dan dari barat, dan ada dari tanah Sinim."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 13, 'Bersorak-sorailah, hai langit, bersorak-soraklah, hai bumi, dan bergembiralah dengan sorak-sorai, hai gunung-gunung! Sebab TUHAN menghibur umat-Nya dan menyayangi orang-orang-Nya yang tertindas.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 14, 'Sion berkata: "TUHAN telah meninggalkan aku dan Tuhanku telah melupakan aku."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 15, 'Dapatkah seorang perempuan melupakan bayinya, sehingga ia tidak menyayangi anak dari kandungannya? Sekalipun dia melupakannya, Aku tidak akan melupakan engkau.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 16, 'Lihat, Aku telah melukiskan engkau di telapak tangan-Ku; tembok-tembokmu tetap di ruang mata-Ku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 17, 'Orang-orang yang membangun engkau datang bersegera, tetapi orang-orang yang merombak dan merusak engkau meninggalkan engkau.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 18, 'Angkatlah mukamu dan lihatlah ke sekeliling, mereka semua berhimpun datang kepadamu. Demi Aku yang hidup, demikianlah firman TUHAN, sungguh, mereka semua akan kaupakai sebagai perhiasan, dan mereka akan kaulilitkan, seperti yang dilakukan pengantin perempuan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 19, 'Sebab tempat-tempatmu yang tandus dan sunyi sepi dan negerimu yang dirombak, sungguh, sekarang terlalu sempit untuk sekian banyak pendudukmu dan orang-orang yang mau menelan engkau akan menjauh.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 20, 'Malahan, anak-anakmu yang kausangka hilang akan berkata kepadamu: "Tempat itu terlalu sempit bagiku, menyisihlah, supaya aku dapat diam di situ!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 21, 'Maka engkau akan berkata dalam hatimu: "Siapakah yang telah melahirkan sekaliannya ini bagiku? Bukankah aku bulus dan mandul, diangkut ke dalam pembuangan dan disingkirkan? Tetapi anak-anak ini, siapakah yang membesarkan mereka? Sesungguhnya, aku tertinggal seorang diri, tetapi mereka ini, dari manakah datangnya?"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 22, 'Beginilah firman Tuhan ALLAH: "Lihat, Aku akan mengangkat tangan-Ku sebagai tanda untuk bangsa-bangsa dan memasang panji-panji-Ku untuk suku-suku bangsa, maka mereka akan menggendong anak-anakmu laki-laki dan anak-anakmu perempuan akan didukung di atas bahunya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 23, 'Maka raja-raja akan menjadi pengasuhmu dan permaisuri-permaisuri mereka menjadi inangmu. Mereka akan sujud kepadamu dengan mukanya sampai ke tanah dan akan menjilat debu kakimu. Maka engkau akan mengetahui, bahwa Akulah TUHAN, dan bahwa orang-orang yang menanti-nantikan Aku tidak akan mendapat malu."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 24, 'Dapatkah direbut kembali jarahan dari pahlawan atau dapatkah lolos tawanan orang gagah?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 25, 'Sungguh, beginilah firman TUHAN: "Tawanan pahlawanpun dapat direbut kembali, dan jarahan orang gagah dapat lolos, sebab Aku sendiri akan melawan orang yang melawan engkau dan Aku sendiri akan menyelamatkan anak-anakmu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 49, 26, 'Aku akan memaksa orang-orang yang menindas engkau memakan dagingnya sendiri, dan mereka akan mabuk minum darahnya sendiri, seperti orang mabuk minum anggur baru, supaya seluruh umat manusia mengetahui, bahwa Aku, TUHAN, adalah Juruselamatmu dan Penebusmu, Yang Mahakuat, Allah Yakub."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 50, 1, 'Beginilah firman TUHAN: "Di manakah gerangan surat cerai ibumu tanda Aku telah mengusir dia? Atau kepada siapakah di antara penagih hutang-Ku Aku pernah menjual engkau? Sesungguhnya, oleh karena kesalahanmu sendiri kamu terjual dan oleh karena pelanggaranmu sendiri ibumu diusir.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 50, 2, 'Mengapa ketika Aku datang tidak ada orang, dan ketika Aku memanggil tidak ada yang menjawab? Mungkinkah tangan-Ku terlalu pendek untuk membebaskan atau tidak adakah kekuatan pada-Ku untuk melepaskan? Sesungguhnya, dengan hardik-Ku Aku mengeringkan laut, Aku membuat sungai-sungai menjadi padang gurun; ikan-ikannya berbau amis karena tidak ada air dan mati kehausan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 50, 3, 'Aku mengenakan pakaian kelam kepada langit dan menyelimutinya dengan kain kabung."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 50, 4, 'Tuhan ALLAH telah memberikan kepadaku lidah seorang murid, supaya dengan perkataan aku dapat memberi semangat baru kepada orang yang letih lesu. Setiap pagi Ia mempertajam pendengaranku untuk mendengar seperti seorang murid.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 50, 5, 'Tuhan ALLAH telah membuka telingaku, dan aku tidak memberontak, tidak berpaling ke belakang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 50, 6, 'Aku memberi punggungku kepada orang-orang yang memukul aku, dan pipiku kepada orang-orang yang mencabut janggutku. Aku tidak menyembunyikan mukaku ketika aku dinodai dan diludahi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 50, 7, 'Tetapi Tuhan ALLAH menolong aku; sebab itu aku tidak mendapat noda. Sebab itu aku meneguhkan hatiku seperti keteguhan gunung batu karena aku tahu, bahwa aku tidak akan mendapat malu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 50, 8, 'Dia yang menyatakan aku benar telah dekat. Siapakah yang berani berbantah dengan aku? Marilah kita tampil bersama-sama! Siapakah lawanku berperkara? Biarlah ia mendekat kepadaku!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 50, 9, 'Sesungguhnya, Tuhan ALLAH menolong aku; siapakah yang berani menyatakan aku bersalah? Sesungguhnya, mereka semua akan memburuk seperti pakaian yang sudah usang; ngengat akan memakan mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 50, 10, 'Siapa di antaramu yang takut akan TUHAN dan mendengarkan suara hamba-Nya? Jika ia hidup dalam kegelapan dan tidak ada cahaya bersinar baginya, baiklah ia percaya kepada nama TUHAN dan bersandar kepada Allahnya!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 50, 11, 'Sesungguhnya, kamu semua yang menyalakan api dan yang memasang panah-panah api, masuklah ke dalam nyala apimu, dan ke tengah-tengah panah-panah api yang telah kamu pasang! Oleh tangan-Kulah hal itu akan terjadi atasmu; kamu akan berbaring di tempat siksaan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 1, 'Dengarkanlah Aku, hai kamu yang mengejar apa yang benar, hai kamu yang mencari TUHAN! Pandanglah gunung batu yang dari padanya kamu terpahat, dan kepada lobang penggalian batu yang dari padanya kamu tergali.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 2, 'Pandanglah Abraham, bapa leluhurmu, dan Sara yang melahirkan kamu; ketika Abraham seorang diri, Aku memanggil dia, lalu Aku memberkati dan memperbanyak dia.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 3, 'Sebab TUHAN menghibur Sion, menghibur segala reruntuhannya; Ia membuat padang gurunnya seperti taman Eden dan padang belantaranya seperti taman TUHAN. Di situ terdapat kegirangan dan sukacita, nyanyian syukur dan lagu yang nyaring.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 4, 'Perhatikanlah suara-Ku, hai bangsa-bangsa, dan pasanglah telinga kepada-Ku, hai suku-suku bangsa! Sebab pengajaran akan keluar dari pada-Ku dan hukum-Ku sebagai terang untuk bangsa-bangsa.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 5, 'Dalam sekejap mata keselamatan yang dari pada-Ku akan dekat, kelepasan yang Kuberikan akan tiba, dan dengan tangan kekuasaan-Ku Aku akan memerintah bangsa-bangsa; kepada-Kulah pulau-pulau menanti-nanti, perbuatan tangan-Ku mereka harapkan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 6, 'Arahkanlah matamu ke langit dan lihatlah ke bumi di bawah; sebab langit lenyap seperti asap, bumi memburuk seperti pakaian yang sudah usang dan penduduknya akan mati seperti nyamuk; tetapi kelepasan yang Kuberikan akan tetap untuk selama-lamanya, dan keselamatan yang dari pada-Ku tidak akan berakhir.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 7, 'Dengarkanlah Aku, hai kamu yang mengetahui apa yang benar, hai bangsa yang menyimpan pengajaran-Ku dalam hatimu! Janganlah takut jika diaibkan oleh manusia dan janganlah terkejut jika dinista oleh mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 8, 'Sebab ngengat akan memakan mereka seperti memakan pakaian dan gegat akan memakan mereka seperti memakan kain bulu domba; tetapi keselamatan yang dari pada-Ku akan tetap untuk selama-lamanya dan kelepasan yang Kuberikan akan lanjut dari keturunan kepada keturunan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 9, 'Terjagalah, terjagalah! Kenakanlah kekuatan, hai tangan TUHAN! Terjagalah seperti pada zaman purbakala, pada zaman keturunan yang dahulu kala! Bukankah Engkau yang meremukkan Rahab, yang menikam naga sampai mati?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 10, 'Bukankah Engkau yang mengeringkan laut, air samudera raya yang hebat? yang membuat laut yang dalam menjadi jalan, supaya orang-orang yang diselamatkan dapat menyeberang?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 11, 'Maka orang-orang yang dibebaskan TUHAN akan pulang dan masuk ke Sion dengan sorak-sorai, sedang sukacita abadi meliputi mereka; kegirangan dan sukacita akan memenuhi mereka, duka dan keluh akan menjauh.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 12, 'Akulah, Akulah yang menghibur kamu. Siapakah engkau maka engkau takut terhadap manusia yang memang akan mati, terhadap anak manusia yang dibuang seperti rumput,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 13, 'sehingga engkau melupakan TUHAN yang menjadikan engkau, yang membentangkan langit dan meletakkan dasar bumi, sehingga engkau terus gentar sepanjang hari terhadap kepanasan amarah orang penganiaya, apabila ia bersiap-siap memusnahkan? Di manakah gerangan kepanasan amarah orang penganiaya itu?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 14, 'Dia yang dipasung terbelenggu akan segera dibebaskan; ia tidak akan turun mati ke liang kubur, dan tidak akan kekurangan makanan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 15, 'Sebab Akulah TUHAN, Allahmu, yang mengharubirukan laut, sehingga gelombang-gelombangnya ribut, ?TUHAN semesta alam nama-Nya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 16, 'Aku menaruh firman-Ku ke dalam mulutmu dan menyembunyikan engkau dalam naungan tangan-Ku, supaya Aku kembali membentangkan langit dan meletakkan dasar bumi, dan berkata kepada Sion: Engkau adalah umat-Ku!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 17, 'Terjagalah, terjagalah, bangunlah, hai Yerusalem, hai engkau yang telah meminum dari tangan TUHAN isi piala kehangatan murka-Nya, engkau yang telah meminum, menghirup habis isi cangkir yang memusingkan!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 18, 'Dari semua anak-anak yang dilahirkannya tidak ada yang membimbing dia dan dari semua anak-anak yang dibesarkannya tidak ada yang memegang tangannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 19, 'Kedua hal ini telah menimpa engkau?siapakah yang akan turut berdukacita dengan engkau? Kebinasaan dan keruntuhan, kelaparan dan pedang?siapakah yang akan menghibur engkau?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 20, 'Anak-anakmu sudah terlentang kelesuan di semua ujung jalan seperti lembu hutan kena jaring; mereka diliputi kehangatan murka TUHAN dan hardik Allahmu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 21, 'Sebab itu, dengarlah ini, hai engkau yang tertindas, hai engkau yang mabuk, tetapi bukan karena anggur!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 22, 'Beginilah firman Tuhanmu, TUHAN, Allahmu yang memperjuangkan perkara umat-Nya: "Sesungguhnya, Aku mengambil dari tanganmu piala dengan isinya yang memusingkan, dan isi cangkir kehangatan murka-Ku tidak akan kauminum lagi,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 51, 23, 'tetapi Aku akan memberikannya ke tangan orang yang menindas engkau, orang yang tadinya berkata kepadamu: Tunduklah, supaya kami lewat menginjak kamu! Maka engkau merentangkan punggungmu serata tanah dan sebagai jalan bagi orang yang lewat dari atasnya."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 52, 1, 'Terjagalah, terjagalah! Kenakanlah kekuatanmu seperti pakaian, hai Sion! Kenakanlah pakaian kehormatanmu, hai Yerusalem, kota yang kudus! Sebab tidak seorangpun yang tak bersunat atau yang najis akan masuk lagi ke dalammu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 52, 2, 'Kebaskanlah debu dari padamu, bangunlah, hai Yerusalem yang tertawan! Tanggalkanlah ikatan-ikatan dari lehermu, hai puteri Sion yang tertawan!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 52, 3, 'Sebab beginilah firman TUHAN: Kamu dijual tanpa pembayaran, maka kamu akan ditebus tanpa pembayaran juga.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 52, 4, 'Sebab beginilah firman Tuhan ALLAH: Dahulu umat-Ku berangkat ke Mesir untuk tinggal di situ sebagai orang asing, lalu Asyur memeras dia tanpa alasan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 52, 5, 'Tetapi sekarang, apakah lagi urusan-Ku di sini? demikianlah firman TUHAN. Umat-Ku sudah dirampas begitu saja. Mereka yang berkuasa atas dia memegahkan diri, demikianlah firman TUHAN, dan nama-Ku terus dihujat sepanjang hari.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 52, 6, 'Sebab itu umat-Ku akan mengenal nama-Ku dan pada waktu itu mereka akan mengerti bahwa Akulah Dia yang berbicara, ya Aku!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 52, 7, 'Betapa indahnya kelihatan dari puncak bukit-bukit kedatangan pembawa berita, yang mengabarkan berita damai dan memberitakan kabar baik, yang mengabarkan berita selamat dan berkata kepada Sion: "Allahmu itu Raja!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 52, 8, 'Dengarlah suara orang-orang yang mengawal engkau: mereka bersama-sama bersorak-sorai. Sebab dengan mata kepala sendiri mereka melihat bagaimana TUHAN kembali ke Sion.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 52, 9, 'Bergembiralah, bersorak-sorailah bersama-sama, hai reruntuhan Yerusalem! Sebab TUHAN telah menghibur umat-Nya, telah menebus Yerusalem.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 52, 10, 'TUHAN telah menunjukkan tangan-Nya yang kudus di depan mata semua bangsa; maka segala ujung bumi melihat keselamatan yang dari Allah kita.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 52, 11, 'Menjauhlah, menjauhlah! Keluarlah dari sana! Janganlah engkau kena kepada yang najis! Keluarlah dari tengah-tengahnya, sucikanlah dirimu, hai orang-orang yang mengangkat perkakas rumah TUHAN!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 52, 12, 'Sungguh, kamu tidak akan buru-buru keluar dan tidak akan lari-lari berjalan, sebab TUHAN akan berjalan di depanmu, dan Allah Israel akan menjadi penutup barisanmu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 52, 13, 'Sesungguhnya, hamba-Ku akan berhasil, ia akan ditinggikan, disanjung dan dimuliakan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 52, 14, 'Seperti banyak orang akan tertegun melihat dia?begitu buruk rupanya, bukan seperti manusia lagi, dan tampaknya bukan seperti anak manusia lagi?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 52, 15, 'demikianlah ia akan membuat tercengang banyak bangsa, raja-raja akan mengatupkan mulutnya melihat dia; sebab apa yang tidak diceritakan kepada mereka akan mereka lihat, dan apa yang tidak mereka dengar akan mereka pahami.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 53, 1, 'Siapakah yang percaya kepada berita yang kami dengar, dan kepada siapakah tangan kekuasaan TUHAN dinyatakan?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 53, 2, 'Sebagai taruk ia tumbuh di hadapan TUHAN dan sebagai tunas dari tanah kering. Ia tidak tampan dan semaraknyapun tidak ada sehingga kita memandang dia, dan rupapun tidak, sehingga kita menginginkannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 53, 3, 'Ia dihina dan dihindari orang, seorang yang penuh kesengsaraan dan yang biasa menderita kesakitan; ia sangat dihina, sehingga orang menutup mukanya terhadap dia dan bagi kitapun dia tidak masuk hitungan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 53, 4, 'Tetapi sesungguhnya, penyakit kitalah yang ditanggungnya, dan kesengsaraan kita yang dipikulnya, padahal kita mengira dia kena tulah, dipukul dan ditindas Allah.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 53, 5, 'Tetapi dia tertikam oleh karena pemberontakan kita, dia diremukkan oleh karena kejahatan kita; ganjaran yang mendatangkan keselamatan bagi kita ditimpakan kepadanya, dan oleh bilur-bilurnya kita menjadi sembuh.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 53, 6, 'Kita sekalian sesat seperti domba, masing-masing kita mengambil jalannya sendiri, tetapi TUHAN telah menimpakan kepadanya kejahatan kita sekalian.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 53, 7, 'Dia dianiaya, tetapi dia membiarkan diri ditindas dan tidak membuka mulutnya seperti anak domba yang dibawa ke pembantaian; seperti induk domba yang kelu di depan orang-orang yang menggunting bulunya, ia tidak membuka mulutnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 53, 8, 'Sesudah penahanan dan penghukuman ia terambil, dan tentang nasibnya siapakah yang memikirkannya? Sungguh, ia terputus dari negeri orang-orang hidup, dan karena pemberontakan umat-Ku ia kena tulah.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 53, 9, 'Orang menempatkan kuburnya di antara orang-orang fasik, dan dalam matinya ia ada di antara penjahat-penjahat, sekalipun ia tidak berbuat kekerasan dan tipu tidak ada dalam mulutnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 53, 10, 'Tetapi TUHAN berkehendak meremukkan dia dengan kesakitan. Apabila ia menyerahkan dirinya sebagai korban penebus salah, ia akan melihat keturunannya, umurnya akan lanjut, dan kehendak TUHAN akan terlaksana olehnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 53, 11, 'Sesudah kesusahan jiwanya ia akan melihat terang dan menjadi puas; dan hamba-Ku itu, sebagai orang yang benar, akan membenarkan banyak orang oleh hikmatnya, dan kejahatan mereka dia pikul.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 53, 12, 'Sebab itu Aku akan membagikan kepadanya orang-orang besar sebagai rampasan, dan ia akan memperoleh orang-orang kuat sebagai jarahan, yaitu sebagai ganti karena ia telah menyerahkan nyawanya ke dalam maut dan karena ia terhitung di antara pemberontak-pemberontak, sekalipun ia menanggung dosa banyak orang dan berdoa untuk pemberontak-pemberon', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 54, 1, 'Bersorak-sorailah, hai si mandul yang tidak pernah melahirkan! Bergembiralah dengan sorak-sorai dan memekiklah, hai engkau yang tidak pernah menderita sakit bersalin! Sebab yang ditinggalkan suaminya akan mempunyai lebih banyak anak dari pada yang bersuami, firman TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 54, 2, 'Lapangkanlah tempat kemahmu, dan bentangkanlah tenda tempat kediamanmu, janganlah menghematnya; panjangkanlah tali-tali kemahmu dan pancangkanlah kokoh-kokoh patok-patokmu!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 54, 3, 'Sebab engkau akan mengembang ke kanan dan ke kiri, keturunanmu akan memperoleh tempat bangsa-bangsa, dan akan mendiami kota-kota yang sunyi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 54, 4, 'Janganlah takut, sebab engkau tidak akan mendapat malu, dan janganlah merasa malu, sebab engkau tidak akan tersipu-sipu. Sebab engkau akan melupakan malu keremajaanmu, dan tidak akan mengingat lagi aib kejandaanmu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 54, 5, 'Sebab yang menjadi suamimu ialah Dia yang menjadikan engkau, TUHAN semesta alam nama-Nya; yang menjadi Penebusmu ialah Yang Mahakudus, Allah Israel, Ia disebut Allah seluruh bumi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 54, 6, 'Sebab seperti isteri yang ditinggalkan dan yang bersusah hati TUHAN memanggil engkau kembali; masakan isteri dari masa muda akan tetap ditolak? firman Allahmu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 54, 7, 'Hanya sesaat lamanya Aku meninggalkan engkau, tetapi karena kasih sayang yang besar Aku mengambil engkau kembali.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 54, 8, 'Dalam murka yang meluap Aku telah menyembunyikan wajah-Ku terhadap engkau sesaat lamanya, tetapi dalam kasih setia abadi Aku telah mengasihani engkau, firman TUHAN, Penebusmu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 54, 9, 'Keadaan ini bagi-Ku seperti pada zaman Nuh: seperti Aku telah bersumpah kepadanya bahwa air bah tidak akan meliputi bumi lagi, demikianlah Aku telah bersumpah bahwa Aku tidak akan murka terhadap engkau dan tidak akan menghardik engkau lagi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 54, 10, 'Sebab biarpun gunung-gunung beranjak dan bukit-bukit bergoyang, tetapi kasih setia-Ku tidak akan beranjak dari padamu dan perjanjian damai-Ku tidak akan bergoyang, firman TUHAN, yang mengasihani engkau.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 54, 11, 'Hai yang tertindas, yang dilanggar angin badai, yang tidak dihiburkan! Sesungguhnya, Aku akan meletakkan alasmu dari batu hitam dan dasar-dasarmu dari batu nilam.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 54, 12, 'Aku akan membuat kemuncak-kemuncak tembokmu dari batu delima, pintu-pintu gerbangmu dari batu manikam merah dan segenap tembok perbatasanmu dari batu permata.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 54, 13, 'Semua anakmu akan menjadi murid TUHAN, dan besarlah kesejahteraan mereka;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 54, 14, 'engkau akan ditegakkan di atas kebenaran. Engkau akan jauh dari pemerasan, sebab engkau tidak usah lagi takut, dan engkau akan jauh dari kekejutan, sebab ia tidak akan mendekat kepadamu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 54, 15, 'Apabila orang menyerbu, itu bukanlah dari pada-Ku; siapapun yang menyerbu engkau, ia akan rebah melawan engkau.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 54, 16, 'Sesungguhnya, Akulah yang menciptakan tukang besi yang menghembus api dan menghasilkan senjata menurut kecakapannya, tetapi Akulah juga yang menciptakan pemusnah untuk merusakkannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 54, 17, 'Setiap senjata yang ditempa terhadap engkau tidak akan berhasil, dan setiap orang yang melontarkan tuduhan melawan engkau dalam pengadilan, akan engkau buktikan salah. Inilah yang menjadi bagian hamba-hamba TUHAN dan kebenaran yang mereka terima dari pada-Ku, demikianlah firman TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 55, 1, 'Ayo, hai semua orang yang haus, marilah dan minumlah air, dan hai orang yang tidak mempunyai uang, marilah! Terimalah gandum tanpa uang pembeli dan makanlah, juga anggur dan susu tanpa bayaran!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 55, 2, 'Mengapakah kamu belanjakan uang untuk sesuatu yang bukan roti, dan upah jerih payahmu untuk sesuatu yang tidak mengenyangkan? Dengarkanlah Aku maka kamu akan memakan yang baik dan kamu akan menikmati sajian yang paling lezat.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 55, 3, 'Sendengkanlah telingamu dan datanglah kepada-Ku; dengarkanlah, maka kamu akan hidup! Aku hendak mengikat perjanjian abadi dengan kamu, menurut kasih setia yang teguh yang Kujanjikan kepada Daud.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 55, 4, 'Sesungguhnya, Aku telah menetapkan dia menjadi saksi bagi bangsa-bangsa, menjadi seorang raja dan pemerintah bagi suku-suku bangsa;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 55, 5, 'sesungguhnya, engkau akan memanggil bangsa yang tidak kaukenal, dan bangsa yang tidak mengenal engkau akan berlari kepadamu, oleh karena TUHAN, Allahmu, dan karena Yang Mahakudus, Allah Israel, yang mengagungkan engkau.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 55, 6, 'Carilah TUHAN selama Ia berkenan ditemui; berserulah kepada-Nya selama Ia dekat!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 55, 7, 'Baiklah orang fasik meninggalkan jalannya, dan orang jahat meninggalkan rancangannya; baiklah ia kembali kepada TUHAN, maka Dia akan mengasihaninya, dan kepada Allah kita, sebab Ia memberi pengampunan dengan limpahnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 55, 8, 'Sebab rancangan-Ku bukanlah rancanganmu, dan jalanmu bukanlah jalan-Ku, demikianlah firman TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 55, 9, 'Seperti tingginya langit dari bumi, demikianlah tingginya jalan-Ku dari jalanmu dan rancangan-Ku dari rancanganmu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 55, 10, 'Sebab seperti hujan dan salju turun dari langit dan tidak kembali ke situ, melainkan mengairi bumi, membuatnya subur dan menumbuhkan tumbuh-tumbuhan, memberikan benih kepada penabur dan roti kepada orang yang mau makan,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 55, 11, 'demikianlah firman-Ku yang keluar dari mulut-Ku: ia tidak akan kembali kepada-Ku dengan sia-sia, tetapi ia akan melaksanakan apa yang Kukehendaki, dan akan berhasil dalam apa yang Kusuruhkan kepadanya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 55, 12, 'Sungguh, kamu akan berangkat dengan sukacita dan akan dihantarkan dengan damai; gunung-gunung serta bukit-bukit akan bergembira dan bersorak-sorai di depanmu, dan segala pohon-pohonan di padang akan bertepuk tangan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 55, 13, 'Sebagai ganti semak duri akan tumbuh pohon sanobar, dan sebagai ganti kecubung akan tumbuh pohon murad, dan itu akan terjadi sebagai kemasyhuran bagi TUHAN, sebagai tanda abadi yang tidak akan lenyap.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 56, 1, 'Beginilah firman TUHAN: Taatilah hukum dan tegakkanlah keadilan, sebab sebentar lagi akan datang keselamatan yang dari pada-Ku, dan keadilan-Ku akan dinyatakan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 56, 2, 'Berbahagialah orang yang melakukannya, dan anak manusia yang berpegang kepadanya: yang memelihara hari Sabat dan tidak menajiskannya, dan yang menahan diri dari setiap perbuatan jahat.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 56, 3, 'Janganlah orang asing yang menggabungkan diri kepada TUHAN berkata: "Sudah tentu TUHAN hendak memisahkan aku dari pada umat-Nya"; dan janganlah orang kebiri berkata: "Sesungguhnya, aku ini pohon yang kering."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 56, 4, 'Sebab beginilah firman TUHAN: "Kepada orang-orang kebiri yang memelihara hari-hari Sabat-Ku dan yang memilih apa yang Kukehendaki dan yang berpegang kepada perjanjian-Ku,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 56, 5, 'kepada mereka akan Kuberikan dalam rumah-Ku dan di lingkungan tembok-tembok kediaman-Ku suatu tanda peringatan dan nama?itu lebih baik dari pada anak-anak lelaki dan perempuan?,suatu nama abadi yang tidak akan lenyap akan Kuberikan kepada mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 56, 6, 'Dan orang-orang asing yang menggabungkan diri kepada TUHAN untuk melayani Dia, untuk mengasihi nama TUHAN dan untuk menjadi hamba-hamba-Nya, semuanya yang memelihara hari Sabat dan tidak menajiskannya, dan yang berpegang kepada perjanjian-Ku,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 56, 7, 'mereka akan Kubawa ke gunung-Ku yang kudus dan akan Kuberi kesukaan di rumah doa-Ku. Aku akan berkenan kepada korban-korban bakaran dan korban-korban sembelihan mereka yang dipersembahkan di atas mezbah-Ku, sebab rumah-Ku akan disebut rumah doa bagi segala bangsa.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 56, 8, 'Demikianlah firman Tuhan ALLAH yang menghimpun orang-orang Israel yang terbuang: Aku akan menghimpunkan orang kepadanya lagi sebagai tambahan kepada orang-orangnya yang telah terhimpun."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 56, 9, 'Hai segala binatang di padang, hai segala binatang di hutan, datanglah untuk makan!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 56, 10, 'Sebab pengawal-pengawal umat-Ku adalah orang-orang buta, mereka semua tidak tahu apa-apa; mereka semua adalah anjing-anjing bisu, tidak tahu menyalak; mereka berbaring melamun dan suka tidur saja;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 56, 11, 'anjing-anjing pelahap, yang tidak tahu kenyang. Dan orang-orang itulah gembala-gembala, yang tidak dapat mengerti! Mereka semua mengambil jalannya sendiri, masing-masing mengejar laba, tiada yang terkecuali.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 56, 12, '"Datanglah," kata mereka, "aku akan mengambil anggur, baiklah kita minum arak banyak-banyak; besok akan sama seperti hari ini, dan lebih hebat lagi!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 57, 1, 'Orang benar binasa, dan tidak ada seorangpun yang memperhatikannya; orang-orang saleh tercabut nyawanya, dan tidak ada seorangpun yang mengindahkannya; sungguh, karena merajalelanya kejahatan, tercabutlah nyawa orang benar', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 57, 2, 'dan ia masuk ke tempat damai; orang-orang yang hidup dengan lurus hati mendapat perhentian di atas tempat tidurnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 57, 3, 'Tetapi kamu, mendekatlah kamu ke mari, hai anak-anak dari perempuan-perempuan sihir, hai keturunan orang yang berzinah dan perempuan sundal!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 57, 4, 'Tentang siapakah kamu berkelakar, terhadap siapakah kamu melontarkan kata-kata yang bukan-bukan dan mengejeknya? Bukankah kamu ini anak-anak pemberontak, keturunan pendusta,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 57, 5, 'hai orang-orang yang terbakar oleh hawa nafsu dekat pohon-pohon keramat, di bawah setiap pohon yang rimbun, hai orang-orang yang menyembelih anak-anak di lembah-lembah, di dalam celah-celah bukit batu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 57, 6, 'Padamu hanya ada batu-batu licin dari sungai, dan hanya itu sajalah yang ditentukan bagimu; kepada mereka juga engkau mengunjukkan korban curahan, dan mempersembahkan korban sajian. Masakan Aku sabar akan hal itu?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 57, 7, 'Engkau menaruh petiduranmu di atas gunung yang tinggi dan menjulang dan ke atas gunung itu juga engkau naik untuk mempersembahkan korban sembelihan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 57, 8, 'Engkau telah menaruh lambang berhalamu di ambang pintu masuk rumahmu, ya, engkau telah meninggalkan Aku dan menelanjangi dirimu, engkau telah menaiki petiduranmu dan telah melebarkannya; engkau telah mengadakan janji dengan beberapa orang yang kauingini untuk tidur bersama-sama mereka dan engkau memandangi lingga.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 57, 9, 'Engkau datang menghadap Molokh dengan membawa minyak dan banyak-banyak wangi-wangian; engkau menyuruh duta-dutamu pergi sampai jauh, dan sampai ke bawah di dunia orang mati.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 57, 10, 'Oleh perjalananmu yang jauh engkau sudah letih lesu, tetapi engkau tidak berkata: "Tidak ada harapan!" Engkau mendapat kekuatan yang baru, dan sebab itu engkau tidak menjadi lemah.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 57, 11, 'Kepada siapa gerangan engkau gentar dan takut, sehingga engkau berdusta dan tidak mengingat Aku atau memberi perhatian kepada-Ku? Bukankah karena Aku membisu dan menutup mata, maka engkau tidak takut kepada-Ku!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 57, 12, 'Aku akan menyebutkan kesalehanmu dan segala perbuatanmu, tetapi semuanya itu tidak akan berguna bagimu:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 57, 13, 'apabila engkau berteriak, biarlah berhala-berhalamu melepaskan engkau! Mereka semua akan ditiup angin, akan diterbangkan hembusan nafas. Tetapi orang yang berlindung kepada-Ku akan mewarisi negeri dan akan memiliki gunung-Ku yang kudus.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 57, 14, 'Ada yang berkata: "Bukalah, bukalah, persiapkanlah jalan, angkatlah batu sandungan dari jalan umat-Ku!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 57, 15, 'Sebab beginilah firman Yang Mahatinggi dan Yang Mahamulia, yang bersemayam untuk selamanya dan Yang Mahakudus nama-Nya: "Aku bersemayam di tempat tinggi dan di tempat kudus tetapi juga bersama-sama orang yang remuk dan rendah hati, untuk menghidupkan semangat orang-orang yang rendah hati dan untuk menghidupkan hati orang-orang yang remuk.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 57, 16, 'Sebab bukan untuk selama-lamanya Aku hendak berbantah, dan bukan untuk seterusnya Aku hendak murka, supaya semangat mereka jangan lemah lesu di hadapan-Ku, padahal Akulah yang membuat nafas kehidupan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 57, 17, 'Aku murka karena kesalahan kelobaannya, Aku menghajar dia, menyembunyikan wajah-Ku dan murka, tetapi dengan murtad ia menempuh jalan yang dipilih hatinya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 57, 18, 'Aku telah melihat segala jalannya itu, tetapi Aku akan menyembuhkan dan akan menuntun dia dan akan memulihkan dia dengan penghiburan; juga pada bibir orang-orangnya yang berkabung', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 57, 19, 'Aku akan menciptakan puji-pujian. Damai, damai sejahtera bagi mereka yang jauh dan bagi mereka yang dekat?firman TUHAN?Aku akan menyembuhkan dia!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 57, 20, 'Tetapi orang-orang fasik adalah seperti laut yang berombak-ombak sebab tidak dapat tetap tenang, dan arusnya menimbulkan sampah dan lumpur.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 57, 21, 'Tiada damai bagi orang-orang fasik itu," firman Allahku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 58, 1, 'Serukanlah kuat-kuat, janganlah tahan-tahan! Nyaringkanlah suaramu bagaikan sangkakala, beritahukanlah kepada umat-Ku pelanggaran mereka dan kepada kaum keturunan Yakub dosa mereka!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 58, 2, 'Memang setiap hari mereka mencari Aku dan suka untuk mengenal segala jalan-Ku. Seperti bangsa yang melakukan yang benar dan yang tidak meninggalkan hukum Allahnya mereka menanyakan Aku tentang hukum-hukum yang benar, mereka suka mendekat menghadap Allah, tanyanya:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 58, 3, '"Mengapa kami berpuasa dan Engkau tidak memperhatikannya juga? Mengapa kami merendahkan diri dan Engkau tidak mengindahkannya juga?" Sesungguhnya, pada hari puasamu engkau masih tetap mengurus urusanmu, dan kamu mendesak-desak semua buruhmu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 58, 4, 'Sesungguhnya, kamu berpuasa sambil berbantah dan berkelahi serta memukul dengan tinju dengan tidak semena-mena. Dengan caramu berpuasa seperti sekarang ini suaramu tidak akan didengar di tempat tinggi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 58, 5, 'Sungguh-sungguh inikah berpuasa yang Kukehendaki, dan mengadakan hari merendahkan diri, jika engkau menundukkan kepala seperti gelagah dan membentangkan kain karung dan abu sebagai lapik tidur? Sungguh-sungguh itukah yang kausebutkan berpuasa, mengadakan hari yang berkenan pada TUHAN?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 58, 6, 'Bukan! Berpuasa yang Kukehendaki, ialah supaya engkau membuka belenggu-belenggu kelaliman, dan melepaskan tali-tali kuk, supaya engkau memerdekakan orang yang teraniaya dan mematahkan setiap kuk,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 58, 7, 'supaya engkau memecah-mecah rotimu bagi orang yang lapar dan membawa ke rumahmu orang miskin yang tak punya rumah, dan apabila engkau melihat orang telanjang, supaya engkau memberi dia pakaian dan tidak menyembunyikan diri terhadap saudaramu sendiri!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 58, 8, 'Pada waktu itulah terangmu akan merekah seperti fajar dan lukamu akan pulih dengan segera; kebenaran menjadi barisan depanmu dan kemuliaan TUHAN barisan belakangmu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 58, 9, 'Pada waktu itulah engkau akan memanggil dan TUHAN akan menjawab, engkau akan berteriak minta tolong dan Ia akan berkata: Ini Aku! Apabila engkau tidak lagi mengenakan kuk kepada sesamamu dan tidak lagi menunjuk-nunjuk orang dengan jari dan memfitnah,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 58, 10, 'apabila engkau menyerahkan kepada orang lapar apa yang kauinginkan sendiri dan memuaskan hati orang yang tertindas maka terangmu akan terbit dalam gelap dan kegelapanmu akan seperti rembang tengah hari.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 58, 11, 'TUHAN akan menuntun engkau senantiasa dan akan memuaskan hatimu di tanah yang kering, dan akan membaharui kekuatanmu; engkau akan seperti taman yang diairi dengan baik dan seperti mata air yang tidak pernah mengecewakan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 58, 12, 'Engkau akan membangun reruntuhan yang sudah berabad-abad, dan akan memperbaiki dasar yang diletakkan oleh banyak keturunan. Engkau akan disebutkan "yang memperbaiki tembok yang tembus", "yang membetulkan jalan supaya tempat itu dapat dihuni".', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 58, 13, 'Apabila engkau tidak menginjak-injak hukum Sabat dan tidak melakukan urusanmu pada hari kudus-Ku; apabila engkau menyebutkan hari Sabat "hari kenikmatan", dan hari kudus TUHAN "hari yang mulia"; apabila engkau menghormatinya dengan tidak menjalankan segala acaramu dan dengan tidak mengurus urusanmu atau berkata omong kosong,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 58, 14, 'maka engkau akan bersenang-senang karena TUHAN, dan Aku akan membuat engkau melintasi puncak bukit-bukit di bumi dengan kendaraan kemenangan; Aku akan memberi makan engkau dari milik pusaka Yakub, bapa leluhurmu, sebab mulut Tuhanlah yang mengatakannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 59, 1, 'Sesungguhnya, tangan TUHAN tidak kurang panjang untuk menyelamatkan, dan pendengaran-Nya tidak kurang tajam untuk mendengar;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 59, 2, 'tetapi yang merupakan pemisah antara kamu dan Allahmu ialah segala kejahatanmu, dan yang membuat Dia menyembunyikan diri terhadap kamu, sehingga Ia tidak mendengar, ialah segala dosamu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 59, 3, 'Sebab tanganmu cemar oleh darah dan jarimu oleh kejahatan; mulutmu mengucapkan dusta, lidahmu menyebut-nyebut kecurangan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 59, 4, 'Tidak ada yang mengajukan pengaduan dengan alasan benar, dan tidak ada yang menghakimi dengan alasan teguh; orang mengandalkan kesia-siaan dan mengucapkan dusta, orang mengandung bencana dan melahirkan kelaliman.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 59, 5, 'Mereka menetaskan telur ular beludak, dan menenun sarang laba-laba; siapa yang makan dari telurnya itu akan mati, dan apabila sebutir ditekan pecah, keluarlah seekor ular beludak.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 59, 6, 'Sarang yang ditenun itu tidak dapat dipergunakan sebagai pakaian, dan buatan mereka itu tidak dapat dipakai sebagai kain; perbuatan mereka adalah perbuatan kelaliman, dan yang dikerjakan tangan mereka adalah kekerasan belaka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 59, 7, 'Mereka segera melakukan kejahatan, dan bersegera hendak menumpahkan darah orang yang tidak bersalah; rancangan mereka adalah rancangan kelaliman, dan ke mana saja mereka pergi mereka meninggalkan kebinasaan dan keruntuhan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 59, 8, 'Mereka tidak mengenal jalan damai, dan dalam jejak mereka tidak ada keadilan; mereka mengambil jalan-jalan yang bengkok, dan setiap orang yang berjalan di situ tidaklah mengenal damai.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 59, 9, 'Sebab itu keadilan tetap jauh dari pada kami dan kebenaran tidak sampai kepada kami. Kami menanti-nantikan terang, tetapi hanya kegelapan belaka, menanti-nantikan cahaya, tetapi kami berjalan dalam kekelaman.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 59, 10, 'Kami meraba-raba dinding seperti orang buta, dan meraba-raba seolah-olah tidak punya mata; kami tersandung di waktu tengah hari seperti di waktu senja, duduk di tempat gelap seperti orang mati.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 59, 11, 'Kami sekalian meraung seperti beruang; suara kami redup seperti suara burung merpati; kami menanti-nantikan keadilan, tetapi tidak ada, menanti-nantikan keselamatan, tetapi tetap jauh dari kami.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 59, 12, 'Sungguh, dosa pemberontakan kami banyak di hadapan-Mu dan dosa kami bersaksi melawan kami; sungguh, kami menyadari pemberontakan kami dan kami mengenal kejahatan kami:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 59, 13, 'kami telah memberontak dan mungkir terhadap TUHAN, dan berbalik dari mengikuti Allah kami, kami merancangkan pemerasan dan penyelewengan, mengandung dusta dalam hati dan melahirkannya dalam kata-kata.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 59, 14, 'Hukum telah terdesak ke belakang, dan keadilan berdiri jauh-jauh, sebab kebenaran tersandung di tempat umum dan ketulusan ditolak orang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 59, 15, 'Dengan demikian kebenaran telah hilang, dan siapa yang menjauhi kejahatan, ia menjadi korban rampasan. Tetapi TUHAN melihatnya, dan adalah jahat di mata-Nya bahwa tidak ada hukum.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 59, 16, 'Ia melihat bahwa tidak seorangpun yang tampil, dan Ia tertegun karena tidak ada yang membela. Maka tangan-Nya sendiri memberi Dia pertolongan, dan keadilan-Nyalah yang membantu Dia.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 59, 17, 'Ia mengenakan keadilan sebagai baju zirah dan ketopong keselamatan ada di kepala-Nya; Ia mengenakan pakaian pembalasan dan menyelubungkan kecemburuan sebagai jubah.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 59, 18, 'Sesuai dengan perbuatan-perbuatan orang, demikianlah Ia memberi pembalasan: kehangatan murka kepada lawan-lawan-Nya, ganjaran kepada musuh-musuh-Nya; bahkan kepada pulau-pulau yang jauh Ia memberi ganjaran.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 59, 19, 'Maka orang akan takut kepada nama TUHAN di tempat matahari terbenam dan kepada kemuliaan-Nya di tempat matahari terbit, sebab Ia akan datang seperti arus dari tempat yang sempit, yang didorong oleh nafas TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 59, 20, 'Dan Ia akan datang sebagai Penebus untuk Sion dan untuk orang-orang Yakub yang bertobat dari pemberontakannya, demikianlah firman TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 59, 21, 'Adapun Aku, inilah perjanjian-Ku dengan mereka, firman TUHAN: Roh-Ku yang menghinggapi engkau dan firman-Ku yang Kutaruh dalam mulutmu tidak akan meninggalkan mulutmu dan mulut keturunanmu dan mulut keturunan mereka, dari sekarang sampai selama-lamanya, firman TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 60, 1, 'Bangkitlah, menjadi teranglah, sebab terangmu datang, dan kemuliaan TUHAN terbit atasmu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 60, 2, 'Sebab sesungguhnya, kegelapan menutupi bumi, dan kekelaman menutupi bangsa-bangsa; tetapi terang TUHAN terbit atasmu, dan kemuliaan-Nya menjadi nyata atasmu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 60, 3, 'Bangsa-bangsa berduyun-duyun datang kepada terangmu, dan raja-raja kepada cahaya yang terbit bagimu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 60, 4, 'Angkatlah mukamu dan lihatlah ke sekeliling, mereka semua datang berhimpun kepadamu; anak-anakmu laki-laki datang dari jauh, dan anak-anakmu perempuan digendong.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 60, 5, 'Pada waktu itu engkau akan heran melihat dan berseri-seri, engkau akan tercengang dan akan berbesar hati, sebab kelimpahan dari seberang laut akan beralih kepadamu, dan kekayaan bangsa-bangsa akan datang kepadamu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 60, 6, 'Sejumlah besar unta akan menutupi daerahmu, unta-unta muda dari Midian dan Efa. Mereka semua akan datang dari Syeba, akan membawa emas dan kemenyan, serta memberitakan perbuatan masyhur TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 60, 7, 'Segala kambing domba Kedar akan berhimpun kepadamu, domba-domba jantan Nebayot akan tersedia untuk ibadahmu; semuanya akan dipersembahkan di atas mezbah-Ku sebagai korban yang berkenan kepada-Ku, dan Aku akan menyemarakkan rumah keagungan-Ku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 60, 8, 'Siapakah mereka ini yang melayang seperti awan dan seperti burung merpati ke pintu kandangnya?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 60, 9, 'Sungguh, Akulah yang dinanti-nantikan pulau-pulau yang jauh; kapal-kapal Tarsis berlayar di depan untuk membawa anak-anakmu laki-laki dari jauh, perak dan emasnya dibawa serta, untuk nama TUHAN, Allahmu, dan oleh karena Yang Mahakudus, Allah Israel, sebab Ia mengagungkan engkau.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 60, 10, 'Orang-orang asing akan membangun tembokmu, dan raja-raja mereka akan melayani engkau; sebab dalam murka-Ku Aku telah menghajar engkau, namun Aku telah berkenan untuk mengasihani engkau.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 60, 11, 'Pintu-pintu gerbangmu akan terbuka senantiasa, baik siang maupun malam tidak akan tertutup, supaya orang dapat membawa kekayaan bangsa-bangsa kepadamu, sedang raja-raja mereka ikut digiring sebagai tawanan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 60, 12, 'Sungguh, bangsa dan kerajaan yang tidak mau mengabdi kepadamu akan lenyap; bangsa-bangsa itu akan dirusakbinasakan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 60, 13, 'Kemuliaan Libanon, yaitu pohon sanobar, pohon berangan dan pohon cemara, akan dibawa bersama-sama kepadamu, untuk mempersemarak tempat bait kudus-Ku, sebab Aku hendak memuliakan tempat kaki-Ku berjejak.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 60, 14, 'Anak-anak orang-orang yang menindas engkau akan datang kepadamu dan tunduk, dan semua orang yang menista engkau akan sujud menyembah telapak kakimu; mereka akan menyebutkan engkau "kota TUHAN", "Sion, milik Yang Mahakudus, Allah Israel."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 60, 15, 'Sebagai ganti keadaanmu dahulu, ketika engkau ditinggalkan, dibenci dan tidak disinggahi seorangpun, sekarang Aku akan membuat engkau menjadi kebanggaan abadi, menjadi kegirangan turun-temurun.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 60, 16, 'Engkau akan mengisap susu bangsa-bangsa dan akan meminum susu kerajaan-kerajaan maka engkau akan mengetahui, bahwa Akulah, TUHAN, Juruselamatmu, dan Penebusmu, Yang Mahakuasa, Allah Yakub.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 60, 17, 'Sebagai ganti tembaga Aku akan membawa emas, dan sebagai ganti besi Aku akan membawa perak, sebagai ganti kayu, tembaga, dan sebagai ganti batu, besi; Aku akan memberikan damai sejahtera dan keadilan yang akan melindungi dan mengatur hidupmu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 60, 18, 'Tidak akan ada lagi kabar tentang perbuatan kekerasan di negerimu, tentang kebinasaan atau keruntuhan di daerahmu; engkau akan menyebutkan tembokmu "Selamat" dan pintu-pintu gerbangmu "Pujian".', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 60, 19, 'Bagimu matahari tidak lagi menjadi penerang pada siang hari dan cahaya bulan tidak lagi memberi terang pada malam hari, tetapi TUHAN akan menjadi penerang abadi bagimu dan Allahmu akan menjadi keagunganmu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 60, 20, 'Bagimu akan ada matahari yang tidak pernah terbenam dan bulan yang tidak surut, sebab TUHAN akan menjadi penerang abadi bagimu, dan hari-hari perkabunganmu akan berakhir.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 60, 21, 'Pendudukmu semuanya orang-orang benar, mereka memiliki negeri untuk selama-lamanya; mereka sebagai cangkokan yang Kutanam sendiri untuk memperlihatkan keagungan-Ku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 60, 22, 'Yang paling kecil akan menjadi kaum yang besar, dan yang paling lemah akan menjadi bangsa yang kuat; Aku, TUHAN, akan melaksanakannya dengan segera pada waktunya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 61, 1, 'Roh Tuhan ALLAH ada padaku, oleh karena TUHAN telah mengurapi aku; Ia telah mengutus aku untuk menyampaikan kabar baik kepada orang-orang sengsara, dan merawat orang-orang yang remuk hati, untuk memberitakan pembebasan kepada orang-orang tawanan, dan kepada orang-orang yang terkurung kelepasan dari penjara,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 61, 2, 'untuk memberitakan tahun rahmat TUHAN dan hari pembalasan Allah kita, untuk menghibur semua orang berkabung,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 61, 3, 'untuk mengaruniakan kepada mereka perhiasan kepala ganti abu, minyak untuk pesta ganti kain kabung, nyanyian puji-pujian ganti semangat yang pudar, supaya orang menyebutkan mereka "pohon tarbantin kebenaran", "tanaman TUHAN" untuk memperlihatkan keagungan-Nya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 61, 4, 'Mereka akan membangun reruntuhan yang sudah berabad-abad, dan akan mendirikan kembali tempat-tempat yang sejak dahulu menjadi sunyi; mereka akan membaharui kota-kota yang runtuh, tempat-tempat yang telah turun-temurun menjadi sunyi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 61, 5, 'Orang-orang luar akan melayani kamu sebagai gembala kambing dombamu, dan orang-orang asing akan bekerja bagimu sebagai petani dan tukang kebun anggurmu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 61, 6, 'Tetapi kamu akan disebut imam TUHAN dan akan dinamai pelayan Allah kita. Kamu akan menikmati kekayaan bangsa-bangsa dan akan memegahkan diri dengan segala harta benda mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 61, 7, 'Sebagai ganti bahwa kamu mendapat malu dua kali lipat, dan sebagai ganti noda dan ludah yang menjadi bagianmu, kamu akan mendapat warisan dua kali lipat di negerimu dan sukacita abadi akan menjadi kepunyaanmu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 61, 8, 'Sebab Aku, TUHAN, mencintai hukum, dan membenci perampasan dan kecurangan; Aku akan memberi upahmu dengan tepat, dan akan mengikat perjanjian abadi dengan kamu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 61, 9, 'Keturunanmu akan terkenal di antara bangsa-bangsa, dan anak cucumu di tengah-tengah suku-suku bangsa, sehingga semua orang yang melihat mereka akan mengakui, bahwa mereka adalah keturunan yang diberkati TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 61, 10, 'Aku bersukaria di dalam TUHAN, jiwaku bersorak-sorai di dalam Allahku, sebab Ia mengenakan pakaian keselamatan kepadaku dan menyelubungi aku dengan jubah kebenaran, seperti pengantin laki-laki yang mengenakan perhiasan kepala dan seperti pengantin perempuan yang memakai perhiasannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 61, 11, 'Sebab seperti bumi memancarkan tumbuh-tumbuhan, dan seperti kebun menumbuhkan benih yang ditaburkan, demikianlah Tuhan ALLAH akan menumbuhkan kebenaran dan puji-pujian di depan semua bangsa-bangsa.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 62, 1, 'Oleh karena Sion aku tidak dapat berdiam diri, dan oleh karena Yerusalem aku tidak akan tinggal tenang, sampai kebenarannya bersinar seperti cahaya dan keselamatannya menyala seperti suluh.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 62, 2, 'Maka bangsa-bangsa akan melihat kebenaranmu, dan semua raja akan melihat kemuliaanmu, dan orang akan menyebut engkau dengan nama baru yang akan ditentukan oleh TUHAN sendiri.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 62, 3, 'Engkau akan menjadi mahkota keagungan di tangan TUHAN dan serban kerajaan di tangan Allahmu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 62, 4, 'Engkau tidak akan disebut lagi "yang ditinggalkan suami", dan negerimu tidak akan disebut lagi "yang sunyi", tetapi engkau akan dinamai "yang berkenan kepada-Ku" dan negerimu "yang bersuami", sebab TUHAN telah berkenan kepadamu, dan negerimu akan bersuami.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 62, 5, 'Sebab seperti seorang muda belia menjadi suami seorang anak dara, demikianlah Dia yang membangun engkau akan menjadi suamimu, dan seperti girang hatinya seorang mempelai melihat pengantin perempuan, demikianlah Allahmu akan girang hati atasmu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 62, 6, 'Di atas tembok-tembokmu, hai Yerusalem, telah Kutempatkan pengintai-pengintai. Sepanjang hari dan sepanjang malam, mereka tidak akan pernah berdiam diri. Hai kamu yang harus mengingatkan TUHAN kepada Sion, janganlah kamu tinggal tenang', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 62, 7, 'dan janganlah biarkan Dia tinggal tenang, sampai Ia menegakkan Yerusalem dan sampai Ia membuatnya menjadi kemasyhuran di bumi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 62, 8, 'TUHAN telah bersumpah demi tangan kanan-Nya, demi tangan kekuatan-Nya: "Sesungguhnya, Aku tidak akan memberi gandummu lagi sebagai makanan kepada musuhmu, dan sesungguhnya, orang-orang asing tidak akan meminum air anggurmu yang telah kauhasilkan dengan bersusah-susah;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 62, 9, 'tetapi orang yang menuainya akan memakannya juga dan akan memuji-muji TUHAN, dan orang yang mengumpulkannya akan meminumnya juga di pelataran-pelataran tempat kudus-Ku."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 62, 10, 'Berjalanlah, berjalanlah melalui pintu-pintu gerbang, persiapkanlah jalan bagi umat, bukalah, bukalah jalan raya, singkirkanlah batu-batu, tegakkanlah panji-panji untuk bangsa-bangsa!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 62, 11, 'Sebab inilah yang telah diperdengarkan TUHAN sampai ke ujung bumi! Katakanlah kepada puteri Sion: Sesungguhnya, keselamatanmu datang; sesungguhnya, mereka yang menjadi upah jerih payah-Nya ada bersama-sama Dia dan mereka yang diperoleh-Nya berjalan di hadapan-Nya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 62, 12, 'Orang akan menyebutkan mereka "bangsa kudus", "orang-orang tebusan TUHAN", dan engkau akan disebutkan "yang dicari", "kota yang tidak ditinggalkan".', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 63, 1, '"Siapa dia yang datang dari Edom, yang datang dari Bozra dengan baju yang merah, dia yang bersemarak dengan pakaiannya, yang melangkah dengan kekuatannya yang besar?" "Akulah yang menjanjikan keadilan dan yang berkuasa untuk menyelamatkan!"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 63, 2, '"Mengapakah pakaian-Mu semerah itu, dan baju-Mu seperti baju pengirik buah anggur?"', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 63, 3, '"Aku seorang dirilah yang melakukan pengirikan, dan dari antara umat-Ku tidak ada yang menemani Aku! Aku telah mengirik bangsa-bangsa dalam murka-Ku, dan Aku telah menginjak-injak mereka dalam kehangatan amarah-Ku; semburan darah mereka memercik kepada baju-Ku, dan seluruh pakaian-Ku telah cemar.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 63, 4, 'Sebab hari pembalasan telah Kurencanakan dan tahun penuntutan bela telah datang.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 63, 5, 'Aku melayangkan pandangan-Ku: tidak ada yang menolong; Aku tertegun: tidak ada yang membantu. Lalu tangan-Ku memberi Aku pertolongan, dan kehangatan amarah-Ku, itulah yang membantu Aku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 63, 6, 'Aku memijak-mijak bangsa-bangsa dalam murka-Ku, menghancurkan mereka dalam kehangatan amarah-Ku dan membuat semburan darah mereka mengalir ke tanah."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 63, 7, 'Aku hendak menyebut-nyebut perbuatan kasih setia TUHAN, perbuatan TUHAN yang masyhur, sesuai dengan segala yang dilakukan TUHAN kepada kita, dan kebajikan yang besar kepada kaum Israel yang dilakukan-Nya kepada mereka sesuai dengan kasih sayang-Nya dan sesuai dengan kasih setia-Nya yang besar.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 63, 8, 'Bukankah Ia berfirman: "Sungguh, merekalah umat-Ku, anak-anak yang tidak akan berlaku curang," maka Ia menjadi Juruselamat mereka', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 63, 9, 'dalam segala kesesakan mereka. Bukan seorang duta atau utusan, melainkan Ia sendirilah yang menyelamatkan mereka; Dialah yang menebus mereka dalam kasih-Nya dan belas kasihan-Nya. Ia mengangkat dan menggendong mereka selama zaman dahulu kala.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 63, 10, 'Tetapi mereka memberontak dan mendukakan Roh Kudus-Nya; maka Ia berubah menjadi musuh mereka, dan Ia sendiri berperang melawan mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 63, 11, 'Lalu teringatlah mereka kepada zaman dahulu kala, zaman Musa, hamba-Nya itu: Di manakah Dia yang membawa mereka naik dari laut bersama-sama dengan penggembala kambing domba-Nya? Di manakah Dia yang menaruh Roh Kudus-Nya dalam hati mereka;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 63, 12, 'yang dengan tangan-Nya yang agung menyertai Musa di sebelah kanan; yang membelah air di depan mereka untuk membuat nama abadi bagi-Nya;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 63, 13, 'yang menuntun mereka melintasi samudera raya seperti kuda melintasi padang gurun? Mereka tidak pernah tersandung,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 63, 14, 'seperti ternak yang turun ke dalam lembah. Roh TUHAN membawa mereka ke tempat perhentian. Demikianlah Engkau memimpin umat-Mu untuk membuat nama yang agung bagi-Mu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 63, 15, 'Pandanglah dari sorga dan lihatlah dari kediaman-Mu yang kudus dan agung! Di manakah kecemburuan-Mu dan keperkasaan-Mu, hati-Mu yang tergerak dan kasih sayang-Mu? Janganlah kiranya Engkau menahan diri!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 63, 16, 'Bukankah Engkau Bapa kami? Sungguh, Abraham tidak tahu apa-apa tentang kami, dan Israel tidak mengenal kami. Ya TUHAN, Engkau sendiri Bapa kami; nama-Mu ialah "Penebus kami" sejak dahulu kala.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 63, 17, 'Ya TUHAN, mengapa Engkau biarkan kami sesat dari jalan-Mu, dan mengapa Engkau tegarkan hati kami, sehingga tidak takut kepada-Mu? Kembalilah oleh karena hamba-hamba-Mu, oleh karena suku-suku milik kepunyaan-Mu!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 63, 18, 'Mengapa orang-orang fasik menghina tempat kudus-Mu, para lawan kami memijak-mijak bait kudus-Mu?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 63, 19, 'Keadaan kami seolah-olah kami dari dahulu kala tidak pernah berada di bawah pemerintahan-Mu, seolah-olah nama-Mu tidak pernah disebut atas kami.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 64, 1, 'Sekiranya Engkau mengoyakkan langit dan Engkau turun, sehingga gunung-gunung goyang di hadapan-Mu', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 64, 2, '?seperti api membuat ranggas menyala-nyala dan seperti api membuat air mendidih?untuk membuat nama-Mu dikenal oleh lawan-lawan-Mu, sehingga bangsa-bangsa gemetar di hadapan-Mu,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 64, 3, 'karena Engkau melakukan kedahsyatan yang tidak kami harapkan, seperti tidak pernah didengar orang sejak dahulu kala!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 64, 4, 'Tidak ada telinga yang mendengar, dan tidak ada mata yang melihat seorang allah yang bertindak bagi orang yang menanti-nantikan dia; hanya Engkau yang berbuat demikian.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 64, 5, 'Engkau menyongsong mereka yang melakukan yang benar dan yang mengingat jalan yang Kautunjukkan! Sesungguhnya, Engkau ini murka, sebab kami berdosa; terhadap Engkau kami memberontak sejak dahulu kala.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 64, 6, 'Demikianlah kami sekalian seperti seorang najis dan segala kesalehan kami seperti kain kotor; kami sekalian menjadi layu seperti daun dan kami lenyap oleh kejahatan kami seperti daun dilenyapkan oleh angin.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 64, 7, 'Tidak ada yang memanggil nama-Mu atau yang bangkit untuk berpegang kepada-Mu; sebab Engkau menyembunyikan wajah-Mu terhadap kami, dan menyerahkan kami ke dalam kekuasaan dosa kami.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 64, 8, 'Tetapi sekarang, ya TUHAN, Engkaulah Bapa kami! Kamilah tanah liat dan Engkaulah yang membentuk kami, dan kami sekalian adalah buatan tangan-Mu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 64, 9, 'Ya TUHAN, janganlah murka amat sangat dan janganlah mengingat-ingat dosa untuk seterusnya! Sesungguhnya, pandanglah kiranya, kami sekalian adalah umat-Mu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 64, 10, 'Kota-kota-Mu yang kudus sudah menjadi padang gurun, Sion sudah menjadi padang gurun, Yerusalem sunyi sepi.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 64, 11, 'Bait kami yang kudus dan agung, tempat nenek moyang kami memuji-muji Engkau, sudah menjadi umpan api, maka milik kami yang paling indah sudah menjadi reruntuhan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 64, 12, 'Melihat semuanya ini, ya TUHAN, masakan Engkau menahan diri, masakan Engkau tinggal diam dan menindas kami amat sangat?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 1, 'Aku telah berkenan memberi petunjuk kepada orang yang tidak menanyakan Aku; Aku telah berkenan ditemukan oleh orang yang tidak mencari Aku. Aku telah berkata: "Ini Aku, ini Aku!" kepada bangsa yang tidak memanggil nama-Ku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 2, 'Sepanjang hari Aku telah mengulurkan tangan-Ku kepada suku bangsa yang memberontak, yang menempuh jalan yang tidak baik dan mengikuti rancangannya sendiri;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 3, 'suku bangsa yang menyakitkan hati-Ku senantiasa di depan mata-Ku, dengan mempersembahkan korban di taman-taman dewa dan membakar korban di atas batu bata;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 4, 'yang duduk di kuburan-kuburan dan bermalam di dalam gua-gua; yang memakan daging babi dan kuah daging najis ada dalam kuali mereka;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 5, 'yang berkata: "Menjauhlah, janganlah meraba aku, nanti engkau menjadi kudus olehku!" Semuanya ini seperti asap yang naik ke dalam hidung-Ku, seperti api yang menyala sepanjang hari.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 6, 'Sesungguhnya, telah ada tertulis di hadapan-Ku: Aku tidak akan tinggal diam, malah Aku akan mengadakan pembalasan, ya, pembalasan terhadap diri mereka,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 7, 'atas segala kesalahan mereka sendiri, maupun atas kesalahan nenek moyangnya, semuanya serentak, firman TUHAN. Sebab mereka telah membakar korban di atas gunung-gunung dan mengaibkan Aku di atas bukit-bukit. Memang Aku akan menakar ke dalam jubah mereka upah untuk perbuatan-perbuatan mereka yang dahulu!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 8, 'Beginilah firman TUHAN: "Seperti kata orang jika pada tandan buah anggur masih terdapat airnya: Janganlah musnahkan itu, sebab di dalamnya masih ada berkat! demikianlah Aku akan bertindak oleh karena hamba-hamba-Ku, yakni Aku tidak akan memusnahkan sekaliannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 9, 'Aku akan membangkitkan keturunan dari Yakub, dan orang yang mewarisi gunung-gunung-Ku dari Yehuda; orang-orang pilihan-Ku akan mewarisinya, dan hamba-hamba-Ku akan tinggal di situ.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 10, 'Saron akan menjadi padang rumput bagi kambing domba, dan lembah Akhor menjadi tempat pembaringan bagi lembu sapi, untuk umat-Ku yang mencari Aku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 11, 'Tetapi kamu yang telah meninggalkan TUHAN, yang telah melupakan gunung-Ku yang kudus, yang menyajikan hidangan bagi dewa Gad, dan yang menyuguhkan anggur bercampur rempah bagi dewa Meni:', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 12, 'Aku akan menentukan kamu bagi pedang, dan kamu sekalian akan menekuk lutut untuk dibantai! Oleh karena ketika Aku memanggil, kamu tidak menjawab, ketika Aku berbicara, kamu tidak mendengar, tetapi kamu melakukan apa yang jahat di mata-Ku dan lebih menyukai apa yang tidak berkenan kepada-Ku."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 13, 'Sebab itu beginilah firman Tuhan ALLAH: "Sesungguhnya, hamba-hamba-Ku akan makan, tetapi kamu akan menderita kelaparan; sesungguhnya, hamba-hamba-Ku akan minum, tetapi kamu akan menderita kehausan; sesungguhnya, hamba-hamba-Ku akan bersukacita, tetapi kamu akan mendapat malu;', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 14, 'sesungguhnya, hamba-hamba-Ku akan bersorak-sorai karena gembira hatinya, tetapi kamu akan mengerang karena sedih hati, dan kamu akan menangis karena patah semangat.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 15, 'Kamu harus meninggalkan namamu kepada orang-orang pilihan-Ku untuk dipakai sebagai sumpah kutuk ini: Tuhan ALLAH kiranya membuat engkau seperti mereka! Tetapi hamba-hamba-Ku akan disebut dengan nama lain,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 16, 'sehingga orang yang hendak mendapat berkat di negeri akan memohon berkat demi Allah yang setia, dan orang yang hendak bersumpah di negeri akan bersumpah demi Allah yang setia, sebab kesesakan-kesesakan yang dahulu sudah terlupa, dan sudah tersembunyi dari mata-Ku."', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 17, '"Sebab sesungguhnya, Aku menciptakan langit yang baru dan bumi yang baru; hal-hal yang dahulu tidak akan diingat lagi, dan tidak akan timbul lagi dalam hati.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 18, 'Tetapi bergiranglah dan bersorak-sorak untuk selama-lamanya atas apa yang Kuciptakan, sebab sesungguhnya, Aku menciptakan Yerusalem penuh sorak-sorak dan penduduknya penuh kegirangan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 19, 'Aku akan bersorak-sorak karena Yerusalem, dan bergirang karena umat-Ku; di dalamnya tidak akan kedengaran lagi bunyi tangisan dan bunyi erangpun tidak.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 20, 'Di situ tidak akan ada lagi bayi yang hanya hidup beberapa hari atau orang tua yang tidak mencapai umur suntuk, sebab siapa yang mati pada umur seratus tahun masih akan dianggap muda, dan siapa yang tidak mencapai umur seratus tahun akan dianggap kena kutuk.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 21, 'Mereka akan mendirikan rumah-rumah dan mendiaminya juga; mereka akan menanami kebun-kebun anggur dan memakan buahnya juga.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 22, 'Mereka tidak akan mendirikan sesuatu, supaya orang lain mendiaminya, dan mereka tidak akan menanam sesuatu, supaya orang lain memakan buahnya; sebab umur umat-Ku akan sepanjang umur pohon, dan orang-orang pilihan-Ku akan menikmati pekerjaan tangan mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 23, 'Mereka tidak akan bersusah-susah dengan percuma dan tidak akan melahirkan anak yang akan mati mendadak, sebab mereka itu keturunan orang-orang yang diberkati TUHAN, dan anak cucu mereka ada beserta mereka.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 24, 'Maka sebelum mereka memanggil, Aku sudah menjawabnya; ketika mereka sedang berbicara, Aku sudah mendengarkannya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 65, 25, 'Serigala dan anak domba akan bersama-sama makan rumput, singa akan makan jerami seperti lembu dan ular akan hidup dari debu. Tidak ada yang akan berbuat jahat atau yang berlaku busuk di segenap gunung-Ku yang kudus," firman TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 1, 'Beginilah firman TUHAN: Langit adalah takhta-Ku dan bumi adalah tumpuan kaki-Ku; rumah apakah yang akan kamu dirikan bagi-Ku, dan tempat apakah yang akan menjadi perhentian-Ku?', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 2, 'Bukankah tangan-Ku yang membuat semuanya ini, sehingga semuanya ini terjadi? demikianlah firman TUHAN. Tetapi kepada orang inilah Aku memandang: kepada orang yang tertindas dan patah semangatnya dan yang gentar kepada firman-Ku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 3, 'Orang menyembelih lembu jantan, namun membunuh manusia juga, orang mengorbankan domba, namun mematahkan batang leher anjing, orang mempersembahkan korban sajian, namun mempersembahkan darah babi, orang mempersembahkan kemenyan, namun memuja berhala juga. Karena itu: sama seperti mereka lebih menyukai jalan mereka sendiri, dan jiwanya menghendaki dewa kejijikan mereka,', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 4, 'demikianlah Aku lebih menyukai memperlakukan mereka dengan sewenang-wenang dan mendatangkan kepada mereka apa yang ditakutkan mereka; oleh karena apabila Aku memanggil, tidak ada yang menjawab, apabila Aku berbicara, mereka tidak mendengarkan, tetapi mereka melakukan yang jahat di mata-Ku dan lebih menyukai apa yang tidak Kukehendaki.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 5, 'Dengarlah firman TUHAN, hai kamu yang gentar kepada firman-Nya! Saudara-saudaramu, yang membenci kamu, yang mengucilkan kamu oleh karena kamu menghormati nama-Ku, telah berkata: "Baiklah TUHAN menyatakan kemuliaan-Nya, supaya kami melihat sukacitamu!" Tetapi mereka sendirilah yang mendapat malu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 6, 'Dengar, bunyi kegemparan dari kota, dengar, datangnya dari Bait Suci! Dengar, TUHAN melakukan pembalasan kepada musuh-musuh-Nya!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 7, 'Sebelum menggeliat sakit, ia sudah bersalin, sebelum mengalami sakit beranak, ia sudah melahirkan anak laki-laki.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 8, 'Siapakah yang telah mendengar hal yang seperti itu, siapakah yang telah melihat hal yang demikian? Masakan suatu negeri diperanakkan dalam satu hari, atau suatu bangsa dilahirkan dalam satu kali? Namun baru saja menggeliat sakit, Sion sudah melahirkan anak-anaknya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 9, 'Masakan Aku membukakan rahim orang, dan tidak membuatnya melahirkan? firman TUHAN. Atau masakan Aku membuat orang melahirkan, dan menutup rahimnya pula? firman Allahmu.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 10, 'Bersukacitalah bersama-sama Yerusalem, dan bersorak-soraklah karenanya, hai semua orang yang mencintainya! Bergiranglah bersama-sama dia segirang-girangnya, hai semua orang yang berkabung karenanya!', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 11, 'supaya kamu mengisap dan menjadi kenyang dari susu yang menyegarkan kamu, supaya kamu menghirup dan menikmati dari dadanya yang bernas.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 12, 'Sebab beginilah firman TUHAN: Sesungguhnya, Aku mengalirkan kepadanya keselamatan seperti sungai, dan kekayaan bangsa-bangsa seperti batang air yang membanjir; kamu akan menyusu, akan digendong, akan dibelai-belai di pangkuan.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 13, 'Seperti seseorang yang dihibur ibunya, demikianlah Aku ini akan menghibur kamu; kamu akan dihibur di Yerusalem.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 14, 'Apabila kamu melihatnya, hatimu akan girang, dan kamu akan seperti rumput muda yang tumbuh dengan lebat; maka tangan TUHAN akan nyata kepada hamba-hamba-Nya, dan amarah-Nya kepada musuh-musuh-Nya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 15, 'Sebab sesungguhnya, TUHAN akan datang dengan api, dan kereta-kereta-Nya akan seperti puting beliung, untuk melampiaskan murka-Nya dengan kepanasan dan hardik-Nya dengan nyala api.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 16, 'Sebab TUHAN akan menghukum segala yang hidup dengan api dan dengan pedang-Nya, dan orang-orang yang mati terbunuh oleh TUHAN akan banyak jumlahnya.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 17, 'Mereka yang menguduskan dan mentahirkan dirinya untuk taman-taman dewa, dengan mengikuti seseorang yang ada di tengah-tengahnya, yang memakan daging babi dan binatang-binatang jijik serta tikus, mereka semuanya akan lenyap sekaligus, demikianlah firman TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 18, 'Aku mengenal segala perbuatan dan rancangan mereka, dan Aku datang untuk mengumpulkan segala bangsa dari semua bahasa, dan mereka itu akan datang dan melihat kemuliaan-Ku.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 19, 'Aku akan menaruh tanda di tengah-tengah mereka dan akan mengutus dari antara mereka orang-orang yang terluput kepada bangsa-bangsa, yakni Tarsis, Pul dan Lud, ke Mesekh dan Rosh, ke Tubal dan Yawan, ke pulau-pulau yang jauh yang belum pernah mendengar kabar tentang Aku dan yang belum pernah melihat kemuliaan-Ku, supaya mereka memberitakan kemuliaan-Ku di antara bangsa-bangsa.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 20, 'Mereka itu akan membawa semua saudaramu dari antara segala bangsa sebagai korban untuk TUHAN di atas kuda dan kereta dan di atas usungan, di atas bagal dan unta betina yang cepat, ke atas gunung-Ku yang kudus, ke Yerusalem, firman TUHAN, sama seperti orang Israel membawa korban dalam wadah yang tahir ke dalam rumah TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 21, 'Juga dari antara mereka akan Kuambil imam-imam dan orang-orang Lewi, firman TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 22, 'Sebab sama seperti langit yang baru dan bumi yang baru yang akan Kujadikan itu, tinggal tetap di hadapan-Ku, demikianlah firman TUHAN, demikianlah keturunanmu dan namamu akan tinggal tetap.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 23, 'Bulan berganti bulan, dan Sabat berganti Sabat, maka seluruh umat manusia akan datang untuk sujud menyembah di hadapan-Ku, firman TUHAN.', 'id', 'TB'),
  ('23', 'yes', 'Yesaya', 66, 24, 'Mereka akan keluar dan akan memandangi bangkai orang-orang yang telah memberontak kepada-Ku. Di situ ulat-ulatnya tidak akan mati, dan apinya tidak akan padam, maka semuanya akan menjadi kengerian bagi segala yang hidup.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 1, 1, 'Inilah perkataan-perkataan Yeremia bin Hilkia, dari keturunan imam yang ada di Anatot di tanah Benyamin.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 1, 2, 'Dalam zaman Yosia bin Amon, raja Yehuda, dalam tahun yang ketiga belas dari pemerintahannya datanglah firman TUHAN kepada Yeremia.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 1, 3, 'Firman itu datang juga dalam zaman Yoyakim bin Yosia, raja Yehuda, sampai akhir tahun yang kesebelas zaman Zedekia bin Yosia, raja Yehuda, hingga penduduk Yerusalem diangkut ke dalam pembuangan dalam bulan yang kelima.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 1, 4, 'Firman TUHAN datang kepadaku, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 1, 5, '"Sebelum Aku membentuk engkau dalam rahim ibumu, Aku telah mengenal engkau, dan sebelum engkau keluar dari kandungan, Aku telah menguduskan engkau, Aku telah menetapkan engkau menjadi nabi bagi bangsa-bangsa."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 1, 6, 'Maka aku menjawab: "Ah, Tuhan ALLAH! Sesungguhnya aku tidak pandai berbicara, sebab aku ini masih muda."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 1, 7, 'Tetapi TUHAN berfirman kepadaku: "Janganlah katakan: Aku ini masih muda, tetapi kepada siapapun engkau Kuutus, haruslah engkau pergi, dan apapun yang Kuperintahkan kepadamu, haruslah kausampaikan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 1, 8, 'Janganlah takut kepada mereka, sebab Aku menyertai engkau untuk melepaskan engkau, demikianlah firman TUHAN."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 1, 9, 'Lalu TUHAN mengulurkan tangan-Nya dan menjamah mulutku; TUHAN berfirman kepadaku: "Sesungguhnya, Aku menaruh perkataan-perkataan-Ku ke dalam mulutmu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 1, 10, 'Ketahuilah, pada hari ini Aku mengangkat engkau atas bangsa-bangsa dan atas kerajaan-kerajaan untuk mencabut dan merobohkan, untuk membinasakan dan meruntuhkan, untuk membangun dan menanam."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 1, 11, 'Sesudah itu firman TUHAN datang kepadaku, bunyinya: "Apakah yang kaulihat, hai Yeremia?" Jawabku: "Aku melihat sebatang dahan pohon badam."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 1, 12, 'Lalu firman TUHAN kepadaku: "Baik penglihatanmu, sebab Aku siap sedia untuk melaksanakan firman-Ku."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 1, 13, 'Firman TUHAN datang kepadaku untuk kedua kalinya, bunyinya: "Apakah yang kaulihat?" Jawabku: "Aku melihat sebuah periuk yang mendidih; datangnya dari sebelah utara."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 1, 14, 'Lalu firman TUHAN kepadaku: "Dari utara akan mengamuk malapetaka menimpa segala penduduk negeri ini.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 1, 15, 'Sebab sesungguhnya, Aku memanggil segala kaum kerajaan sebelah utara, demikianlah firman TUHAN, dan mereka akan datang dan mendirikan takhtanya masing-masing di mulut pintu-pintu gerbang Yerusalem, dekat segala tembok di sekelilingnya dan dekat segala kota Yehuda.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 1, 16, 'Maka Aku akan menjatuhkan hukuman-Ku atas mereka, karena segala kejahatan mereka, sebab mereka telah meninggalkan Aku, dengan membakar korban kepada allah lain dan sujud menyembah kepada buatan tangannya sendiri.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 1, 17, 'Tetapi engkau ini, baiklah engkau bersiap, bangkitlah dan sampaikanlah kepada mereka segala yang Kuperintahkan kepadamu. Janganlah gentar terhadap mereka, supaya jangan Aku menggentarkan engkau di depan mereka!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 1, 18, 'Mengenai Aku, sesungguhnya pada hari ini Aku membuat engkau menjadi kota yang berkubu, menjadi tiang besi dan menjadi tembok tembaga melawan seluruh negeri ini, menentang raja-raja Yehuda dan pemuka-pemukanya, menentang para imamnya dan rakyat negeri ini.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 1, 19, 'Mereka akan memerangi engkau, tetapi tidak akan mengalahkan engkau, sebab Aku menyertai engkau untuk melepaskan engkau, demikianlah firman TUHAN."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 1, 'Firman TUHAN datang kepadaku, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 2, '"Pergilah memberitahukan kepada penduduk Yerusalem dengan mengatakan: Beginilah firman TUHAN: Aku teringat kepada kasihmu pada masa mudamu, kepada cintamu pada waktu engkau menjadi pengantin, bagaimana engkau mengikuti Aku di padang gurun, di negeri yang tiada tetaburannya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 3, 'Ketika itu Israel kudus bagi TUHAN, sebagai buah bungaran dari hasil tanah-Nya. Semua orang yang memakannya menjadi bersalah, malapetaka menimpa mereka, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 4, 'Dengarlah firman TUHAN, hai kaum keturunan Yakub, hai segala kaum keluarga keturunan Israel.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 5, 'Beginilah firman TUHAN: Apakah kecurangan yang didapati nenek moyangmu pada-Ku, sehingga mereka menjauh dari pada-Ku, mengikuti dewa kesia-siaan, sampai mereka menjadi sia-sia?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 6, 'Dan mereka tidak lagi bertanya: Di manakah TUHAN, yang menuntun kita keluar dari tanah Mesir; yang memimpin kita di padang gurun, di tanah yang tandus dan yang lekak-lekuk, di tanah yang sangat kering dan gelap, di tanah yang tidak dilintasi orang dan yang tidak didiami manusia?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 7, 'Aku telah membawa kamu ke tanah yang subur untuk menikmati buahnya dan segala yang baik dari padanya. Tetapi segera setelah kamu masuk, kamu menajiskan tanah-Ku; tanah milik-Ku telah kamu buat menjadi kekejian.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 8, 'Para imam tidak lagi bertanya: Di manakah TUHAN? Orang-orang yang melaksanakan hukum tidak mengenal Aku lagi, dan para gembala mendurhaka terhadap Aku. Para nabi bernubuat demi Baal, mereka mengikuti apa yang tidak berguna.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 9, 'Sebab itu Aku akan berbantah lagi dengan kamu, demikianlah firman TUHAN, dan dengan anak cucumu Aku akan berbantah.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 10, 'Menyeberang sajalah ke tanah pesisir orang Kitim dan lihatlah; suruhlah orang ke Kedar dan perhatikanlah dengan sungguh-sungguh! Lihatlah apakah ada terjadi yang seperti ini:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 11, 'pernahkah suatu bangsa menukarkan allahnya meskipun itu sebenarnya bukan allah? Tetapi umat-Ku menukarkan Kemuliaannya dengan apa yang tidak berguna.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 12, 'Tertegunlah atas hal itu, hai langit, menggigil dan gemetarlah dengan sangat, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 13, 'Sebab dua kali umat-Ku berbuat jahat: mereka meninggalkan Aku, sumber air yang hidup, untuk menggali kolam bagi mereka sendiri, yakni kolam yang bocor, yang tidak dapat menahan air.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 14, 'Adakah Israel itu budak atau anak budak? Maka mengapa ia menjadi rampasan?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 15, 'Terhadapnya singa-singa muda mengaum, menyaringkan suaranya; negerinya dibuat orang menjadi tandus, kota-kotanya terbakar, tidak lagi berpenduduk.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 16, 'Bahkan orang-orang Memfis dan Tahpanhes telah menggundul batu kepalamu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 17, 'Bukankah engkau sendiri yang menimpakan ini ke atas dirimu, oleh karena engkau meninggalkan TUHAN, Allahmu, ketika Ia menuntun engkau di jalan?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 18, 'Dan sekarang, apakah untungmu untuk pergi ke Mesir, hendak meminum air sungai Nil? Dan apakah untungmu untuk pergi ke Asyur, hendak meminum air sungai Efrat?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 19, 'Kejahatanmu akan menghajar engkau, dan kemurtadanmu akan menyiksa engkau! Ketahuilah dan lihatlah, betapa jahat dan pedihnya engkau meninggalkan TUHAN, Allahmu; dan tidak gemetar terhadap Aku, demikianlah firman Tuhan ALLAH semesta alam.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 20, 'Sebab dari dahulu kala engkau telah mematahkan kukmu, telah memutuskan tali pengikatmu, dan berkata: Aku tidak mau lagi diperbudak. Bahkan di atas setiap bukit yang menjulang dan di bawah setiap pohon yang rimbun engkau berbaring dan bersundal.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 21, 'Namun Aku telah membuat engkau tumbuh sebagai pokok anggur pilihan, sebagai benih yang sungguh murni. Betapa engkau berubah menjadi pohon berbau busuk, pohon anggur liar!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 22, 'Bahkan, sekalipun engkau mencuci dirimu dengan air abu, dan dengan banyak sabun, namun noda kesalahanmu tetap ada di depan mata-Ku, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 23, 'Bagaimanakah engkau berani berkata: Aku tidak pernah menajiskan diriku, aku tidak pernah mengikuti para Baal? Lihatlah tingkah langkahmu di dalam lembah, ketahuilah apa yang telah kaulakukan: hai, unta betina yang ringan kaki yang berlari-lari kian ke mari,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 24, 'yang melepaskan diri lari ke padang gurun, karena ingin menghirup udara! Siapakah yang dapat menahan nafsunya untuk berjantan? Semua yang mencari dia, tidak usah berlelah, mereka akan menemukannya dalam musim berjantan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 25, 'Jagalah, supaya kakimu jangan tak bersepatu dan supaya rongkonganmu jangan haus! Tetapi engkau berkata: Percuma saja! Percuma! Sebab aku cinta kepada orang-orang asing, jadi aku mau mengikuti mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 26, 'Seperti malunya pencuri, apabila kedapatan, demikianlah malunya kaum Israel, yakni para rajanya, pemukanya, para imamnya dan nabinya,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 27, 'yang berkata kepada sepotong kayu: Engkaulah bapaku! dan kepada batu: Engkaulah yang melahirkan aku! Sungguh, mereka membelakangi Aku dan tidak menghadapkan mukanya kepada-Ku, tetapi pada waktu mereka ditimpa malapetaka mereka berkata: Bangkitlah menyelamatkan kami!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 28, 'Di manakah para allahmu yang kaubuat untuk dirimu? Biarlah mereka bangkit, jika mereka dapat menyelamatkan engkau pada waktu malapetakamu! Sebab seperti banyaknya kotamu demikian banyaknya para allahmu, hai Yehuda!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 29, 'Mengapakah kamu mau berbantah dengan Aku? Kamu sekalian telah mendurhaka kepada-Ku, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 30, 'Sia-sia Aku telah memukuli anak-anakmu, hajaran tidaklah mereka terima; pedangmu sendiri telah memakan habis para nabimu seperti singa muda yang memusnahkan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 31, 'Keturunan apakah kamu ini? Perhatikanlah firman TUHAN! Sudahkah Aku menjadi padang gurun bagi Israel atau tanah yang gelap gulita? Maka mengapa umat-Ku berkata: Kami sudah bebas, kami tidak lagi mau datang kepada-Mu?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 32, 'Dapatkah seorang dara melupakan perhiasannya, atau seorang pengantin perempuan melupakan ikat pinggangnya? Tetapi umat-Ku melupakan Aku, sejak waktu yang tidak terbilang lamanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 33, 'Alangkah baiknya engkau mengatur jalanmu untuk mencari percintaan! Sebab itu juga engkau membiasakan segala jalanmu kepada kejahatan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 34, 'Sampai-sampai pada bajumu terdapat darah orang-orang miskin yang tidak bersalah; bukan waktu mereka membongkar untuk mencuri kaudapati mereka! Meskipun semuanya itu demikian,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 35, 'engkau berkata: Aku tidak bersalah! Memang, murka-Nya telah meninggalkan aku! Sesungguhnya Aku akan membawa engkau ke pengadilan, oleh karena engkau berkata: Aku tidak berdosa!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 36, 'Alangkah ringannya kaupandang untuk mengubah tingkah langkahmu! Juga karena Mesir engkau akan menjadi malu, seperti engkau telah menjadi malu karena Asyur.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 2, 37, 'Dari sanapun juga engkau akan keluar dengan mengangkat tanganmu, sebab TUHAN telah menolak mereka yang telah kaupercayai dan engkau tidak akan berhasil dengan mereka."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 1, 'Firman-Nya: "Jika seseorang menceraikan isterinya, lalu perempuan itu pergi dari padanya dan menjadi isteri orang lain, akan kembalikah laki-laki yang pertama kepada perempuan itu? Bukankah negeri itu sudah tetap cemar? Engkau telah berzinah dengan banyak kekasih, dan mau kembali kepada-Ku? demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 2, 'Layangkanlah matamu ke bukit-bukit gundul dan lihatlah! Di manakah engkau tidak pernah ditiduri? Di pinggir jalan-jalan engkau duduk menantikan kekasih, seperti seorang Arab di padang gurun. Engkau telah mencemarkan negeri dengan zinahmu dan dengan kejahatanmu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 3, 'Sebab itu dirus hujan tertahan dan hujan pada akhir musim tidak datang. Tetapi dahimu adalah dahi perempuan sundal, engkau tidak mengenal malu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 4, 'Bukankah baru saja engkau memanggil Aku: Bapaku! Engkaulah kawanku sejak kecil!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 5, 'Untuk selama-lamanyakah Ia akan murka atau menaruh dendam untuk seterusnya? Demikianlah katamu, namun engkau sedapat-dapatnya melakukan kejahatan."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 6, 'TUHAN berfirman kepadaku dalam zaman raja Yosia: "Sudahkah engkau melihat apa yang dilakukan Israel, perempuan murtad itu, bagaimana dia naik ke atas setiap bukit yang menjulang dan pergi ke bawah setiap pohon yang rimbun untuk bersundal di sana?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 7, 'Pikir-Ku: Sesudah melakukan semuanya ini, ia akan kembali kepada-Ku, tetapi ia tidak kembali. Hal itu telah dilihat oleh Yehuda, saudaranya perempuan yang tidak setia.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 8, 'Dilihatnya, bahwa oleh karena zinahnya Aku telah menceraikan Israel, perempuan murtad itu, dan memberikan kepadanya surat cerai; namun Yehuda, saudaranya perempuan yang tidak setia itu tidak takut, melainkan ia juga pun pergi bersundal.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 9, 'Dengan sundalnya yang sembrono itu maka ia mencemarkan negeri dan berzinah dengan menyembah batu dan kayu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 10, 'Juga dengan semuanya ini Yehuda, saudaranya perempuan yang tidak setia itu, tidak kembali kepada-Ku dengan tulus hatinya, tetapi dengan pura-pura, demikianlah firman TUHAN."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 11, 'Dan TUHAN berfirman kepadaku: "Israel, perempuan murtad itu, membuktikan dirinya lebih benar dari pada Yehuda, perempuan yang tidak setia itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 12, 'Pergilah menyerukan perkataan-perkataan ini ke utara, katakanlah: Kembalilah, hai Israel, perempuan murtad, demikianlah firman TUHAN. Muka-Ku tidak akan muram terhadap kamu, sebab Aku ini murah hati, demikianlah firman TUHAN, tidak akan murka untuk selama-lamanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 13, 'Hanya akuilah kesalahanmu, bahwa engkau telah mendurhaka terhadap TUHAN, Allahmu, telah melampiaskan cinta berahimu kepada orang-orang asing di bawah setiap pohon yang rimbun, dan tidak mendengarkan suara-Ku, demikianlah firman TUHAN."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 14, 'Kembalilah, hai anak-anak yang murtad, demikianlah firman TUHAN, karena Aku telah menjadi tuan atas kamu! Aku akan mengambil kamu, seorang dari setiap kota dan dua orang dari setiap keluarga, dan akan membawa kamu ke Sion.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 15, 'Aku akan mengangkat bagimu gembala-gembala yang sesuai dengan hati-Ku; mereka akan menggembalakan kamu dengan pengetahuan dan pengertian.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 16, 'Apabila pada masa itu kamu bertambah banyak dan beranak cucu di negeri ini, demikianlah firman TUHAN, maka orang tidak lagi akan berbicara tentang tabut perjanjian TUHAN. Itu tidak lagi akan timbul dalam hati dan tidak lagi akan diingat orang; orang tidak lagi akan mencarinya atau membuatnya kembali.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 17, 'Pada waktu itu Yerusalem akan disebut takhta TUHAN, dan segala bangsa akan berkumpul ke sana, demi nama TUHAN ke Yerusalem, dan mereka tidak lagi akan bertingkah langkah menurut kedegilan hatinya yang jahat.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 18, 'Pada masa itu kaum Yehuda akan pergi kepada kaum Israel, dan mereka akan datang bersama-sama dari negeri utara ke negeri yang telah Kubagikan kepada nenek moyangmu menjadi milik pusaka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 19, 'Tadinya pikir-Ku: "Sungguh Aku mau menempatkan engkau di tengah-tengah anak-anak-Ku dan memberikan kepadamu negeri yang indah, milik pusaka yang paling permai dari bangsa-bangsa. Pikir-Ku, engkau akan memanggil Aku: Bapaku, dan tidak akan berbalik dari mengikuti Aku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 20, 'Tetapi sesungguhnya, seperti seorang isteri tidak setia terhadap temannya, demikianlah kamu tidak setia terhadap Aku, hai kaum Israel, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 21, 'Dengar! Di atas bukit-bukit gundul kedengaran tangis memohon-mohon dari anak-anak Israel, sebab mereka telah memilih jalan yang sesat, dan telah melupakan TUHAN, Allah mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 22, 'Kembalilah, hai anak-anak yang murtad! Aku akan menyembuhkan engkau dari murtadmu." "Inilah kami, kami datang kepada-Mu, sebab Engkaulah TUHAN, Allah kami.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 23, 'Sesungguhnya, bukit-bukit pengorbanan adalah tipu daya, yakni keramaian di atas bukit-bukit itu! Sesungguhnya, hanya pada TUHAN, Allah kita, ada keselamatan Israel!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 24, 'Tetapi berhala yang memalukan itu menelan segala hasil jerih lelah nenek moyang kita dari masa muda kita; kambing domba mereka dan lembu-lembu mereka, anak-anak lelaki dan anak-anak perempuan mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 3, 25, 'Maka biarlah kita berbaring dengan perasaan malu, dan biarlah noda kita menyelimuti kita, sebab kita telah berdosa kepada TUHAN, Allah kita, yakni kita dan nenek moyang kita dari masa muda kita sampai hari ini; dan kita tidak mendengarkan suara TUHAN, Allah kita."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 1, '"Jika engkau mau kembali, hai Israel, demikianlah firman TUHAN, kembalilah engkau kepada-Ku; dan jika engkau mau menjauhkan dewa-dewamu yang menjijikkan, tidak usahlah engkau melarikan diri dari hadapan-Ku!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 2, 'Dan jika engkau bersumpah dalam kesetiaan, dalam keadilan dan dalam kebenaran: Demi TUHAN yang hidup!, maka bangsa-bangsa akan saling memberkati di dalam Dia dan akan bermegah di dalam Dia."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 3, 'Sebab beginilah firman TUHAN kepada orang Yehuda dan kepada penduduk Yerusalem: "Bukalah bagimu tanah baru, dan janganlah menabur di tempat duri tumbuh.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 4, 'Sunatlah dirimu bagi TUHAN, dan jauhkanlah kulit khatan hatimu, hai orang Yehuda dan penduduk Yerusalem, supaya jangan murka-Ku mengamuk seperti api, dan menyala-nyala dengan tidak ada yang memadamkan, oleh karena perbuatan-perbuatanmu yang jahat!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 5, 'Beritahukanlah di Yehuda dan kabarkanlah di Yerusalem: Tiuplah sangkakala di dalam negeri, berserulah keras-keras: "Berkumpullah dan marilah kita pergi ke kota-kota yang berkubu!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 6, 'Angkatlah panji-panji ke arah Sion! Cepat-cepatlah kamu mengungsi, jangan tinggal diam! Sebab Aku mendatangkan malapetaka dari utara dan kehancuran yang besar.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 7, 'Singa telah bangkit dari belukar, pemusnah bangsa-bangsa telah berangkat, telah keluar dari tempatnya untuk membuat negerimu menjadi tandus; kota-kotamu akan dijadikan puing, tidak ada yang mendiaminya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 8, 'Oleh karena itu lilitkanlah kain kabung, menangis dan merataplah; sebab murka TUHAN yang menyala-nyala tidak surut dari pada kita.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 9, '"Pada waktu itu, demikianlah firman TUHAN, raja dan para pemuka akan kehilangan semangat; para imam akan tertegun dan para nabi akan tercengang-cengang,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 10, 'sambil berkata: Ah, Tuhan ALLAH, sungguh, Engkau telah sangat memperdayakan bangsa ini dan penduduk Yerusalem, dengan mengatakan: Damai kiranya ada padamu, padahal pedang telah mengancam nyawa kami!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 11, 'Pada masa itu akan dikatakan kepada bangsa ini dan kepada penduduk Yerusalem: "Angin panas dari bukit-bukit gundul di padang gurun bertiup ke arah puteri umat-Ku; bukan untuk menampi dan bukan untuk membersihkan,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 12, 'melainkan angin yang keras datang atas perintah-Ku. Sekarang Aku sendiri akan menjatuhkan hukuman atas mereka."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 13, 'Lihat, ia naik seperti awan-awan, keretanya kencang seperti angin badai, kudanya lebih tangkas dari pada burung rajawali. Celakalah kita, sebab kita dibinasakan!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 14, 'Bersihkanlah hatimu dari kejahatan, hai Yerusalem, supaya engkau diselamatkan! Berapa lama lagi tinggal di dalam hatimu rancangan-rancang kedurjanaanmu?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 15, 'Dengar! Orang memberitahukan dari Dan, mengabarkan malapetaka dari pegunungan Efraim.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 16, 'Peringatkanlah kepada bangsa-bangsa: Sungguh ia datang! Kabarkanlah di Yerusalem: "Pengepung datang dari negeri yang jauh, memperdengarkan suaranya terhadap kota-kota Yehuda.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 17, 'Seperti orang-orang yang menunggui ladang mereka mengelilinginya dari segala pihak, sebab Yehuda telah memberontak terhadap Aku, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 18, 'Tingkah langkahmu dan perbuatanmu telah menyebabkan semuanya ini kepadamu. Itulah nasibmu yang buruk, betapa pahitnya, sampai menusuk hatimu."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 19, 'Aduh, dadaku, dadaku! Aku menggeliat sakit! Aduh, dinding jantungku! Jantungku berdebar-debar, aku tidak dapat berdiam diri, sebab aku mendengar bunyi sangkakala, pekik perang.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 20, 'Kehancuran demi kehancuran dikabarkan, seluruh negeri dirusakkan; kemahku dirusakkan dengan tiba-tiba, tendaku dalam sekejap mata.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 21, 'Berapa lama lagi aku melihat panji-panji itu, dan mendengar bunyi sangkakala itu?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 22, '"Sungguh, bodohlah umat-Ku itu, mereka tidak mengenal Aku! Mereka adalah anak-anak tolol, dan tidak mempunyai pengertian! Mereka pintar untuk berbuat jahat, tetapi untuk berbuat baik mereka tidak tahu."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 23, 'Aku melihat kepada bumi, ternyata campur baur dan kosong, dan melihat kepada langit, tidak ada terangnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 24, 'Aku melihat kepada gunung-gunung, ternyata goncang; dan seluruh bukitpun goyah.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 25, 'Aku melihat, ternyata tidak ada manusia, dan semua burung di udara sudah lari terbang.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 26, 'Aku melihat, ternyata tanah subur sudah menjadi padang gurun, dan segala kotanya sudah runtuh di hadapan TUHAN, di hadapan murka-Nya yang menyala-nyala!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 27, 'Sebab beginilah firman TUHAN: "Seluruh negeri ini akan menjadi sunyi sepi, tetapi Aku tidak akan membuatnya habis lenyap.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 28, 'Karena hal ini bumi akan berkabung, dan langit di atas akan menjadi gelap, sebab Aku telah mengatakannya, Aku telah merancangnya, Aku tidak akan menyesalinya dan tidak akan mundur dari pada itu."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 29, 'Oleh karena hiruk-pikuk pasukan berkuda dan pemanah seluruh negeri melarikan diri. Mereka masuk ke dalam belukar dan naik ke bukit-bukit batu; setiap kota sudah ditinggalkan dan tidak seorangpun tinggal di dalamnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 30, 'Dan engkau, yang dimusnahkan, apakah yang hendak kaulakukan, mengapa engkau mengenakan pakaian kirmizi, menghiasi dirimu dengan perhiasan emas, memalit matamu dengan celak? Sia-sia engkau memperelok dirimu, pencinta-pencintamu menolak engkau, bahkan mereka ingin mencabut nyawamu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 4, 31, 'Sebab aku mendengar suara seperti suara perempuan bersalin, suara orang kesesakan seperti suara ibu yang melahirkan anak pertama, suara puteri Sion yang mengap-mengap, yang merentang-rentangkan tangannya: "Celakalah aku, sebab aku binasa di depan para pembunuh!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 1, 'Lintasilah jalan-jalan Yerusalem, lihatlah baik-baik dan camkanlah! Periksalah di tanah-tanah lapangnya, apakah kamu dapat menemui seseorang, apakah ada yang melakukan keadilan dan yang mencari kebenaran, maka Aku mau mengampuni kota itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 2, 'Sekalipun mereka berkata: "Demi TUHAN yang hidup," namun mereka bersumpah palsu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 3, 'Ya TUHAN, tidakkah mata-Mu terarah kepada kebenaran? Engkau memukul mereka, tetapi mereka tidak kesakitan; Engkau meremukkan mereka, tetapi mereka tidak mau menerima hajaran. Mereka mengeraskan kepalanya lebih dari pada batu, dan mereka tidak mau bertobat.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 4, 'Lalu aku berpikir: "Itu hanya orang-orang kecil; mereka adalah orang-orang bodoh, sebab mereka tidak mengetahui jalan TUHAN, hukum Allah mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 5, 'Baiklah aku pergi kepada orang-orang besar, dan berbicara kepada mereka, sebab merekalah yang mengetahui jalan TUHAN, hukum Allah mereka." Tetapi merekapun semuanya telah mematahkan kuk, telah memutuskan tali-tali pengikat.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 6, 'Sebab itu singa dari hutan akan memukul mati mereka, dan serigala dari padang yang kersang akan merusakkan mereka. Macan tutul akan mengintai di pinggir kota-kota mereka, setiap orang yang ke luar akan diterkam. Sebab pelanggaran mereka amat banyak, dan kesesatannya besar sekali.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 7, 'Bagaimana, kalau begitu, dapatkah Aku mengampuni engkau? Anak-anakmu telah meninggalkan Aku, dan bersumpah demi yang bukan allah. Setelah Aku mengenyangkan mereka, mereka berzinah dan bertemu ke rumah persundalan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 8, 'Mereka adalah kuda-kuda jantan yang gemuk dan gasang, masing-masing meringkik menginginkan isteri sesamanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 9, 'Masakan Aku tidak menghukum mereka karena semuanya ini?, demikianlah firman TUHAN. Masakan Aku tidak membalas dendam-Ku kepada bangsa yang seperti ini?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 10, 'Naiklah ke kebun anggurnya yang bertangga-tangga, rusakkanlah, tetapi jangan membuatnya habis lenyap. Buanglah carang-carang pokok anggurnya, sebab semuanya itu bukan kepunyaan TUHAN!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 11, 'Sebab kaum Israel dan kaum Yehuda telah sungguh-sungguh berlaku tidak setia terhadap Aku, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 12, 'Mereka memungkiri TUHAN dan berkata: "Dia tidak berbuat apa-apa! Malapetaka tidak akan menimpa kita, perang dan kelaparan tidak akan kita alami.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 13, 'Para nabi akan menjadi angin, firman TUHAN tidak ada pada mereka."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 14, 'Sebab itu beginilah firman TUHAN, Allah semesta alam: "Oleh karena mereka berkata seperti itu, maka beginilah akan terjadi kepada mereka: Sesungguhnya Aku akan membuat perkataan-perkataan-Ku menjadi api di dalam mulutmu, dan bangsa ini menjadi kayu bakar, maka api akan memakan habis mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 15, 'Sesungguhnya, Aku akan mendatangkan suatu bangsa dari jauh menyerang kamu, hai kaum Israel, demikianlah firman TUHAN, suatu bangsa yang kokoh kuat, suatu bangsa dari dahulu kala, suatu bangsa yang tidak engkau kenal bahasanya, dan yang tidak engkau mengerti apa yang dikatakannya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 16, 'Tabung panahnya seperti kubur yang ternganga, mereka semuanya adalah pahlawan-pahlawan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 17, 'Mereka akan memakan habis hasil tuaianmu dan makananmu, akan memakan habis anak-anakmu lelaki dan perempuan, akan memakan habis kambing dombamu dan lembu sapimu, akan memakan habis pohon anggurmu dan pohon aramu, akan menghancurkan dengan pedang kota-kotamu yang berkubu, yang kauandalkan."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 18, '"Tetapi pada waktu itupun juga, demikianlah firman TUHAN, Aku tidak akan membuat kamu habis lenyap.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 19, 'Dan apabila kamu nanti bertanya-tanya: Untuk apakah TUHAN, Allah kita, melakukan segala hal ini atas kita?, maka engkau akan menjawab mereka: Seperti kamu meninggalkan Aku dan memperhambakan diri kepada allah asing di negerimu, demikianlah kamu akan memperhambakan diri kepada orang-orang asing di suatu negeri yang bukan negerimu."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 20, 'Beritahukanlah ini di antara kaum keturunan Yakub, kabarkanlah itu di Yehuda dengan mengatakan:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 21, '"Dengarkanlah ini, hai bangsa yang tolol dan yang tidak mempunyai pikiran, yang mempunyai mata, tetapi tidak melihat, yang mempunyai telinga, tetapi tidak mendengar!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 22, 'Masakan kamu tidak takut kepada-Ku, demikianlah firman TUHAN, kamu tidak gemetar terhadap Aku? Bukankah Aku yang membuat pantai pasir sebagai perbatasan bagi laut, sebagai perhinggaan tetap yang tidak dapat dilampauinya? Biarpun ia bergelora, ia tidak sanggup, biarpun gelombang-gelombangnya ribut, mereka tidak dapat melampauinya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 23, 'Tetapi bangsa ini mempunyai hati yang selalu melawan dan memberontak; mereka telah menyimpang dan menghilang.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 24, 'Mereka tidak berkata dalam hatinya: Baiklah kita takut akan TUHAN, Allah kita, yang memberi hujan pada waktunya, hujan pada awal musim maupun hujan pada akhir musim, dan yang menjamin bagi kita minggu-minggu yang tetap untuk panen.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 25, 'Kesalahanmu menghalangi semuanya ini, dan dosamu menghambat yang baik dari padamu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 26, 'Sesungguhnya, di antara umat-Ku terdapat orang-orang fasik yang memasang jaringnya; seperti penangkap burung mereka memasang perangkapnya, mereka menangkap manusia.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 27, 'Seperti sangkar menjadi penuh dengan burung-burung, demikianlah rumah mereka menjadi penuh dengan tipu; itulah sebabnya mereka menjadi orang besar dan kaya,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 28, 'orang gemuk dan gendut. Di samping itu mereka membiarkan berlalu kejahatan-kejahatan, tidak mengindahkan hukum, tidak memenangkan perkara anak yatim, dan tidak membela hak orang miskin.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 29, 'Masakan Aku tidak menghukum mereka karena semuanya ini?, demikianlah firman TUHAN. Masakan Aku tidak membalas dendam-Ku kepada bangsa yang seperti ini?"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 30, 'Kedahsyatan dan kengerian terjadi di negeri ini:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 5, 31, 'Para nabi bernubuat palsu dan para imam mengajar dengan sewenang-wenang, dan umat-Ku menyukai yang demikian! Tetapi apakah yang akan kamu perbuat, apabila datang kesudahannya?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 1, 'Larilah mengungsi, hai orang-orang Benyamin, dari tengah-tengah Yerusalem! Tiuplah sangkakala di Tekoa, dan naikkanlah asap sebagai tanda di atas Bet-Kerem! Sebab malapetaka telah mengintai dari utara, yakni suatu kehancuran besar.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 2, 'Adakah puteri Sion sama seperti padang yang paling disukai,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 3, 'sehingga gembala-gembala mendatanginya beserta kawanan ternak mereka? Mereka telah memasang kemah-kemahnya sekelilingnya, masing-masing memakan habis apa yang didapatnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 4, '"Persiapkanlah perang melawan dia; ayo, marilah kita maju menyerang pada tengah hari!" "Celakalah kita, sebab matahari sudah lingsir, bayang-bayang senja hari sudah memanjang!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 5, '"Ayo, marilah kita maju menyerang pada waktu malam dan merusakkan puri-purinya!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 6, 'Sebab beginilah firman TUHAN semesta alam: "Tebanglah pohon-pohonnya dan timbunlah tanah menjadi tembok terhadap Yerusalem! Itulah kota yang harus dihukum! Hanya penindasan saja di dalamnya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 7, 'Seperti mata air meluapkan airnya, demikianlah kota itu meluapkan kejahatannya. Kekerasan dan aniaya terdengar di dalamnya, luka dan pukulan selalu ada Kulihat.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 8, 'Terimalah penghajaran, hai Yerusalem, supaya Aku jangan menarik diri dari padamu, supaya Aku jangan membuat engkau sunyi sepi, menjadi negeri yang tidak berpenduduk!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 9, 'Beginilah firman TUHAN semesta alam: "Petiklah habis-habisan sisa-sisa orang Israel seperti pokok anggur dipetik habis-habisan. Kembalilah seperti pemetik buah anggur dengan tanganmu mencari-cari buah pada ranting-rantingnya."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 10, 'Kepada siapakah aku harus berbicara dan bersaksi, supaya mereka mau memperhatikan? Sungguh, telinga mereka tidak bersunat, mereka tidak dapat mendengar! Sungguh, firman TUHAN menjadi cemoohan bagi mereka, mereka tidak menyukainya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 11, 'Tetapi aku penuh dengan kehangatan murka TUHAN, aku telah payah menahannya, harus menumpahkannya kepada bayi di jalan, dan kepada kumpulan teruna bersama-sama. Sesungguhnya, baik laki-laki maupun perempuan akan ditangkap, baik orang yang tua maupun orang yang sudah lanjut usianya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 12, 'Rumah-rumah mereka akan beralih kepada orang lain, bersama ladang-ladang dan isteri-isteri mereka. ?"Sesungguhnya, Aku mengacungkan tangan-Ku melawan penduduk negeri ini, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 13, 'Sesungguhnya, dari yang kecil sampai yang besar di antara mereka, semuanya mengejar untung, baik nabi maupun imam semuanya melakukan tipu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 14, 'Mereka mengobati luka umat-Ku dengan memandangnya ringan, katanya: Damai sejahtera! Damai sejahtera!, tetapi tidak ada damai sejahtera.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 15, 'Seharusnya mereka merasa malu, sebab mereka melakukan kejijikan; tetapi mereka sama sekali tidak merasa malu dan tidak kenal noda mereka. Sebab itu mereka akan rebah di antara orang-orang yang rebah; mereka akan tersandung jatuh pada waktu Aku menghukum mereka, firman TUHAN."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 16, 'Beginilah firman TUHAN: "Ambillah tempatmu di jalan-jalan dan lihatlah, tanyakanlah jalan-jalan yang dahulu kala, di manakah jalan yang baik, tempuhlah itu, dengan demikian jiwamu mendapat ketenangan. Tetapi mereka berkata: Kami tidak mau menempuhnya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 17, 'Juga aku mengangkat atas mereka penjaga-penjaga, firman-Ku: Perhatikanlah bunyi sangkakala! Tetapi mereka berkata: Kami tidak mau memperhatikannya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 18, 'Sebab itu dengarlah, hai bangsa-bangsa, dan ketahuilah, hai jemaat, apa yang akan terjadi atas mereka!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 19, 'Dengarlah, hai bumi! Sungguh, ke atas bangsa ini Aku akan mendatangkan malapetaka, akibat dari rancangan-rancangan mereka, sebab mereka tidak memperhatikan perkataan-perkataan-Ku dan menolak pengajaran-Ku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 20, 'Apakah gunanya bagi-Ku kamu bawa kemenyan dari Syeba dan tebu yang baik dari negeri yang jauh? Aku tidak berkenan kepada korban-korban bakaranmu dan korban-korban sembelihanmu tidak menyenangkan hati-Ku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 21, 'Sebab itu beginilah firman TUHAN: Sungguh, Aku akan menaruh batu sandungan di depan bangsa ini, supaya mereka jatuh tersandung oleh karenanya; bapa-bapa serta dengan anak-anak, tetangga dan temannya, semuanya akan binasa."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 22, 'Beginilah firman TUHAN: "Sesungguhnya, suatu bangsa akan datang dari tanah utara, suatu suku bangsa yang besar akan bergerak maju dari ujung bumi.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 23, 'Mereka memakai panah dan tombak; mereka bengis, tidak kenal belas kasihan. Suara mereka gemuruh seperti laut, mereka mengendarai kuda, berlengkap seperti orang maju berperang, menyerang engkau, hai puteri Sion!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 24, 'Kami telah mendengar kabarnya, tangan kami sudah menjadi lemah lesu; kesesakan telah menyergap kami, kami kesakitan seperti perempuan yang melahirkan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 25, '"Janganlah keluar ke padang, dan janganlah berjalan di jalan, sebab pedang musuh mengamuk?kegentaran datang dari segala jurusan!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 26, 'Hai puteri bangsaku, kenakanlah kain kabung, dan berguling-gulinglah dalam debu! Berkabunglah seperti menangisi seorang anak tunggal, merataplah dengan pahit pedih! Sebab sekonyong-konyong akan datang si pembinasa menyerangmu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 27, 'Aku telah mengangkat engkau di antara umat-Ku sebagai penguji, engkau harus tahu bagaimana menyelidikinya, dan harus menguji tingkah langkah mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 28, 'Semua mereka adalah pendurhaka belaka, berjalan kian kemari sebagai pemfitnah; sekaliannya mereka berlaku busuk!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 29, 'Puputan sudah mengembus, tetapi yang keluar dari api hanya timah hitam, tembaga dan besi. Sia-sia orang melebur terus-menerus, tetapi orang-orang yang jahat tidak terpisahkan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 6, 30, 'Sebutkanlah mereka perak yang ditolak, sebab TUHAN telah menolak mereka!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 1, 'Firman yang datang kepada Yeremia dari pada TUHAN, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 2, '"Berdirilah di pintu gerbang rumah TUHAN, serukanlah di sana firman ini dan katakanlah: Dengarlah firman TUHAN, hai sekalian orang Yehuda yang masuk melalui semua pintu gerbang ini untuk sujud menyembah kepada TUHAN!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 3, 'Beginilah firman TUHAN semesta alam, Allah Israel: Perbaikilah tingkah langkahmu dan perbuatanmu, maka Aku mau diam bersama-sama kamu di tempat ini.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 4, 'Janganlah percaya kepada perkataan dusta yang berbunyi: Ini bait TUHAN, bait TUHAN, bait TUHAN,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 5, 'melainkan jika kamu sungguh-sungguh memperbaiki tingkah langkahmu dan perbuatanmu, jika kamu sungguh-sungguh melaksanakan keadilan di antara kamu masing-masing,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 6, 'tidak menindas orang asing, yatim dan janda, tidak menumpahkan darah orang yang tak bersalah di tempat ini dan tidak mengikuti allah lain, yang menjadi kemalanganmu sendiri,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 7, 'maka Aku mau diam bersama-sama kamu di tempat ini, di tanah yang telah Kuberikan kepada nenek moyangmu, dari dahulu kala sampai selama-lamanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 8, 'Tetapi sesungguhnya, kamu percaya kepada perkataan dusta yang tidak memberi faedah.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 9, 'Masakan kamu mencuri, membunuh, berzinah dan bersumpah palsu, membakar korban kepada Baal dan mengikuti allah lain yang tidak kamu kenal,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 10, 'kemudian kamu datang berdiri di hadapan-Ku di rumah yang atasnya nama-Ku diserukan, sambil berkata: Kita selamat, supaya dapat pula melakukan segala perbuatan yang keji ini!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 11, 'Sudahkah menjadi sarang penyamun di matamu rumah yang atasnya nama-Ku diserukan ini? Kalau Aku, Aku sendiri melihat semuanya, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 12, 'Tetapi baiklah pergi dahulu ke tempat-Ku yang di Silo itu, di mana Aku membuat nama-Ku diam dahulu, dan lihatlah apa yang telah Kulakukan kepadanya karena kejahatan umat-Ku Israel!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 13, 'Maka sekarang, oleh karena kamu telah melakukan segala perbuatan itu juga, demikianlah firman TUHAN, dan oleh karena kamu tidak mau mendengarkan, sekalipun Aku berbicara kepadamu terus-menerus, dan kamu tidak mau menjawab, sekalipun Aku berseru kepadamu,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 14, 'karena itulah kepada rumah, yang atasnya nama-Ku diserukan dan yang kamu andalkan itu, dan kepada tempat, yang telah Kuberikan kepadamu dan kepada nenek moyangmu itu, akan Kulakukan seperti yang telah Kulakukan kepada Silo;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 15, 'Aku akan melemparkan kamu dari hadapan-Ku, seperti semua saudaramu, yakni seluruh keturunan Efraim, telah Kulemparkan."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 16, '"Tetapi engkau, janganlah berdoa untuk bangsa ini, janganlah sampaikan seruan permohonan dan doa untuk mereka, dan janganlah desak Aku, sebab Aku tidak akan mendengarkan engkau.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 17, 'Tiadakah engkau melihat apa yang dilakukan mereka di kota-kota Yehuda dan di jalan-jalan Yerusalem?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 18, 'Anak-anak memungut kayu bakar, bapa-bapa menyalakan api dan perempuan-perempuan meremas adonan untuk membuat penganan persembahan bagi ratu sorga, dan orang mempersembahkan korban curahan kepada allah lain dengan maksud menyakiti hati-Ku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 19, 'Hati-Kukah sebenarnya yang mereka sakiti, demikianlah firman TUHAN, bukankah hati mereka sendiri, sehingga mereka menjadi malu?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 20, 'Sebab itu beginilah firman Tuhan ALLAH: Sesungguhnya, murka-Ku dan kehangatan amarah-Ku akan tercurah ke tempat ini, ke atas manusia, ke atas hewan, ke atas pohon-pohonan di padang dan ke atas hasil tanah; amarah itu akan menyala-nyala dengan tidak padam-padam."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 21, 'Beginilah firman TUHAN semesta alam, Allah Israel: "Tambah sajalah korban bakaranmu kepada korban sembelihanmu dan nikmatilah dagingnya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 22, 'Sungguh, pada waktu Aku membawa nenek moyangmu keluar dari tanah Mesir Aku tidak mengatakan atau memerintahkan kepada mereka sesuatu tentang korban bakaran dan korban sembelihan;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 23, 'hanya yang berikut inilah yang telah Kuperintahkan kepada mereka: Dengarkanlah suara-Ku, maka Aku akan menjadi Allahmu dan kamu akan menjadi umat-Ku, dan ikutilah seluruh jalan yang Kuperintahkan kepadamu, supaya kamu berbahagia!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 24, 'Tetapi mereka tidak mau mendengarkan dan tidak mau memberi perhatian, melainkan mereka mengikuti rancangan-rancangan dan kedegilan hatinya yang jahat, dan mereka memperlihatkan belakangnya dan bukan mukanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 25, 'Dari sejak waktu nenek moyangmu keluar dari tanah Mesir sampai waktu ini, Aku mengutus kepada mereka hamba-hamba-Ku, para nabi, hari demi hari, terus-menerus,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 26, 'tetapi mereka tidak mau mendengarkan kepada-Ku dan tidak mau memberi perhatian, bahkan mereka menegarkan tengkuknya, berbuat lebih jahat dari pada nenek moyang mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 27, 'Sekalipun engkau mengatakan kepada mereka segala perkara ini, mereka tidak akan mendengarkan perkataanmu, dan sekalipun engkau berseru kepada mereka, mereka tidak akan menjawab engkau.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 28, 'Sebab itu, katakanlah kepada mereka: Inilah bangsa yang tidak mau mendengarkan suara TUHAN, Allah mereka, dan yang tidak mau menerima penghajaran! Ketulusan mereka sudah lenyap, sudah hapus dari mulut mereka."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 29, 'Cukurlah rambut kepalamu dan buanglah! Angkatlah ratapan di atas bukit-bukit gundul, sebab TUHAN telah menolak dan membuang bangsa yang kena murka-Nya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 30, 'Sungguh, orang Yehuda telah melakukan apa yang jahat di mata-Ku, demikianlah firman TUHAN, telah menempatkan dewa-dewa mereka yang menjijikkan di rumah yang atasnya nama-Ku diserukan ini untuk menajiskannya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 31, 'Mereka telah mendirikan bukit pengorbanan yang bernama Tofet di Lembah Ben-Hinom untuk membakar anak-anaknya lelaki dan perempuan, suatu hal yang tidak pernah Kuperintahkan dan yang tidak pernah timbul dalam hati-Ku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 32, 'Sebab itu, sesungguhnya, waktunya akan datang, demikianlah firman TUHAN, bahwa orang tidak akan mengatakan lagi "Tofet" dan "Lembah Ben-Hinom", melainkan "Lembah Pembunuhan"; orang akan menguburkan mayat di Tofet karena kekurangan tempat,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 33, 'bahkan mayat bangsa ini akan menjadi makanan burung-burung di udara serta binatang-binatang di bumi dengan tidak ada yang mengganggunya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 7, 34, 'Di kota-kota Yehuda serta di jalan-jalan Yerusalem akan Kuhentikan suara kegirangan dan suara sukacita, suara pengantin laki-laki dan suara pengantin perempuan, sebab negeri itu akan menjadi tempat yang tandus.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 8, 1, 'Pada masa itu, demikianlah firman TUHAN, tulang-tulang raja-raja Yehuda, tulang-tulang pemuka-pemukanya, tulang-tulang imam-imam, tulang-tulang nabi-nabi dan tulang-tulang segenap penduduk Yerusalem akan dikeluarkan dari dalam kubur mereka', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 8, 2, 'dan diserakkan di depan matahari, di depan bulan dan di depan segenap tentara langit yang dahulunya dicintai, diabdi, diikuti, ditanyakan dan disembah oleh mereka. Semuanya itu tidak akan dikumpulkan dan tidak akan dikuburkan; mereka akan menjadi pupuk di ladang.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 8, 3, 'Tetapi semua orang yang masih tinggal dari kaum yang jahat ini akan lebih suka mati dari pada hidup di segala tempat ke mana Aku menceraiberaikan mereka, demikianlah firman TUHAN semesta alam.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 8, 4, 'Engkau harus mengatakan kepada mereka: "Beginilah firman TUHAN: Apabila orang jatuh, masakan ia tidak bangun kembali? Apabila orang berpaling, masakan ia tidak kembali?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 8, 5, 'Mengapakah bangsa ini berpaling, berpaling terus-menerus? Mereka berpegang pada tipu, mereka menolak untuk kembali.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 8, 6, 'Aku telah memperhatikan dan mendengarkan: mereka tidak berkata dengan jujur! Tidak ada yang menyesal karena kejahatannya dengan mengatakan: Apakah yang telah kulakukan ini! Sambil berlari semua mereka berpaling, seperti kuda yang menceburkan diri ke dalam pertempuran.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 8, 7, 'Bahkan burung ranggung di udara mengetahui musimnya, burung tekukur, burung layang-layang dan burung bangau berpegang pada waktu kembalinya, tetapi umat-Ku tidak mengetahui hukum TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 8, 8, 'Bagaimanakah kamu berani berkata: Kami bijaksana, dan kami mempunyai Taurat TUHAN? Sesungguhnya, pena palsu penyurat sudah membuatnya menjadi bohong.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 8, 9, 'Orang-orang bijaksana akan menjadi malu, akan terkejut dan tertangkap. Sesungguhnya, mereka telah menolak firman TUHAN, maka kebijaksanaan apakah yang masih ada pada mereka?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 8, 10, 'Sebab itu Aku akan memberikan isteri-isteri mereka kepada orang lain, ladang-ladang mereka kepada penjajah. Sesungguhnya, dari yang kecil sampai yang besar, semuanya mengejar untung; baik nabi maupun imam, semuanya melakukan tipu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 8, 11, 'Mereka mengobati luka puteri umat-Ku dengan memandangnya ringan, katanya: Damai sejahtera! Damai sejahtera!, tetapi tidak ada damai sejahtera.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 8, 12, 'Seharusnya mereka merasa malu, sebab mereka melakukan kejijikan; tetapi mereka sama sekali tidak merasa malu dan tidak kenal noda mereka. Sebab itu mereka akan rebah di antara orang-orang yang rebah, mereka akan tersandung jatuh pada waktu mereka dihukum, firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 8, 13, 'Aku mau memungut hasil mereka, demikianlah firman TUHAN, tetapi tidak ada buah anggur pada pohon anggur, tidak ada buah ara pada pohon ara, dan daun-daunan sudah layu; sebab itu Aku akan menetapkan bagi mereka orang-orang yang akan melindas mereka."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 8, 14, 'Mengapakah kita duduk-duduk saja? Berkumpullah dan marilah kita pergi ke kota-kota yang berkubu dan binasa di sana! Sebab TUHAN, Allah kita, membinasakan kita, memberi kita minum racun, sebab kita telah berdosa kepada TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 8, 15, 'Kita mengharapkan damai, tetapi tidak datang sesuatu yang baik, mengharapkan waktu kesembuhan, tetapi yang ada hanya kengerian!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 8, 16, '"Dengus kuda musuh terdengar dari Dan; karena bunyi ringkik kuda jantan mereka gemetarlah seluruh negeri. Mereka datang dan memakan habis negeri dengan isinya, kota dengan penduduknya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 8, 17, 'Lihatlah, Aku melepaskan ke antaramu ular-ular beludak, yang tidak dapat dimanterai, yang akan memagut kamu, demikianlah firman TUHAN."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 8, 18, 'Tidak tersembuhkan kedukaan yang menimpa diriku, hatiku sakit pedih.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 8, 19, 'Dengar! seruan puteri bangsaku minta tolong dari negeri yang jauh: "Tidak adakah TUHAN di Sion? Tidak adakah Rajanya di dalamnya?" ?Mengapakah mereka menimbulkan sakit hati-Ku dengan patung-patung mereka, dengan dewa-dewa asing yang sia-sia? ?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 8, 20, 'Sudah lewat musim menuai, sudah berakhir musim kemarau, tetapi kita belum diselamatkan juga!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 8, 21, 'Karena luka puteri bangsaku hatiku luka; aku berkabung, kedahsyatan telah menyergap aku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 8, 22, 'Tidak adakah balsam di Gilead? Tidak adakah tabib di sana? Mengapakah belum datang juga kesembuhan luka puteri bangsaku?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 1, 'Sekiranya kepalaku penuh air, dan mataku jadi pancuran air mata, maka siang malam aku akan menangisi orang-orang puteri bangsaku yang terbunuh!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 2, 'Sekiranya di padang gurun aku mempunyai tempat penginapan bagi orang-orang yang sedang dalam perjalanan, maka aku akan meninggalkan bangsaku dan menyingkir dari pada mereka! Sebab mereka sekalian adalah orang-orang berzinah, suatu kumpulan orang-orang yang tidak setia.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 3, 'Mereka melenturkan lidahnya seperti busur; dusta dan bukan kebenaran merajalela dalam negeri; sungguh, mereka melangkah dari kejahatan kepada kejahatan, tetapi TUHAN tidaklah mereka kenal.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 4, 'Baiklah setiap orang berjaga-jaga terhadap temannya, dan janganlah percaya kepada saudara manapun, sebab setiap saudara adalah penipu ulung, dan setiap teman berjalan kian ke mari sebagai pemfitnah.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 5, 'Yang seorang menipu yang lain, dan tidak seorangpun berkata benar; mereka sudah membiasakan lidahnya untuk berkata dusta; mereka melakukan kesalahan dan malas untuk bertobat.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 6, 'Penindasan ditimbuni penindasan, tipu ditimbuni tipu! Mereka enggan mengenal TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 7, 'Sebab itu beginilah firman TUHAN semesta alam: "Sesungguhnya, Aku mau melebur dan menguji mereka, sebab apakah lagi yang dapat Kulakukan terhadap puteri umat-Ku?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 8, 'Lidah mereka adalah anak panah yang membunuh, perkataan dari mulutnya adalah tipu; mereka berbicara damai dengan temannya, tetapi dalam hatinya mereka merancang pengadangan terhadapnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 9, 'Masakan Aku tidak menghukum mereka karena semuanya ini?, demikianlah firman TUHAN. Masakan Aku tidak membalas dendam-Ku kepada bangsa yang seperti ini?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 10, 'Menangis dan merintihlah karena gunung-gunung, dan merataplah karena padang rumput di gurun, sebab semuanya sudah tandus sampai tidak ada orang yang melintasinya, dan orang tidak mendengar lagi suara ternak; baik burung-burung di udara maupun binatang-binatang, semuanya telah lari dan sudah lenyap.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 11, 'Aku akan membuat Yerusalem menjadi timbunan puing, tempat persembunyian serigala-serigala; Aku akan membuat kota-kota Yehuda menjadi sunyi sepi, tidak berpenduduk lagi."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 12, 'Siapakah orang yang begitu bijaksana, sehingga ia dapat mengerti hal ini, orang yang telah menerima firman dari mulut TUHAN, supaya ia dapat memberitahukannya? Apakah sebabnya negeri ini binasa, tandus seperti padang gurun sampai tidak ada orang yang melintasinya?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 13, 'Berfirmanlah TUHAN: "Oleh karena mereka meninggalkan Taurat-Ku yang telah Kuserahkan kepada mereka, dan oleh karena mereka tidak mendengarkan suara-Ku dan tidak mengikutinya,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 14, 'melainkan mengikuti kedegilan hatinya dan mengikuti para Baal seperti yang diajarkan kepada mereka oleh nenek moyang mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 15, 'Sebab itu beginilah firman TUHAN semesta alam, Allah Israel: Sesungguhnya, Aku akan memberi bangsa ini makan ipuh dan minum racun.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 16, 'Aku akan menyerakkan mereka ke antara bangsa-bangsa yang tidak dikenal oleh mereka atau oleh nenek moyang mereka, dan Aku akan melepas pedang mengejar mereka sampai Aku membinasakan mereka."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 17, 'Perhatikanlah! Panggillah perempuan-perempuan peratap, supaya mereka datang, dan suruhlah orang kepada perempuan-perempuan yang bijaksana, supaya mereka datang!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 18, 'Biarlah mereka bersegera dan meratap karena kita, supaya mata kita mencucurkan air mata, dan kelopak mata kita melelehkan air!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 19, 'Sebab terdengar ratapan dari Sion: Wahai binasalah kami! Kami sangat dipermalukan! Sebab kami harus meninggalkan negeri ini, karena rumah-rumah kediaman kami dirobohkan orang.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 20, 'Maka dengarlah firman TUHAN, hai perempuan-perempuan, biarlah telingamu menerima firman dari mulut-Nya; ajarkanlah ratapan kepada anak-anakmu perempuan, dan oleh setiap perempuan nyanyian ratapan kepada temannya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 21, '"Maut telah menyusup ke jendela-jendela kita, masuk ke dalam istana-istana kita; ia melenyapkan kanak-kanak dari jalan, pemuda-pemuda dari lapangan;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 22, 'mayat-mayat manusia berhantaran seperti pupuk di ladang, seperti berkas gandum di belakang orang-orang yang menuai tanpa ada yang mengumpulkan."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 23, 'Beginilah firman TUHAN: "Janganlah orang bijaksana bermegah karena kebijaksanaannya, janganlah orang kuat bermegah karena kekuatannya, janganlah orang kaya bermegah karena kekayaannya,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 24, 'tetapi siapa yang mau bermegah, baiklah bermegah karena yang berikut: bahwa ia memahami dan mengenal Aku, bahwa Akulah TUHAN yang menunjukkan kasih setia, keadilan dan kebenaran di bumi; sungguh, semuanya itu Kusukai, demikianlah firman TUHAN."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 25, '"Lihat, waktunya akan datang, demikianlah firman TUHAN, bahwa Aku menghukum orang-orang yang telah bersunat kulit khatannya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 9, 26, 'orang Mesir, orang Yehuda, orang Edom, bani Amon, orang Moab dan semua orang yang berpotong tepi rambutnya berkeliling, orang-orang yang diam di padang gurun, sebab segala bangsa tidak bersunat dan segenap kaum Israel tidak bersunat hatinya."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 1, 'Dengarlah firman yang disampaikan TUHAN kepadamu, hai kaum Israel!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 2, 'Beginilah firman TUHAN: "Janganlah biasakan dirimu dengan tingkah langkah bangsa-bangsa, janganlah gentar terhadap tanda-tanda di langit, sekalipun bangsa-bangsa gentar terhadapnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 3, 'Sebab yang disegani bangsa-bangsa adalah kesia-siaan. Bukankah berhala itu pohon kayu yang ditebang orang dari hutan, yang dikerjakan dengan pahat oleh tangan tukang kayu?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 4, 'Orang memperindahnya dengan emas dan perak; orang memperkuatnya dengan paku dan palu, supaya jangan goyang.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 5, 'Berhala itu sama seperti orang-orangan di kebun mentimun, tidak dapat berbicara; orang harus mengangkatnya, sebab tidak dapat melangkah. Janganlah takut kepadanya, sebab berhala itu tidak dapat berbuat jahat, dan berbuat baikpun tidak dapat."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 6, 'Tidak ada yang sama seperti Engkau, ya TUHAN! Engkau besar dan nama-Mu besar oleh keperkasaan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 7, 'Siapakah yang tidak takut kepada-Mu, ya Raja bangsa-bangsa? Sungguh, kepada-Mulah seharusnya sikap yang demikian; sebab di antara semua orang bijaksana dari bangsa-bangsa dan di antara raja-raja mereka tidak ada yang sama seperti Engkau!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 8, 'Berhala itu semuanya bodoh dan dungu; petunjuk dewa itu sia-sia, karena ia hanya kayu belaka. ?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 9, 'Perak kepingan dibawa dari Tarsis, dan emas dari Ufas; berhala itu buatan tukang dan buatan tangan pandai emas. Pakaiannya dari kain ungu tua dan kain ungu muda, semuanya buatan orang-orang ahli. ?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 10, 'Tetapi TUHAN adalah Allah yang benar, Dialah Allah yang hidup dan Raja yang kekal. Bumi goncang karena murka-Nya, dan bangsa-bangsa tidak tahan akan geram-Nya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 11, 'Beginilah harus kamu katakan kepada mereka: "Para allah yang tidak menjadikan langit dan bumi akan lenyap dari bumi dan dari kolong langit ini."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 12, 'Tuhanlah yang menjadikan bumi dengan kekuatan-Nya, yang menegakkan dunia dengan kebijaksanaan-Nya, dan yang membentangkan langit dengan akal budi-Nya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 13, 'Apabila Ia memperdengarkan suara-Nya, menderulah bunyi air di langit, Ia menaikkan kabut awan dari ujung bumi, Ia membuat kilat serta dengan hujan, dan mengeluarkan angin dari perbendaharaan-Nya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 14, 'Setiap manusia ternyata bodoh, tidak berpengetahuan, dan setiap pandai emas menjadi malu karena patung buatannya. Sebab patung tuangannya itu adalah tipu, tidak ada nyawa di dalamnya,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 15, 'semuanya adalah kesia-siaan, pekerjaan yang menjadi buah ejekan, dan yang akan binasa pada waktu dihukum.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 16, 'Tidaklah begitu Dia yang menjadi bagian Yakub, sebab Dialah yang membentuk segala-galanya, dan Israel adalah suku milik-Nya; nama-Nya ialah TUHAN semesta alam!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 17, 'Angkutlah barang-barangmu dari negeri ini, hai orang-orang yang berada dalam pengepungan!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 18, 'Sebab beginilah firman TUHAN: "Sesungguhnya, sekali ini Aku akan melemparkan penduduk negeri ini, dan Aku akan menyesakkan mereka, supaya mereka merasakannya." ?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 19, 'Celakalah aku karena penyakitku, lukaku tidak tersembuhkan! Aku berpikir: "Ah, inilah suatu kepedihan yang harus kutanggung!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 20, 'Kemahku sudah rusak, dan semua talinya sudah putus. Anak-anakku telah pergi dari padaku, tidak ada lagi; tidak ada lagi yang mendirikan kemahku dan yang membentangkan tendaku. ?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 21, 'Sungguh, gembala-gembala sudah menjadi bodoh, mereka tidak menanyakan petunjuk TUHAN. Sebab itu mereka tidak berbahagia dan seluruh binatang gembalaan mereka cerai-berai.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 22, 'Terdengarlah suatu berita, bunyinya: Kegemparan besar akan datang dari tanah sebelah utara, untuk membuat kota-kota Yehuda menjadi sunyi sepi, menjadi tempat persembunyian serigala-serigala.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 23, 'Aku tahu, ya TUHAN, bahwa manusia tidak berkuasa untuk menentukan jalannya, dan orang yang berjalan tidak berkuasa untuk menetapkan langkahnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 24, 'Hajarlah aku, ya TUHAN, tetapi dengan selayaknya, jangan dengan murka-Mu, supaya aku jangan Kaubinasakan!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 10, 25, 'Tumpahkanlah kepanasan amarah-Mu ke atas bangsa-bangsa yang tidak mengenal Engkau, ke atas kaum-kaum keluarga yang tidak menyerukan nama-Mu; sebab mereka telah memakan Yakub dan menghabisinya, dan membuat tempat kediamannya menjadi puing.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 1, 'Firman yang datang kepada Yeremia dari TUHAN, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 2, '"Dengarlah perkataan-perkataan perjanjian ini dan sampaikanlah itu kepada orang Yehuda dan kepada penduduk Yerusalem!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 3, 'Katakanlah kepada mereka: Beginilah firman TUHAN, Allah Israel: Terkutuklah orang yang tidak mendengarkan perkataan-perkataan perjanjian ini,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 4, 'yang telah Kuperintahkan kepada nenek moyangmu pada waktu mereka Kubawa keluar dari tanah Mesir, dari dapur peleburan besi, dengan berfirman: Dengarkanlah suara-Ku dan lakukanlah segala apa yang Kuperintahkan kepadamu, maka kamu akan menjadi umat-Ku dan Aku akan menjadi Allahmu,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 5, 'sehingga Aku dapat menepati sumpah yang telah Kuikrarkan kepada nenek moyangmu untuk memberikan kepada mereka tanah yang berlimpah-limpah susu dan madunya, seperti halnya pada waktu ini." Lalu jawabku: "Begitulah hendaknya, ya TUHAN!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 6, 'Berfirmanlah TUHAN kepadaku: "Serukanlah segala perkataan ini di kota-kota Yehuda dan di jalan-jalan Yerusalem dengan mengatakan: Dengarkanlah perkataan-perkataan perjanjian ini dan lakukanlah itu!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 7, 'Sebab Aku sungguh-sungguh memperingatkan nenek moyangmu, pada waktu Aku menuntun mereka keluar dari tanah Mesir; sampai kepada waktu ini Aku memperingatkan mereka terus-menerus: Dengarkanlah suara-Ku!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 8, 'Tetapi mereka tidak mau mendengarkan ataupun memperhatikannya, melainkan mereka masing-masing mengikuti kedegilan hatinya yang jahat; maka Aku telah mendatangkan ke atas mereka segala perkataan perjanjian ini, yang telah Kuperintahkan dipegang, tetapi mereka tidak memegangnya."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 9, 'Berfirmanlah TUHAN kepadaku: "Telah terdapat persepakatan jahat di antara orang Yehuda dan penduduk Yerusalem.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 10, 'Mereka sudah jatuh kembali kepada kesalahan nenek moyang mereka yang dahulu telah menolak mendengarkan firman-Ku. Mereka mengikuti allah lain dan beribadah kepadanya. Kaum Israel dan kaum Yehuda telah mengingkari perjanjian-Ku yang telah Kuikat dengan nenek moyang mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 11, 'Sebab itu beginilah firman TUHAN: Sesungguhnya, Aku mendatangkan ke atas mereka malapetaka yang tidak dapat mereka hindari, dan apabila mereka berseru-seru kepada-Ku, maka Aku tidak akan mendengarkan mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 12, 'Dan biarpun kota-kota Yehuda dan penduduk Yerusalem pergi berseru-seru kepada para allah yang mereka sembah dengan korban bakaran, tetapi allah itu sama sekali tidak dapat menolong mereka pada waktu mereka ditimpa malapetaka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 13, 'Sebab seperti banyaknya kotamu demikian banyaknya para allahmu, hai Yehuda, dan seperti banyaknya jalan di Yerusalem demikian banyaknya mezbah yang kamu dirikan untuk membakar korban kepada Baal.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 14, 'Adapun engkau, janganlah engkau berdoa untuk bangsa ini dan janganlah naikkan permohonan dan doa untuk mereka, sebab Aku tidak akan mendengarkan pada waktu mereka berseru kepada-Ku karena malapetaka mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 15, 'Apakah lagi urusan kekasih-Ku di dalam rumah-Ku, bukankah ia sudah melaksanakan rancangan-rancangan yang jahat? Dapatkah nazar-nazar dan daging yang suci melewatkan malapetaka dari padamu, sehingga kemudian engkau dapat beria-ria?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 16, 'Pohon zaitun yang rimbun, elok dipandang mata, pernah TUHAN menamai engkau. Tetapi dengan bunyi keributan yang hebat Ia menyalakan api pada daun-daunnya, sehingga ranting-rantingnya terbakar.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 17, 'TUHAN semesta alam, yang telah membuat engkau tumbuh, telah menentukan malapetaka atasmu karena kejahatan yang telah dilakukan oleh kaum Israel dan kaum Yehuda untuk menimbulkan sakit hati-Ku dengan membakar korban kepada Baal."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 18, 'TUHAN memberitahukan hal itu kepadaku, maka aku mengetahuinya; pada waktu itu Engkau, TUHAN, memperlihatkan perbuatan mereka kepadaku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 19, 'Tetapi aku dulu seperti anak domba jinak yang dibawa untuk disembelih, aku tidak tahu bahwa mereka mengadakan persepakatan jahat terhadap aku: "Marilah kita binasakan pohon ini dengan buah-buahnya! Marilah kita melenyapkannya dari negeri orang-orang yang hidup, sehingga namanya tidak diingat orang lagi!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 20, 'Tetapi, TUHAN semesta alam, yang menghakimi dengan adil, yang menguji batin dan hati, biarlah aku melihat pembalasan-Mu terhadap mereka, sebab kepada-Mulah kuserahkan perkaraku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 21, 'Sebab itu beginilah firman TUHAN tentang orang-orang Anatot yang ingin mencabut nyawaku dengan mengatakan: "Janganlah bernubuat demi nama TUHAN, supaya jangan engkau mati oleh tangan kami!" ?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 22, 'Sebab itu beginilah firman TUHAN semesta alam: "Sesungguhnya, Aku akan menghukum mereka: pemuda-pemuda mereka akan mati oleh pedang, anak-anak mereka yang laki-laki dan perempuan akan habis mati kelaparan;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 11, 23, 'tidak ada yang tinggal hidup di antara mereka, sebab Aku akan mendatangkan malapetaka kepada orang-orang Anatot pada tahun hukuman mereka."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 12, 1, 'Engkau memang benar, ya TUHAN, bilamana aku berbantah dengan Engkau! Tetapi aku mau berbicara dengan Engkau tentang keadilan: Mengapakah mujur hidup orang-orang fasik, sentosa semua orang yang berlaku tidak setia?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 12, 2, 'Engkau membuat mereka tumbuh, dan merekapun juga berakar, mereka tumbuh subur dan menghasilkan buah juga. Memang selalu Engkau di mulut mereka, tetapi jauh dari hati mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 12, 3, 'Ya TUHAN, Engkau mengenal aku, Engkau melihat aku, dan Engkau menguji bagaimana hatiku terhadap Engkau. Tariklah mereka ke luar seperti domba-domba sembelihan, dan khususkanlah mereka untuk hari penyembelihan. ?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 12, 4, 'Berapa lama lagi negeri ini menjadi kering, dan rumput di segenap padang menjadi layu? Karena kejahatan penduduknya binatang-binatang dan burung-burung habis lenyap, sebab mereka telah mengira: "Ia tidak akan melihat tingkah langkah kita!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 12, 5, '"Jika engkau telah berlari dengan orang berjalan kaki, dan engkau telah dilelahkan, bagaimanakah engkau hendak berpacu melawan kuda? Dan jika di negeri yang damai engkau tidak merasa tenteram, apakah yang akan engkau perbuat di hutan belukar sungai Yordan?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 12, 6, 'Sebab saudara-saudaramu dan kaum keluargamu, mereka sendiri juga berbuat khianat terhadap engkau; mereka juga bersama-sama di belakangmu. Janganlah percaya kepada mereka, sekalipun mereka berkata manis kepadamu!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 12, 7, 'Aku telah meninggalkan kediaman-Ku, telah membuangkan negeri milik-Ku; Aku telah menyerahkan buah hati-Ku ke dalam tangan musuhnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 12, 8, 'Negeri milik-Ku sudah menjadi seperti singa di hutan bagi-Ku; ia mengeraskan suaranya menentang Aku, sebab itu Aku membencinya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 12, 9, 'Negeri milik-Ku sudah menjadi seperti burung belang bagi-Ku; burung-burung buas mengerumuninya. Ayo, kumpulkanlah segala binatang di padang, bawalah untuk menghabiskannya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 12, 10, 'Banyak gembala telah merusakkan kebun anggur-Ku, memijak-mijak tanah-Ku, dan membuat tanah kedambaan-Ku menjadi padang gurun yang sunyi sepi.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 12, 11, 'Ya, mereka telah membuatnya sunyi sepi, sunyi sepi tanah itu berkabung di hadapan-Ku! Sunyi sepi sekarang segenap negeri itu, tetapi tidak ada orang yang memperhatikannya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 12, 12, 'Para pembinasa telah datang melintasi segala bukit gundul di padang gurun; sebab pedang TUHAN mengamuk makan dari ujung negeri yang satu ke ujung lain; tidak ada damai bagi segala yang hidup.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 12, 13, 'Mereka telah menabur gandum, tetapi yang dituai adalah semak duri; mereka telah bersusah payah, tetapi usaha mereka tidak berguna; mereka malu karena hasil yang diperoleh mereka, akibat dari murka TUHAN yang menyala-nyala."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 12, 14, 'Beginilah firman TUHAN: "Mengenai sekalian tetangga-Ku yang jahat yang telah mengusik negeri yang telah Kuberikan sebagai milik pusaka kepada umat-Ku Israel, bahwasanya Aku akan mencabut mereka dari tanah mereka dan Aku mencabut kaum Yehuda dari tengah-tengah mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 12, 15, 'Tetapi setelah Aku mencabut mereka, maka Aku akan menyayangi mereka kembali. Aku akan mengembalikan mereka masing-masing ke milik pusakanya dan masing-masing ke negerinya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 12, 16, 'Dan jika mereka sungguh-sungguh belajar cara hidup umat-Ku sehingga bersumpah demi nama-Ku: Demi TUHAN yang hidup, seperti tadinya mereka mengajar umat-Ku untuk bersumpah demi Baal, maka mereka akan dibangun di tengah-tengah umat-Ku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 12, 17, 'Tetapi jika mereka tidak mau mendengarkan, maka Aku akan sungguh-sungguh mencabut dan membinasakan bangsa yang demikian, demikianlah firman TUHAN."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 1, 'Beginilah firman TUHAN kepadaku: "Pergilah membeli ikat pinggang lenan, ikatkanlah itu pada pinggangmu, tetapi jangan kaucelupkan ke dalam air!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 2, 'Maka aku membeli ikat pinggang seperti yang difirmankan TUHAN, lalu mengikatkannya pada pinggangku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 3, 'Sesudah itu datanglah firman TUHAN kepadaku untuk kedua kalinya, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 4, '"Ambillah ikat pinggang yang telah kaubeli dan yang sekarang pada pinggangmu itu! Pergilah segera ke sungai Efrat untuk menyembunyikannya di sana di celah-celah bukit batu!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 5, 'Maka pergilah aku, lalu menyembunyikannya di pinggir sungai Efrat seperti yang diperintahkan TUHAN kepadaku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 6, 'Sesudah beberapa waktu lamanya, berfirmanlah TUHAN kepadaku: "Pergilah segera ke sungai Efrat mengambil dari sana ikat pinggang yang Kuperintahkan kausembunyikan di sana!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 7, 'Maka pergilah aku ke sungai Efrat, lalu aku menggali dan mengambil ikat pinggang itu dari tempat aku menyembunyikannya, tetapi ternyata ikat pinggang itu sudah lapuk, tidak berguna untuk apapun.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 8, 'Lalu datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 9, '"Beginilah firman TUHAN: Demikianlah Aku akan menghapuskan kecongkakbongakan Yehuda dan Yerusalem.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 10, 'Bangsa yang jahat ini, yang enggan mendengarkan perkataan-perkataan-Ku, yang mengikuti kedegilan hatinya dan mengikuti allah lain untuk beribadah dan sujud menyembah kepada mereka, akan menjadi seperti ikat pinggang ini yang tidak berguna untuk apapun.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 11, 'Sebab seperti ikat pinggang melekat pada pinggang seseorang, demikianlah tadinya segenap kaum Israel dan segenap kaum Yehuda Kulekatkan kepada-Ku, demikianlah firman TUHAN, supaya mereka itu menjadi umat, menjadi ternama, terpuji dan terhormat bagi-Ku. Tetapi mereka itu tidak mau mendengar."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 12, '"Katakanlah kepada mereka firman ini: Beginilah firman TUHAN, Allah Israel: Setiap buyung harus dipenuhi dengan anggur! Dan jika mereka berkata kepadamu: Masakan kami tidak tahu betul, bahwa setiap buyung harus dipenuhi dengan anggur?,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 13, 'maka katakanlah kepada mereka: Beginilah firman TUHAN: Sesungguhnya, seluruh penduduk negeri ini akan Kupenuhi dengan kemabukan: para raja yang duduk di atas takhta Daud, para imam, para nabi dan seluruh penduduk Yerusalem.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 14, 'Aku akan membantingkan seorang kepada yang lain sampai mereka hancur, bapa-bapa dengan anak-anaknya, demikianlah firman TUHAN. Aku akan membinasakan mereka tanpa belas kasihan, tanpa merasa sayang dan tanpa ampun."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 15, 'Dengarlah, pasanglah telingamu, janganlah kamu tinggi hati, sebab TUHAN telah berfirman.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 16, 'Permuliakanlah TUHAN, Allahmu, sebelum Ia membuat hari menjadi gelap, sebelum kakimu tersandung di atas bukit-bukit yang diliputi senja, sementara kamu menanti-nantikan terang, tetapi Ia menjadikan hari kelam pekat dan mengubahnya menjadi gelap gulita.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 17, 'Jika kamu tidak mau mendengarkannya, aku akan menangis di tempat yang tersembunyi oleh karena kesombonganmu, air mataku akan berlinang-linang, bahkan akan bercucuran, oleh sebab kawanan domba TUHAN diangkut tertawan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 18, 'Katakanlah kepada raja dan kepada ibu suri: "Duduklah di tempat yang rendah sekali, sebab mahkota kemuliaanmu sudah turun dari kepalamu!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 19, 'Kota-kota tanah Negeb sudah ditutup gerbangnya, dan tidak ada seorangpun yang membukanya. Segenap Yehuda sudah diangkut ke dalam pembuangan, diangkut ke dalam pembuangan seluruhnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 20, 'Layangkanlah matamu, hai Yerusalem, dan lihatlah, ada orang-orang datang dari utara! Di manakah kawanan ternak yang diberikan kepadamu, kambing domba yang menjadi kemuliaanmu?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 21, 'Apakah yang kaukatakan, apabila diangkat menjadi kepalamu orang-orang yang kauperlakukan sebagai pacar? Bukankah kesakitan akan menyergap engkau seperti halnya seorang perempuan yang melahirkan?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 22, 'Dan apabila engkau bertanya dalam hatimu: "Mengapakah semuanya ini menimpa aku?" Karena banyaknya kesalahanmulah maka disingkapkan ujung kainmu dan engkau diperkosa!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 23, 'Dapatkah orang Etiopia mengganti kulitnya atau macan tutul mengubah belangnya? Masakan kamu dapat berbuat baik, hai orang-orang yang membiasakan diri berbuat jahat?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 24, 'Aku akan menghamburkan mereka seperti sekam yang diterbangkan angin padang gurun.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 25, 'Itulah nasibmu, bagianmu yang telah Kuukur untukmu, demikianlah firman TUHAN, karena engkau melupakan Aku, dan mempercayai dusta.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 26, 'Akupun juga akan mengangkat ujung kainmu sampai kepada mukamu, sehingga kelihatan auratmu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 13, 27, 'Zinahmu dan ringkikmu, persundalanmu yang mesum di atas bukit-bukit dan di padang-padang, Aku sudah melihat perbuatanmu yang keji itu. Celakalah engkau, hai Yerusalem, berapa lama lagi hingga engkau menjadi tahir?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 14, 1, 'Firman TUHAN yang datang kepada Yeremia mengenai musim kering.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 14, 2, 'Yehuda berkabung, pintu-pintu gerbangnya rebah dan dengan sedih terhantar di tanah; jeritan Yerusalem naik ke atas.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 14, 3, 'Pembesar-pembesarnya menyuruh pelayan-pelayannya mencari air; mereka sampai ke sumur-sumur, tetapi tidak menemukan air, sehingga mereka pulang dengan kendi-kendi kosong. Mereka malu, mukanya menjadi merah, sampai mereka menyelubungi kepala mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 14, 4, 'Pekerjaan di ladang sudah terhenti, sebab hujan tiada turun di negeri, maka petani-petani merasa kecewa dan menyelubungi kepala mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 14, 5, 'Bahkan rusa betina di padang meninggalkan anaknya yang baru lahir, sebab tidak ada rumput muda.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 14, 6, 'Keledai-keledai hutan berdiri di atas bukit gundul, mengap-mengap seperti serigala, matanya menjadi lesu, sebab tidak ada rumput.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 14, 7, '"Sekalipun kesalahan-kesalahan kami bersaksi melawan kami, bertindaklah membela kami, ya TUHAN, oleh karena nama-Mu! Sebab banyak kemurtadan kami, kami telah berdosa kepada-Mu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 14, 8, 'Ya Pengharapan Israel, Penolongnya di waktu kesusahan! Mengapakah Engkau seperti orang asing di negeri ini, seperti orang perjalanan yang hanya singgah untuk bermalam?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 14, 9, 'Mengapakah Engkau seperti orang yang bingung, seperti pahlawan yang tidak sanggup menolong? Tetapi Engkau ada di antara kami, ya TUHAN, dan nama-Mu diserukan di atas kami; janganlah tinggalkan kami!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 14, 10, 'Beginilah firman TUHAN tentang bangsa ini: "Mereka sangat senang mengembara dan tidak menahan kakinya. Sebab itu TUHAN tidak berkenan kepada mereka; tetapi sekarang Ia mau mengingat kesalahan mereka dan mau menghukum dosa mereka."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 14, 11, 'TUHAN berfirman kepadaku: "Janganlah engkau berdoa untuk kebaikan bangsa ini!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 14, 12, 'Sekalipun mereka berpuasa, Aku tidak akan mendengarkan seruan mereka; sekalipun mereka mempersembahkan korban bakaran dan korban sajian, Aku tidak akan berkenan kepada mereka, melainkan Aku akan menghabiskan mereka dengan perang, dengan kelaparan dan dengan penyakit sampar."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 14, 13, 'Lalu aku berkata: "Aduh, Tuhan ALLAH! Bukankah para nabi telah berkata kepada mereka: Kamu tidak akan mengalami perang, dan kelaparan tidak akan menimpa kamu, tetapi Aku akan memberikan kepada kamu damai sejahtera yang mantap di tempat ini!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 14, 14, 'Jawab TUHAN kepadaku: "Para nabi itu bernubuat palsu demi nama-Ku! Aku tidak mengutus mereka, tidak memerintahkan mereka dan tidak berfirman kepada mereka. Mereka menubuatkan kepadamu penglihatan bohong, ramalan kosong dan tipu rekaan hatinya sendiri.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 14, 15, 'Sebab itu beginilah firman TUHAN mengenai para nabi yang bernubuat demi nama-Ku, padahal Aku tidak mengutus mereka, dan yang berkata: Perang dan kelaparan tidak akan menimpa negeri ini?:Para nabi itu sendiri akan habis mati oleh perang dan kelaparan!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 14, 16, 'Dan bangsa yang kepadanya mereka bernubuat akan tercampak mati di jalan-jalan Yerusalem, disebabkan oleh kelaparan dan perang, dan tidak ada orang yang akan menguburkan mereka: mereka sendiri, isteri-isteri mereka, anak-anak mereka yang laki-laki dan yang perempuan. Demikianlah akan Kutumpahkan kejahatan mereka ke atas mereka."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 14, 17, 'Katakanlah perkataan ini kepada mereka: "Air mataku bercucuran siang dan malam dengan tidak berhenti-henti, sebab anak dara, puteri bangsaku, dilukai dengan luka parah, luka yang sama sekali tidak tersembuhkan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 14, 18, 'Apabila aku keluar ke padang, di sana ada orang-orang yang mati terbunuh oleh pedang! Apabila aku masuk ke dalam kota, di sana ada orang-orang sakit kelaparan! Bahkan, baik nabi maupun imam menjelajah negeri yang tidak dikenalnya."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 14, 19, 'Telah Kautolakkah Yehuda sama sekali? Telah merasa muakkah Engkau terhadap Sion? Mengapakah kami Kaupukul sedemikian, hingga tidak ada kesembuhan lagi bagi kami? Kami mengharapkan damai sejahtera, tetapi tidak datang sesuatu yang baik; mengharapkan waktu kesembuhan, tetapi hanya ada kengerian!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 14, 20, 'Ya TUHAN, kami mengetahui kefasikan kami dan kesalahan nenek moyang kami; sungguh, kami telah berdosa kepada-Mu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 14, 21, 'Janganlah Engkau menampik kami, oleh karena nama-Mu, dan janganlah Engkau menghinakan takhta kemuliaan-Mu! Ingatlah perjanjian-Mu dengan kami, janganlah membatalkannya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 14, 22, 'Adakah yang dapat menurunkan hujan di antara dewa kesia-siaan bangsa-bangsa itu? Atau dapatkah langit sendiri memberi hujan lebat? Bukankah hanya Engkau saja, ya TUHAN Allah kami, Pengharapan kami, yang membuat semuanya itu?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 15, 1, 'TUHAN berfirman kepadaku: "Sekalipun Musa dan Samuel berdiri di hadapan-Ku, hati-Ku tidak akan berbalik kepada bangsa ini. Usirlah mereka dari hadapan-Ku, biarlah mereka pergi!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 15, 2, 'Dan apabila mereka bertanya kepadamu: Ke manakah kami harus pergi?, maka jawablah mereka: Beginilah firman TUHAN: Yang ke maut, ke mautlah! Yang ke pedang, ke pedanglah! Yang ke kelaparan, ke kelaparanlah! dan yang ke tawanan, ke tawananlah!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 15, 3, 'Aku akan mendatangkan atas mereka empat hukuman, demikianlah firman TUHAN: pedang untuk membunuh, anjing-anjing untuk menyeret-nyeret, burung-burung di udara dan binatang-binatang di bumi untuk memakan dan menghabiskan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 15, 4, 'Dengan demikian Aku akan membuat mereka menjadi kengerian bagi segala kerajaan di bumi, oleh karena segala apa yang dilakukan Manasye bin Hizkia, raja Yehuda, di Yerusalem."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 15, 5, '"Siapakah yang akan merasa kasihan terhadap engkau, hai Yerusalem, dan siapakah yang akan turut berdukacita dengan engkau? Siapakah yang akan singgah untuk menanyakan perihal kesehatanmu?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 15, 6, 'Engkau sendiri telah menolak Aku, demikianlah firman TUHAN, telah pergi meninggalkan Aku. Maka Aku mengacungkan tangan-Ku dan membinasakan engkau; Aku sudah jemu untuk merasa sesal.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 15, 7, 'Aku menampi mereka dengan tampi di kota-kota negeri; Aku membuat umat-Ku kehilangan anak dan membinasakan mereka, karena mereka tidak berbalik dari tingkah langkah mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 15, 8, 'Janda-janda di antara mereka Kubuat lebih besar jumlahnya dari pada pasir laut. Aku mendatangkan ke atas ibu dan teruna suatu pembinasa pada tengah hari. Dengan tiba-tiba Aku menurunkan ke atas mereka kegelisahan dan kekejutan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 15, 9, 'Maka meranalah perempuan yang sudah tujuh kali melahirkan, nafasnya mengap-mengap, baginya matahari sudah terbenam selagi hari siang, ia menjadi malu dan tersipu-sipu. Sisa mereka akan Kuserahkan kepada pedang di depan musuh-musuh mereka, demikianlah firman TUHAN."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 15, 10, 'Celaka aku, ya ibuku, bahwa engkau melahirkan aku, seorang yang menjadi buah perbantahan dan buah percederaan bagi seluruh negeri. Aku bukan orang yang menghutangkan ataupun orang yang menghutang kepada siapapun, tetapi mereka semuanya mengutuki aku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 15, 11, 'Sungguh, ya TUHAN, aku telah melayani Engkau dengan sebaik-baiknya, dan telah membela musuh di depan-Mu pada masa kecelakaannya dan kesesakannya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 15, 12, 'Dapatkah orang mematahkan besi, besi dari utara dan tembaga?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 15, 13, '"Harta kekayaanmu dan barang-barang perbendaharaanmu akan Kuberikan dirampas sebagai ganjaran atas segala dosamu di segenap daerahmu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 15, 14, 'Aku akan membuat engkau menjadi budak musuhmu di negeri yang tidak kaukenal, sebab dalam murka-Ku telah mencetus api yang akan menyala atasmu."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 15, 15, 'Engkau mengetahuinya; ya TUHAN, ingatlah aku dan perhatikanlah aku, lakukanlah pembalasan untukku terhadap orang-orang yang mengejar aku. Janganlah membiarkan aku diambil, karena panjang sabar-Mu, ketahuilah bagaimana aku menanggung celaan oleh karena Engkau!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 15, 16, 'Apabila aku bertemu dengan perkataan-perkataan-Mu, maka aku menikmatinya; firman-Mu itu menjadi kegirangan bagiku, dan menjadi kesukaan hatiku, sebab nama-Mu telah diserukan atasku, ya TUHAN, Allah semesta alam.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 15, 17, 'Tidak pernah aku duduk beria-ria dalam pertemuan orang-orang yang bersenda gurau; karena tekanan tangan-Mu aku duduk sendirian, sebab Engkau telah memenuhi aku dengan geram.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 15, 18, 'Mengapakah penderitaanku tidak berkesudahan, dan lukaku sangat payah, sukar disembuhkan? Sungguh, Engkau seperti sungai yang curang bagiku, air yang tidak dapat dipercayai.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 15, 19, 'Karena itu beginilah jawab TUHAN: "Jika engkau mau kembali, Aku akan mengembalikan engkau menjadi pelayan di hadapan-Ku, dan jika engkau mengucapkan apa yang berharga dan tidak hina, maka engkau akan menjadi penyambung lidah bagi-Ku. Biarpun mereka akan kembali kepadamu, namun engkau tidak perlu kembali kepada mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 15, 20, 'Terhadap bangsa ini Aku akan membuat engkau sebagai tembok berkubu dari tembaga; mereka akan memerangi engkau, tetapi tidak akan mengalahkan engkau, sebab Aku menyertai engkau untuk menyelamatkan dan melepaskan engkau, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 15, 21, 'Aku akan melepaskan engkau dari tangan orang-orang jahat dan membebaskan engkau dari genggaman orang-orang lalim."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 16, 1, 'Firman TUHAN datang kepadaku, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 16, 2, '"Janganlah mengambil isteri dan janganlah mempunyai anak-anak lelaki dan anak-anak perempuan di tempat ini.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 16, 3, 'Sebab beginilah firman TUHAN tentang anak-anak lelaki dan anak-anak perempuan yang lahir di tempat ini, tentang ibu-ibu mereka yang melahirkan mereka dan tentang bapa-bapa mereka yang memperanakkan mereka di negeri ini:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 16, 4, 'Mereka akan mati karena penyakit-penyakit yang membawa maut; mereka tidak akan diratapi dan tidak akan dikuburkan; mereka akan menjadi pupuk di ladang; mereka akan habis oleh pedang dan kelaparan; mayat mereka akan menjadi makanan burung-burung di udara dan binatang-binatang di bumi.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 16, 5, 'Sungguh, beginilah firman TUHAN: Janganlah masuk ke rumah perkabungan, dan janganlah pergi meratap dan janganlah turut berdukacita dengan mereka, sebab Aku telah menarik damai sejahtera pemberian-Ku dari pada bangsa ini, demikianlah firman TUHAN, juga kasih setia dan belas kasihan-Ku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 16, 6, 'Besar kecil akan mati di negeri ini; mereka tidak akan dikuburkan, dan tidak ada orang yang akan meratapi mereka; tidak ada orang yang akan menoreh-noreh diri dan yang akan menggundul kepala karena mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 16, 7, 'Tidak ada orang yang akan memecah-mecahkan roti bagi orang yang berkabung untuk menghiburkan dia karena kematian itu. Bahkan tidak ada orang yang akan memberi dia minum dari piala penghiburan oleh karena kematian ayah atau ibunya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 16, 8, 'Janganlah engkau masuk ke rumah orang mengadakan perjamuan untuk duduk makan minum dengan mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 16, 9, 'Sebab beginilah firman TUHAN semesta alam, Allah Israel: Sesungguhnya, di tempat ini, di depan matamu dan pada zamanmu, akan Kuhentikan suara kegirangan dan suara sukacita, suara pengantin laki-laki dan suara pengantin perempuan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 16, 10, 'Apabila engkau memberitahukan kepada bangsa ini segala perkataan itu dan mereka berkata kepadamu: Mengapakah TUHAN mengancamkan segala malapetaka yang besar ini terhadap kami? Apakah kesalahan kami dan apakah dosa yang telah kami lakukan terhadap TUHAN, Allah kami?,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 16, 11, 'maka engkau akan berkata kepada mereka: Oleh karena nenek moyangmu telah meninggalkan Aku, demikianlah firman TUHAN, dan oleh karena mereka telah mengikuti allah lain dengan beribadah dan sujud menyembah kepadanya, tetapi mereka meninggalkan Aku dan tidak berpegang pada Taurat-Ku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 16, 12, 'Dan kamu sendiri berlaku lebih jahat dari pada nenek moyangmu! Lihat, kamu masing-masing mengikuti kedegilan hatinya yang jahat dari pada mendengarkan kepada-Ku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 16, 13, 'Maka Aku akan melemparkan kamu dari negeri ini ke negeri yang tidak dikenal oleh kamu ataupun oleh nenek moyangmu. Di sana kamu akan beribadah kepada allah lain siang malam, sebab Aku tidak akan menaruh kasihan lagi kepadamu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 16, 14, 'Sebab itu, demikianlah firman TUHAN, sesungguhnya, waktunya akan datang, bahwa tidak dikatakan orang lagi: Demi TUHAN yang hidup yang menuntun orang Israel keluar dari tanah Mesir!,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 16, 15, 'melainkan: Demi TUHAN yang hidup yang menuntun orang Israel keluar dari tanah utara dan dari segala negeri ke mana Ia telah menceraiberaikan mereka! Sebab Aku akan membawa mereka pulang ke tanah yang telah Kuberikan kepada nenek moyang mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 16, 16, 'Sesungguhnya, Aku mau menyuruh banyak penangkap ikan, demikianlah firman TUHAN, yang akan menangkap mereka, sesudah itu Aku mau menyuruh banyak pemburu yang akan memburu mereka dari atas segala gunung dan dari atas segala bukit dan dari celah-celah bukit batu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 16, 17, 'Sebab Aku mengamat-amati segala tingkah langkah mereka; semuanya itu tidak tersembunyi dari pandangan-Ku, dan kesalahan merekapun tidak terlindung di depan mata-Ku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 16, 18, 'Aku akan mengganjar dua kali lipat kesalahan dan dosa mereka, oleh karena mereka telah menajiskan negeri-Ku dengan bangkai dewa-dewa mereka yang menjijikkan dan telah memenuhi tanah milik-Ku dengan perbuatan mereka yang keji."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 16, 19, 'Ya TUHAN, kekuatanku dan bentengku, tempat pelarianku pada hari kesesakan! Kepada-Mu akan datang bangsa-bangsa dari ujung bumi serta berkata: "Sungguh, nenek moyang kami hanya memiliki dewa penipu, dewa kesia-siaan yang satupun tiada berguna.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 16, 20, 'Dapatkah manusia membuat allah bagi dirinya sendiri? Yang demikian bukan allah!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 16, 21, '"Sebab itu, ketahuilah, Aku mau memberitahukan kepada mereka, sekali ini Aku akan memberitahukan kepada mereka kekuasaan-Ku dan keperkasaan-Ku, supaya mereka tahu, bahwa nama-Ku TUHAN."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 1, '"Dosa Yehuda telah tertulis dengan pena besi, yang matanya dari intan, terukir pada loh hati mereka dan pada tanduk-tanduk mezbah mereka', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 2, 'sebagai peringatan terhadap mereka! ?Mezbah-mezbah mereka dan tiang-tiang berhala mereka memang ada di samping pohon yang rimbun di atas bukit yang tinggi,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 3, 'yakni pegunungan di padang. ?Harta kekayaanmu dan segala barang perbendaharaanmu akan Kuberikan dirampas sebagai ganjaran atas dosamu di segenap daerahmu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 4, 'Engkau terpaksa lepas tangan dari milik pusakamu yang telah Kuberikan kepadamu, dan Aku akan membuat engkau menjadi budak musuhmu di negeri yang tidak kaukenal, sebab dalam murka-Ku api telah mencetus yang akan menyala untuk selama-lamanya."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 5, 'Beginilah firman TUHAN: "Terkutuklah orang yang mengandalkan manusia, yang mengandalkan kekuatannya sendiri, dan yang hatinya menjauh dari pada TUHAN!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 6, 'Ia akan seperti semak bulus di padang belantara, ia tidak akan mengalami datangnya keadaan baik; ia akan tinggal di tanah angus di padang gurun, di negeri padang asin yang tidak berpenduduk.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 7, 'Diberkatilah orang yang mengandalkan TUHAN, yang menaruh harapannya pada TUHAN!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 8, 'Ia akan seperti pohon yang ditanam di tepi air, yang merambatkan akar-akarnya ke tepi batang air, dan yang tidak mengalami datangnya panas terik, yang daunnya tetap hijau, yang tidak kuatir dalam tahun kering, dan yang tidak berhenti menghasilkan buah.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 9, 'Betapa liciknya hati, lebih licik dari pada segala sesuatu, hatinya sudah membatu: siapakah yang dapat mengetahuinya?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 10, 'Aku, TUHAN, yang menyelidiki hati, yang menguji batin, untuk memberi balasan kepada setiap orang setimpal dengan tingkah langkahnya, setimpal dengan hasil perbuatannya."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 11, 'Seperti ayam hutan yang mengerami yang tidak ditelurkannya, demikianlah orang yang menggaruk kekayaan secara tidak halal, pada pertengahan usianya ia akan kehilangan semuanya, dan pada kesudahan usianya ia terkenal sebagai seorang bebal.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 12, 'Takhta kemuliaan, luhur dari sejak semula, tempat bait kudus kita!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 13, 'Ya Pengharapan Israel, TUHAN, semua orang yang meninggalkan Engkau akan menjadi malu; orang-orang yang menyimpang dari pada-Mu akan dilenyapkan di negeri, sebab mereka telah meninggalkan sumber air yang hidup, yakni TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 14, 'Sembuhkanlah aku, ya TUHAN, maka aku akan sembuh; selamatkanlah aku, maka aku akan selamat, sebab Engkaulah kepujianku!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 15, 'Sesungguhnya, mereka berkata kepadaku: "Di manakah firman TUHAN itu? Biarlah ia sampai!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 16, 'Namun tidak pernah aku mendesak kepada-Mu untuk mendatangkan malapetaka, aku tidak mengingini hari bencana! Engkaulah yang mengetahui apa yang keluar dari bibirku, semuanya terpampang di hadapan mata-Mu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 17, 'Janganlah Engkau menjadi kedahsyatan bagiku, Engkaulah perlindunganku pada hari malapetaka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 18, 'Biarlah orang-orang yang mengejar aku menjadi malu, tetapi janganlah aku ini menjadi malu; biarlah mereka terkejut, tetapi janganlah aku ini terkejut! Buatlah hari malapetaka menimpa mereka, dan hancurkanlah mereka dengan kehancuran berganda.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 19, 'Beginilah firman TUHAN kepadaku: "Pergilah engkau dan berdirilah di pintu gerbang Anak Rakyat, yang dilalui keluar masuk oleh raja-raja Yehuda, dan di segala pintu gerbang Yerusalem;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 20, 'katakanlah kepada mereka: Dengarlah firman TUHAN, hai raja-raja Yehuda, hai segenap Yehuda dan segenap penduduk Yerusalem yang masuk melalui pintu-pintu gerbang ini!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 21, 'Beginilah firman TUHAN: Berawas-awaslah demi nyawamu! Janganlah mengangkut barang-barang pada hari Sabat dan membawanya melalui pintu-pintu gerbang Yerusalem!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 22, 'Janganlah membawa barang-barang dari rumahmu ke luar pada hari Sabat dan janganlah lakukan sesuatu pekerjaan, tetapi kuduskanlah hari Sabat seperti yang telah Kuperintahkan kepada nenek moyangmu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 23, 'Namun mereka tidak mau mendengarkan dan tidak mau memperhatikannya, melainkan mereka berkeras kepala, sehingga tidak mau mendengarkan dan tidak mau menerima tegoran.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 24, 'Apabila kamu sungguh-sungguh mendengarkan Aku, demikianlah firman TUHAN, dan tidak membawa masuk barang-barang melalui pintu-pintu gerbang kota ini pada hari Sabat, tetapi menguduskan hari Sabat dan tidak melakukan sesuatu pekerjaan pada hari itu,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 25, 'maka melalui pintu-pintu gerbang kota ini akan berarak masuk raja-raja dan pemuka-pemuka, yang akan duduk di atas takhta Daud, dengan mengendarai kereta dan kuda: mereka dan pemuka-pemuka mereka, orang-orang Yehuda dan penduduk Yerusalem. Dan kota ini akan didiami orang untuk selama-lamanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 26, 'Orang akan datang dari kota-kota Yehuda dan dari tempat-tempat sekitar Yerusalem, dari tanah Benyamin dan dari Daerah Bukit, dari pegunungan dan dari tanah Negeb, dengan membawa korban bakaran, korban sembelihan, korban sajian dan kemenyan, membawa korban syukur ke dalam rumah TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 17, 27, 'Tetapi apabila kamu tidak mendengarkan perintah-Ku untuk menguduskan hari Sabat dan untuk tidak masuk mengangkut barang-barang melalui pintu-pintu gerbang Yerusalem pada hari Sabat, maka di pintu-pintu gerbangnya Aku akan menyalakan api, yang akan memakan habis puri-puri Yerusalem, dan yang tidak akan terpadamkan."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 1, 'Firman yang datang dari TUHAN kepada Yeremia, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 2, '"Pergilah dengan segera ke rumah tukang periuk! Di sana Aku akan memperdengarkan perkataan-perkataan-Ku kepadamu."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 3, 'Lalu pergilah aku ke rumah tukang periuk, dan kebetulan ia sedang bekerja dengan pelarikan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 4, 'Apabila bejana, yang sedang dibuatnya dari tanah liat di tangannya itu, rusak, maka tukang periuk itu mengerjakannya kembali menjadi bejana lain menurut apa yang baik pada pemandangannya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 5, 'Kemudian datanglah firman TUHAN kepadaku, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 6, '"Masakan Aku tidak dapat bertindak kepada kamu seperti tukang periuk ini, hai kaum Israel!, demikianlah firman TUHAN. Sungguh, seperti tanah liat di tangan tukang periuk, demikianlah kamu di tangan-Ku, hai kaum Israel!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 7, 'Ada kalanya Aku berkata tentang suatu bangsa dan tentang suatu kerajaan bahwa Aku akan mencabut, merobohkan dan membinasakannya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 8, 'Tetapi apabila bangsa yang terhadap siapa Aku berkata demikian telah bertobat dari kejahatannya, maka menyesallah Aku, bahwa Aku hendak menjatuhkan malapetaka yang Kurancangkan itu terhadap mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 9, 'Ada kalanya Aku berkata tentang suatu bangsa dan tentang suatu kerajaan bahwa Aku akan membangun dan menanam mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 10, 'Tetapi apabila mereka melakukan apa yang jahat di depan mata-Ku dan tidak mendengarkan suara-Ku, maka menyesallah Aku, bahwa Aku hendak mendatangkan keberuntungan yang Kujanjikan itu kepada mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 11, 'Sebab itu, katakanlah kepada orang Yehuda dan kepada penduduk Yerusalem: Beginilah firman TUHAN: Sesungguhnya, Aku ini sedang menyiapkan malapetaka terhadap kamu dan merancangkan rencana terhadap kamu. Baiklah kamu masing-masing bertobat dari tingkah langkahmu yang jahat, dan perbaikilah tingkah langkahmu dan perbuatanmu!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 12, 'Tetapi mereka berkata: Tidak ada gunanya! Sebab kami hendak berkelakuan mengikuti rencana kami sendiri dan masing-masing hendak bertindak mengikuti kedegilan hatinya yang jahat."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 13, 'Sebab itu beginilah firman TUHAN: "Cobalah tanyakan di kalangan bangsa-bangsa: siapakah yang telah mendengar hal seperti ini? Anak dara Israel telah melakukan hal-hal yang sangat ngeri!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 14, 'Masakan salju putih akan beralih dari gunung batu Siryon? Masakan air gunung akan habis; air yang sejuk dan mengalir?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 15, 'Tetapi umat-Ku telah melupakan Aku, mereka telah membakar korban kepada dewa kesia-siaan; mereka telah tersandung jatuh di jalan-jalan mereka, yakni jalan-jalan dari dahulu kala, dan telah mengambil jalan simpangan, yakni jalan yang tidak diratakan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 16, 'Maka mereka membuat negerinya menjadi kengerian menjadi sasaran suitan untuk selamanya. Setiap orang yang melewatinya akan merasa ngeri, dan akan menggeleng-gelengkan kepalanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 17, 'Seperti angin timur Aku akan menyerakkan mereka di depan musuhnya. Belakang-Ku akan Kuperlihatkan kepada mereka dan bukan muka-Ku pada hari bencana mereka."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 18, 'Berkatalah mereka: "Marilah kita mengadakan persepakatan terhadap Yeremia, sebab imam tidak akan kehabisan pengajaran, orang bijaksana tidak akan kehabisan nasihat dan nabi tidak akan kehabisan firman. Marilah kita memukul dia dengan bahasanya sendiri dan jangan memperhatikan setiap perkataannya!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 19, 'Perhatikanlah aku, ya TUHAN, dan dengarkanlah suara pengaduanku!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 20, 'Akan dibalaskah kebaikan dengan kejahatan? Namun mereka telah menggali pelubang untuk aku! Ingatlah bahwa aku telah berdiri di hadapan-Mu, dan telah berbicara membela mereka, supaya amarah-Mu disurutkan dari mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 21, 'Sebab itu serahkanlah anak-anak mereka kepada kelaparan, dan biarkanlah mereka dipancung pedang! Biarlah isteri-isteri mereka kehilangan anak dan suami; biarlah laki-laki mereka mati oleh sampar, dan pemuda-pemuda mereka mati karena pedang di pertempuran!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 22, 'Biarlah kedengaran jeritan dari rumah-rumah mereka, apabila Engkau dengan tiba-tiba mendatangkan gerombolan perampok kepada mereka! Sebab mereka telah menggali pelubang untuk menangkap aku, dan telah memasang jerat untuk kakiku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 18, 23, 'Tetapi Engkau, ya TUHAN, Engkau mengetahui segala rancangan mereka untuk membunuh aku. Janganlah ampuni kesalahan mereka, dan janganlah hapuskan dosa mereka dari hadapan-Mu, tetapi biarlah mereka tersandung di hadapan mata-Mu; bertindaklah pada hari murka-Mu terhadap mereka!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 19, 1, 'Beginilah pula firman TUHAN kepadaku: "Pergilah membeli buli-buli yang dibuat dari tanah, lalu ajaklah bersama-sama engkau beberapa orang tua-tua bangsa itu dan beberapa orang imam yang tertua,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 19, 2, 'kemudian berangkatlah ke Lembah Ben-Hinom yang di depan pintu gerbang Beling! Serukanlah di sana perkataan-perkataan yang akan Kusampaikan kepadamu!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 19, 3, 'Katakanlah: Dengarlah firman TUHAN, hai raja-raja Yehuda dan penduduk Yerusalem! Beginilah firman TUHAN semesta alam, Allah Israel: Sesungguhnya, Aku akan mendatangkan malapetaka kepada tempat ini, sehingga telinga orang yang mendengarnya, mendenging!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 19, 4, 'Sebab mereka telah meninggalkan Aku, telah memberikan tempat ini kepada allah asing dan telah membakar korban di sini kepada allah lain yang tidak dikenal oleh mereka sendiri dan oleh nenek moyang mereka dan oleh raja-raja Yehuda. Mereka telah membuat tempat ini penuh dengan darah orang-orang yang tidak bersalah.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 19, 5, 'Mereka telah mendirikan bukit-bukit pengorbanan bagi Baal untuk membakar anak-anak mereka sebagai korban bakaran kepada Baal, suatu hal yang tidak pernah Kuperintahkan atau Kukatakan dan yang tidak pernah timbul dalam hati-Ku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 19, 6, 'Sebab itu, sesungguhnya, waktunya akan datang, demikianlah firman TUHAN, bahwa tempat ini tidak akan disebut lagi: Tofet dan Lembah Ben-Hinom, melainkan Lembah Pembunuhan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 19, 7, 'Aku akan menggagalkan rancangan Yehuda dan Yerusalem di tempat ini dan Aku akan membuat mereka rebah oleh pedang di depan musuh mereka dan oleh tangan orang-orang yang ingin mencabut nyawa mereka. Aku akan membiarkan mayat-mayat mereka dimakan oleh burung-burung di udara dan oleh binatang-binatang di bumi.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 19, 8, 'Aku akan membuat kota ini menjadi kengerian dan menjadi sasaran suitan. Setiap orang yang melewatinya akan merasa ngeri dan bersuit karena segala pukulan yang dideritanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 19, 9, 'Aku akan membuat mereka memakan daging anak-anaknya laki-laki dan daging anak-anaknya perempuan, dan setiap orang memakan daging temannya, dalam keadaan susah dan sulit yang ditimbulkan musuhnya kepada mereka dan oleh orang-orang yang ingin mencabut nyawa mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 19, 10, 'Selanjutnya pecahkanlah buli-buli itu di depan mata orang-orang yang turut bersama-sama engkau.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 19, 11, 'Katakanlah kepada mereka: Beginilah firman TUHAN semesta alam: Demikianlah akan Kupecahkan bangsa ini dan kota ini, seperti orang memecahkan tembikar tukang periuk, sehingga tidak dapat diperbaiki lagi. Dan Tofet akan menjadi tempat penguburan, karena tidak ada tempat lain untuk menguburkan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 19, 12, 'Begitulah akan Kulakukan kepada tempat ini, demikianlah firman TUHAN, dan kepada penduduknya. Aku akan membuat kota ini seperti Tofet:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 19, 13, 'rumah-rumah Yerusalem dan rumah-rumah para raja Yehuda akan menjadi najis seperti tempat Tofet, yakni segala rumah yang di atas sotohnya orang membakar korban kepada segala tentara langit dan mempersembahkan korban curahan kepada allah lain."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 19, 14, 'Ketika Yeremia pulang dari Tofet, ke mana TUHAN telah mengutusnya untuk bernubuat, berdirilah ia di pelataran rumah TUHAN dan berkata kepada segenap orang banyak:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 19, 15, '"Beginilah firman TUHAN semesta alam, Allah Israel: Sesungguhnya, Aku akan mendatangkan ke atas kota ini dan ke atas segala kota sekitarnya seluruh malapetaka yang telah Kukatakan akan menimpa mereka, sebab mereka berkeras kepala dan tidak mendengarkan perkataan-perkataan', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 20, 1, 'Pasyhur bin Imer, imam yang pada waktu itu menjabat kepala di rumah TUHAN, mendengar Yeremia menubuatkan perkataan-perkataan itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 20, 2, 'Lalu Pasyhur memukul nabi Yeremia dan memasungkan dia di pintu gerbang Benyamin yang ada di atas rumah TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 20, 3, 'Tetapi ketika Pasyhur keesokan harinya mengeluarkan Yeremia dari pasungan itu, berkatalah Yeremia kepadanya: "TUHAN akan menyebut namamu bukan Pasyhur, melainkan Kegentaran-dari-segala-jurusan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 20, 4, 'Sebab beginilah firman TUHAN: Sesungguhnya, Aku akan membuat engkau menjadi kegentaran bagimu sendiri dan bagi semua sahabatmu; mereka akan rebah mati oleh pedang musuhnya di depan matamu sendiri. Dan seluruh Yehuda akan Kuserahkan ke dalam tangan raja Babel yang akan mengangkut mereka ke dalam pembuangan ke Babel dan memukul mati mereka dengan pedang.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 20, 5, 'Juga harta benda kota ini, segala hasil jerih payahnya, segala barangnya yang berharga dan segala barang perbendaharaan raja-raja Yehuda akan Kuserahkan ke dalam tangan musuhnya, yang akan menjarah, mengumpulkan dan membawa semuanya itu ke Babel.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 20, 6, 'Mengenai engkau, hai Pasyhur, dan semua orang yang diam di rumahmu, kamu akan diangkut tertawan; engkau akan sampai ke Babel dan akan mati di sana dan akan dikuburkan di sana: engkau ini dengan semua sahabatmu yang kepadanya engkau telah bernubuat palsu."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 20, 7, 'Engkau telah membujuk aku, ya TUHAN, dan aku telah membiarkan diriku dibujuk; Engkau terlalu kuat bagiku dan Engkau menundukkan aku. Aku telah menjadi tertawaan sepanjang hari, semuanya mereka mengolok-olokkan aku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 20, 8, 'Sebab setiap kali aku berbicara, terpaksa aku berteriak, terpaksa berseru: "Kelaliman! Aniaya!" Sebab firman TUHAN telah menjadi cela dan cemooh bagiku, sepanjang hari.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 20, 9, 'Tetapi apabila aku berpikir: "Aku tidak mau mengingat Dia dan tidak mau mengucapkan firman lagi demi nama-Nya", maka dalam hatiku ada sesuatu yang seperti api yang menyala-nyala, terkurung dalam tulang-tulangku; aku berlelah-lelah untuk menahannya, tetapi aku tidak sanggup.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 20, 10, 'Aku telah mendengar bisikan banyak orang: "Kegentaran datang dari segala jurusan! Adukanlah dia! Kita mau mengadukan dia!" Semua orang sahabat karibku mengintai apakah aku tersandung jatuh: "Barangkali ia membiarkan dirinya dibujuk, sehingga kita dapat mengalahkan dia dan dapat melakukan pembalasan kita terhadap dia!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 20, 11, 'Tetapi TUHAN menyertai aku seperti pahlawan yang gagah, sebab itu orang-orang yang mengejar aku akan tersandung jatuh dan mereka tidak dapat berbuat apa-apa. Mereka akan menjadi malu sekali, sebab mereka tidak berhasil, suatu noda yang selama-lamanya tidak terlupakan!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 20, 12, 'Ya TUHAN semesta alam, yang menguji orang benar, yang melihat batin dan hati, biarlah aku melihat pembalasan-Mu terhadap mereka, sebab kepada-Mulah kuserahkan perkaraku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 20, 13, 'Menyanyilah untuk TUHAN, pujilah TUHAN! Sebab ia telah melepaskan nyawa orang miskin dari tangan orang-orang yang berbuat jahat.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 20, 14, 'Terkutuklah hari ketika aku dilahirkan! Biarlah jangan diberkati hari ketika ibuku melahirkan aku!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 20, 15, 'Terkutuklah orang yang membawa kabar kepada bapaku dengan mengatakan: "Seorang anak laki-laki telah dilahirkan bagimu!" yang membuat dia bersukacita dengan sangat.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 20, 16, 'Terjadilah kepada hari itu seperti kepada kota-kota yang ditunggangbalikkan TUHAN tanpa belas kasihan! Didengarnyalah kiranya teriakan pada waktu pagi dan hiruk-pikuk pada waktu tengah hari!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 20, 17, 'Karena hari itu tidak membunuh aku selagi di kandungan, sehingga ibuku menjadi kuburanku, dan ia mengandung untuk selamanya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 20, 18, 'Mengapa gerangan aku keluar dari kandungan, melihat kesusahan dan kedukaan, sehingga hari-hariku habis berlalu dalam malu?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 21, 1, 'Firman yang datang dari TUHAN kepada Yeremia, ketika raja Zedekia mengutus Pasyhur bin Malkia dan imam Zefanya bin Maaseya kepadanya dengan pesan:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 21, 2, '"Tanyakanlah kiranya petunjuk TUHAN untuk kami, sebab Nebukadnezar, raja Babel, memerangi kami! Barangkali TUHAN mau melakukan kepada kami tepat seperti perbuatan-perbuatan-Nya yang ajaib, sehingga Nebukadnezar mundur meninggalkan kami."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 21, 3, 'Kata Yeremia kepada mereka: "Beginilah kamu katakan kepada Zedekia:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 21, 4, 'Beginilah firman TUHAN, Allah Israel: Sesungguhnya, Aku akan membalikkan senjata perang yang kamu pegang, yang kamu pakai berperang melawan raja Babel dan melawan orang-orang Kasdim yang mengepung kamu dari luar tembok; Aku akan mengumpulkannya ke dalam kota ini.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 21, 5, 'Aku sendiri akan berperang melawan kamu dengan tangan yang teracung, dengan lengan yang kuat, dengan murka, dengan kehangatan amarah dan dengan kegusaran yang besar.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 21, 6, 'Aku akan memukul penduduk kota ini, baik manusia maupun binatang; mereka akan mati oleh penyakit sampar yang hebat.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 21, 7, 'Sesudah itu, demikianlah firman TUHAN, maka Zedekia, raja Yehuda, dan pegawai-pegawainya dan rakyat di kota ini, yang masih tinggal hidup dari penyakit sampar, dari pedang dan dari kelaparan, akan Kuserahkan ke dalam tangan Nebukadnezar, raja Babel, yaitu ke dalam tangan musuh mereka yang berusaha mencabut nyawa mereka; orang akan memukul mati mereka dengan mata pedang tanpa merasa sayang, tanpa belas kasihan dan tanpa ampun.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 21, 8, 'Tetapi kepada bangsa ini haruslah kaukatakan: Beginilah firman TUHAN: Sesungguhnya, Aku menghadapkan kepada kamu jalan kehidupan dan jalan kematian.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 21, 9, 'Siapa yang tinggal di kota ini akan mati karena pedang, karena kelaparan dan karena penyakit sampar; tetapi siapa yang keluar dari sini dan menyerahkan diri kepada orang-orang Kasdim yang mengepung kamu, ia akan tetap hidup; nyawanya akan menjadi jarahan baginya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 21, 10, 'Sebab Aku telah menentang kota ini untuk mendatangkan kecelakaan dan bukan untuk mendatangkan keberuntungannya, demikianlah firman TUHAN. Kota ini akan diserahkan ke dalam tangan raja Babel yang akan membakarnya habis dengan api."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 21, 11, 'Kepada keluarga raja Yehuda. Dengarlah firman TUHAN:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 21, 12, '"Beginilah firman TUHAN, hai keturunan Daud: Jatuhkanlah hukum yang adil setiap pagi dan lepaskanlah dari tangan pemerasnya orang yang dirampas haknya, supaya kehangatan murka-Ku jangan menyambar seperti api dan menyala-nyala dengan tidak ada yang memadamkannya, oleh karena perbuatan-perbuatanmu yang jahat!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 21, 13, 'Sesungguhnya, Aku akan menjadi lawanmu, hai kota yang di atas lembah, gunung batu di dataran, demikianlah firman TUHAN, hai kamu yang berkata: Siapakah yang berani turun kepada kami dan siapakah yang berani masuk ke tempat perteduhan kami?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 21, 14, 'Aku akan melakukan pembalasan kepadamu sesuai dengan hasil perbuatanmu, demikianlah firman TUHAN. Aku akan menyalakan api di hutannya yang akan memakan habis segala sesuatu yang di sekitarnya."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 1, 'Beginilah firman TUHAN: "Pergilah ke istana raja Yehuda dan sampaikanlah di sana firman ini!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 2, 'Katakanlah: Dengarlah firman TUHAN, hai raja Yehuda yang duduk di atas takhta Daud, engkau, pegawai-pegawaimu dan rakyatmu yang masuk melalui pintu-pintu gerbang ini!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 3, 'Beginilah firman TUHAN: Lakukanlah keadilan dan kebenaran, lepaskanlah dari tangan pemerasnya orang yang dirampas haknya, janganlah engkau menindas dan janganlah engkau memperlakukan orang asing, yatim dan janda dengan keras, dan janganlah engkau menumpahkan darah orang yang tak bersalah di tempat ini!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 4, 'Sebab jika kamu sungguh-sungguh melakukan semuanya itu, maka melalui pintu-pintu gerbang istana ini akan berarak masuk raja-raja yang akan duduk di atas takhta Daud dengan mengendarai kereta dan kuda: mereka itu, pegawai-pegawainya dan rakyatnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 5, 'Tetapi jika kamu tidak mendengarkan perkataan-perkataan ini, maka Aku sudah bersumpah demi diri-Ku, demikianlah firman TUHAN, bahwa istana ini akan menjadi reruntuhan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 6, 'Sebab beginilah firman TUHAN mengenai keluarga raja Yehuda: Engkau seperti Gilead bagi-Ku, seperti puncak gunung Libanon! Namun pastilah Aku akan membuat engkau menjadi padang gurun, menjadi kota yang tidak didiami orang.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 7, 'Aku akan menetapkan pemusnah-pemusnah terhadap engkau, masing-masing dengan senjatanya; mereka akan menebang pohon aras pilihanmu dan mencampakkannya ke dalam api.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 8, 'Dan apabila banyak bangsa melewati kota ini, maka mereka akan berkata seorang kepada yang lain: Mengapakah TUHAN melakukan seperti itu kepada kota yang besar ini?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 9, 'Orang akan menjawab: Oleh karena mereka telah melupakan perjanjian TUHAN, Allah mereka, dan telah sujud menyembah kepada allah lain dan beribadah kepadanya."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 10, 'Janganlah kamu menangisi orang mati dan janganlah turut berdukacita karena dia. Lebih baiklah kamu menangisi dia yang sudah pergi, sebab ia tidak akan kembali lagi, ia tidak lagi akan melihat tanah kelahirannya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 11, 'Sebab beginilah firman TUHAN mengenai Salum bin Yosia, raja Yehuda, yang telah menjadi raja menggantikan Yosia, ayahnya, dan yang telah meninggalkan tempat ini: "Ia tidak lagi akan kembali ke sini,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 12, 'tetapi ia akan mati di tempat pembuangannya, dan tidak lagi akan melihat negeri ini."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 13, 'Celakalah dia yang membangun istananya berdasarkan ketidakadilan dan anjungnya berdasarkan kelaliman, yang mempekerjakan sesamanya dengan cuma-cuma dan tidak memberikan upahnya kepadanya;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 14, 'yang berkata: "Aku mau mendirikan istana yang besar lebar dan anjung yang lapang luas!", lalu menetas dinding istana membuat jendela, memapani istana itu dengan kayu aras dan mencatnya merah.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 15, 'Sangkamu rajakah engkau, jika engkau bertanding dalam hal pemakaian kayu aras? Tidakkah ayahmu makan minum juga dan beroleh kenikmatan? Tetapi ia melakukan keadilan dan kebenaran,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 16, 'serta mengadili perkara orang sengsara dan orang miskin dengan adil. Bukankah itu namanya mengenal Aku? demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 17, 'Tetapi matamu dan hatimu hanya tertuju kepada pengejaran untung, kepada penumpahan darah orang yang tak bersalah, kepada pemerasan dan kepada penganiayaan!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 18, 'Sebab itu beginilah firman TUHAN mengenai Yoyakim bin Yosia, raja Yehuda: "Orang tidak akan meratapi dia: Aduhai abangku! Aduhai kakakku! Orang tidak akan menangisi dia: Aduhai tuan! Aduhai Seri Paduka!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 19, 'Ia akan dikubur secara penguburan keledai, diseret dan dilemparkan ke luar pintu-pintu gerbang Yerusalem."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 20, 'Naiklah ke gunung Libanon dan berteriaklah! Perdengarkanlah suaramu di pegunungan Basan! Berteriaklah dari pegunungan Abarim, sebab semua kekasihmu sudah hancur!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 21, 'Aku telah berbicara kepadamu selagi engkau sentosa, tetapi engkau berkata: "Aku tidak mau mendengarkan!" Itulah tingkah langkahmu dari sejak masa mudamu, sebab engkau tidak mau mendengarkan suara-Ku!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 22, 'Semua orang yang menggembalakan kamu akan dihalau angin ribut, dan para kekasihmu akan diangkut tertawan. Pada waktu itu engkau akan menjadi malu dan bernoda dari sebab segala kejahatanmu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 23, 'Hai engkau yang diam di gunung Libanon, dan yang bersarang di pohon-pohon aras! Betapa engkau akan mengeluh ketika kesakitan menimpa engkau, kesakitan seperti yang ditanggung perempuan yang melahirkan!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 24, '"Demi Aku yang hidup, demikianlah firman TUHAN, bahkan sekalipun Konya bin Yoyakim, raja Yehuda, adalah sebagai cincin meterai pada tangan kanan-Ku, namun Aku akan mencabut engkau!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 25, 'Aku akan menyerahkan engkau ke dalam tangan orang-orang yang berusaha mencabut nyawamu, ke dalam tangan orang-orang yang engkau takuti, ke dalam tangan Nebukadnezar, raja Babel, dan ke dalam tangan orang-orang Kasdim.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 26, 'Aku akan melemparkan engkau serta ibumu yang melahirkan engkau ke negeri lain, yang bukan tempat kelahiranmu; di sanalah kamu akan mati.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 27, 'Tetapi ke negeri yang mereka rindukan untuk kembali ke situ, mereka tidak akan kembali!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 28, 'Adakah Konya ini suatu benda yang hina, yang akan dipecahkan orang, atau suatu periuk yang tidak disukai orang? Mengapakah ia dicampakkan dan dilemparkan ke negeri yang tidak dikenalnya?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 29, 'Hai negeri, negeri, negeri! Dengarlah firman TUHAN!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 22, 30, 'Beginilah firman TUHAN: "Catatlah orang ini sebagai orang yang tak punya anak, sebagai laki-laki yang tidak pernah berhasil dalam hidupnya; sebab seorangpun dari keturunannya tidak akan berhasil duduk di atas takhta Daud dan memerintah kembali di Yehuda."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 1, '"Celakalah para gembala yang membiarkan kambing domba gembalaan-Ku hilang dan terserak!" ?demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 2, 'Sebab itu beginilah firman TUHAN, Allah Israel, terhadap para gembala yang menggembalakan bangsaku: "Kamu telah membiarkan kambing domba-Ku terserak dan tercerai-berai, dan kamu tidak menjaganya. Maka ketahuilah, Aku akan membalaskan kepadamu perbuatan-perbuatanmu yang jahat, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 3, 'Dan Aku sendiri akan mengumpulkan sisa-sisa kambing domba-Ku dari segala negeri ke mana Aku menceraiberaikan mereka, dan Aku akan membawa mereka kembali ke padang mereka: mereka akan berkembang biak dan bertambah banyak.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 4, 'Aku akan mengangkat atas mereka gembala-gembala yang akan menggembalakan mereka, sehingga mereka tidak takut lagi, tidak terkejut dan tidak hilang seekorpun, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 5, 'Sesungguhnya, waktunya akan datang, demikianlah firman TUHAN, bahwa Aku akan menumbuhkan Tunas adil bagi Daud. Ia akan memerintah sebagai raja yang bijaksana dan akan melakukan keadilan dan kebenaran di negeri.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 6, 'Dalam zamannya Yehuda akan dibebaskan, dan Israel akan hidup dengan tenteram; dan inilah namanya yang diberikan orang kepadanya: TUHAN?keadilan kita.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 7, 'Sebab itu, demikianlah firman TUHAN, sesungguhnya, waktunya akan datang, bahwa orang tidak lagi mengatakan: Demi TUHAN yang hidup yang menuntun orang Israel keluar dari tanah Mesir!,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 8, 'melainkan: Demi TUHAN yang hidup yang menuntun dan membawa pulang keturunan kaum Israel keluar dari tanah utara dan dari segala negeri ke mana Ia telah menceraiberaikan mereka!, maka mereka akan tinggal di tanahnya sendiri."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 9, 'Mengenai nabi-nabi. Hatiku hancur dalam dadaku, segala tulangku goyah. Keadaanku seperti orang mabuk, seperti laki-laki yang terlalu banyak minum anggur, oleh karena TUHAN dan oleh karena firman-Nya yang kudus.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 10, 'Negeri telah penuh dengan orang-orang berzinah; sungguh, oleh karena kutuk ini gersanglah negeri dan layulah padang-padang rumput di gurun; apa yang dikejar mereka adalah kejahatan, dan kekuatan mereka adalah ketidakadilan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 11, '"Sungguh, baik nabi maupun imam berlaku fasik; di rumah-Kupun juga Aku mendapati kejahatan mereka, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 12, 'Sebab itu jalan mereka akan seperti jalan-jalan yang licin bagi mereka; di dalam gelap mereka akan terserandung dan akan jatuh di sana; sebab Aku akan mendatangkan malapetaka atas mereka dalam tahun waktu mereka dihukum, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 13, 'Di kalangan para nabi Samaria Aku melihat ada yang kurang pantas: mereka bernubuat demi Baal dan menyesatkan umat-Ku Israel.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 14, 'Tetapi di kalangan para nabi Yerusalem Aku melihat ada yang mengerikan: mereka berzinah dan berkelakuan tidak jujur; mereka menguatkan hati orang-orang yang berbuat jahat, sehingga tidak ada seorangpun yang bertobat dari kejahatannya; semuanya mereka telah menjadi seperti Sodom bagi-Ku dan penduduknya seperti Gomora."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 15, 'Sebab itu beginilah firman TUHAN semesta alam mengenai para nabi itu: "Sesungguhnya, Aku akan memberi mereka makan ipuh dan minum racun, sebab dari para nabi Yerusalem telah meluas kefasikan ke seluruh negeri."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 16, 'Beginilah firman TUHAN semesta alam: "Janganlah dengarkan perkataan para nabi yang bernubuat kepada kamu! Mereka hanya memberi harapan yang sia-sia kepadamu, dan hanya mengungkapkan penglihatan rekaan hatinya sendiri, bukan apa yang datang dari mulut TUHAN;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 17, 'mereka selalu berkata kepada orang-orang yang menista firman TUHAN: Kamu akan selamat! dan kepada setiap orang yang mengikuti kedegilan hatinya mereka berkata: Malapetaka tidak akan menimpa kamu!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 18, 'Sebab siapakah yang hadir dalam dewan musyawarah TUHAN, sehingga ia memperhatikan dan mendengar firman-Nya? Siapakah yang memperhatikan firman-Nya dan mendengarnya?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 19, 'Lihatlah, angin badai TUHAN, yakni kehangatan murka, telah keluar menyambar, ?angin puting beliung?dan turun menimpa kepala orang-orang fasik.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 20, 'Murka TUHAN tidak akan surut, sampai Ia telah melaksanakan dan mewujudkan apa yang dirancang-Nya dalam hati-Nya; pada hari-hari yang terakhir kamu akan benar-benar mengerti hal itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 21, '"Aku tidak mengutus para nabi itu, namun mereka giat; Aku tidak berfirman kepada mereka, namun mereka bernubuat.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 22, 'Sekiranya mereka hadir dalam dewan musyawarah-Ku, niscayalah mereka akan mengabarkan firman-Ku kepada umat-Ku, membawa mereka kembali dari tingkah langkahnya yang jahat dan dari perbuatan-perbuatannya yang jahat.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 23, 'Masakan Aku ini hanya Allah yang dari dekat, demikianlah firman TUHAN, dan bukan Allah yang dari jauh juga?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 24, 'Sekiranya ada seseorang menyembunyikan diri dalam tempat persembunyian, masakan Aku tidak melihat dia? demikianlah firman TUHAN. Tidakkah Aku memenuhi langit dan bumi? demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 25, 'Aku telah mendengar apa yang dikatakan oleh para nabi, yang bernubuat palsu demi nama-Ku dengan mengatakan: Aku telah bermimpi, aku telah bermimpi!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 26, 'Sampai bilamana hal itu ada dalam hati para nabi yang bernubuat palsu dan yang menubuatkan tipu rekaan hatinya sendiri,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 27, 'yang merancang membuat umat-Ku melupakan nama-Ku dengan mimpi-mimpinya yang mereka ceritakan seorang kepada seorang, sama seperti nenek moyang mereka melupakan nama-Ku oleh karena Baal?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 28, 'Nabi yang beroleh mimpi, biarlah menceritakan mimpinya itu, dan nabi yang beroleh firman-Ku, biarlah menceritakan firman-Ku itu dengan benar! Apakah sangkut-paut jerami dengan gandum? demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 29, 'Bukankah firman-Ku seperti api, demikianlah firman TUHAN dan seperti palu yang menghancurkan bukit batu?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 30, 'Sebab itu, sesungguhnya, Aku akan menjadi lawan para nabi, demikianlah firman TUHAN, yang mencuri firman-Ku masing-masing dari temannya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 31, 'Sesungguhnya, Aku akan menjadi lawan para nabi, demikianlah firman TUHAN, yang memakai lidahnya sewenang-wenang untuk mengutarakan firman ilahi.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 32, 'Sesungguhnya, Aku akan menjadi lawan mereka yang menubuatkan mimpi-mimpi dusta, demikianlah firman TUHAN, dan yang menceritakannya serta menyesatkan umat-Ku dengan dustanya dan dengan bualnya. Aku ini tidak pernah mengutus mereka dan tidak pernah memerintahkan mereka. Mereka sama sekali tiada berguna untuk bangsa ini, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 33, 'Apabila bangsa ini?baik nabi ataupun imam?bertanya kepadamu: Apakah Sabda yang dibebankan oleh TUHAN?, maka jawablah mereka: Kamulah beban itu! Sebab itu kamu akan Kubuang dari hadapan-Ku, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 34, 'Adapun nabi atau imam atau rakyat yang masih berbicara tentang Sabda yang dibebankan oleh TUHAN, kepada orang itu dan kepada keluarganya akan Kulakukan pembalasan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 35, 'Beginilah harus kamu katakan, masing-masing kepada temannya dan masing-masing kepada saudaranya: Apakah jawab TUHAN? atau: Apakah firman TUHAN?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 36, 'Tetapi Sabda yang dibebankan oleh TUHAN janganlah kamu sebut-sebutkan lagi, sebab yang menjadi beban bagi setiap orang ialah perkataannya sendiri, oleh karena kamu telah memutarbalikkan perkataan-perkataan Allah yang hidup, TUHAN semesta alam, Allah kita.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 37, 'Beginilah engkau harus berkata kepada nabi: Apakah jawab TUHAN kepadamu? atau: Apakah firman TUHAN?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 38, 'Tetapi jika kamu masih berbicara tentang Sabda yang dibebankan oleh TUHAN, maka beginilah firman TUHAN: Oleh karena kamu masih memakai ungkapan Sabda yang dibebankan oleh TUHAN itu, sekalipun Aku mengutus orang kepadamu mengatakan: Janganlah kamu berbicara tentang Sabda yang dibebankan oleh TUHAN,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 39, 'maka sesungguhnya, Aku akan menangkap kamu dan membuang kamu dari hadapan-Ku, kamu serta kota yang telah Kuberikan kepadamu dan kepada nenek moyangmu itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 23, 40, 'Aku akan menimpakan kepadamu aib yang kekal dan noda yang kekal yang tidak akan terlupakan."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 24, 1, 'Lihatlah, TUHAN memperlihatkan kepadaku dua keranjang buah ara berdiri di hadapan bait TUHAN. Hal itu terjadi sesudah Nebukadnezar, raja Babel, mengangkut ke dalam pembuangan Yekhonya bin Yoyakim, raja Yehuda, beserta para pemuka Yehuda, tukang dan pandai besi dari Yerusalem dan membawa mereka ke Babel.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 24, 2, 'Keranjang yang satu berisi buah ara yang sangat baik seperti buah ara bungaran, tetapi keranjang yang lain berisi buah ara yang jelek, yang tak dapat dimakan karena jeleknya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 24, 3, 'Lalu berfirmanlah TUHAN kepadaku: "Apakah yang kaulihat, hai Yeremia?" Maka jawabku: "Buah ara! Buah ara yang baik itu sangat baik, dan buah ara yang jelek, yang tak dapat dimakan karena jeleknya."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 24, 4, 'Kemudian datanglah firman TUHAN kepadaku, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 24, 5, '"Beginilah firman TUHAN, Allah Israel: Sama seperti buah ara yang baik ini, demikianlah Aku akan memperhatikan untuk kebaikannya orang-orang Yehuda yang Kubawa dari tempat ini ke dalam pembuangan, ke negeri orang-orang Kasdim.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 24, 6, 'Maka Aku akan mengarahkan mata-Ku kepada mereka untuk kebaikan mereka, dan Aku akan membawa mereka kembali ke negeri ini. Aku akan membangun mereka, bukan meruntuhkannya; Aku akan menanam, bukan mencabutnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 24, 7, 'Aku akan memberi mereka suatu hati untuk mengenal Aku, yaitu bahwa Akulah TUHAN. Mereka akan menjadi umat-Ku dan Aku ini akan menjadi Allah mereka, sebab mereka akan bertobat kepada-Ku dengan segenap hatinya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 24, 8, 'Tetapi seperti buah ara yang jelek itu, yang tak dapat dimakan karena jeleknya?sungguh, beginilah firman TUHAN?demikianlah Aku akan memperlakukan Zedekia, raja Yehuda, beserta para pemukanya, dan sisa-sisa penduduk Yerusalem yang masih tinggal di negeri ini dan orang-orang yang menetap di negeri Mesir.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 24, 9, 'Aku akan membuat mereka menjadi kengerian bagi segala kerajaan di bumi, menjadi aib dan perumpamaan, menjadi sindiran dan kutuk di segala tempat ke mana Aku menceraiberaikan mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 24, 10, 'Dan Aku akan mengirimkan perang, kelaparan dan penyakit sampar ke antara mereka, sampai mereka habis dilenyapkan dari atas tanah yang telah Kuberikan kepada mereka dan kepada nenek moyang mereka."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 1, 'Firman yang datang kepada Yeremia tentang segenap kaum Yehuda dalam tahun keempat pemerintahan Yoyakim bin Yosia, raja Yehuda, yaitu dalam tahun pertama pemerintahan Nebukadnezar, raja Babel.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 2, 'Firman itu telah disampaikan oleh nabi Yeremia kepada segenap kaum Yehuda dan kepada segenap penduduk Yerusalem, katanya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 3, '"Sejak dari tahun yang ketiga belas pemerintahan Yosia bin Amon, raja Yehuda, sampai hari ini, jadi sudah dua puluh tiga tahun lamanya, firman TUHAN datang kepadaku dan terus-menerus aku mengucapkannya kepadamu, tetapi kamu tidak mau mendengarkannya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 4, 'Juga TUHAN terus-menerus mengutus kepadamu semua hamba-Nya, yakni nabi-nabi, tetapi kamu tidak mau mendengarkan dan memperhatikannya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 5, 'Kata mereka: Bertobatlah masing-masing kamu dari tingkah langkahmu yang jahat dan dari perbuatan-perbuatanmu yang jahat; maka kamu akan tetap diam di tanah yang diberikan TUHAN kepadamu dan kepada nenek moyangmu, dari selama-lamanya sampai selama-lamanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 6, 'Juga janganlah kamu mengikuti allah lain untuk beribadah dan sujud menyembah kepadanya; janganlah kamu menimbulkan sakit hati-Ku dengan buatan tanganmu, supaya jangan Aku mendatangkan malapetaka kepadamu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 7, 'Tetapi kamu tidak mendengarkan Aku, demikianlah firman TUHAN, sehingga kamu menimbulkan sakit hati-Ku dengan buatan tanganmu untuk kemalanganmu sendiri.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 8, 'Sebab itu beginilah firman TUHAN semesta alam: Oleh karena kamu tidak mendengarkan perkataan-perkataan-Ku,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 9, 'sesungguhnya, Aku akan mengerahkan semua kaum dari utara?demikianlah firman TUHAN?menyuruh memanggil Nebukadnezar, raja Babel, hamba-Ku itu; Aku akan mendatangkan mereka melawan negeri ini, melawan penduduknya dan melawan bangsa-bangsa sekeliling ini, yang akan Kutumpas dan Kubuat menjadi kengerian, menjadi sasaran suitan dan menjadi ketandusan untuk selama-lamanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 10, 'Aku akan melenyapkan dari antara mereka suara kegirangan dan suara sukacita, suara pengantin laki-laki dan pengantin perempuan, bunyi batu kilangan dan cahaya pelita.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 11, 'Maka seluruh negeri ini akan menjadi reruntuhan dan ketandusan, dan bangsa-bangsa ini akan menjadi hamba kepada raja Babel tujuh puluh tahun lamanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 12, 'Kemudian sesudah genap ketujuh puluh tahun itu, demikianlah firman TUHAN, maka Aku akan melakukan pembalasan kepada raja Babel dan kepada bangsa itu oleh karena kesalahan mereka, juga kepada negeri orang-orang Kasdim, dengan membuatnya menjadi tempat-tempat yang tandus untuk selama-lamanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 13, 'Aku akan menimpakan kepada negeri ini segala apa yang Kufirmankan tentang dia, yaitu segala apa yang tertulis dalam kitab ini seperti yang telah dinubuatkan Yeremia tentang segala bangsa itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 14, 'Sebab merekapun juga akan menjadi hamba kepada banyak bangsa-bangsa dan raja-raja yang besar, dan Aku akan mengganjar mereka setimpal dengan pekerjaan mereka dan setimpal dengan perbuatan tangan mereka."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 15, 'Beginilah firman TUHAN, Allah Israel, kepadaku: "Ambillah dari tangan-Ku piala berisi anggur kehangatan amarah ini dan minumkanlah isinya kepada segala bangsa yang kepadanya Aku mengutus engkau,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 16, 'supaya mereka minum, menjadi terhuyung-huyung dan bingung karena pedang yang hendak Kukirimkan ke antaranya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 17, 'Maka aku mengambil piala itu dari tangan TUHAN, lalu meminumkan isinya kepada segala bangsa yang kepadanya TUHAN mengutus aku,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 18, 'yakni kepada Yerusalem dan kota-kota Yehuda, beserta raja-rajanya dan pemuka-pemukanya, untuk membuat semuanya itu menjadi reruntuhan, ketandusan dan sasaran suitan dan kutuk seperti halnya pada hari ini;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 19, 'kepada Firaun, raja Mesir, beserta pegawai-pegawainya, dan pemuka-pemukanya, dan segenap rakyatnya,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 20, 'juga kepada semua orang campuran dari berbagai-bagai bangsa; kepada semua raja negeri Us; kepada semua raja negeri Filistin, yakni Askelon, Gaza, Ekron dan orang-orang yang masih tinggal hidup di Asdod;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 21, 'kepada Edom, Moab dan bani Amon;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 22, 'kepada semua raja Tirus, semua raja Sidon dan kepada raja-raja tanah pesisir di seberang laut;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 23, 'kepada Dedan, Tema, Bus dan kepada orang-orang yang berpotong tepi rambutnya berkeliling;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 24, 'kepada semua raja Arab yang tinggal di padang gurun;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 25, 'kepada semua raja Zimri, kepada semua raja Elam dan kepada semua raja Madai;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 26, 'kepada semua raja dari utara, yang dekat dan yang jauh, satu demi satu, dan kepada semua kerajaan dunia yang ada di atas muka bumi; juga raja Sesakh akan meminumnya sesudah mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 27, 'Kemudian haruslah kaukatakan kepada mereka: Beginilah firman TUHAN semesta alam, Allah Israel: Minumlah sampai mabuk dan muntah-muntah! Rebahlah dan jangan bangun lagi, oleh karena pedang yang hendak Kukirimkan ke antara kamu!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 28, 'Tetapi apabila mereka enggan menerima piala itu dari tanganmu untuk meminum isinya, maka haruslah kaukatakan kepada mereka: Beginilah firman TUHAN semesta alam: Kamu wajib meminumnya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 29, 'Sebab sesungguhnya di kota yang nama-Ku telah diserukan di atasnya Aku akan mulai mendatangkan malapetaka; masakan kamu ini akan bebas dari hukuman? kamu tidak akan bebas dari hukuman, sebab Aku ini mengerahkan pedang ke atas segenap penduduk bumi, demikianlah firman TUHAN semesta alam.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 30, 'Dan engkau ini, nubuatkanlah segala firman ini kepada mereka. Katakanlah kepada mereka: TUHAN akan menengking dari tempat tinggi dan memperdengarkan suara-Nya dari tempat pernaungan-Nya yang kudus; Ia akan mengaum hebat terhadap tempat penggembalaan-Nya, suatu pekik, seperti yang dipekikkan pengirik-pengirik buah anggur, terhadap segenap penduduk bumi.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 31, 'Deru perang akan sampai ke ujung bumi, sebab TUHAN mempunyai pengaduan terhadap bangsa-bangsa; Ia akan berperkara dengan segala makhluk: Orang-orang fasik akan diserahkan-Nya kepada pedang, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 32, 'Beginilah firman TUHAN semesta alam: Sesungguhnya, malapetaka akan menjalar dari bangsa ke bangsa, suatu badai besar akan berkecamuk dari ujung-ujung bumi.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 33, 'Maka pada hari itu akan bergelimpangan orang-orang yang mati terbunuh oleh TUHAN dari ujung bumi sampai ke ujung bumi. Mereka tidak akan diratapi, tidak akan dikumpulkan dan tidak akan dikuburkan; mereka akan menjadi pupuk di ladang.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 34, 'Mengeluh dan berteriaklah, hai para gembala! Berguling-gulinglah dalam debu, hai pemimpin-pemimpin kawanan kambing domba! Sebab sudah genap waktunya kamu akan disembelih, dan kamu akan rebah seperti domba jantan pilihan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 35, 'Maka bagi para gembala tidak akan ada lagi kelepasan, dan bagi para pemimpin kawanan kambing domba tidak akan ada lagi keluputan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 36, 'Dengar! para gembala berteriak, para pemimpin kawanan kambing domba mengeluh! Sebab TUHAN telah merusakkan padang gembalaan mereka,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 37, 'dan sunyi sepilah padang rumput yang sentosa, oleh karena murka TUHAN yang menyala-nyala itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 25, 38, 'Seperti singa Ia meninggalkan semak belukar persembunyian-Nya, sebab negeri mereka sudah menjadi ketandusan, oleh karena pedang yang dahsyat, oleh karena murka-Nya yang menyala-nyala."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 1, 'Pada permulaan pemerintahan Yoyakim, anak Yosia raja Yehuda, datanglah firman ini dari TUHAN, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 2, 'Beginilah firman TUHAN: "Berdirilah di pelataran rumah TUHAN dan katakanlah kepada penduduk segala kota Yehuda, yang datang untuk sujud di rumah TUHAN, segala firman yang Kuperintahkan untuk kaukatakan kepada mereka. Janganlah kaukurangi sepatah katapun!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 3, 'Mungkin mereka mau mendengarkan dan masing-masing mau berbalik dari tingkah langkahnya yang jahat, sehingga Aku menyesal akan malapetaka yang Kurancangkan itu terhadap mereka oleh karena perbuatan-perbuata mereka yang jahat.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 4, 'Jadi katakanlah kepada mereka: Beginilah firman TUHAN: Jika kamu tidak mau mendengarkan Aku, tidak mau mengikuti Taurat-Ku yang telah Kubentangkan di hadapanmu,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 5, 'dan tidak mau mendengarkan perkataan hamba-hamba-Ku, para nabi, yang terus-menerus Kuutus kepadamu, ?tetapi kamu tidak mau mendengarkan?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 6, 'maka Aku akan membuat rumah ini sama seperti Silo, dan kota ini menjadi kutuk bagi segala bangsa di bumi."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 7, 'Para imam, para nabi dan seluruh rakyat mendengar Yeremia mengucapkan perkataan-perkataan itu dalam rumah TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 8, 'Lalu sesudah Yeremia selesai mengatakan segala apa yang diperintahkan TUHAN untuk dikatakan kepada seluruh rakyat itu, maka para imam, para nabi dan seluruh rakyat itu menangkap dia serta berkata: "Engkau harus mati!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 9, 'Mengapa engkau bernubuat demi nama TUHAN dengan berkata: Rumah ini akan sama seperti Silo, dan kota ini akan menjadi reruntuhan, sehingga tidak ada lagi penduduknya?" Dan seluruh rakyat berkumpul mengerumuni Yeremia di rumah TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 10, 'Ketika para pemuka Yehuda mendengar tentang hal ini, pergilah mereka dari istana raja ke rumah TUHAN, lalu duduk di pintu gerbang baru di rumah TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 11, 'Kemudian berkatalah para imam dan para nabi itu kepada para pemuka dan kepada seluruh rakyat itu, katanya: "Orang ini patut mendapat hukuman mati, sebab ia telah bernubuat tentang kota ini, seperti yang kamu dengar dengan telingamu sendiri."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 12, 'Tetapi Yeremia berkata kepada segala pemuka dan kepada seluruh rakyat itu, katanya: "Tuhanlah yang telah mengutus aku supaya bernubuat tentang rumah dan kota ini untuk menyampaikan segala perkataan yang telah kamu dengar itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 13, 'Oleh sebab itu, perbaikilah tingkah langkahmu dan perbuatanmu, dan dengarkanlah suara TUHAN, Allahmu, sehingga TUHAN menyesal akan malapetaka yang diancamkan-Nya atas kamu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 14, 'Tetapi aku ini, sesungguhnya, aku ada di tanganmu, perbuatlah kepadaku apa yang baik dan benar di matamu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 15, 'Hanya ketahuilah sungguh-sungguh, bahwa jika kamu membunuh aku, maka kamu mendatangkan darah orang yang tak bersalah atas kamu dan atas kota ini dan penduduknya, sebab TUHAN benar-benar mengutus aku kepadamu untuk menyampaikan segala perkataan ini kepadamu."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 16, 'Lalu berkatalah para pemuka dan seluruh rakyat itu kepada imam-imam dan nabi-nabi itu: "Orang ini tidak patut mendapat hukuman mati, sebab ia telah berbicara kepada kita demi nama TUHAN, Allah kita."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 17, 'Memang beberapa orang dari para tua-tua negeri itu tampil juga ke depan dan berkata kepada kumpulan rakyat itu, katanya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 18, '"Mikha, orang Moresyet itu, telah bernubuat di zaman Hizkia, raja Yehuda. Dia telah berkata kepada segenap bangsa Yehuda: Beginilah firman TUHAN semesta alam: Sion akan dibajak seperti ladang dan Yerusalem akan menjadi timbunan puing dan gunung Bait Suci akan menjadi bukit yang berhutan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 19, 'Apakah Hizkia, raja Yehuda, beserta segenap Yehuda membunuh dia? Tidakkah ia takut akan TUHAN, sehingga ia memohon belas kasihan TUHAN, agar TUHAN menyesal akan malapetaka yang diancamkan-Nya atas mereka? Dan kita, maukah kita mendatangkan malapetaka yang begitu besar atas diri kita sendiri?"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 20, 'Ada juga seorang lain yang bernubuat demi nama TUHAN, yaitu Uria bin Semaya, dari Kiryat-Yearim. Dia bernubuat tentang kota dan negeri ini tepat seperti yang dikatakan Yeremia.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 21, 'Ketika raja Yoyakim, bersama-sama dengan segenap perwiranya dan semua pemuka, mendengar perkataan orang itu, maka rajapun mencari ikhtiar untuk membunuhnya. Mendengar hal itu maka takutlah Uria, lalu melarikan diri dan tiba di Mesir.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 22, 'Kemudian raja Yoyakim menyuruh orang ke Mesir, yaitu Elnatan bin Akhbor beserta beberapa orang.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 23, 'Mereka mengambil Uria dari Mesir dan membawanya kepada raja Yoyakim. Raja menyuruh membunuh dia dengan pedang dan melemparkan mayatnya ke kuburan rakyat biasa.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 26, 24, 'Tetapi Yeremia dilindungi oleh Ahikam bin Safan, sehingga ia tidak diserahkan ke dalam tangan rakyat untuk dibunuh.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 27, 1, 'Pada permulaan pemerintahan Zedekia, anak Yosia raja Yehuda, datanglah firman ini dari TUHAN kepada Yeremia.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 27, 2, 'Beginilah firman TUHAN kepadaku: "Buatlah tali pengikat dan gandar, lalu pasanglah itu pada tengkukmu!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 27, 3, 'Kemudian kirimlah pesan kepada raja Edom, kepada raja Moab, kepada raja bani Amon, kepada raja Tirus dan kepada raja Sidon, dengan perantaraan utusan-utusan yang telah datang ke Yerusalem menghadap Zedekia, raja Yehuda.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 27, 4, 'Perintahkanlah mereka mengatakan kepada tuan-tuan mereka: Beginilah firman TUHAN semesta alam, Allah Israel: Beginilah harus kamu katakan kepada tuan-tuanmu:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 27, 5, 'Akulah yang menjadikan bumi, manusia dan hewan yang ada di atas muka bumi dengan kekuatan-Ku yang besar dan dengan lengan-Ku yang terentang, dan Aku memberikannya kepada orang yang benar di mata-Ku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 27, 6, 'Dan sekarang, Aku menyerahkan segala negeri ini ke dalam tangan hamba-Ku, yakni Nebukadnezar, raja Babel; juga binatang di padang telah Kuserahkan supaya tunduk kepadanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 27, 7, 'Segala bangsa akan takluk kepadanya dan kepada anaknya dan kepada cucunya, sampai saatnya juga tiba bagi negerinya sendiri, maka banyak bangsa dan raja-raja yang besar akan menaklukkannya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 27, 8, 'Tetapi bangsa dan kerajaan yang tidak mau takluk kepada Nebukadnezar, raja Babel, dan yang tidak mau menyerahkan tengkuknya ke bawah kuk raja Babel, maka bangsa itu akan Kuhukum dengan pedang, kelaparan dan penyakit sampar, demikianlah firman TUHAN, sampai mereka Kuserahkan ke dalam tangannya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 27, 9, 'Mengenai kamu, janganlah kamu mendengarkan nabi-nabimu, juru-juru tenungmu, juru-juru mimpimu, tukang-tukang ramalmu dan tukang-tukang sihirmu yang berkata kepadamu: Janganlah kamu mau takluk kepada raja Babel!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 27, 10, 'Sebab mereka bernubuat palsu kepadamu dengan maksud menjauhkan kamu dari atas tanahmu, sehingga kamu Kuceraiberaikan dan menjadi binasa.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 27, 11, 'Tetapi bangsa yang mau menaruh tengkuknya ke bawah kuk raja Babel dan yang takluk kepadanya, maka mereka akan Kubiarkan di atas tanahnya, demikianlah firman TUHAN, dan mereka akan mengolahnya dan diam di sana."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 27, 12, 'Kepada Zedekia, raja Yehuda, aku telah berbicara dengan cara yang sama, kataku: "Taruhlah tengkukmu ke bawah kuk raja negeri Babel, takluklah kepadanya dan kepada rakyatnya, maka kamu akan hidup.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 27, 13, 'Mengapa engkau beserta rakyatmu harus mati oleh pedang, kelaparan dan penyakit sampar seperti yang difirmankan TUHAN tentang bangsa yang tidak mau takluk kepada raja Babel itu?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 27, 14, 'Janganlah dengarkan perkataan nabi-nabi yang berkata kepadamu: Janganlah kamu mau takluk kepada raja Babel! Sebab mereka bernubuat palsu kepadamu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 27, 15, 'Sebab Aku tidak mengutus mereka, demikianlah firman TUHAN, tetapi mereka bernubuat palsu demi nama-Ku, sehingga kamu Kuceraiberaikan dan menjadi binasa bersama-sama dengan nabi-nabi yang bernubuat kepadamu itu."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 27, 16, 'Juga kepada imam-imam dan kepada seluruh rakyat itu aku berbicara, kataku: "Beginilah firman TUHAN: Janganlah dengarkan perkataan nabi-nabimu yang bernubuat kepadamu: Sesungguhnya, perkakas-perkakas rumah TUHAN tidak berapa lama lagi akan dibawa kembali dari Babel! Sebab mereka bernubuat palsu kepadamu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 27, 17, 'Janganlah kamu mendengarkan mereka, takluklah kepada raja Babel, maka kamu akan hidup. Mengapa kota ini harus menjadi reruntuhan?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 27, 18, 'Jika memang mereka itu nabi dan jika ada firman TUHAN pada mereka, baiklah mereka mendesak kepada TUHAN semesta alam, supaya perkakas-perkakas yang masih tinggal dalam rumah TUHAN dan dalam istana raja Yehuda dan di Yerusalem itu jangan diangkut ke Babel.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 27, 19, 'Sebab beginilah firman TUHAN semesta alam tentang tiang-tiang, bejana ?laut? dan galang, tentang sisa perkakas-perkakas yang masih tinggal di kota ini,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 27, 20, 'yang tidak diambil oleh Nebukadnezar, raja Babel, ketika ia mengangkut Yekhonya bin Yoyakim, raja Yehuda, ke dalam pembuangan beserta segala pemuka Yehuda dan Yerusalem, dari Yerusalem ke Babel, ?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 27, 21, 'sungguh, beginilah firman TUHAN semesta alam, Allah Israel, tentang perkakas-perkakas yang masih tinggal itu di rumah TUHAN dan di istana raja Yehuda dan di Yerusalem:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 27, 22, 'Semuanya akan diangkut ke Babel dan akan tinggal di sana sampai kepada hari Aku memperhatikannya lagi, demikianlah firman TUHAN, lalu membawanya kembali ke tempat ini."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 28, 1, 'Dalam tahun itu juga, pada permulaan pemerintahan Zedekia, raja Yehuda, dalam bulan yang kelima tahun yang keempat, berkatalah nabi Hananya bin Azur yang berasal dari Gibeon itu kepadaku di rumah TUHAN, di depan mata imam-imam dan seluruh rakyat:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 28, 2, '"Beginilah firman TUHAN semesta alam, Allah Israel: Aku telah mematahkan kuk raja Babel itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 28, 3, 'Dalam dua tahun ini Aku akan mengembalikan ke tempat ini segala perkakas rumah TUHAN yang telah diambil dari tempat ini oleh Nebukadnezar, raja Babel, dan yang diangkutnya ke Babel.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 28, 4, 'Juga Yekhonya bin Yoyakim, raja Yehuda, beserta semua orang buangan dari Yehuda yang dibawa ke Babel akan Kukembalikan ke tempat ini, demikianlah firman TUHAN! Sungguh, Aku akan mematahkan kuk raja Babel itu!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 28, 5, 'Lalu berkatalah nabi Yeremia kepada nabi Hananya di depan mata imam-imam dan di depan mata seluruh rakyat yang berdiri di rumah TUHAN itu,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 28, 6, 'kata nabi Yeremia: "Amin! Moga-moga TUHAN berbuat demikian! Moga-moga TUHAN menepati perkataan-perkataan yang kaunubuatkan itu dengan dikembalikannya perkakas-perkakas rumah TUHAN dan semua orang buangan itu dari Babel ke tempat ini.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 28, 7, 'Hanya, dengarkanlah hendaknya perkataan yang akan kukatakan ke telingamu dan ke telinga seluruh rakyat ini:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 28, 8, 'Nabi-nabi yang ada sebelum aku dan sebelum engkau dari dahulu kala telah bernubuat kepada banyak negeri dan terhadap kerajaan-kerajaan yang besar tentang perang dan malapetaka dan penyakit sampar.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 28, 9, 'Tetapi mengenai seorang nabi yang bernubuat tentang damai sejahtera, jika nubuat nabi itu digenapi, maka barulah ketahuan, bahwa nabi itu benar-benar diutus oleh TUHAN."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 28, 10, 'Kemudian nabi Hananya mengambil gandar itu dari pada tengkuk nabi Yeremia, lalu mematahkannya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 28, 11, 'Berkatalah Hananya di depan mata seluruh rakyat itu: "Beginilah firman TUHAN: Dalam dua tahun ini begitu jugalah Aku akan mematahkan kuk Nebukadnezar, raja Babel itu, dari pada tengkuk segala bangsa!" Tetapi pergilah nabi Yeremia dari sana.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 28, 12, 'Maka sesudah nabi Hananya mematahkan gandar dari pada tengkuk nabi Yeremia, datanglah firman TUHAN kepada Yeremia:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 28, 13, '"Pergilah mengatakan kepada Hananya: Beginilah firman TUHAN: Engkau telah mematahkan gandar kayu, tetapi Aku akan membuat gandar besi sebagai gantinya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 28, 14, 'Sebab beginilah firman TUHAN semesta alam, Allah Israel: Kuk besi akan Kutaruh ke atas tengkuk segala bangsa ini, sehingga mereka takluk kepada Nebukadnezar, raja Babel; sungguh, mereka akan takluk kepadanya! Malahan binatang-binatang di padang telah Kuserahkan kepadanya."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 28, 15, 'Lalu berkatalah nabi Yeremia kepada nabi Hananya: "Dengarkanlah, hai Hananya! TUHAN tidak mengutus engkau, tetapi engkau telah membuat bangsa ini percaya kepada dusta.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 28, 16, 'Sebab itu beginilah firman TUHAN: Sesungguhnya, Aku menyuruh engkau pergi dari muka bumi. Tahun ini juga engkau akan mati, sebab engkau telah mengajak murtad terhadap TUHAN."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 28, 17, 'Maka matilah nabi Hananya dalam tahun itu juga, pada bulan yang ketujuh.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 1, 'Beginilah bunyi surat yang dikirim oleh nabi Yeremia dari Yerusalem kepada tua-tua di antara orang buangan, kepada imam-imam, kepada nabi-nabi dan kepada seluruh rakyat yang telah diangkut ke dalam pembuangan oleh Nebukadnezar dari Yerusalem ke Babel.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 2, 'Itu terjadi sesudah raja Yekhonya beserta ibu suri, pegawai-pegawai istana, pemuka-pemuka Yehuda dan Yerusalem, tukang dan pandai besi telah keluar dari Yerusalem.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 3, 'Surat itu dikirim dengan perantaraan Elasa bin Safan dan Gemarya bin Hilkia yang diutus oleh Zedekia, raja Yehuda, ke Babel, kepada Nebukadnezar, raja Babel. Bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 4, '"Beginilah firman TUHAN semesta alam, Allah Israel, kepada semua orang buangan yang diangkut ke dalam pembuangan dari Yerusalem ke Babel:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 5, 'Dirikanlah rumah untuk kamu diami; buatlah kebun untuk kamu nikmati hasilnya;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 6, 'ambillah isteri untuk memperanakkan anak laki-laki dan perempuan; ambilkanlah isteri bagi anakmu laki-laki dan carikanlah suami bagi anakmu perempuan, supaya mereka melahirkan anak laki-laki dan perempuan, agar di sana kamu bertambah banyak dan jangan berkurang!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 7, 'Usahakanlah kesejahteraan kota ke mana kamu Aku buang, dan berdoalah untuk kota itu kepada TUHAN, sebab kesejahteraannya adalah kesejahteraanmu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 8, 'Sungguh, beginilah firman TUHAN semesta alam, Allah Israel: Janganlah kamu diperdayakan oleh nabi-nabimu yang ada di tengah-tengahmu dan oleh juru-juru tenungmu, dan janganlah kamu dengarkan mimpi-mimpi yang mereka mimpikan!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 9, 'Sebab mereka bernubuat palsu kepadamu demi nama-Ku. Aku tidak mengutus mereka, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 10, 'Sebab beginilah firman TUHAN: Apabila telah genap tujuh puluh tahun bagi Babel, barulah Aku memperhatikan kamu. Aku akan menepati janji-Ku itu kepadamu dengan mengembalikan kamu ke tempat ini.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 11, 'Sebab Aku ini mengetahui rancangan-rancangan apa yang ada pada-Ku mengenai kamu, demikianlah firman TUHAN, yaitu rancangan damai sejahtera dan bukan rancangan kecelakaan, untuk memberikan kepadamu hari depan yang penuh harapan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 12, 'Dan apabila kamu berseru dan datang untuk berdoa kepada-Ku, maka Aku akan mendengarkan kamu;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 13, 'apabila kamu mencari Aku, kamu akan menemukan Aku; apabila kamu menanyakan Aku dengan segenap hati,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 14, 'Aku akan memberi kamu menemukan Aku, demikianlah firman TUHAN, dan Aku akan memulihkan keadaanmu dan akan mengumpulkan kamu dari antara segala bangsa dan dari segala tempat ke mana kamu telah Kuceraiberaikan, demikianlah firman TUHAN, dan Aku akan mengembalikan kamu ke tempat yang dari mana Aku telah membuang kamu. ?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 15, 'Memang kamu berkata: TUHAN telah membangkitkan nabi-nabi bagi kami di Babel. ?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 16, 'Sungguh, beginilah firman TUHAN tentang raja yang duduk di atas takhta Daud dan tentang seluruh rakyat yang diam di kota ini, yakni saudara-saudaramu yang tidak keluar beserta kamu ke dalam pembuangan:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 17, 'Beginilah firman TUHAN semesta alam: Sesungguhnya, Aku akan mengirim pedang, kelaparan dan penyakit sampar ke antara mereka, dan Aku akan membuat mereka seperti buah ara yang busuk dan demikian jeleknya, sehingga tidak dapat dimakan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 18, 'Aku akan mengejar mereka dengan pedang, kelaparan dan penyakit sampar, dan Aku akan membuat mereka menjadi kengerian bagi segala kerajaan di bumi, menjadi kutuk, kedahsyatan, suitan dan aib di antara segala bangsa ke mana mereka Kuceraiberaikan,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 19, 'sebagai ganjaran bahwa mereka tidak mendengarkan perkataan-Ku, demikianlah firman TUHAN, yang telah Kusampaikan kepada mereka terus-menerus dengan perantaraan hamba-hamba-Ku, yakni para nabi; tetapi kamu tidak mendengarkannya, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 20, 'Tetapi dengarkanlah firman TUHAN, hai kamu semua orang buangan, yang telah Kukirim dari Yerusalem ke Babel!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 21, 'Beginilah firman TUHAN semesta alam, Allah Israel, tentang Ahab bin Kolaya dan tentang Zedekia bin Maaseya, orang-orang yang bernubuat palsu kepadamu demi nama-Ku: Sesungguhnya Aku akan menyerahkan mereka ke dalam tangan Nebukadnezar, raja Babel, yang akan memarang mereka mati di depan matamu sendiri,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 22, 'sehingga dari keadaan mereka akan dijadikan suatu kutuk oleh semua orang buangan dari Yehuda yang ada di Babel, demikian: Biarlah TUHAN memperlakukan kamu seperti Zedekia dan Ahab yang telah dipanggang oleh raja negeri Babel di dalam api!,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 23, 'oleh karena mereka telah melakukan kebebalan di Israel, telah berzinah dengan isteri sesama mereka dan telah mengucapkan demi nama-Ku perkataan dusta yang tidak Kupesankan kepada mereka. Aku sendirilah yang mengetahui dan menyaksikannya, demikianlah firman TUHAN."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 24, 'Kepada Semaya, orang Nehelam itu, haruslah kaukatakan:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 25, '"Beginilah firman TUHAN semesta alam, Allah Israel: Oleh sebab engkau telah mengirim surat atas namamu sendiri kepada seluruh rakyat yang ada di Yerusalem, yaitu kepada imam Zefanya bin Maaseya dan kepada segala imam, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 26, 'TUHAN telah mengangkat engkau, Zefanya, menjadi imam menggantikan imam Yoyada, supaya engkau menjadi pengawas di rumah TUHAN untuk memasungkan setiap orang gila yang menganggap dirinya nabi dan untuk merantai lehernya dengan besi.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 27, 'Tetapi sekarang, mengapakah engkau tidak menegor Yeremia, orang Anatot itu, yang menganggap dirinya nabi di antaramu?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 28, 'Bukankah ia telah mengirim pesan kepada kami di Babel, katanya: Pembuanganmu masih lama. Dirikanlah rumah untuk kamu diami; buatlah kebun untuk kamu nikmati hasilnya!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 29, 'Surat ini dibacakan oleh imam Zefanya ke telinga nabi Yeremia.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 30, 'Maka datanglah firman TUHAN kepada Yeremia, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 31, '"Kirimlah pesan kepada semua orang buangan itu: Beginilah firman TUHAN tentang Semaya, orang Nehelam itu: Oleh karena Semaya telah bernubuat kepadamu, sekalipun Aku tidak mengutusnya, dan ia telah membuat kamu percaya kepada dusta,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 29, 32, 'maka beginilah firman TUHAN: Sesungguhnya, Aku akan menghukum Semaya, orang Nehelam itu, dan keturunannya: tidak ada seorangpun dari keluarganya akan diam di tengah-tengah bangsa ini untuk melihat yang baik yang akan Kulakukan kepada umat-Ku, demikianlah firman TUHAN, sebab ia telah mengajak murtad terhadap TUHAN."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 1, 'Firman yang datang dari TUHAN kepada Yeremia, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 2, '"Beginilah firman TUHAN, Allah Israel: Tuliskanlah segala perkataan yang telah Kufirmankan kepadamu itu dalam suatu kitab.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 3, 'Sebab, sesungguhnya, waktunya akan datang, demikianlah firman TUHAN, bahwa Aku akan memulihkan keadaan umat-Ku Israel dan Yehuda?firman TUHAN?dan Aku akan mengembalikan mereka ke negeri yang telah Kuberikan kepada nenek moyang mereka, dan mereka akan memilikinya."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 4, 'Inilah perkataan-perkataan yang telah difirmankan TUHAN tentang Israel dan tentang Yehuda:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 5, '"Sungguh, beginilah firman TUHAN: Telah kami dengar jerit kegentaran, kedahsyatan dan tidak ada damai.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 6, 'Cobalah tanyakan dan selidiki, adakah laki-laki melahirkan? Mengapakah setiap laki-laki Kulihat tangannya pada pinggangnya seperti seorang perempuan yang melahirkan? Mengapakah setiap muka berubah menjadi pucat?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 7, 'Hai, alangkah hebatnya hari itu, tidak ada taranya; itulah waktu kesusahan bagi Yakub, tetapi ia akan diselamatkan dari padanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 8, 'Maka pada hari itu, demikianlah firman TUHAN semesta alam, Aku akan mematahkan kuk dari tengkuk mereka dan memutuskan tali-tali pengikat mereka, dan mereka tidak akan mengabdi lagi kepada orang-orang asing.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 9, 'Mereka akan mengabdi kepada TUHAN, Allah mereka, dan kepada Daud, raja mereka, yang akan Kubangkitkan bagi mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 10, 'Maka engkau, janganlah takut, hai hamba-Ku Yakub, demikianlah firman TUHAN, janganlah gentar, hai Israel! Sebab sesungguhnya, Aku menyelamatkan engkau dari tempat jauh dan keturunanmu dari negeri pembuangan mereka. Yakub akan kembali dan hidup tenang dan aman, dengan tidak ada yang mengejutkan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 11, 'Sebab Aku menyertai engkau, demikianlah firman TUHAN, untuk menyelamatkan engkau: segala bangsa yang ke antaranya engkau Kuserahkan akan Kuhabiskan, tetapi engkau ini tidak akan Kuhabiskan. Aku akan menghajar engkau menurut hukum, tetapi Aku sama sekali tidak memandang engkau tak bersalah.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 12, 'Sungguh, beginilah firman TUHAN: Penyakitmu sangat payah, lukamu tidak tersembuhkan!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 13, 'Tidak ada yang membela hakmu, tidak ada obat untuk bisul, kesembuhan tidak ada bagimu!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 14, 'Semua kekasihmu melupakan engkau, mereka tidak menanyakan engkau lagi. Sungguh, Aku telah memukul engkau dengan pukulan musuh, dengan hajaran yang bengis, karena kesalahanmu banyak, dosamu berjumlah besar.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 15, 'Mengapakah engkau berteriak karena penyakitmu, karena kepedihanmu sangat payah? Karena kesalahanmu banyak, dosamu berjumlah besar, maka Aku telah melakukan semuanya ini kepadamu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 16, 'Tetapi semua orang yang menelan engkau akan tertelan, dan semua lawanmu akan masuk ke dalam tawanan; orang-orang yang merampok engkau akan menjadi rampokan, dan semua orang yang menjarah engkau akan Kubuat menjadi jarahan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 17, 'Sebab Aku akan mendatangkan kesembuhan bagimu, Aku akan mengobati luka-lukamu, demikianlah firman TUHAN, sebab mereka telah menyebutkan engkau: orang buangan, yakni sisa yang tiada seorangpun menanyakannya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 18, 'Beginilah firman TUHAN: Sesungguhnya, Aku akan memulihkan keadaan kemah-kemah Yakub, dan akan mengasihani tempat-tempat tinggalnya, kota itu akan dibangun kembali di atas reruntuhannya, dan puri itu akan berdiri di tempatnya yang asli.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 19, 'Nyanyian syukur akan terdengar dari antara mereka, juga suara orang yang bersukaria. Aku akan membuat mereka banyak dan mereka tidak akan berkurang lagi; Aku akan membuat mereka dipermuliakan dan mereka tidak akan dihina lagi.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 20, 'Anak-anak mereka akan menjadi seperti dahulu kala, dan perkumpulan mereka akan tinggal tetap di hadapan-Ku; Aku akan menghukum semua orang yang menindas mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 21, 'Orang yang memerintah atas mereka akan tampil dari antara mereka sendiri, dan orang yang berkuasa atas mereka akan bangkit dari tengah-tengah mereka; Aku akan membuat dia maju dan mendekat kepada-Ku, sebab siapakah yang berani mempertaruhkan nyawanya untuk mendekat kepada-Ku? demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 22, 'Maka kamu akan menjadi umat-Ku, dan Aku akan menjadi Allahmu."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 23, 'Lihatlah, angin badai TUHAN, yakni kehangatan murka, telah keluar menyambar, ?angin puting beliung?dan turun menimpa kepala orang-orang fasik.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 30, 24, 'Murka TUHAN yang menyala-nyala itu tidak akan surut sampai Ia telah melaksanakan dan mewujudkan apa yang dirancang-Nya dalam hati-Nya; pada hari-hari yang terakhir kamu akan mengerti hal itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 1, '"Pada waktu itu, demikianlah firman TUHAN, Aku akan menjadi Allah segala kaum keluarga Israel dan mereka akan menjadi umat-Ku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 2, 'Beginilah firman TUHAN: Ia mendapat kasih karunia di padang gurun, yaitu bangsa yang terluput dari pedang itu! Israel berjalan mencari istirahat bagi dirinya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 3, 'Dari jauh TUHAN menampakkan diri kepadanya: Aku mengasihi engkau dengan kasih yang kekal, sebab itu Aku melanjutkan kasih setia-Ku kepadamu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 4, 'Aku akan membangun engkau kembali, sehingga engkau dibangun, hai anak dara Israel! Engkau akan menghiasi dirimu kembali dengan rebana dan akan tampil dalam tari-tarian orang yang bersukaria.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 5, 'Engkau akan membuat kebun anggur kembali di gunung-gunung Samaria; ya, orang-orang yang membuatnya akan memetik hasilnya pula.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 6, 'Sungguh, akan datang harinya bahwa para penjaga akan berseru di gunung Efraim: Ayo, marilah kita naik ke Sion, kepada TUHAN, Allah kita!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 7, 'Sebab beginilah firman TUHAN: Bersorak-sorailah bagi Yakub dengan sukacita, bersukarialah tentang pemimpin bangsa-bangsa! Kabarkanlah, pujilah dan katakanlah: TUHAN telah menyelamatkan umat-Nya, yakni sisa-sisa Israel!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 8, 'Sesungguhnya, Aku akan membawa mereka dari tanah utara dan akan mengumpulkan mereka dari ujung bumi; di antara mereka ada orang buta dan lumpuh, ada perempuan yang mengandung bersama-sama dengan perhimpunan yang melahirkan; dalam kumpulan besar mereka akan kembali ke mari!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 9, 'Dengan menangis mereka akan datang, dengan hiburan Aku akan membawa mereka; Aku akan memimpin mereka ke sungai-sungai, di jalan yang rata, di mana mereka tidak akan tersandung; sebab Aku telah menjadi bapa Israel, Efraim adalah anak sulung-Ku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 10, 'Dengarlah firman TUHAN, hai bangsa-bangsa, beritahukanlah itu di tanah-tanah pesisir yang jauh, katakanlah: Dia yang telah menyerakkan Israel akan mengumpulkannya kembali, dan menjaganya seperti gembala terhadap kawanan dombanya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 11, 'Sebab TUHAN telah membebaskan Yakub, telah menebusnya dari tangan orang yang lebih kuat dari padanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 12, 'Mereka akan datang bersorak-sorak di atas bukit Sion, muka mereka akan berseri-seri karena kebajikan TUHAN, karena gandum, anggur dan minyak, karena anak-anak kambing domba dan lembu sapi; hidup mereka akan seperti taman yang diairi baik-baik, mereka tidak akan kembali lagi merana.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 13, 'Pada waktu itu anak-anak dara akan bersukaria menari beramai-ramai, orang-orang muda dan orang-orang tua akan bergembira. Aku akan mengubah perkabungan mereka menjadi kegirangan, akan menghibur mereka dan menyukakan mereka sesudah kedukaan mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 14, 'Aku akan memuaskan jiwa para imam dengan kelimpahan, dan umat-Ku akan menjadi kenyang dengan kebajikan-Ku, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 15, 'Beginilah firman TUHAN: Dengar! Di Rama terdengar ratapan, tangisan yang pahit pedih: Rahel menangisi anak-anaknya, ia tidak mau dihibur karena anak-anaknya, sebab mereka tidak ada lagi.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 16, 'Beginilah firman TUHAN: Cegahlah suaramu dari menangis, dan matamu dari mencucurkan air mata, sebab untuk jerih payahmu ada ganjaran, demikianlah firman TUHAN; mereka akan kembali dari negeri musuh.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 17, 'Masih ada harapan untuk hari depanmu, demikianlah firman TUHAN: anak-anak akan kembali ke daerah mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 18, 'Telah Kudengar sungguh-sungguh Efraim meratap: Engkau telah menghajar aku, dan aku telah menerima hajaran, seperti anak lembu yang tidak terlatih. Bawalah aku kembali, supaya aku berbalik, sebab Engkaulah TUHAN, Allahku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 19, 'Sungguh, sesudah aku berbalik, aku menyesal, dan sesudah aku tahu akan diriku, aku menepuk pinggang sebagai tanda berkabung; aku merasa malu dan bernoda, sebab aku menanggung aib masa mudaku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 20, 'Anak kesayangankah gerangan Efraim bagi-Ku atau anak kesukaan? Sebab setiap kali Aku menghardik dia, tak putus-putusnya Aku terkenang kepadanya; sebab itu hati-Ku terharu terhadap dia; tak dapat tidak Aku akan menyayanginya, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 21, 'Dirikanlah bagimu rambu-rambu jalan, pasanglah bagimu tanda-tanda jalan; perhatikanlah jalan raya baik-baik, yakni jalan yang telah kautempuh! Kembalilah, hai anak dara Israel, kembalilah ke kota-kotamu ini!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 22, 'Berapa lama lagi engkau mundur maju, hai anak perempuan yang tidak taat? Sebab TUHAN menciptakan sesuatu yang baru di negeri: perempuan merangkul laki-laki."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 23, 'Beginilah firman TUHAN semesta alam, Allah orang Israel: "Orang akan mengucapkan perkataan ini lagi di tanah Yehuda dan di kota-kotanya, apabila Aku telah memulihkan keadaan mereka: TUHAN kiranya memberkati engkau, hai tempat kediaman kebenaran, hai gunung yang kudus!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 24, 'Di sana akan duduk Yehuda beserta segala kotanya, petani-petani dan orang-orang yang mengembara dengan kawanan ternaknya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 25, 'Sebab Aku akan membuat segar orang yang lelah, dan setiap orang yang merana akan Kubuat puas."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 26, 'Sebab itu aku bangun dan melihat; tidurku menyenangkan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 27, '"Sesungguhnya, waktunya akan datang, demikianlah firman TUHAN, bahwa Aku akan melimpahi kaum Israel dan kaum Yehuda dengan benih manusia dan benih hewan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 28, 'Maka seperti tadinya Aku berjaga-jaga atas mereka untuk mencabut dan merobohkan, untuk meruntuhkan dan membinasakan dan mencelakakan, demikianlah juga Aku akan berjaga-jaga atas mereka untuk membangun dan menanam, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 29, 'Pada waktu itu orang tidak akan berkata lagi: Ayah-ayah makan buah mentah, dan gigi anak-anaknya menjadi ngilu,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 30, 'melainkan: Setiap orang akan mati karena kesalahannya sendiri; setiap manusia yang makan buah mentah, giginya sendiri menjadi ngilu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 31, 'Sesungguhnya, akan datang waktunya, demikianlah firman TUHAN, Aku akan mengadakan perjanjian baru dengan kaum Israel dan kaum Yehuda,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 32, 'bukan seperti perjanjian yang telah Kuadakan dengan nenek moyang mereka pada waktu Aku memegang tangan mereka untuk membawa mereka keluar dari tanah Mesir; perjanjian-Ku itu telah mereka ingkari, meskipun Aku menjadi tuan yang berkuasa atas mereka, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 33, 'Tetapi beginilah perjanjian yang Kuadakan dengan kaum Israel sesudah waktu itu, demikianlah firman TUHAN: Aku akan menaruh Taurat-Ku dalam batin mereka dan menuliskannya dalam hati mereka; maka Aku akan menjadi Allah mereka dan mereka akan menjadi umat-Ku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 34, 'Dan tidak usah lagi orang mengajar sesamanya atau mengajar saudaranya dengan mengatakan: Kenallah TUHAN! Sebab mereka semua, besar kecil, akan mengenal Aku, demikianlah firman TUHAN, sebab Aku akan mengampuni kesalahan mereka dan tidak lagi mengingat dosa mereka."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 35, 'Beginilah firman TUHAN, yang memberi matahari untuk menerangi siang, yang menetapkan bulan dan bintang-bintang untuk menerangi malam, yang mengharu biru laut, sehingga gelombang-gelombangnya ribut, ?TUHAN semesta alam nama-Nya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 36, '"Sesungguhnya, seperti ketetapan-ketetapan ini tidak akan beralih dari hadapan-Ku, demikianlah firman TUHAN, demikianlah keturunan Israel juga tidak akan berhenti menjadi bangsa di hadapan-Ku untuk sepanjang waktu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 37, 'Beginilah firman TUHAN: Sesungguhnya, seperti langit di atas tidak terukur dan dasar-dasar bumi di bawah tidak terselidiki, demikianlah juga Aku tidak akan menolak segala keturunan Israel, karena segala apa yang dilakukan mereka, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 38, 'Sesungguhnya, waktunya akan datang, demikianlah firman TUHAN, bahwa kota itu akan dibangun kembali bagi TUHAN, dari menara Hananeel sampai Pintu Gerbang Sudut;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 39, 'kemudian tali pengukur itu akan merentang terus sampai ke bukit Gareb, lalu membelok ke Goa.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 31, 40, 'Dan segenap lembah itu, dengan mayat-mayat dan abu korbannya, dan segenap tanah di tepi sungai Kidron sampai ke sudut Pintu Gerbang Kuda ke arah timur, akan menjadi kudus bagi TUHAN. Orang tidak akan meruntuhkan dan merobohkan lagi di sana untuk selama-lamanya."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 1, 'Firman yang datang dari TUHAN kepada Yeremia dalam tahun yang kesepuluh pemerintahan Zedekia, raja Yehuda; itulah tahun yang kedelapan belas pemerintahan Nebukadnezar.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 2, 'Pada waktu itu tentara raja Babel mengepung Yerusalem, dan nabi Yeremia ditahan di pelataran penjagaan yang ada di istana raja Yehuda.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 3, 'Sebab Zedekia, raja Yehuda, telah menahan dia di sana dengan tuduhan: "Mengapa engkau bernubuat: Beginilah firman TUHAN: Sesungguhnya, Aku menyerahkan kota ini ke dalam tangan raja Babel, supaya ia mendudukinya;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 4, 'Zedekia, raja Yehuda, tidak akan luput dari tangan orang Kasdim, melainkan pasti akan diserahkan ke dalam tangan raja Babel, sehingga ia berbicara dengan dia mulut sama mulut dan melihat dia mata sama mata;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 5, 'Zedekia akan dibawanya ke Babel dan di sanalah ia akan tinggal, sampai Aku memperhatikannya, demikianlah firman TUHAN. Apabila kamu berperang melawan orang Kasdim itu, kamu tidak akan beruntung!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 6, 'Berkatalah Yeremia: "Firman TUHAN datang kepadaku, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 7, 'Sesungguhnya, Hanameel, anak Salum, pamanmu, akan datang kepadamu dengan usul: Belilah ladangku yang di Anatot itu, sebab engkaulah yang mempunyai hak tebus untuk membelinya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 8, 'Kemudian, sesuai dengan firman TUHAN, datanglah Hanameel, anak pamanku, kepadaku di pelataran penjagaan, dan mengusulkan kepadaku: Belilah ladangku yang di Anatot di daerah Benyamin itu, sebab engkaulah yang mempunyai hak milik dan hak tebus; belilah itu! Maka tahulah aku, bahwa itu adalah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 9, 'Jadi aku membeli ladang yang di Anatot itu dari Hanameel, anak pamanku, dan menimbang uang baginya: tujuh belas syikal perak.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 10, 'Aku menulis surat pembelian, memeteraikannya, memanggil saksi-saksi dan menimbang perak itu dengan neraca.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 11, 'Lalu aku mengambil surat pembelian yang berisi syarat dan ketetapan itu, baik yang dimeteraikan maupun salinannya yang terbuka;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 12, 'kemudian aku memberikan surat pembelian itu kepada Barukh bin Neria bin Mahseya di depan Hanameel, anak pamanku, di depan para saksi yang telah menandatangani surat pembelian itu, dan di depan semua orang Yehuda yang ada di pelataran penjagaan itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 13, 'Di depan mereka aku memerintahkan kepada Barukh, kataku:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 14, 'Beginilah firman TUHAN semesta alam, Allah Israel: Ambillah surat-surat ini, baik surat pembelian yang dimeteraikan itu maupun salinan yang terbuka ini, taruhlah semuanya itu dalam bejana tanah, supaya dapat tahan lama.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 15, 'Sebab beginilah firman TUHAN semesta alam, Allah Israel: Rumah, ladang dan kebun anggur akan dibeli pula di negeri ini!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 16, 'Sesudah kuberikan surat pembelian itu kepada Barukh bin Neria, berdoalah aku kepada TUHAN, kataku:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 17, 'Ah, Tuhan ALLAH! Sesungguhnya, Engkaulah yang telah menjadikan langit dan bumi dengan kekuatan-Mu yang besar dan dengan lengan-Mu yang terentang. Tiada suatu apapun yang mustahil untuk-Mu!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 18, 'Engkaulah yang menunjukkan kasih setia-Mu kepada beribu-ribu orang dan yang membalaskan kesalahan bapa kepada anak-anaknya yang datang kemudian. Ya Allah yang besar dan perkasa, nama-Mu adalah TUHAN semesta alam,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 19, 'besar dalam rancangan-Mu dan agung dalam perbuatan-Mu; mata-Mu terbuka terhadap segala tingkah langkah anak-anak manusia dengan mengganjar setiap orang sesuai dengan tingkah langkahnya dan sesuai dengan buah perbuatannya;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 20, 'Engkau yang memperlihatkan tanda-tanda dan mujizat-mujizat di tanah Mesir, sampai kepada waktu ini kepada Israel dan kepada umat manusia, sehingga Engkau membuat nama bagi-Mu, seperti yang ternyata pada waktu ini.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 21, 'Engkau telah membawa umat-Mu Israel keluar dari tanah Mesir dengan tanda-tanda dan mujizat-mujizat, dengan tangan yang kuat dan lengan yang teracung dan dengan kedahsyatan yang besar.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 22, 'Dan Engkau telah memberikan kepada mereka negeri ini, seperti yang telah Kaujanjikan dengan sumpah kepada nenek moyang mereka untuk memberikannya kepada mereka, suatu negeri yang berlimpah-limpah susu dan madunya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 23, 'Kemudian mereka memasuki dan mendudukinya, tetapi mereka tidak mendengarkan suara-Mu dan tidak berkelakuan menurut Taurat-Mu; mereka tidak melakukan segala apa yang Kauperintahkan kepada mereka untuk dilakukan. Sebab itu Engkau melimpahkan kepada mereka segala malapetaka ini.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 24, 'Sesungguhnya, tembok-tembok pengepungan yang dipakai untuk merebut kota telah sampai mendekatinya; oleh karena pedang, kelaparan dan penyakit sampar maka kota itu telah diserahkan kepada orang-orang Kasdim yang memeranginya. Maka apa yang Kaufirmankan itu telah terjadi; sungguh, Engkau sendiri melihatnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 25, 'Namun Engkau, ya Tuhan ALLAH, telah berfirman kepadaku: Belilah ladang itu dengan perak dan panggillah saksi-saksi! ?padahal kota itu telah diserahkan ke dalam tangan orang-orang Kasdim."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 26, 'Firman TUHAN datang kepada Yeremia, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 27, '"Sesungguhnya, Akulah TUHAN, Allah segala makhluk; adakah sesuatu apapun yang mustahil untuk-Ku?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 28, 'Sebab itu beginilah firman TUHAN: Sesungguhnya, Aku berikan kota ini ke dalam tangan orang-orang Kasdim dan ke dalam tangan Nebukadnezar, raja Babel, dan ia akan merebutnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 29, 'Orang-orang Kasdim yang memerangi kota ini akan datang membakarnya dan menghanguskannya serta dengan rumah-rumah yang di atas sotohnya orang membakar korban kepada Baal dan mempersembahkan korban curahan kepada allah lain untuk menimbulkan sakit hati-Ku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 30, 'Sebab orang Israel dan orang Yehuda hanyalah melakukan yang jahat di mata-Ku sejak masa mudanya; sungguh, orang Israel hanya menimbulkan sakit hati-Ku dengan perbuatan tangan mereka, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 31, 'Ya, kota ini telah membangkitkan murka dan kehangatan amarah-Ku mulai dari hari didirikannya sampai hari ini, sehingga Aku harus menyingkirkannya dari hadapan-Ku,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 32, 'karena segala kejahatan yang dilakukan oleh orang Israel dan orang Yehuda untuk menimbulkan sakit hati-Ku, oleh mereka sendiri, raja-raja mereka, pemuka-pemuka mereka, imam-imam mereka, nabi-nabi mereka, orang Yehuda dan penduduk Yerusalem.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 33, 'Mereka membelakangi Aku dan tidak menghadap kepada-Ku, dan sekalipun Aku mengajar mereka, terus-menerus, tiada mereka mau mendengarkan atau menerima penghajaran.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 34, 'Mereka menempatkan dewa-dewa mereka yang menjijikkan di rumah yang di atasnya nama-Ku diserukan, untuk menajiskannya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 35, 'Mereka mendirikan bukit-bukit pengorbanan untuk Baal di Lembah Ben-Hinom, untuk mempersembahkan anak-anak lelaki dan anak-anak perempuan mereka kepada Molokh sebagai korban dalam api, sekalipun Aku tidak pernah memerintahkannya kepada mereka dan sekalipun hal itu tidak pernah timbul dalam hati-Ku, yakni hal melakukan kejijikan ini, sehingga Yehuda tergelincir ke dalam dosa.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 36, 'Oleh sebab itu, beginilah firman TUHAN, Allah Israel, mengenai kota ini, yang engkau katakan telah diserahkan ke dalam tangan raja Babel karena pedang, kelaparan dan penyakit sampar:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 37, 'Sesungguhnya, Aku mengumpulkan mereka dari segala negeri, ke mana Aku menceraiberaikan mereka karena murka-Ku, kehangatan amarah-Ku dan gusar-Ku yang besar, dan Aku akan mengembalikan mereka ke tempat ini dan akan membuat mereka diam dengan tenteram.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 38, 'Maka mereka akan menjadi umat-Ku dan Aku akan menjadi Allah mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 39, 'Aku akan memberi mereka satu hati dan satu tingkah langkah, sehingga mereka takut kepada-Ku sepanjang masa untuk kebaikan mereka dan anak-anak mereka yang datang kemudian.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 40, 'Aku akan mengikat perjanjian kekal dengan mereka, bahwa Aku tidak akan membelakangi mereka, melainkan akan berbuat baik kepada mereka; Aku akan menaruh takut kepada-Ku ke dalam hati mereka, supaya mereka jangan menjauh dari pada-Ku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 41, 'Aku akan bergirang karena mereka untuk berbuat baik kepada mereka dan Aku akan membuat mereka tumbuh di negeri ini dengan kesetiaan, dengan segenap hati-Ku dan dengan segenap jiwa-Ku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 42, 'Sebab beginilah firman TUHAN: Seperti Aku mendatangkan kepada bangsa ini segenap malapetaka yang hebat ini, demikianlah Aku mendatangkan ke atas mereka keberuntungan yang Kujanjikan kepada mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 43, 'Orang akan membeli ladang lagi di negeri ini yang kamu katakan: Itu adalah tempat tandus tanpa manusia dan hewan; itu telah diserahkan ke dalam tangan orang-orang Kasdim!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 32, 44, 'Orang akan membeli ladang-ladang dengan perak, menulis surat pembelian, memeteraikannya dan memanggil saksi-saksi di daerah Benyamin, di sekitar Yerusalem, di kota-kota Yehuda, di kota-kota Pegunungan, di kota-kota Daerah Bukit dan di kota-kota Tanah Negeb. Sebab Aku akan memulihkan keadaan mereka, demikianlah firman TUHAN."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 1, 'Datanglah firman TUHAN untuk kedua kalinya kepada Yeremia, ketika ia masih terkurung di pelataran penjagaan itu, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 2, '"Beginilah firman TUHAN, yang telah menjadikan bumi dengan membentuknya dan menegakkannya?TUHAN ialah nama-Nya?:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 3, 'Berserulah kepada-Ku, maka Aku akan menjawab engkau dan akan memberitahukan kepadamu hal-hal yang besar dan yang tidak terpahami, yakni hal-hal yang tidak kauketahui.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 4, 'Sebab beginilah firman TUHAN, Allah Israel, mengenai rumah-rumah di kota ini dan mengenai gedung-gedung istana raja Yehuda yang dirobohkan untuk dipakai terhadap tembok-tembok pengepungan dan pedang:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 5, 'Orang akan masuk pertempuran melawan orang-orang Kasdim dan kota ini akan penuh dengan bangkai-bangkai manusia yang telah Kupukul mati karena murka-Ku dan kehangatan amarah-Ku, sebab Aku telah menyembunyikan wajah-Ku dari kota ini oleh karena segala kejahatan mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 6, 'Sesungguhnya, Aku akan mendatangkan kepada mereka kesehatan dan kesembuhan, dan Aku akan menyembuhkan mereka dan akan menyingkapkan kepada mereka kesejahteraan dan keamanan yang berlimpah-limpah.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 7, 'Aku akan memulihkan keadaan Yehuda dan Israel dan akan membangun mereka seperti dahulu:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 8, 'Aku akan mentahirkan mereka dari segala kesalahan yang mereka lakukan dengan berdosa terhadap Aku, dan Aku akan mengampuni segala kesalahan yang mereka lakukan dengan berdosa dan dengan memberontak terhadap Aku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 9, 'Dan kota ini akan menjadi pokok kegirangan: ternama, terpuji dan terhormat bagi-Ku di depan segala bangsa di bumi yang telah mendengar tentang segala kebajikan yang Kulakukan kepadanya; mereka akan terkejut dan gemetar karena segala kebajikan dan segala kesejahteraan yang Kulakukan kepadanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 10, 'Beginilah firman TUHAN: Di tempat ini, yang kamu katakan telah menjadi reruntuhan tanpa manusia dan tanpa hewan, di kota-kota Yehuda dan di jalan-jalan Yerusalem yang sunyi sepi itu tanpa manusia, tanpa penduduk dan tanpa hewan,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 11, 'akan terdengar lagi suara kegirangan dan suara sukacita, suara pengantin laki-laki dan suara pengantin perempuan, suara orang-orang yang mengatakan: Bersyukurlah kepada TUHAN semesta alam, sebab TUHAN itu baik, bahwasanya untuk selama-lamanya kasih setia-Nya!, sambil mempersembahkan korban syukur di rumah TUHAN. Sebab Aku akan memulihkan keadaan negeri ini seperti dahulu, firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 12, 'Beginilah firman TUHAN semesta alam: Di daerah ini, yang sudah menjadi reruntuhan, tanpa manusia dan tanpa hewan, dan di segala kotanya akan ada lagi padang rumput bagi gembala-gembala yang membaringkan kambing domba di situ.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 13, 'Di kota-kota Pegunungan, di kota-kota Daerah Bukit, di kota-kota Tanah Negeb, di daerah Benyamin, di sekitar Yerusalem dan di kota-kota Yehuda, kambing domba akan lewat lagi dari bawah tangan orang yang menghitungnya, demikianlah firman TUHAN."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 14, '"Sesungguhnya, waktunya akan datang, demikianlah firman TUHAN, bahwa Aku akan menepati janji yang telah Kukatakan kepada kaum Israel dan kaum Yehuda.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 15, 'Pada waktu itu dan pada masa itu Aku akan menumbuhkan Tunas keadilan bagi Daud. Ia akan melaksanakan keadilan dan kebenaran di negeri.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 16, 'Pada waktu itu Yehuda akan dibebaskan, dan Yerusalem akan hidup dengan tenteram. Dan dengan nama inilah mereka akan dipanggil: TUHAN keadilan kita!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 17, 'Sebab beginilah firman TUHAN: Keturunan Daud tidak akan terputus duduk di atas takhta kerajaan kaum Israel!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 18, 'Dan keturunan imam-imam orang Lewi tidak akan terputus mempersembahkan korban bakaran di hadapan-Ku dan membakar korban sajian dan mengorbankan korban sembelihan sepanjang masa."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 19, 'Firman TUHAN datang kepada Yeremia, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 20, '"Beginilah firman TUHAN: Jika kamu dapat mengingkari perjanjian-Ku dengan siang dan perjanjian-Ku dengan malam, sehingga siang dan malam tidak datang lagi pada waktunya,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 21, 'maka juga perjanjian-Ku dengan hamba-Ku Daud dapat diingkari, sehingga ia tidak mempunyai anak lagi yang memerintah di atas takhtanya; begitu juga perjanjian-Ku dengan orang-orang Lewi, yakni imam-imam yang menjadi pelayan-Ku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 22, 'Seperti tentara langit tidak terbilang dan seperti pasir laut tidak tertakar, demikianlah Aku akan membuat banyak keturunan hamba-Ku Daud dan orang-orang Lewi yang melayani Aku."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 23, 'Firman TUHAN datang kepada Yeremia, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 24, '"Tidakkah kauperhatikan apa yang dikatakan orang-orang ini: Kedua kaum keluarga yang dipilih TUHAN itu telah ditolak-Nya? Dengan demikian mereka menghina umat-Ku, dianggapnya bukan suatu bangsa lagi.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 25, 'Beginilah firman TUHAN: Jika Aku tidak menetapkan perjanjian-Ku dengan siang dan malam dan aturan langit dan bumi,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 33, 26, 'maka juga Aku pasti akan menolak keturunan Yakub dan hamba-Ku Daud, sehingga berhenti mengangkat dari keturunannya orang-orang yang memerintah atas keturunan Abraham, Ishak dan Yakub. Sebab Aku akan memulihkan keadaan mereka dan menyayangi mereka."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 34, 1, 'Firman yang datang dari TUHAN kepada Yeremia, ketika Nebukadnezar, raja Babel, dan segala tentaranya, segala kerajaan di bumi yang dibawah pemerintahannya, dan segala bangsa berperang melawan Yerusalem dan segala kotanya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 34, 2, '"Beginilah firman TUHAN, Allah Israel: Pergilah berbicara kepada Zedekia, raja Yehuda, katakan kepadanya: Beginilah firman TUHAN: Sesungguhnya, Aku menyerahkan kota ini ke dalam tangan raja Babel, supaya dihanguskannya dengan api.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 34, 3, 'Dan engkau sendiri tidak akan luput dari tangannya, melainkan akan pasti tertangkap dan diserahkan ke dalam tangannya; engkau akan melihat raja Babel mata berhadapan mata dan ia akan berbicara dengan engkau mulut berhadapan mulut. Kemudian engkau akan pergi ke Babel.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 34, 4, 'Namun demikian, dengarlah firman TUHAN, hai Zedekia, raja Yehuda, beginilah firman TUHAN mengenai engkau: engkau tidak akan mati oleh pedang!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 34, 5, 'Engkau akan mati dengan damai. Dan sebagaimana dinyalakan api untuk menghormati bapa-bapa leluhurmu, raja-raja dahulu, yang hidup sebelum engkau, demikianlah orang akan menyalakan api untuk menghormati engkau, dan akan meratapi engkau dengan berkata: Aduhai, tuan! Sungguh, Akulah yang mengucapkan firman ini, demikianlah firman TUHAN."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 34, 6, 'Nabi Yeremia menyampaikan segala perkataan ini kepada Zedekia, raja Yehuda, di Yerusalem,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 34, 7, 'ketika tentara raja Babel berperang melawan Yerusalem dan segala kota Yehuda yang masih tinggal, yaitu Lakhis dan Aseka, sebab kota-kota itulah yang masih tinggal di antara kota-kota Yehuda sebagai kota-kota yang berkubu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 34, 8, 'Firman yang datang dari TUHAN kepada Yeremia, sesudah raja Zedekia mengikat perjanjian dengan segenap rakyat yang ada di Yerusalem untuk memaklumkan pembebasan,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 34, 9, 'supaya setiap orang melepaskan budaknya bangsa Ibrani, baik laki-laki maupun perempuan, sebagai orang merdeka, sehingga tidak ada seorangpun lagi yang memperbudak seorang Yehuda, saudaranya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 34, 10, 'Maka semua pemuka dan segenap rakyat yang ikut serta dalam perjanjian itu menyetujui, bahwa setiap orang akan melepaskan budaknya laki-laki dan budaknya perempuan sebagai orang merdeka, sehingga tidak ada lagi yang memperbudak mereka. Orang-orang itu menyetujuinya, lalu melepaskan mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 34, 11, 'Tetapi sesudah itu mereka berbalik pikiran, lalu mengambil kembali budak-budak lelaki dan perempuan yang telah mereka lepaskan sebagai orang merdeka itu dan menundukkan mereka menjadi budak laki-laki dan budak perempuan lagi.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 34, 12, 'Lalu datanglah firman TUHAN kepada Yeremia, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 34, 13, '"Beginilah firman TUHAN, Allah Israel: Aku sendiri telah mengikat perjanjian dengan nenek moyangmu pada waktu Aku membawa mereka keluar dari tanah Mesir, dari tempat perbudakan, isinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 34, 14, 'Pada akhir tujuh tahun haruslah kamu masing-masing melepaskan saudaranya bangsa Ibrani yang sudah menjual dirinya kepadamu; ia akan bekerja padamu enam tahun lamanya, kemudian haruslah engkau melepaskan dia sebagai orang merdeka. Tetapi nenek moyangmu tidak mendengarkan Aku dan tidak memperhatikan Aku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 34, 15, 'Hari ini kamu telah bertobat dan melakukan apa yang benar di mata-Ku karena setiap orang memaklumkan pembebasan kepada saudaranya, dan kamu telah mengikat perjanjian di hadapan-Ku di rumah yang atasnya nama-Ku diserukan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 34, 16, 'Tetapi kamu telah berbalik pikiran dan telah menajiskan nama-Ku; kamu masing-masing telah mengambil kembali budaknya laki-laki dan budaknya perempuan, yang telah kamu lepaskan sebagai orang merdeka menurut keinginannya, dan telah menundukkan mereka, supaya mereka menjadi budakmu laki-laki dan budakmu perempuan lagi.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 34, 17, 'Sebab itu beginilah firman TUHAN: Kamu ini tidak mendengarkan Aku agar setiap orang memaklumkan pembebasan kepada sesamanya dan kepada saudaranya, maka sesungguhnya, Aku memaklumkan bagimu pembebasan, demikianlah firman TUHAN, untuk diserahkan kepada pedang, penyakit sampar dan kelaparan. Aku akan membuat kamu menjadi kengerian bagi segala kerajaan di bumi.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 34, 18, 'Dan Aku akan menyerahkan orang-orang, yang melanggar perjanjian-Ku dan yang tidak menepati isi perjanjian yang mereka ikat di hadapan-Ku, dengan memotong anak lembu jantan menjadi dua untuk berjalan di antara belahan-belahannya;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 34, 19, 'pemuka-pemuka Yehuda, pemuka-pemuka Yerusalem, pegawai-pegawai istana, imam-imam dan segenap rakyat negeri yang telah berjalan di antara belahan-belahan anak lembu jantan itu,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 34, 20, 'mereka akan Kuserahkan ke dalam tangan musuh mereka dan ke dalam tangan orang-orang yang berusaha mencabut nyawa mereka, sehingga mayat mereka menjadi makanan burung-burung di udara dan binatang-binatang di bumi.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 34, 21, 'Juga Zedekia, raja Yehuda, beserta para pemukanya akan Kuserahkan ke dalam tangan musuh mereka dan ke dalam tangan orang-orang yang berusaha mencabut nyawa mereka dan ke dalam tangan tentara raja Babel yang sekarang telah berangkat dari pada kamu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 34, 22, 'Sesungguhnya, demikianlah firman TUHAN, Aku memberi perintah dan membawa mereka kembali ke kota ini untuk memeranginya, merebutnya dan menghanguskannya dengan api. Aku akan membuat kota-kota Yehuda menjadi ketandusan tanpa penduduk."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 35, 1, 'Firman yang datang dari TUHAN kepada Yeremia di zaman Yoyakim bin Yosia, raja Yehuda, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 35, 2, '"Pergilah kepada kaum orang Rekhab, bicaralah dengan mereka dan bawalah mereka ke rumah TUHAN, ke dalam salah satu kamar, kemudian berilah mereka minum anggur!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 35, 3, 'Maka aku menjemput Yaazanya bin Yeremia bin Habazinya beserta saudara-saudaranya dan semua anaknya, pendeknya segenap kaum orang Rekhab.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 35, 4, 'Aku membawa mereka ke rumah TUHAN, ke dalam kamar anak-anak Hanan bin Yigdalya, abdi Allah; itulah kamar yang di sebelah kamar para pembesar, di atas kamar Maaseya bin Salum, penjaga pintu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 35, 5, 'Di depan anggota-anggota kaum orang Rekhab itu aku meletakkan piala-piala penuh anggur dan cawan-cawan, lalu aku berkata kepada mereka: "Silakan minum anggur!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 35, 6, 'Tetapi mereka menjawab: "Kami tidak minum anggur, sebab Yonadab bin Rekhab, bapa leluhur kami, telah memberi perintah kepada kami, katanya: Janganlah kamu atau anak-anakmupun minum anggur sampai selama-lamanya;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 35, 7, 'janganlah kamu mendirikan rumah, janganlah kamu menabur benih; janganlah kamu membuat atau mempunyai kebun anggur, melainkan haruslah kamu diam di kemah-kemah selama hidupmu, supaya lama kamu hidup di tanah, di mana kamu tinggal sebagai orang asing!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 35, 8, 'Kami mentaati suara Yonadab bin Rekhab, bapa leluhur kami dalam segala apa yang diperintahkannya kepada kami, agar kami tidak minum anggur selama hidup kami, yakni kami sendiri, isteri kami, anak-anak lelaki dan anak-anak perempuan kami;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 35, 9, 'agar kami tidak mendirikan rumah-rumah untuk kami diami, tidak mempunyai kebun anggur atau ladang serta benih,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 35, 10, 'melainkan kami diam di kemah-kemah dan taat melakukan tepat seperti yang diperintahkan kepada kami oleh Yonadab, bapa leluhur kami.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 35, 11, 'Tetapi ketika Nebukadnezar, raja Babel, bergerak maju melawan negeri ini, maka kami berkata: Marilah kita mengungsi ke Yerusalem, karena tentara orang Kasdim dan tentara orang Aram itu! Demikianlah kami diam di Yerusalem."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 35, 12, 'Pada waktu itu datanglah firman TUHAN kepada Yeremia, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 35, 13, '"Beginilah firman TUHAN semesta alam, Allah Israel: Pergilah dan katakanlah kepada orang Yehuda dan kepada penduduk Yerusalem: Tidakkah kamu mau menerima penghajaran, yaitu mendengarkan perkataan-perkataan-', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 35, 14, 'Memang perintah Yonadab bin Rekhab itu masih ditepati; ia telah memerintahkan kepada keturunannya, supaya mereka jangan minum anggur, dan sampai sekarang ini mereka tidak meminumnya, sebab mereka mendengarkan perintah bapa leluhur mereka. Aku sendiri telah berbicara kepada kamu, terus-menerus, tetapi kamu tidak mendengarkan Aku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 35, 15, 'Aku telah mengutus kepadamu segala hamba-Ku, yakni para nabi, terus-menerus, mengatakan: Kembalilah kamu masing-masing dari tingkah langkahmu yang jahat itu, perbaikilah perbuatanmu, janganlah mengikuti allah lain untuk beribadah kepada mereka, maka kamu akan tetap diam di tanah yang telah Kuberikan kepadamu dan kepada nenek moyangmu. Tetapi kamu tidak mau memperhatikannya dan kamu tidak mau mendengarkan Aku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 35, 16, 'Sungguh, keturunan Yonadab bin Rekhab menepati perintah yang diberikan bapa leluhurnya kepada mereka, tetapi bangsa ini tidak mau mendengarkan Aku!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 35, 17, 'Sebab itu beginilah firman TUHAN, Allah semesta alam, Allah Israel: Sesungguhnya, Aku mendatangkan kepada Yehuda dan kepada segenap penduduk Yerusalem segala malapetaka yang Kuancamkan atas mereka; karena Aku telah berbicara kepada mereka, tetapi mereka tidak mau mendengarkan, dan Aku telah berseru kepada mereka, tetapi mereka tidak mau menjawab."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 35, 18, 'Tetapi berkatalah Yeremia kepada kaum orang Rekhab: "Beginilah firman TUHAN semesta alam, Allah Israel: Oleh karena kamu telah mendengarkan perintah Yonadab, bapa leluhurmu, telah berpegang pada segala perintahnya dan telah melakukan tepat seperti yang diperintahkannya kepadamu,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 35, 19, 'maka beginilah firman TUHAN semesta alam, Allah Israel: Keturunan Yonadab bin Rekhab takkan terputus melayani Aku sepanjang masa."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 1, 'Dalam tahun yang keempat pemerintahan Yoyakim bin Yosia, raja Yehuda, datanglah firman ini dari TUHAN kepada Yeremia, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 2, '"Ambillah kitab gulungan dan tulislah di dalamnya segala perkataan yang telah Kufirmankan kepadamu mengenai Israel, Yehuda dan segala bangsa, dari sejak Aku berbicara kepadamu, yakni dari sejak zaman Yosia, sampai waktu ini.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 3, 'Mungkin apabila kaum Yehuda mendengar tentang segala malapetaka yang Aku rancangkan hendak mendatangkannya kepada mereka, maka mereka masing-masing akan bertobat dari tingkah langkahnya yang jahat itu, sehingga Aku mengampuni kesalahan dan dosa mereka."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 4, 'Jadi Yeremia memanggil Barukh bin Neria, lalu Barukh menuliskan dalam kitab gulungan itu langsung dari mulut Yeremia segala perkataan yang telah difirmankan TUHAN kepadanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 5, 'Pada suatu kali Yeremia memberi perintah kepada Barukh: "Aku ini berhalangan, tidak dapat pergi ke rumah TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 6, 'Jadi pada hari puasa engkaulah yang pergi membacakan perkataan-perkataan TUHAN kepada orang banyak di rumah TUHAN dari gulungan yang kautuliskan langsung dari mulutku itu; kepada segenap orang Yehuda yang datang dari kota-kotanya haruslah kaubacakannya juga.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 7, 'Mungkin permohonan mereka sampai di hadapan TUHAN dan mereka masing-masing bertobat dari tingkah langkahnya yang jahat itu, sebab besar murka dan kehangatan amarah yang diancamkan TUHAN kepada bangsa ini."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 8, 'Lalu Barukh bin Neria melakukan tepat seperti yang diperintahkan kepadanya oleh nabi Yeremia untuk membacakan perkataan-perkataan TUHAN dari kitab itu di rumah TUHAN. ?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 9, 'Adapun dalam tahun yang kelima pemerintahan Yoyakim bin Yosia, raja Yehuda, dalam bulan yang kesembilan, orang telah memaklumkan puasa di hadapan TUHAN bagi segenap rakyat di Yerusalem dan bagi segenap rakyat yang telah datang dari kota-kota Yehuda ke Yerusalem. ?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 10, 'Maka Barukh membacakan kepada segenap rakyat perkataan Yeremia dari kitab itu, di rumah TUHAN, di kamar Gemarya anak panitera Safan, di pelataran atas di muka pintu gerbang baru dari rumah TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 11, 'Ketika Mikhaya bin Gemarya bin Safan mendengar segala firman TUHAN dari kitab itu,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 12, 'turunlah ia ke istana raja, ke kamar panitera. Di sana tampak duduk semua pemuka, yakni panitera Elisama, Delaya bin Semaya, Elnatan bin Akhbor, Gemarya bin Safan, Zedekia bin Hananya dan semua pemuka lain.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 13, 'Lalu Mikhaya memberitahukan kepada mereka segala firman yang telah didengarnya, ketika Barukh membacakan kitab itu kepada orang banyak.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 14, 'Kemudian para pemimpin itu menyuruh Yehudi bin Netanya bin Selemya bin Kusyi kepada Barukh mengatakan: "Bawalah gulungan yang telah kaubacakan kepada orang banyak itu dan datanglah ke mari!" Maka Barukh bin Neria membawa gulungan itu dan datang kepada mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 15, 'Berkatalah mereka kepadanya: "Silakan duduk dan bacakan itu kepada kami!" Lalu Barukh membacakannya kepada mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 16, 'Setelah mereka mendengar segala perkataan itu, maka terkejutlah mereka dan berkata seorang kepada yang lain: "Kita harus dengan segera memberitahukan segala perkataan ini kepada raja!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 17, 'Bertanyalah mereka kepada Barukh, katanya: "Beritahukanlah kepada kami, bagaimana caranya engkau menuliskan segala perkataan ini!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 18, 'Jawab Barukh kepada mereka: "Segala perkataan ini langsung dari mulut Yeremia kepadaku, dan aku menuliskannya dengan tinta dalam kitab."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 19, 'Lalu berkatalah para pemuka itu kepada Barukh: "Pergilah, sembunyikanlah dirimu bersama Yeremia! Janganlah ada orang yang mengetahui di mana tempatmu!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 20, 'Kemudian pergilah mereka menghadap raja di pelataran, sesudah mereka menyimpan gulungan itu di kamar panitera Elisama. Mereka memberitahukan segala perkataan ini kepada raja.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 21, 'Raja menyuruh Yehudi mengambil gulungan itu, lalu ia mengambilnya dari kamar panitera Elisama itu. Yehudi membacakannya kepada raja dan semua pemuka yang berdiri dekat raja.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 22, 'Waktu itu adalah bulan yang kesembilan dan raja sedang duduk di balai musim dingin, sementara di depannya api menyala di perapian.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 23, 'Setiap kali apabila Yehudi selesai membacakan tiga empat lajur, maka raja mengoyak-ngoyaknya dengan pisau raut, lalu dilemparkan ke dalam api yang di perapian itu, sampai seluruh gulungan itu habis dimakan api yang di perapian itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 24, 'Baik raja maupun para pegawainya, yang mendengarkan segala perkataan ini, seorangpun tidak terkejut dan tidak mengoyakkan pakaiannya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 25, 'Elnatan, Delaya dan Gemarya memang mendesak kepada raja, supaya jangan membakar gulungan itu, tetapi raja tidak mendengarkan mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 26, 'Bahkan raja memerintahkan pangeran Yerahmeel, Seraya bin Azriel dan Selemya bin Abdeel untuk menangkap juru tulis Barukh dan nabi Yeremia, tetapi TUHAN menyembunyikan mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 27, 'Sesudah raja membakar gulungan berisi perkataan-perkataan yang dituliskan oleh Barukh langsung dari mulut Yeremia itu, maka datanglah firman TUHAN kepada Yeremia, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 28, '"Ambil pulalah gulungan lain, tuliskanlah di dalamnya segala perkataan yang semula ada di dalam gulungan yang pertama yang dibakar oleh Yoyakim, raja Yehuda.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 29, 'Mengenai Yoyakim, raja Yehuda, haruslah kaukatakan: Beginilah firman TUHAN: Engkau telah membakar gulungan ini dengan berkata: Mengapakah engkau menulis di dalamnya, bahwa raja Babel pasti akan datang untuk memusnahkan negeri ini dan untuk melenyapkan dari dalamnya manusia dan hewan?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 30, 'Sebab itu beginilah firman TUHAN tentang Yoyakim, raja Yehuda: Ia tidak akan mempunyai keturunan yang akan duduk di atas takhta Daud, dan mayatnya akan tercampak, sehingga kena panas di waktu siang dan kena dingin di waktu malam.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 31, 'Aku akan menghukum dia, keturunannya dan hamba-hambanya karena kesalahan mereka; Aku akan mendatangkan atas mereka, atas segala penduduk Yerusalem dan atas orang Yehuda segenap malapetaka yang Kuancamkan kepada mereka, yang mereka tidak mau mendengarnya."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 36, 32, 'Maka Yeremia mengambil gulungan lain dan memberikannya kepada juru tulis Barukh bin Neria yang menuliskan di dalamnya langsung dari mulut Yeremia segala perkataan yang ada di dalam kitab yang telah dibakar Yoyakim, raja Yehuda dalam api itu. Lagipula masih ditambahi dengan banyak perkataan seperti itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 37, 1, 'Zedekia bin Yosia menjadi raja menggantikan Konya bin Yoyakim; Nebukadnezar, raja Babel, telah mengangkat dia menjadi raja atas negeri Yehuda.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 37, 2, 'Tetapi baik ia, baik pegawai-pegawainya maupun rakyat negeri itu, tidak mendengarkan firman yang disampaikan TUHAN dengan perantaraan nabi Yeremia.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 37, 3, 'Pada suatu kali raja Zedekia menyuruh Yukhal bin Selemya dan imam Zefanya bin Maaseya kepada Yeremia untuk meminta: "Berdoalah hendaknya untuk kami kepada TUHAN, Allah kita!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 37, 4, 'Adapun pada waktu itu Yeremia masih bebas pergi datang di tengah-tengah rakyat; ia belum dimasukkan orang ke dalam penjara.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 37, 5, 'Adapun tentara Firaun telah berangkat keluar dari Mesir; mendengar kabar itu maka orang-orang Kasdim yang mengepung Yerusalem angkat kaki dari Yerusalem.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 37, 6, 'Lalu datanglah firman TUHAN kepada nabi Yeremia, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 37, 7, '"Beginilah firman TUHAN, Allah Israel. Kepada raja Yehuda, yang menyuruh kamu kepada-Ku untuk meminta petunjuk, harus kamu katakan begini: Lihat, tentara Firaun yang telah berangkat keluar untuk membantu kamu akan kembali ke negerinya, ke Mesir.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 37, 8, 'Tetapi orang-orang Kasdim akan datang kembali memerangi kota ini, merebutnya dan menghanguskannya dengan api.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 37, 9, 'Beginilah firman TUHAN: Janganlah kamu membohongi dirimu sendiri dengan mengatakan: Orang-orang Kasdim itu telah pergi untuk selamanya dari pada kita! Padahal mereka tidak pergi untuk selamanya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 37, 10, 'Dan seandainya kamu memukul kalah segenap tentara orang Kasdim yang telah memerangi kamu itu, sehingga di antara mereka hanya tinggal orang-orang yang luka parah, masing-masing di kemahnya mereka akan bangun dan menghanguskan kota ini dengan api."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 37, 11, 'Ketika tentara orang Kasdim itu telah angkat kaki dari Yerusalem oleh karena takut kepada tentara Firaun,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 37, 12, 'maka keluarlah Yeremia dari Yerusalem untuk pergi ke daerah Benyamin dengan maksud mengurus di sana pembagian warisan di antara kaum keluarga.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 37, 13, 'Tetapi ketika ia sampai ke pintu gerbang Benyamin, maka di sana ada seorang kepala jaga yang bernama Yeria bin Selemya bin Hananya; ia menangkap nabi Yeremia sambil berteriak: "Engkau mau menyeberang kepada orang Kasdim!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 37, 14, 'Dan sekalipun Yeremia menjawab: "Itu bohong, aku tidak hendak menyeberang kepada orang Kasdim!", tetapi Yeria tidak mendengarkan, lalu ia menangkap Yeremia dan membawanya menghadap para pemuka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 37, 15, 'Para pemuka ini menjadi marah kepada Yeremia; mereka memukul dia dan memasukkannya ke dalam rumah tahanan, rumah panitera Yonatan itu; adapun rumah itu telah dibuat mereka menjadi penjara.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 37, 16, 'Demikianlah halnya Yeremia masuk ke dalam ruang cadangan air di bawah tanah itu. Dan lama Yeremia tinggal di sana.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 37, 17, 'Pada suatu kali raja Zedekia menyuruh orang mengambil dia. Lalu dengan diam-diam bertanyalah raja di istananya kepadanya: "Adakah datang firman dari TUHAN?" Jawab Yeremia: "Ada!" Lagi katanya: "Bunyinya: Engkau akan diserahkan ke dalam tangan raja Babel!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 37, 18, 'Kemudian berkatalah Yeremia kepada raja Zedekia: "Apakah dosa yang kuperbuat kepadamu, kepada pegawai-pegawaimu dan kepada bangsa ini, sehingga kamu memasukkan aku ke dalam penjara?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 37, 19, 'Di manakah gerangan para nabimu yang telah bernubuat kepadamu, bahwa raja Babel tidak akan datang menyerang kamu dan negeri ini?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 37, 20, 'Sekarang, dengarkanlah, hai tuanku raja! Biarlah permohonanku sampai di hadapanmu: janganlah kembalikan aku ke rumah panitera Yonatan, nanti aku mati di sana."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 37, 21, 'Raja Zedekia memberi perintah, lalu orang menahan Yeremia di pelataran penjagaan dan memberikan setiap hari kepadanya sepotong roti dari jalan tukang roti, sampai pada waktu segala roti habis di kota itu. Demikianlah Yeremia tinggal di pelataran penjagaan itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 1, 'Tetapi Sefaca bin Matan, Gedalya bin Pasyhur, Yukhal bin Selemya dan Pasyhur bin Malkia mendengar perkataan yang tidak henti-henti diucapkan oleh Yeremia kepada segenap orang banyak itu:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 2, '"Beginilah firman TUHAN: Siapa yang tinggal di kota ini akan mati karena pedang, karena kelaparan dan karena penyakit sampar; tetapi siapa yang keluar dari sini mendapatkan orang Kasdim, ia akan tetap hidup; nyawanya akan menjadi jarahan baginya dan ia tetap hidup.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 3, 'Beginilah firman TUHAN: Kota ini akan pasti diserahkan ke dalam tangan tentara raja Babel yang akan merebutnya."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 4, 'Maka berkatalah para pemuka itu kepada raja: "Baiklah orang ini dihukum mati! Sebab sebenarnya dengan mengatakan hal-hal seperti itu maka ia melemahkan semangat prajurit-prajurit yang masih tinggal di kota ini dan semangat segenap rakyat. Sungguh, orang ini tidak mengusahakan kesejahteraan untuk bangsa ini, melainkan kemalangan."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 5, 'Raja Zedekia menjawab: "Baiklah, ia ada dalam kuasamu! Sebab raja tidak dapat berbuat apa-apa menentang kamu!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 6, 'Maka mereka mengambil Yeremia dan memasukkannya ke dalam perigi milik pangeran Malkia yang ada di pelataran penjagaan itu; mereka menurunkan Yeremia dengan tali. Di perigi itu tidak ada air, hanya lumpur, lalu terperosoklah Yeremia ke dalam lumpur itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 7, 'Tetapi ketika didengar Ebed-Melekh, orang Etiopia itu?ia seorang sida-sida yang tinggal di istana raja?bahwa Yeremia telah dimasukkan ke dalam perigi?pada waktu itu raja sedang duduk di pintu gerbang Benyamin?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 8, 'maka keluarlah Ebed-Melekh dari istana raja itu, lalu berkata kepada raja:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 9, '"Ya tuanku raja, perbuatan orang-orang ini jahat dalam segala apa yang mereka lakukan terhadap nabi Yeremia, yakni memasukkan dia ke dalam perigi; ia akan mati kelaparan di tempat itu! Sebab tidak ada lagi roti di kota."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 10, 'Lalu raja memberi perintah kepada Ebed-Melekh, orang Etiopia itu, katanya: "Bawalah tiga orang dari sini dan angkatlah nabi Yeremia dari perigi itu sebelum ia mati!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 11, 'Ebed-Melekh membawa orang-orang itu dan masuk ke istana raja, ke gudang pakaian di tempat perbendaharaan; dari sana ia mengambil pakaian yang buruk-buruk dan pakaian yang robek-robek, lalu menurunkannya dengan tali kepada Yeremia di perigi itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 12, 'Berserulah Ebed-Melekh, orang Etiopia itu, kepada Yeremia: "Taruhlah pakaian yang buruk-buruk dan robek-robek itu di bawah ketiakmu sebagai ganjal tali!" Yeremiapun berbuat demikian.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 13, 'Kemudian mereka menarik dan mengangkat Yeremia dengan tali dari perigi itu. Demikianlah Yeremia tinggal di pelataran penjagaan itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 14, 'Raja Zedekia menyuruh orang membawa nabi Yeremia kepadanya di pintu yang ketiga pada rumah TUHAN. Berkatalah raja kepada Yeremia: "Aku mau menanyakan sesuatu kepadamu; janganlah sembunyikan apa-apa kepadaku!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 15, 'Jawab Yeremia kepada Zedekia: "Apabila aku memberitahukannya kepadamu, tentulah engkau akan membunuh aku, bukan? Dan apabila aku memberi nasihat kepadamu, engkau tidak juga akan mendengarkan aku!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 16, 'Lalu bersumpahlah raja Zedekia dengan diam-diam kepada Yeremia, katanya: "Demi TUHAN yang hidup yang telah memberi nyawa ini kepada kita, aku tidak akan membunuh engkau dan tidak akan menyerahkan engkau ke dalam tangan orang-orang yang berusaha mencabut nyawamu itu!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 17, 'Sesudah itu berkatalah Yeremia kepada Zedekia: "Beginilah firman TUHAN, Allah semesta alam, Allah Israel: Jika engkau keluar menyerahkan diri kepada para perwira raja Babel, maka nyawamu akan terpelihara, dan kota ini tidak akan dihanguskan dengan api; engkau dengan keluargamu akan hidup.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 18, 'Tetapi jika engkau tidak menyerahkan diri kepada para perwira raja Babel, maka kota ini akan diserahkan ke dalam tangan orang-orang Kasdim yang akan menghanguskannya dengan api; dan engkau sendiri tidak akan luput dari tangan mereka."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 19, 'Kemudian berkatalah raja Zedekia kepada Yeremia: "Aku takut kepada orang-orang Yehuda yang menyeberang kepada orang Kasdim itu; nanti aku diserahkan ke dalam tangan mereka, sehingga mereka mempermainkan aku."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 20, 'Yeremia menjawab: "Hal itu tidak akan terjadi! Dengarkanlah suara TUHAN dalam hal apa yang kukatakan kepadamu, maka keadaanmu akan baik dan nyawamu akan terpelihara.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 21, 'Tetapi jika engkau enggan menyerahkan diri, maka inilah firman yang dinyatakan TUHAN kepadaku:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 22, 'Sungguh, semua perempuan yang masih tinggal di istana raja Yehuda digiring ke luar ke hadapan para perwira raja Babel sambil berseru: Engkau diperdayakan, dikalahkan oleh sahabat-sahabatmu. Tetapi baru saja kakimu terperosok ke dalam lumpur, mereka sudah berpaling pulang.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 23, 'Semua isterimu dan anak-anakmu akan digiring ke luar ke hadapan orang-orang Kasdim itu. Dan engkau sendiri tidak akan terluput dari tangan mereka, tetapi engkau akan tertangkap oleh raja Babel. Dan kota ini akan dihanguskan dengan api."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 24, 'Lalu berkatalah Zedekia kepada Yeremia: "Janganlah ada orang yang mengetahui tentang pembicaraan ini, supaya engkau jangan mati.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 25, 'Apabila para pemuka mendengar, bahwa aku telah berbicara dengan engkau, lalu mereka datang meminta kepadamu: Beritahukanlah kepada kami apa yang telah kaukatakan kepada raja dan apa yang telah dikatakan raja kepadamu; janganlah sembunyikan kepada kami, supaya engkau jangan kami bunuh!,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 26, 'maka haruslah kaukatakan kepada mereka: Aku menyampaikan permohonanku ke hadapan raja, supaya aku jangan dikembalikannya ke rumah Yonatan untuk mati di sana."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 27, 'Memang semua pemuka itu datang bertanya kepada Yeremia, tetapi ia memberi jawab kepada mereka tepat seperti segala yang diperintahkan raja. Maka mereka membiarkan dia, sebab sesuatupun dari pembicaraan itu tidak ada yang diketahui siapapun.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 38, 28, 'Demikianlah Yeremia tinggal di pelataran penjagaan itu sampai kepada hari Yerusalem direbut.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 39, 1, 'Ketika Yerusalem direbut?dalam tahun yang kesembilan pemerintahan Zedekia, raja Yehuda, dalam bulan yang kesepuluh, telah datang Nebukadnezar, raja Babel, beserta segenap tentaranya untuk mengepung Yerusalem;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 39, 2, 'dalam tahun yang kesebelas pemerintahan Zedekia, dalam bulan yang keempat, pada tanggal sembilan bulan itu, terbelahlah tembok kota itu?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 39, 3, 'maka datanglah para perwira raja Babel itu, lalu mengambil tempat di pintu gerbang tengah, mereka itu ialah Nergal-Sarezer, pembesar dari Sin-Magir, panglima, dan Nebusyazban, kepala istana, dan para perwira lainnya dari raja Babel.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 39, 4, 'Melihat mereka semuanya maka Zedekia, raja Yehuda, dengan semua tentara melarikan diri, meninggalkan kota itu pada waktu malam dengan mengambil jalan taman raja, dengan melalui pintu gerbang antara kedua tembok; kemudian mereka berjalan menuju Araba-Yordan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 39, 5, 'Tetapi tentara Kasdim itu mengejar mereka dan menyusul Zedekia di dataran Yerikho; mereka menangkap dia dan membawa dia ke Ribla di tanah Hamat, kepada Nebukadnezar, raja Babel, yang menjatuhkan hukuman atas dia.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 39, 6, 'Raja Babel menyuruh menyembelih anak-anak Zedekia di depan matanya di Ribla; juga semua pembesar Yehuda disembelih oleh raja Babel.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 39, 7, 'Kemudian mata Zedekia dibutakannya, lalu ia dibelenggu dengan rantai tembaga untuk dibawa ke Babel.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 39, 8, 'Orang-orang Kasdim membakar istana raja dan perumahan rakyat dengan api, lalu mereka merobohkan tembok-tembok Yerusalem.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 39, 9, 'Kemudian Nebuzaradan, kepala pasukan pengawal, mengangkut ke dalam pembuangan ke Babel sisa-sisa rakyat yang masih tinggal di kota itu dan para pembelot yang menyeberang ke pihaknya dan sisa-sisa para pekerja tangan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 39, 10, 'Tetapi sebagian dari rakyat, yakni orang-orang miskin yang tidak mempunyai apa-apa, ditinggalkan di tanah Yehuda oleh Nebuzaradan, kepala pasukan pengawal. Pada waktu itu juga diberikannyalah kebun-kebun anggur dan ladang-ladang kepada mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 39, 11, 'Mengenai Yeremia, Nebukadnezar, raja Babel, telah memberi perintah dengan perantaraan Nebuzaradan, kepala pasukan pengawal, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 39, 12, '"Bawalah dan perhatikanlah dia, janganlah apa-apakan dia, melainkan haruslah kaulakukan kepadanya sesuai dengan permintaannya kepadamu!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 39, 13, 'Maka Nebuzaradan, kepala pasukan pengawal, beserta Nebusyazban, kepala istana, dan Nergal-Sarezer, panglima, dan semua perwira tinggi raja Babel, mengutus orang?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 39, 14, 'mereka menyuruh mengambil Yeremia dari pelataran penjagaan, lalu menyerahkannya kepada Gedalya bin Ahikam bin Safan untuk membebaskannya, supaya pulang ke rumah. Demikianlah Yeremia tinggal di tengah-tengah rakyat.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 39, 15, 'Selagi Yeremia masih terkurung di pelataran penjagaan, firman TUHAN datang kepadanya, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 39, 16, '"Pergilah kepada Ebed-Melekh, orang Etiopia itu dan katakanlah kepadanya: Beginilah firman TUHAN semesta alam, Allah Israel: Sesungguhnya, firman-Ku terhadap kota ini akan Kulaksanakan untuk kemalangan dan bukan untuk kebaikannya, dan semuanya itu akan terjadi di depan matamu pada waktu itu juga.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 39, 17, 'Pada waktu itu juga, demikianlah firman TUHAN, Aku akan melepaskan engkau, dan engkau tidak akan diserahkan ke dalam tangan orang-orang yang kautakuti,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 39, 18, 'tetapi dengan pasti Aku akan meluputkan engkau: engkau tidak akan rebah oleh pedang; nyawamu akan menjadi jarahan bagimu, sebab engkau percaya kepada-Ku, demikianlah firman TUHAN."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 40, 1, 'Firman yang datang dari pada TUHAN kepada Yeremia, sesudah ia dilepaskan dari Rama oleh Nebuzaradan, kepala pasukan pengawal, yang telah menyuruh untuk mengambilnya terbelenggu pada tangannya di tengah-tengah semua orang buangan dari Yerusalem dan Yehuda yang hendak diangkut ke dalam pembuangan ke Babel.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 40, 2, 'Kepala pasukan pengawal itu telah mengambil Yeremia dan berkata kepadanya: "TUHAN, Allahmu, telah mengancamkan malapetaka ini atas tempat ini,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 40, 3, 'dan Ia telah melaksanakannya. TUHAN telah melakukan apa yang diancamkan-Nya, oleh karena kamu telah berdosa kepada TUHAN dan tidak mendengarkan suara-Nya, sehingga terjadilah hal ini kepada kamu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 40, 4, 'Maka sekarang, lihatlah aku melepaskan engkau hari ini dari belenggu yang ada pada tanganmu itu. Jika engkau suka untuk ikut pergi dengan aku ke Babel, marilah! Aku akan memperhatikan engkau. Tetapi jika engkau tidak suka untuk ikut pergi dengan aku ke Babel, janganlah pergi! Lihat, seluruh negeri ini terbuka untuk engkau: engkau boleh pergi ke mana saja engkau pandang baik dan benar.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 40, 5, 'Engkau boleh kembali kepada Gedalya bin Ahikam bin Safan yang telah diangkat oleh raja Babel atas kota-kota Yehuda, dan tinggallah bersama-sama dia di tengah-tengah rakyat, atau ke mana saja engkau pandang benar, pergilah ke situ!" Lalu kepala pasukan pengawal itu memberikan kepadanya bekal makanan dan suatu hadiah, kemudian melepas dia pergi.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 40, 6, 'Jadi pergilah Yeremia kepada Gedalya bin Ahikam di Mizpa, dan diam bersama-sama dengan dia di tengah-tengah rakyat yang masih tinggal di negeri itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 40, 7, 'Ketika semua panglima tentara, yang masih berada di luar kota dengan orang-orangnya, mendengar bahwa raja Babel telah mengangkat Gedalya bin Ahikam bin Safan atas negeri itu dan bahwa kepadanya telah diserahkan pengawasan atas laki-laki, perempuan dan anak-anak, yaitu dari orang-orang lemah di negeri itu, yang tidak diangkut ke dalam pembuangan ke Babel,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 40, 8, 'maka pergilah mereka kepada Gedalya di Mizpa; mereka ialah Ismael bin Netanya, Yohanan bin Kareah, Seraya bin Tanhumet, anak-anak Efai orang Netofa itu, dan Yezanya, anak seorang Maakha, bersama dengan anak buahnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 40, 9, 'Lalu bersumpahlah Gedalya bin Ahikam bin Safan kepada mereka dengan anak buah mereka: "Janganlah kamu takut untuk takluk kepada orang-orang Kasdim itu; tinggallah di negeri ini dan takluklah kepada raja Babel, maka keadaanmu akan menjadi baik.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 40, 10, 'Dan aku sendiri, aku menetap di Mizpa untuk bertindak sebagai wakil di depan orang-orang Kasdim yang akan datang kepada kita; tetapi kamu ini, kumpulkanlah saja hasil anggur, buah-buahan dan minyak, kemudian simpanlah sebagai persediaan, dan tinggallah di kota-kota di mana kamu hendak menetap."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 40, 11, 'Juga ketika semua orang Yehuda, yang ada di Moab di antara bani Amon, di Edom dan di negeri-negeri lain, mendengar bahwa raja Babel telah membiarkan tinggal sisa rakyat di Yehuda dan mengangkat Gedalya bin Ahikam bin Safan atas mereka,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 40, 12, 'maka kembalilah semua orang Yehuda dari segala tempat ke mana mereka telah berserak-serak, dan masuk ke tanah Yehuda kepada Gedalya di Mizpa; mereka mengumpulkan hasil anggur dan buah-buahan amat sangat banyaknya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 40, 13, 'Pada suatu kali Yohanan bin Kareah dan semua panglima tentara yang masih berada di luar kota datang kepada Gedalya di Mizpa,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 40, 14, 'dan mereka berkata kepadanya: "Tahukah engkau bahwa Baalis, raja bani Amon, telah menyuruh Ismael bin Netanya membunuh engkau?" Tetapi Gedalya bin Ahikam tidak percaya kepada mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 40, 15, 'Kemudian Yohanan bin Kareah berkata dengan diam-diam kepada Gedalya di Mizpa: "Baiklah aku pergi membunuh Ismael bin Netanya itu dengan tidak diketahui siapapun juga. Mengapa engkau harus dibunuhnya, sehingga semua orang Yehuda yang telah berkumpul di sekelilingmu berserak-serak lagi dan sisa Yehuda itu binasa?"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 40, 16, 'Tetapi Gedalya bin Ahikam menjawab Yohanan bin Kareah: "Janganlah lakukan itu! Sebab yang kaukatakan tentang Ismael itu adalah bohong."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 41, 1, 'Dalam bulan yang ketujuh datanglah Ismael bin Netanya bin Elisama?ia keturunan raja dan perwira tinggi raja?beserta sepuluh orang kepada Gedalya bin Ahikam di Mizpa. Sementara mereka makan roti bersama-sama di Mizpa,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 41, 2, 'maka bangkitlah Ismael bin Netanya dengan kesepuluh orang yang ada bersama-sama dia, lalu mereka memukul mati Gedalya bin Ahikam bin Safan dengan pedang; demikianlah Ismael membunuh dia yang telah diangkat raja Babel atas negeri itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 41, 3, 'Juga semua orang Yehuda yang ada bersama-sama dengan Gedalya di Mizpa dan orang-orang Kasdim, yakni prajurit, yang terdapat di sana dipukul mati oleh Ismael.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 41, 4, 'Esok harinya sesudah ia membunuh Gedalya?ketika itu belum ada yang tahu?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 41, 5, 'datanglah orang-orang dari Sikhem, dari Silo dan dari Samaria, delapan puluh orang jumlahnya, yang janggutnya bercukur, pakaiannya koyak-koyak dan badannya bertoreh-toreh; mereka membawa korban sajian dan kemenyan untuk dipersembahkan di rumah TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 41, 6, 'Lalu keluarlah Ismael bin Netanya dari Mizpa untuk mendapatkan mereka sambil menangis. Ketika ia bertemu dengan mereka, berkatalah ia kepada mereka: "Pergilah kepada Gedalya bin Ahikam!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 41, 7, 'Tetapi ketika mereka sampai ke tengah-tengah kota itu, maka mereka disembelih oleh Ismael bin Netanya dengan dibantu oleh orang-orang yang bersama-sama dengan dia; mayat-mayat mereka dicampakkan ke dalam perigi.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 41, 8, 'Tetapi di antara mereka terdapat sepuluh orang yang berkata kepada Ismael: "Janganlah bunuh kami, sebab kami masih mempunyai perbekalan tersembunyi di luar kota, yakni gandum, jelai, minyak dan madu!" Maka iapun membiarkan mereka, tidak membunuhnya bersama-sama dengan rekan-rekan mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 41, 9, 'Adapun perigi, ke mana Ismael melemparkan segala mayat orang-orang yang dipukulnya mati itu adalah perigi besar yang telah dibuat oleh raja Asa untuk menghadapi Baesa, raja Israel; itulah yang diisi Ismael bin Netanya dengan mayat orang-orang yang mati terbunuh itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 41, 10, 'Lalu Ismael mengangkut sebagai tawanan seluruh sisa-sisa rakyat yang ada di Mizpa itu, puteri-puteri raja dan semua orang yang masih tinggal di Mizpa yang telah ditempatkan di bawah Gedalya bin Ahikam oleh Nebuzaradan, kepala pasukan pengawal itu. Ismael bin Netanya mengangkut mereka sebagai tawanan, lalu ia berangkat untuk menyeberang ke daerah bani Amon.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 41, 11, 'Tetapi ketika Yohanan bin Kareah serta semua perwira tentara, yang bersama-sama dengan dia, mendengar tentang segala kejahatan yang telah dilakukan Ismael bin Netanya,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 41, 12, 'maka merekapun mengumpulkan semua anak buah mereka, lalu mereka berangkat memerangi Ismael bin Netanya. Mereka bertemu dengan dia di telaga yang di Gibeon.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 41, 13, 'Ketika seluruh rakyat yang bersama-sama dengan Ismael melihat Yohanan bin Kareah serta semua perwira tentara yang bersama-sama dengan dia, maka bersukacitalah mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 41, 14, 'Semua orang yang diangkut sebagai tawanan oleh Ismael dari Mizpa itu berbalik dan pergi mengikuti Yohanan bin Kareah.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 41, 15, 'Tetapi Ismael bin Netanya beserta delapan orang terluput dari tangan Yohanan dan pergi ke daerah bani Amon.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 41, 16, 'Lalu Yohanan bin Kareah serta semua perwira tentara yang bersama-sama dengan dia mengumpulkan seluruh sisa-sisa rakyat yang diangkut sebagai tawanan oleh Ismael bin Netanya dari Mizpa, setelah ia memukul mati Gedalya bin Ahikam: yaitu laki-laki, prajurit-prajurit, perempuan, anak-anak dan pegawai-pegawai istana yang dibawa kembali dari Gibeon,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 41, 17, 'kemudian mereka berjalan terus dan berhenti di tempat penginapan milik Kimham dekat Betlehem, dengan maksud berjalan terus menuju Mesir,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 41, 18, 'untuk mengelakkan orang-orang Kasdim, yang ditakuti mereka, oleh karena Ismael bin Netanya telah memukul mati Gedalya bin Ahikam yang telah diangkat raja Babel atas negeri itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 42, 1, 'Kemudian datanglah semua perwira tentara, di antaranya Yohanan bin Kareah dan Azarya bin Hosaya, beserta seluruh rakyat, dari yang kecil sampai kepada yang besar,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 42, 2, 'dan mereka berkata kepada nabi Yeremia: "Biarlah kiranya permohonan kami sampai di hadapanmu! Berdoalah untuk kami kepada TUHAN, Allahmu, untuk seluruh sisa ini; sebab dari banyak orang hanya sedikit saja kami yang tinggal, seperti yang kaulihat dengan matamu sendiri.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 42, 3, 'Semoga TUHAN, Allahmu, memberitahukan kepada kami jalan yang harus kami tempuh dan apa yang harus kami lakukan."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 42, 4, 'Jawab nabi Yeremia kepada mereka: "Permohonanmu sudah kudengar! Lihat, aku akan berdoa kepada TUHAN, Allahmu, seperti yang kamu minta itu, dan segala firman, yang diberi TUHAN sebagai jawab, akan kuberitahukan kepadamu; sepatah katapun tidak akan kudiamkan kepadamu!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 42, 5, 'Berkatalah mereka kepada Yeremia: "Biarlah TUHAN menjadi saksi yang benar dan yang dapat dipercaya terhadap kami, jika kami tidak berbuat menurut segala firman yang disuruh TUHAN, Allahmu, kausampaikan kepada kami.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 42, 6, 'Maupun baik ataupun buruk, kami akan mendengarkan suara TUHAN, Allah kita, yang kepada-Nya kami mengutus engkau, supaya keadaan kami baik, oleh karena kami mendengarkan suara TUHAN, Allah kita."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 42, 7, 'Sesudah sepuluh hari datanglah firman TUHAN kepada Yeremia.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 42, 8, 'Lalu Yeremia memanggil Yohanan bin Kareah dan semua perwira tentara yang ada bersama-sama dengan dia, dan seluruh rakyat, dari yang kecil sampai kepada yang besar.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 42, 9, 'Berkatalah ia kepada mereka: "Beginilah firman TUHAN, Allah Israel yang kepada-Nya kamu telah mengutus aku untuk menyampaikan permohonanmu ke hadapan-Nya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 42, 10, 'Jika kamu tinggal tetap di negeri ini, maka Aku akan membangun dan tidak akan meruntuhkan kamu, akan membuat kamu tumbuh dan tidak akan mencabut kamu; sebab Aku menyesal telah mendatangkan malapetaka kepadamu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 42, 11, 'Janganlah takut kepada raja Babel yang kamu takuti itu. Janganlah takut kepadanya, demikianlah firman TUHAN, sebab Aku menyertai kamu untuk menyelamatkan kamu dan untuk melepaskan kamu dari tangannya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 42, 12, 'Aku akan membuat kamu mendapat belas kasihan, sehingga ia merasa belas kasihan kepadamu dan membiarkan kamu tinggal di tanahmu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 42, 13, 'Tetapi jika kamu tidak mau mendengarkan suara TUHAN, Allahmu, dengan mengatakan: Kami tidak mau tinggal di negeri ini!,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 42, 14, 'sebab pikirmu: Tidak! Kami mau pergi ke negeri Mesir, di mana kami tidak akan mengalami pertempuran, tidak akan mendengar bunyi sangkakala dan tidak akan menderita kelaparan; di sanalah kami akan tinggal!,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 42, 15, 'maka dengarkanlah sekarang firman Allah, hai sisa Yehuda: Beginilah firman TUHAN semesta alam, Allah Israel: Jika kamu sungguh-sungguh berniat hendak pergi ke Mesir, dan memang kamu pergi dan tinggal sebagai orang asing di sana,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 42, 16, 'maka pedang yang kamu takuti itu akan menimpa kamu di negeri Mesir, dan kelaparan yang kamu gentarkan itu tidak putus-putusnya mengejar-ngejar kamu di Mesir, sampai kamu mati di sana.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 42, 17, 'Semua orang, yang berniat hendak pergi ke Mesir untuk tinggal sebagai orang asing di sana, akan mati karena pedang, kelaparan dan penyakit sampar; seorangpun dari mereka tidak ada yang terlepas atau terluput dari malapetaka yang Kudatangkan atas mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 42, 18, 'Sungguh, beginilah firman TUHAN semesta alam, Allah Israel: Seperti tercurahnya murka-Ku dan kehangatan amarah-Ku ke atas penduduk Yerusalem, demikianlah akan tercurah kehangatan amarah-Ku ke atas kamu, apabila kamu pergi ke Mesir. Kamu akan menjadi kutuk, kengerian, kutukan dan aib; kamu tidak akan melihat tempat ini lagi.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 42, 19, 'TUHAN telah berfirman kepadamu, hai sisa Yehuda: Janganlah pergi ke Mesir! Camkanlah sungguh-sungguh, bahwa aku memperingatkan kamu pada hari ini!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 42, 20, 'Kamu telah menipu dirimu dan membahayakan nyawamu, ketika kamu mengutus aku kepada TUHAN, Allahmu, dengan berkata: Berdoalah untuk kami kepada TUHAN, Allah kita, dan beritahukanlah dengan tepat kepada kami apa yang difirmankan TUHAN, Allah kita, supaya kami melakukannya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 42, 21, 'Tetapi, sekalipun aku memberitahukannya kepadamu pada hari ini, kamu tidak mendengarkan suara TUHAN, Allahmu, yaitu tidak menuruti segala sesuatu yang disuruh-Nya kusampaikan kepadamu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 42, 22, 'Oleh sebab itu, camkanlah sungguh-sungguh, bahwa kamu akan mati karena pedang, kelaparan dan penyakit sampar di tempat yang kamu rindukan untuk tinggal sebagai orang asing di sana."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 43, 1, 'Ketika Yeremia selesai mengatakan kepada seluruh rakyat segala firman TUHAN, Allah mereka, yang disuruh TUHAN, Allah mereka, disampaikannya kepada mereka, yaitu segala firman yang tersebut di atas,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 43, 2, 'maka berkatalah Azarya bin Hosaya dan Yohanan bin Kareah serta semua orang congkak itu kepada Yeremia: "Engkau berkata bohong! TUHAN, Allah kita, tidak mengutus engkau untuk berkata: Janganlah pergi ke Mesir untuk tinggal sebagai orang asing di sana,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 43, 3, 'tetapi Barukh bin Neria menghasut engkau terhadap kami dengan maksud untuk menyerahkan kami ke dalam tangan orang-orang Kasdim, supaya mereka membunuh kami dan mengangkut kami ke dalam pembuangan ke Babel."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 43, 4, 'Demikianlah Yohanan bin Kareah dan semua perwira tentara serta seluruh rakyat tidak mau mendengarkan suara TUHAN untuk tinggal di tanah Yehuda.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 43, 5, 'Lalu Yohanan bin Kareah dan semua perwira tentara itu mengumpulkan seluruh sisa Yehuda, yakni semua orang yang telah kembali dari antara segala bangsa, ke mana mereka telah berserak-serak, untuk menetap di tanah Yehuda,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 43, 6, 'laki-laki, perempuan, anak-anak, puteri-puteri raja dan setiap orang yang telah dibiarkan Nebuzaradan, kepala pasukan pengawal, pada Gedalya bin Ahikam bin Safan; juga nabi Yeremia dan Barukh bin Neria.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 43, 7, 'Lalu mereka pergi ke tanah Mesir, sebab mereka tidak mau mendengarkan suara TUHAN. Maka sampailah mereka di Tahpanhes.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 43, 8, 'Kemudian datanglah firman TUHAN kepada Yeremia di Tahpanhes, bunyinya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 43, 9, '"Ambillah di tanganmu batu-batu besar dan sembunyikanlah itu di tanah liat dekat pintu masuk istana Firaun di Tahpanhes di hadapan mata orang-orang Yehuda itu,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 43, 10, 'lalu katakanlah kepada mereka: Beginilah firman TUHAN semesta alam, Allah Israel: Sesungguhnya, Aku mengutus orang untuk menjemput Nebukadnezar, raja Babel, hamba-Ku itu, supaya ia mendirikan takhtanya di atas batu-batu yang telah Kusuruh sembunyikan ini, dan membentangkan permadani kebesarannya di atasnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 43, 11, 'Dan apabila ia datang, ia akan memukul tanah Mesir: Yang ke maut, ke mautlah! Yang ke tawanan, ke tawananlah! Yang ke pedang, ke pedanglah!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 43, 12, 'Ia akan menyalakan api di kuil-kuil para allah Mesir dan akan membakar atau mengangkutnya sebagai tawanan. Dan ia akan membersihkan tanah Mesir dari kutu-kutu seperti seorang gembala membersihkan pakaiannya dari kutu-kutu, kemudian ia akan pergi dari sana tanpa gangguan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 43, 13, 'Ia akan memecahkan tugu-tugu berhala Bet-Syemes yang ada di Mesir dan akan menghanguskan kuil para allah Mesir itu dengan api."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 1, 'Firman yang datang kepada Yeremia untuk semua orang Yehuda yang diam di tanah Mesir, di Migdol, di Tahpanhes, di Memfis dan di tanah Patros:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 2, '"Beginilah firman TUHAN semesta alam, Allah Israel: Kamu telah mengalami segenap malapetaka yang telah Kudatangkan atas Yerusalem dan atas segala kota Yehuda; sungguh, semuanya itu kini sudah menjadi reruntuhan dan tidak ada seorangpun diam di sana.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 3, 'Itu disebabkan oleh kejahatan yang telah mereka lakukan untuk menimbulkan sakit hati-Ku, yakni mereka pergi membakar korban dan beribadah kepada allah lain yang tidak dikenal oleh mereka sendiri, oleh kamu atau oleh nenek moyangmu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 4, 'Terus-menerus Aku telah mengutus kepadamu semua hamba-Ku, para nabi, dengan mengatakan: Janganlah hendaknya kamu melakukan kejijikan yang Aku benci ini!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 5, 'Tetapi mereka tidak mau mendengarkan dan tidak mau memperhatikan supaya berbalik dari kejahatan mereka dan tidak membakar korban lagi kepada allah lain.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 6, 'Sebab itu kehangatan amarah-Ku dan murka-Ku telah tercurah dan membakar kota-kota Yehuda dan jalan-jalan Yerusalem, sehingga menjadi reruntuhan dan tempat tandus, seperti yang ternyata sekarang ini.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 7, 'Maka sekarang, beginilah firman TUHAN, Allah semesta alam, Allah Israel: Mengapakah kamu mendatangkan celaka besar kepada dirimu sendiri? Kamu mau melenyapkan laki-laki, perempuan, anak-anak dan bayi dari Yehuda dengan tidak meninggalkan sisa apapun?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 8, 'Mengapa kamu mau menimbulkan sakit hati-Ku dengan perbuatan tanganmu, yakni membakar korban kepada allah lain di tanah Mesir yang kamu masuki untuk tinggal sebagai orang asing di sana? Mengapa kamu mau menjadi kutuk dan aib di antara segala bangsa di bumi?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 9, 'Sudah lupakah kamu kepada kejahatan nenek moyangmu, kejahatan raja-raja Yehuda, kejahatan para pemuka mereka, kejahatanmu sendiri dan kejahatan isteri-isterimu yang dilakukan mereka di tanah Yehuda dan di jalan-jalan Yerusalem?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 10, 'Mereka tidak remuk hati sampai kepada hari ini, mereka tidak takut dan tidak mengikuti Taurat-Ku dan ketetapan-Ku yang telah Kuberikan kepadamu dan kepada nenek moyangmu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 11, 'Sebab itu beginilah firman TUHAN semesta alam, Allah Israel: Sesungguhnya, Aku mau menujukan wajah-Ku terhadap kamu untuk kecelakaanmu, yakni Aku mau melenyapkan segenap orang Yehuda.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 12, 'Aku mau mencabut sisa Yehuda yang berniat hendak pergi ke tanah Mesir untuk tinggal sebagai orang asing di sana; mereka semuanya akan habis mati di tanah Mesir; mereka akan rebah mati karena pedang dan akan habis mati karena kelaparan, dari yang kecil sampai kepada yang besar; mereka akan mati karena pedang dan karena kelaparan dan mereka akan menjadi kutuk, kengerian, kutukan dan aib.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 13, 'Aku mau menghukum mereka yang diam di tanah Mesir, sama seperti Aku telah menghukum Yerusalem, yaitu dengan pedang, dengan kelaparan dan dengan penyakit sampar,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 14, 'sehingga dari sisa Yehuda, yang telah pergi ke tanah Mesir untuk tinggal sebagai orang asing di sana, tidak ada seorangpun yang terluput atau terlepas untuk kembali ke tanah Yehuda, ke mana hati mereka sangat rindu untuk diam di sana lagi; sungguh, mereka tidak akan kembali, kecuali beberapa orang pengungsi."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 15, 'Lalu menjawablah kepada Yeremia semua orang laki-laki yang tahu bahwa isteri mereka membakar korban kepada allah lain, dan semua perempuan yang hadir di sana, suatu kumpulan yang besar, yakni segala rakyat yang diam di tanah Mesir dan di Patros, katanya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 16, '"Mengenai apa yang kaukatakan demi nama Allah kepada kami itu, kami tidak akan mendengarkan engkau,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 17, 'tetapi kami akan terus melakukan segala apa yang kami ucapkan, yakni membakar korban kepada ratu sorga dan mempersembahkan korban curahan kepadanya seperti telah kami lakukan, kami sendiri dan nenek moyang kami dan raja-raja kami dan pemuka-pemuka kami di kota-kota Yehuda dan di jalan-jalan Yerusalem. Pada waktu itu kami mempunyai cukup makanan; kami merasa bahagia dan tidak mengalami penderitaan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 18, 'Tetapi sejak kami berhenti membakar korban dan mempersembahkan korban curahan kepada ratu sorga, maka kami kekurangan segala-galanya dan kami dihabiskan oleh pedang dan kelaparan."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 19, 'Lalu perempuan-perempuan itu menambahkan: "Apabila kami membakar korban dan mempersembahkan korban curahan kepada ratu sorga, adakah di luar pengetahuan suami kami bahwa kami membuat penganan persembahan serupa dengan patungnya dan mempersembahkan korban curahan kepadanya?"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 20, 'Sesudah itu berkatalah Yeremia kepada segenap rakyat itu, kepada laki-laki dan perempuan dan kepada semua orang yang telah memberi jawab kepadanya itu, katanya:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 21, '"Justru korban yang dibakar di kota-kota Yehuda dan di jalan-jalan Yerusalem oleh kamu sendiri, oleh nenek moyangmu, oleh raja-rajamu, oleh pemuka-pemukamu dan oleh rakyat negeri, tidakkah itu yang diingat TUHAN dan yang diperhatikan-Nya?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 22, 'TUHAN tidak tahan lagi melihat perbuatan-perbuatanmu yang jahat dan kejijikan yang kamu lakukan; oleh karena itu negerimupun telah menjadi reruntuhan, kengerian dan kutuk tanpa penduduk, seperti yang ternyata sekarang ini.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 23, 'Kamu telah membakar korban dan kamu telah berdosa kepada TUHAN, tidak mendengarkan suara TUHAN dan tidak mengikuti Taurat-Nya, ketetapan-Nya dan peraturan-Nya, itulah sebabnya malapetaka ini menimpa kamu, seperti yang ternyata sekarang ini."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 24, 'Kemudian berkatalah Yeremia kepada segenap rakyat dan kepada semua perempuan itu: "Dengarlah firman TUHAN, hai semua orang Yehuda yang ada di tanah Mesir.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 25, 'Beginilah firman TUHAN semesta alam, Allah Israel: Kamu, laki-laki dan isteri-isterimu! Kamu telah memenuhi apa yang telah kamu ucapkan, yaitu: Kami akan menepati dengan baik nazar yang kami ucapkan untuk membakar korban dan mempersembahkan korban curahan kepada ratu sorga. Baiklah! Wujudkanlah dan tepatilah nazarmu dengan baik!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 26, 'Maka dengarkanlah firman TUHAN, hai semua orang Yehuda yang diam di tanah Mesir: Sesungguhnya, Aku telah bersumpah demi nama-Ku yang besar?firman TUHAN?bahwa nama-Ku tidak akan diserukan lagi oleh seseorang Yehuda di segenap tanah Mesir, dengan berkata: Demi Tuhan ALLAH yang hidup!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 27, 'Sesungguhnya Aku berjaga-jaga untuk kecelakaan mereka dan bukan untuk kebahagiaan mereka; setiap orang Yehuda yang ada di tanah Mesir akan dihabiskan oleh pedang dan oleh kelaparan sampai mereka punah sama sekali.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 28, 'Hanya beberapa orang yang terluput dari pedang?jumlahnya kecil?yang akan kembali dari tanah Mesir ke tanah Yehuda. Maka seluruh sisa Yehuda yang telah pergi ke Mesir untuk tinggal sebagai orang asing di sana akan mengetahui perkataan siapa yang terwujud, perkataan-Ku atau perkataan mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 29, 'Inilah tanda bagimu, demikianlah firman TUHAN, bahwa Aku akan menghukum kamu di tempat ini, supaya kamu mengetahui bahwa perkataan-perkataan-Ku terhadap kamu akan sungguh-sungguh terwujud untuk kecelakaanmu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 44, 30, 'Beginilah firman TUHAN: Sesungguhnya, Aku menyerahkan Firaun, Hofra, raja Mesir, ke dalam tangan musuhnya dan ke dalam tangan orang-orang yang berusaha mencabut nyawanya, sama seperti Aku telah menyerahkan Zedekia, raja Yehuda, ke dalam tangan Nebukadnezar, raja Babel, musuhnya yang berusaha mencabut nyawanya."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 45, 1, 'Firman yang disampaikan oleh nabi Yeremia kepada Barukh bin Neria, waktu Barukh dalam tahun keempat pemerintahan Yoyakim bin Yosia, raja Yehuda, menuliskan segala firman tersebut dalam sebuah kitab langsung dari mulut Yeremia:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 45, 2, '"Beginilah firman TUHAN, Allah Israel, tentang engkau, hai Barukh!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 45, 3, 'Oleh karena engkau telah berkata: Celakalah aku, sebab TUHAN telah menambahkan kedukaan kepada penderitaanku! Aku lesu karena keluh kesahku dan aku tidak mendapat ketenangan,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 45, 4, 'maka beginilah firman TUHAN: Sesungguhnya, apa yang Kubangun akan Kuruntuhkan, dan apa yang Kutanam akan Kucabut, bahkan sekalipun seluruh negeri!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 45, 5, 'Masakan engkau mencari hal-hal yang besar bagimu sendiri? Janganlah mencarinya! Sebab, sesungguhnya, Aku mendatangkan malapetaka atas segala makhluk, demikianlah firman TUHAN, tetapi kepadamu akan Kuberikan nyawamu sebagai jarahan di segala tempat ke mana engkau pergi."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 1, 'Firman TUHAN yang datang kepada nabi Yeremia tentang bangsa-bangsa.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 2, 'Mengenai Mesir. Terhadap tentara Firaun Nekho, raja Mesir, yang berkemah di tepi sungai Efrat dekat Karkemis dan yang dipukul kalah oleh Nebukadnezar, raja Babel, dalam tahun yang keempat pemerintahan Yoyakim bin Yosia, raja Yehuda:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 3, '"Siapkanlah perisai besar dan perisai kecil dan majulah untuk bertempur!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 4, 'Pasanglah kuda, dan naiklah, hai pengendara-pengendara! Ambillah tempatmu dengan memakai ketopong, tajamkanlah tombakmu, pakailah baju zirahmu!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 5, 'Mengapa kulihat mereka terkejut, mundur ke belakang? Pahlawan-pahlawan mereka terpukul kalah, lari kocar-kacir, tanpa menoleh; kedahsyatan dari segala jurusan!, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 6, 'Orang yang tangkas tidak dapat melarikan diri, pahlawan tidak dapat meluputkan diri; di utara, di tepi sungai Efratlah mereka tersandung dan rebah.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 7, 'Siapakah ini yang meluas seperti sungai Nil dan yang airnya bergelora seperti sungai-sungai?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 8, 'Itulah Mesir yang meluas seperti sungai Nil, dan yang airnya bergelora seperti sungai-sungai. Ia berkata: Aku mau meluas menutupi bumi, membinasakan kota dan penduduknya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 9, 'Majulah, hai kuda-kuda! Melajulah, hai kereta-kereta! Majulah berperang, hai pahlawan-pahlawan, hai kamu orang Etiopia dan orang Put yang memegang perisai, dan orang Lidia yang membentur busur!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 10, 'Hari itu ialah hari Tuhan ALLAH semesta alam, hari pembalasan untuk melakukan pembalasan kepada para lawan-Nya. Pedang akan makan sampai kenyang, dan akan puas minum darah mereka. Sebab Tuhan ALLAH semesta alam mengadakan korban penyembelihan di tanah utara, dekat sungai Efrat.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 11, 'Pergilah ke Gilead mengambil balsam, hai anak dara, puteri Mesir! Sia-sia engkau memakai banyak obat, kesembuhan tidak akan kaudapat!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 12, 'Bangsa-bangsa telah mendengar tentang celamu, bumi telah penuh dengan teriakmu, sebab pahlawan yang satu tersandung kepada pahlawan yang lain, keduanya rebah bersama-sama."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 13, 'Firman yang disampaikan TUHAN kepada nabi Yeremia tentang datangnya Nebukadnezar, raja Babel, untuk memukul kalah tanah Mesir:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 14, '"Beritahukanlah di Mesir, dan kabarkanlah di Migdol! Kabarkanlah di Memfis dan di Tahpanhes! Katakanlah: Ambillah tempat dan bersiaplah, sebab sekitarmu habis dimakan pedang!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 15, 'Mengapa Apis melarikan diri, tidakkah sanggup sapi jantanmu bertahan? Sungguh, TUHAN telah menundukkan dia!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 16, 'Banyak dari padamu yang tersandung dan rebah, mereka berkata seorang kepada yang lain: Marilah kita pulang kepada bangsa kita, ke negeri kelahiran kita, untuk mengelakkan pedang yang merajalela ini!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 17, 'Sebutlah nama Firaun, raja Mesir: Tukang ribut yang membiarkan kesempatan berlalu!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 18, 'Demi Aku yang hidup, demikianlah firman Raja yang nama-Nya TUHAN semesta alam, ia akan datang seperti gunung Tabor yang menjulang di antara gunung-gunung lain, seperti gunung Karmel yang menganjur ke laut.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 19, 'Siapkanlah bagimu barang-barang untuk perjalananmu ke pembuangan, hai puteri Mesir yang sudah lama menetap! Sebab Memfis akan menjadi sunyi sepi, dijadikan reruntuhan yang tidak berpenduduk lagi.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 20, 'Mesir adalah lembu muda yang elok, tetapi seekor pikat dari utara mendatangi dia.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 21, 'Juga prajurit-prajurit upahan yang ada padanya adalah seperti anak-anak lembu tambun; merekapun berbalik dan melarikan diri bersama-sama; mereka tidak dapat bertahan, sebab hari bencana mereka menimpa mereka, yakni waktu penghukuman mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 22, 'Suaranya seperti ular yang mendesis, apabila mereka berjalan maju dengan bertentara; mereka mendatangi dia dengan membawa kapak seperti orang-orang penebang pohon.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 23, 'Mereka menebang hutannya, demikianlah firman TUHAN, sekalipun itu tidak dapat dimasuki; sebab lebih banyak mereka dari pada belalang, tidak terbilang jumlahnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 24, 'Puteri Mesir menjadi malu, diserahkan ke dalam tangan bangsa dari utara."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 25, 'TUHAN semesta alam, Allah Israel, berfirman: "Sesungguhnya, Aku mendatangkan hukuman atas dewa Amon dari Tebe, atas Firaun beserta Mesir, dewa-dewanya dan raja-rajanya, yakni atas Firaun beserta orang-orang yang percaya kepadanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 26, 'Aku akan menyerahkan mereka ke dalam tangan orang-orang yang berusaha mencabut nyawa mereka, yakni ke dalam tangan Nebukadnezar, raja Babel, dan para pegawainya. Tetapi sesudahnya negeri itu akan didiami seperti dalam zaman purbakala, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 27, 'Maka engkau, janganlah takut, hai hamba-Ku Yakub, janganlah gentar, hai Israel! Sebab sesungguhnya, Aku menyelamatkan engkau dari tempat jauh dan keturunanmu dari negeri pembuangan mereka. Yakub akan kembali dan hidup tenang dan aman, dengan tidak ada yang mengejutkan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 46, 28, 'Maka engkau, janganlah takut, hai hamba-Ku Yakub, demikianlah firman TUHAN, sebab Aku menyertai engkau: segala bangsa yang ke antaranya engkau Kuceraiberaikan akan Kuhabiskan, tetapi engkau ini tidak akan Kuhabiskan. Aku akan menghajar engkau menurut hukum, tetapi Aku sama sekali tidak memandang engkau tak bersalah."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 47, 1, 'Firman TUHAN yang datang kepada nabi Yeremia mengenai orang Filistin, sebelum Firaun mengalahkan Gaza.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 47, 2, '"Beginilah firman TUHAN: Lihat, air yang meluas mengamuk dari utara menjadi sungai yang membanjir, membanjiri negeri serta isinya, kota serta penduduknya. Manusia akan berteriak, dan seluruh penduduk negeri akan meratap,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 47, 3, 'mendengar bunyi derap kuku kudanya, mendengar derak-derik keretanya, kertak-kertuk rodanya. Para ayah tidak lagi berpaling menoleh kepada anak-anak, sebab tangan mereka sudah lemas,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 47, 4, 'oleh karena telah tiba harinya untuk membinasakan semua orang Filistin, dan melenyapkan bagi Tirus dan Sidon setiap penolong yang masih tinggal. Sungguh, TUHAN akan membinasakan orang Filistin, yakni sisa orang yang datang dari pulau Kaftor.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 47, 5, 'Gaza telah menjadi gundul, Askelon telah menjadi bungkam; hai Asdod, sisa orang Enak, berapa lama lagi engkau menoreh-noreh diri?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 47, 6, 'Ah, pedang TUHAN, berapa lama lagi baru engkau berhenti? Masuklah kembali ke dalam sarungmu, jadilah tenang dan beristirahatlah!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 47, 7, 'Tetapi bagaimana ia dapat berhenti? Bukankah TUHAN memerintahkannya? Ke Askelon dan ke tepi pantai laut, ke sanalah Ia menyuruhnya!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 1, 'Mengenai Moab. Beginilah firman TUHAN semesta alam, Allah Israel: "Celakalah Nebo, sebab kota itu sudah dibinasakan! Kiryataim telah menjadi malu dan direbut! Kota benteng itu menjadi malu dan terkejut:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 2, 'lenyaplah sudah kemegahan Moab! Di Hesybon orang merencanakan malapetaka terhadapnya: Marilah kita melenyapkannya sebagai bangsa! Juga engkau, hai Madmen, akan dibungkamkan, engkau akan dikejar-kejar pedang.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 3, 'Dengar! Teriakan dari Horonaim: Kebinasaan! Kehancuran besar!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 4, 'Moab telah hancur lebur! kedengaran orang berteriak sampai ke Zoar.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 5, 'Sungguh, orang mendaki pendakian Luhit sambil menangis. Sungguh, di jalan turun ke Horonaim orang mendengar teriak karena ditimpa bencana.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 6, 'Larilah, selamatkanlah nyawamu: jadilah seperti keledai liar di padang gurun!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 7, 'Sungguh, oleh karena engkau percaya kepada bentengmu dan perbendaharaanmu, maka engkaupun akan direbut; Kamos akan pergi ke dalam pembuangan, bersama-sama dengan para imam dan pemukanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 8, 'Pembinasa akan datang ke setiap kota, tidak ada kota yang terluput! Lembah akan binasa, tanah datar habis musnah, seperti yang difirmankan TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 9, 'Berikanlah sayap kepada Moab, supaya ia lari terbang; kota-kotanya akan menjadi sunyi sepi, tidak ada lagi penduduk di dalamnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 10, 'Terkutuklah orang yang melaksanakan pekerjaan TUHAN dengan lalai, dan terkutuklah orang yang menghambat pedang-Nya dari penumpahan darah!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 11, 'Moab hidup aman dari sejak masa mudanya, dia hidup tenang seperti anggur di atas endapannya, tidak dituangkan dari tempayan yang satu ke tempayan yang lain, tidak pernah masuk ke dalam pembuangan; sebab itu rasanya tetap padanya, dan baunya tidak berubah.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 12, 'Sebab itu, sesungguhnya, waktunya akan datang, demikianlah firman TUHAN, bahwa Aku akan mengirim kepadanya tukang-tukang yang akan menuangkannya, mencurahkan tempayan-tempayannya dan memecahkan buyung-buyungnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 13, 'Maka Moab akan menjadi malu oleh karena dewa Kamos, sama seperti kaum Israel menjadi malu oleh karena Betel, kepercayaan mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 14, 'Bagaimanakah kamu berani berkata: Kami adalah pahlawan-pahlawan, orang-orang gagah perkasa untuk berperang!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 15, 'Pembinasa Moab telah maju menyerang dia, teruna-terunanya yang pilihan telah turun ke pembantaian, demikianlah firman Raja yang nama-Nya TUHAN semesta alam.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 16, 'Bencana Moab sudah hampir datang, malapetakanya sangat segera sampai.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 17, 'Ratapilah dia, hai semua yang ada di sekitarnya, hai semua yang mengenal namanya! Katakanlah: Sungguh, sudah patah tampuk kekuasaan, tongkat keagungan itu!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 18, 'Turunlah dari kemuliaanmu dan duduklah di atas kotoran, hai puteri Dibon yang sudah lama menetap! Sebab pembinasa Moab sudah maju menyerbu engkau, memusnahkan tempat-tempatmu yang berkubu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 19, 'Berdirilah di tepi jalan dan tinjaulah, hai penduduk Aroer! Tanyakanlah kepada orang yang lari dan yang terluput, katakanlah: Apakah yang telah terjadi?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 20, 'Moab sudah malu, karena ia terkejut! Merataplah dan berteriaklah, beritahukanlah di sungai Arnon: Sungguh, Moab sudah binasa!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 21, 'Penghukuman telah berlaku atas daerah dataran tinggi, atas kota-kota Holon, Yahas, Mefaat,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 22, 'Dibon, Nebo, Bet-Diblataim,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 23, 'Kiryataim, Bet-Gamul, Bet-Meon,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 24, 'Keriot, Bozra dan atas segala kota negeri Moab yang jauh dan yang dekat.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 25, 'Telah patah tanduk kekuatan Moab, dan lengan kekuasaannya telah pecah! demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 26, 'Buatlah dia mabuk, sebab dia membesarkan diri terhadap TUHAN! Moab akan berguling-guling dalam muntahnya, dan ia sendiripun akan menjadi tertawaan orang.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 27, 'Apakah bukan Israel tadinya yang menjadi tertawaan bagimu? Apakah dia terdapat di antara pencuri-pencuri, sehingga engkau menggeleng-gelengkan kepala, setiap kali engkau berbicara tentang dia?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 28, 'Tinggalkanlah kota-kota dan diamlah di bukit batu, hai penduduk Moab! Jadilah seperti burung merpati yang bersarang di dinding mulut liang.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 29, 'Kami telah mendengar tentang keangkuhan Moab, alangkah angkuhnya dia, tentang kesombongannya, keangkuhannya dan kecongkakannya, tentang tinggi hatinya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 30, 'Aku ini kenal kepongahannya, demikianlah firman TUHAN, tidak benar cakapnya, dan tidak benar perilakunya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 31, 'Sebab itu aku akan meratap karena Moab, akan berteriak karena Moab seluruhnya, dan akan mengaduh karena orang-orang Kir-Heres!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 32, 'Aku akan menangis karena engkau, lebih dari pada menangis karena Yaezer, hai pohon anggur Sibma! Ranting-rantingmu merambak sampai ke laut, meluas sampai ke Yaezer. Si pembinasa telah jatuh menimpa hasil musim kemaraumu dan panen buah anggurmu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 33, 'Sukaria dan sorak-sorak telah lenyap dari kebun buah-buahan dan dari negeri Moab. Aku telah menjauhkan anggur dari tempat pemerasan; pengirik tidak ada lagi pengiriknya, pekik kegirangan tidak kedengaran lagi.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 34, 'Hesybon dan Eleale meraung-raung; orang memperdengarkan suaranya sampai ke Yahas, dari Zoar sampai Horonaim dan Eglat-Selisia; sebab air sungai Nimrim juga menjadi ketandusan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 35, 'Firman TUHAN: Aku akan menghentikan orang di Moab mempersembahkan korban bakaran di bukit pengorbanan dan mempersembahkan korban ukupan kepada allahnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 36, 'Sebab itu seperti hatiku terharu mendengar suling, begitulah hatiku terharu melihat keadaan Moab, dan hatiku terharu melihat keadaan orang-orang Kir-Heres; bukankah sudah hilang segala harta yang mereka tumpuk?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 37, 'Sungguh, setiap kepala digundul dan setiap janggut dipotong, pada semua tangan ada toreh-torehan dan kain kabung dikenakan pada semua pinggang.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 38, 'Di atas segala sotoh Moab dan di tanah-tanah lapangnya hanya ada perkabungan belaka; ?sungguh, Aku telah memecahkan Moab seperti tembikar, sehingga tidak ada orang yang menyukainya, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 39, 'Betapa terkejutnya dia! Betapa Moab menyembunyikan mukanya karena malu! Maka Moab telah menjadi tertawaan dan kekejutan bagi semua yang di sekitarnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 40, 'Sebab beginilah firman TUHAN: Sesungguhnya, ia datang melayang seperti burung rajawali dan mengembangkan sayapnya ke atas Moab.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 41, 'Kota-kota direbut, kubu-kubu pertahanan dirampas. Hati para pahlawan Moab pada waktu itu akan seperti hati perempuan yang sakit beranak.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 42, 'Moab akan musnah sebagai bangsa, sebab ia membesarkan diri terhadap TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 43, 'Kejut dan pelubang dan jerat bagimu, hai penduduk Moab! demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 44, 'Yang lari dari kekejutan akan jatuh ke dalam pelubang, dan yang naik dari pelubang akan tertangkap dalam jerat. Sungguh, Aku mendatangkan semuanya ini atas Moab di tahun penghukuman atas mereka, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 45, 'Di naungan Hesybon orang-orang pelarian berhenti, kehabisan kekuatan; tetapi api keluar dari Hesybon, nyala api dari istana Sihon, yang memakan habis pelipis Moab dan batu kepala orang-orang ribut.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 46, 'Celakalah engkau, hai Moab, binasa engkau, hai bangsa dewa Kamos! Sebab anak-anakmu lelaki telah diculik tertawan dan anak-anakmu perempuan menjadi tawanan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 48, 47, 'Tetapi Aku akan memulihkan keadaan Moab di kemudian hari, demikianlah firman TUHAN." Sampai di sinilah firman penghukuman atas Moab.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 1, 'Mengenai bani Amon. Beginilah firman TUHAN: "Tidak adakah anak Israel, tidak adakah ahli warisnya? Mengapakah dewa Milkom memiliki Gad, dan bangsanya mendiami kota-kotanya?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 2, 'Sebab itu, sesungguhnya, waktunya akan datang, demikianlah firman TUHAN, bahwa Aku akan memperdengarkan tempik sorak peperangan terhadap Raba bani Amon. Kota itu akan menjadi anak bukit yang tandus, dan kota-kota jajahannya akan dibakar dengan api; maka Israel akan memiliki orang-orang yang dahulu memilikinya, firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 3, 'Merataplah, hai Hesybon, sebab pembinasa telah maju menyerbu, berteriaklah, hai puteri-puteri Raba, kenakanlah kain kabung, berkabunglah, berjalan kelilinglah dengan luka toreh-torehan, sebab Milkom akan pergi ke dalam pembuangan bersama-sama dengan para imam dan pemuka-pemukanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 4, 'Betapa engkau memegahkan dirimu dengan lembahmu, hai puteri yang congkak, yang percaya akan harta bendanya dan yang berkata: Siapakah yang berani datang menyerang aku?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 5, 'Sesungguhnya, Aku mendatangkan kekejutan atasmu demikianlah firman Tuhan ALLAH semesta alam, dari segala tempat di sekitarmu, sehingga kamu bersorak-sorak, masing-masing ke arahnya sendiri, dan tidak ada yang mengumpulkan orang-orang yang mengembara itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 6, 'Tetapi sesudah itu Aku akan memulihkan keadaan bani Amon itu, demikianlah firman TUHAN."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 7, 'Mengenai Edom. Beginilah firman TUHAN semesta alam: "Tidak adakah lagi kebijaksanaan di Teman? Sudah hilangkah pertimbangan dari orang-orang yang berakal budi, sudah busukkah kebijaksanaan mereka?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 8, 'Larilah cepat, bersembunyilah dalam liang-liang, hai penduduk Dedan! Sebab malapetaka akan Kudatangkan atas Esau, pada waktu Aku menghukum dia.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 9, 'Jika pemetik buah anggur datang kepadamu, mereka tidak akan meninggalkan sisa-sisa pemetikannya! Jika malam-malam pencuri datang kepadamu, mereka akan merusakkan sepuas-puasnya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 10, 'Tetapi Aku ini telah menelanjangi Esau, telah menyingkapkan tempat-tempat persembunyiannya, sehingga ia tidak dapat menyembunyikan diri lagi. Keturunannya telah binasa dan saudara-saudaranya dan bangsa-bangsa tetangganya tidak ada lagi.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 11, 'Tinggalkanlah anak-anak yatimmu, aku akan menghidupi mereka; biarlah janda-jandamu menaruh kepercayaan padaku!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 12, 'Sebab beginilah firman TUHAN: "Sedangkan orang-orang yang tidak selayaknya meminum isi piala itu telah terpaksa meminumnya, masakan engkau ini akan bebas dari hukuman? Engkau tidak akan bebas dari hukuman, tetapi mesti meminumnya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 13, 'Sebab Aku telah bersumpah demi diri-Ku, demikianlah firman TUHAN, bahwa Bozra akan menjadi ketandusan, cela, keruntuhan dan kutuk, dan segala kotanya akan menjadi reruntuhan yang kekal."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 14, 'Suatu kabar telah kudengar dari TUHAN, seorang utusan telah disuruh ke tengah-tengah bangsa-bangsa: "Berkumpullah, pergilah menyerangnya, bersiaplah untuk bertempur!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 15, 'Sebab sesungguhnya, Aku membuat engkau kecil di antara bangsa-bangsa, dihinakan di antara manusia.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 16, 'Sikapmu yang menggemetarkan orang memperdayakan engkau, dan keangkuhan hatimu, ya engkau yang tinggal di liang-liang batu, yang menduduki tempat tinggi bukit! Sekalipun engkau membuat sarangmu tinggi seperti burung rajawali, Aku akan menurunkan engkau dari sana, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 17, 'Edom akan menjadi ketandusan; setiap orang yang melewatinya akan merasa ngeri dan bersuit karena segala pukulan yang dideritanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 18, 'Seperti pada waktu ditunggangbalikkannya Sodom dan Gomora dan kota-kota tetangganya?firman TUHAN?maka seorangpun tidak akan diam lagi di sana dan seorang manusiapun tidak akan tinggal lagi di dalamnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 19, 'Sesungguhnya, seperti singa yang bangkit keluar dari hutan belukar sungai Yordan mendatangi padang rumput tempat kawanan domba, demikianlah Aku akan membuat mereka lari dengan tiba-tiba dari negeri itu dan mengangkat di dalamnya dia yang Kupilih. Sebab siapakah yang seperti Aku? Siapakah yang berani mendakwa Aku? Siapakah gerangan gembala yang tahan menghadapi Aku?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 20, 'Sebab itu dengarlah putusan yang telah diambil TUHAN terhadap Edom dan rancangan-rancangan yang telah dibuat-Nya terhadap penduduk Teman: Bahwa sesungguhnya, yang paling lemahpun di antara kawanan domba akan diseret. Bahwa sesungguhnya, padang rumput mereka sendiri akan merasa ngeri terhadap mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 21, 'Bumi akan goncang karena bunyi jatuhnya mereka; teriakan mereka akan terdengar bunyinya di Laut Teberau.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 22, 'Sesungguhnya, ia naik terbang seperti burung rajawali, melayang dan mengembangkan sayapnya ke atas Bozra. Hati para pahlawan Edom pada waktu itu akan seperti hati perempuan yang sakit beranak."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 23, 'Mengenai Damsyik. "Hamat dan Arpad telah menjadi malu, sebab mereka mendengar kabar buruk; hati mereka gemetar karena kecemasan, tidak dapat menjadi tenang.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 24, 'Damsyik telah menjadi lemah semangat, berpaling untuk lari, kegemparan telah mencekam dia, kesesakan dan sakit beranak telah menggenggam dia seperti seorang perempuan yang sedang melahirkan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 25, 'Sungguh, kota yang terpuji itu sudah ditinggalkan, kota kegirangan itu!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 26, 'Sebab itu teruna-terunanya akan rebah di tanah-tanah lapangnya dan semua prajuritnya akan menjadi bungkam pada waktu itu, demikianlah firman TUHAN semesta alam.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 27, 'Aku akan menyalakan api di tembok Damsyik, yang menghanguskan puri Benhadad."', 'id', 'TB')
